/*
 * OCR GCSE Geography B (J384) — Exam Practice Question Bank
 * Shape: { topicId: { name, questions: [{ q, marks, command, markScheme, diagram? }] } }
 * Topic ids unchanged so topics-config.js still matches.
 *
 * WHY THIS SHAPE. Real OCR GCSE Geography B (J384) questions are built on
 * resources (described figures, tables, maps and photos) and named case studies,
 * with fieldwork questions on sampling, presentation and evaluation. Every item
 * here opens with a fully described resource or a located context.
 *
 * TARIFFS. Part tariffs follow the real mix taken from the site's own past-paper
 * data for this specification.
 *
 * MARK SCHEMES. Board style: point-marked items one point per line; extended
 * items give indicative content and the board's level ladder, including SPaG
 * where the board awards it.
 *
 * Data marked "written for this practice question" is invented but realistic and
 * every calculation has been checked.
 * Drawing canvas flag (diagram: true) enables the sketch area in practice.html.
 */

const GEOGRAPHY_OCR_GCSE_PRACTICE = {
  '1.1': {
    name: 'Global Hazards: Extreme Weather',
    questions: [
      { q: `Section A — Global Hazards.\n\nFig. 1 (data written for this practice question): mean monthly rainfall (mm) at a weather station in northern Australia, 12° S.\nJan 390 | Feb 330 | Mar 280 | Apr 100 | May 20 | Jun 2 | Jul 1 | Aug 5 | Sep 15 | Oct 70 | Nov 140 | Dec 250\n\nIdentify the wettest month shown in Fig. 1.`, marks: 1, command: 'Identify', markScheme: `January (390 mm) (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 2: a diagram of the global atmospheric circulation model for the Northern Hemisphere. It shows three cells of circulating air: one between the Equator and 30° N, one between 30° N and 60° N, and one between 60° N and the North Pole. Air rises at the Equator and at 60° N and sinks at 30° N and at the pole.\n\nState the name of the circulation cell found between 30° N and 60° N.`, marks: 1, command: 'State', markScheme: `Ferrel cell (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 3: the Saffir–Simpson scale for tropical storms (sustained wind speed).\nCategory 1: 119–153 km/h | Category 2: 154–177 km/h | Category 3: 178–208 km/h | Category 4: 209–251 km/h | Category 5: 252 km/h or more\n\nA hurricane approaching the coast of Florida has sustained winds of 230 km/h. Using Fig. 3, identify the category of this hurricane.`, marks: 1, command: 'Identify', markScheme: `Category 4 (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 4: a world map showing the tracks of tropical storms over ten years. Tracks are labelled with the regional name for the storms: 'hurricanes' in the Atlantic Ocean and Caribbean Sea, 'cyclones' in the Indian Ocean and around northern Australia, and a third name in the north-west Pacific Ocean near the Philippines, China and Japan.\n\nGive the name used for tropical storms in the north-west Pacific Ocean.`, marks: 1, command: 'Give', markScheme: `Typhoon(s) (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 5 (data written for this practice question): sea surface temperature difference from the long-term average (°C) in the eastern Pacific Ocean off the coast of Peru, each December.\n2011 −0.9 | 2012 +0.1 | 2013 −0.2 | 2014 +0.7 | 2015 +2.4 | 2016 −0.6 | 2017 −0.9 | 2018 +0.8\n\nEl Niño events occur when the eastern Pacific is much warmer than average. Identify the year in Fig. 5 with the strongest El Niño.`, marks: 1, command: 'Identify', markScheme: `2015 (+2.4 °C) (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 6: a scatter graph of the number of reported extreme weather events in the world each year, 1990–2020. The points rise from about 200 events in 1990 to about 400 events by 2020. The highest point is 2007 with about 430 events; the lowest is 1990.\n\nSuggest one reason why the number of reported extreme weather events may have increased over the period shown in Fig. 6.`, marks: 1, command: 'Suggest', markScheme: `One from (1):\n• climate change / warmer oceans and atmosphere making extreme weather more frequent\n• better monitoring / satellites / communication mean more events are recorded and reported\n• more people living in hazard-prone areas, so more events affect people and are counted\nAccept other valid reasons.` },
      { q: `Section A — Global Hazards.\n\nFig. 1 (data written for this practice question): mean monthly rainfall (mm) at a weather station in northern Australia, 12° S.\nJan 390 | Feb 330 | Mar 280 | Apr 100 | May 20 | Jun 2 | Jul 1 | Aug 5 | Sep 15 | Oct 70 | Nov 140 | Dec 250\n\nCalculate the mean monthly rainfall for the dry season, May to September. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Working: 20 + 2 + 1 + 5 + 15 = 43; 43 ÷ 5 (1)\nAnswer: 8.6 mm (1)\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Global Hazards.\n\nFig. 7 (data written for this practice question): number of named tropical storms in the North Atlantic each year.\n2010: 14 | 2011: 17 | 2012: 12 | 2013: 19 | 2014: 15 | 2015: 28 | 2016: 16 | 2017: 15\n\nCalculate the median number of named storms per year. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Working: values in order 12, 14, 15, 15, 16, 17, 19, 28; middle two values are 15 and 16, (15 + 16) ÷ 2 (1)\nAnswer: 15.5 (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 8 (data written for this practice question): the number of tropical storms reaching Category 4 or 5 worldwide was 171 in the 1980s and 269 in the 2000s.\n\nCalculate the percentage increase in Category 4 and 5 storms between the 1980s and the 2000s. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Working: 269 − 171 = 98; (98 ÷ 171) × 100 (1)\nAnswer: 57.3% (accept 57%) (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 9: the track of a hurricane across the Caribbean Sea. In 3 days the centre of the hurricane moved 1,260 km westwards from the Windward Islands towards Jamaica.\n\nCalculate the mean speed of the hurricane in km per hour. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Working: 3 days = 72 hours; 1,260 ÷ 72 (1)\nAnswer: 17.5 km/h (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 4: a world map showing the tracks of tropical storms over ten years. Tracks start over the oceans between about 5° and 20° north and south of the Equator, curve away from the Equator and end over land or over cooler seas at around 30–40° latitude. There are many tracks in the Caribbean, the north-west Pacific and the Bay of Bengal. There are no tracks in the South Atlantic or along the Equator itself.\n\nDescribe the distribution of tropical storms shown in Fig. 4.`, marks: 2, command: 'Describe', markScheme: `One mark per valid point (max 2), e.g.:\n• form between about 5° and 20/30° north and south of the Equator (tropics) (1)\n• form over oceans / warm seas (1)\n• none on the Equator itself / none in the South Atlantic (1)\n• clusters named, e.g. Caribbean, north-west Pacific, Bay of Bengal (1)\n• tracks move away from the Equator / westwards then polewards (1)` },
      { q: `Section A — Global Hazards.\n\nTropical storms form over warm oceans in the tropics, but almost none form within 5° of the Equator, even though the sea there is warm.\n\nExplain one reason why tropical storms do not form within 5° of the Equator.`, marks: 2, command: 'Explain', markScheme: `Point (1) + development (1), e.g.:\n• the Coriolis effect is too weak close to the Equator (1) so the rising air cannot be made to spin / rotate into a storm (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 2: a diagram of the global atmospheric circulation model. In the Hadley cell, air rises at the Equator, flows towards the poles at high altitude and sinks at about 30° N and 30° S. Large hot deserts such as the Sahara and the Kalahari are found close to 30° N and 30° S.\n\nExplain why hot deserts are found at about 30° north and south of the Equator.`, marks: 2, command: 'Explain', markScheme: `Point (1) + development (1), e.g.:\n• air sinks at 30° creating high pressure (1) so air warms as it sinks and clouds cannot form / little rainfall (1).` },
      { q: `Section A — Global Hazards.\n\nIn September 2017 Hurricane Irma crossed the Caribbean as a Category 5 storm. After it moved over Florida, its wind speeds fell quickly.\n\nSuggest one reason why a tropical storm weakens when it moves over land.`, marks: 2, command: 'Suggest', markScheme: `Point (1) + development (1), e.g.:\n• it loses its supply of warm, moist air from the ocean (1) so there is less evaporation / condensation releasing energy (latent heat) to power the storm (1).\n• friction with the land surface (1) slows the winds (1).` },
      { q: `Section A — Global Hazards.\n\nDuring the 2015–16 El Niño, eastern Australia and Indonesia had much lower rainfall than average, while parts of Peru and Ecuador had heavy rain and floods.\n\nExplain one way that El Niño can cause drought in eastern Australia.`, marks: 2, command: 'Explain', markScheme: `Point (1) + development (1), e.g.:\n• the trade winds weaken / reverse so warm water moves east towards South America (1) so the western Pacific is cooler, less air rises / high pressure forms over Australia and less rain falls (1).` },
      { q: `Section A — Global Hazards.\n\nCASE STUDY — a tropical storm. Typhoon Haiyan (known locally as Yolanda) hit the central Philippines on 8 November 2013, with sustained winds of over 300 km/h and a storm surge of over 5 m in the city of Tacloban.\n\nExplain one primary impact of Typhoon Haiyan.`, marks: 2, command: 'Explain', markScheme: `Primary impact (1) + development/explanation (1), e.g.:\n• over 6,000 people died (1) mainly drowned by the storm surge that flooded low-lying Tacloban (1)\n• around 1 million homes were damaged or destroyed (1) by the strong winds, leaving about 4 million people displaced (1)\n• roads and the airport were destroyed / blocked (1) by the surge and debris (1).\nSecondary impacts (e.g. disease, food shortages, looting) = 0.` },
      { q: `Section A — Global Hazards.\n\nFig. 11: a comparison of two droughts. California, USA (an AC), had a severe drought from 2012 to 2016; there were no deaths linked to food shortages. Ethiopia (an LIDC) had a severe drought in 2015–16 and about 10 million people needed emergency food aid.\n\nExplain one reason why the impacts of drought are often greater in an LIDC than in an AC.`, marks: 2, command: 'Explain', markScheme: `Reason (1) + development (1), e.g.:\n• more people in LIDCs rely on rain-fed subsistence farming (1) so when rains fail crops and livestock die and people go hungry (1)\n• ACs have more money for reservoirs, irrigation and imports (1) so food and water supplies can be kept going (1)\n• LIDCs may rely on international aid which can be slow to arrive (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 12: an extract from a newspaper, July 2022. 'On 19 July the UK recorded a temperature above 40 °C for the first time, reaching 40.3 °C at Coningsby in Lincolnshire. The Met Office issued its first-ever red warning for extreme heat. Grass fires destroyed homes in Wennington, east London, and trains were cancelled or slowed because rails could buckle in the heat.'\n\nUsing Fig. 12, give two impacts of the July 2022 UK heatwave.`, marks: 2, command: 'Give', markScheme: `One mark each (max 2):\n• grass fires / wildfires (1)\n• homes destroyed (in Wennington) (1)\n• trains cancelled / slowed / transport disruption (1)\n• rails at risk of buckling (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 13: deaths caused by major tropical cyclones in Bangladesh: 1970 (Bhola) about 300,000; 1991 about 138,000; 2007 (Sidr) about 3,400. Since the 1970s Bangladesh has built thousands of raised concrete cyclone shelters and trained volunteers to spread warnings.\n\nUsing Fig. 13, explain one way that planning can reduce the number of deaths caused by tropical storms.`, marks: 2, command: 'Explain', markScheme: `Planning strategy (1) + how it reduces deaths (1), e.g.:\n• cyclone shelters (1) give people a safe, raised place above the storm surge (1)\n• warnings spread by volunteers / evacuation plans (1) give people time to move to safety before the storm arrives (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 1 (data written for this practice question): a student has drawn the mean monthly rainfall at a station in northern Australia as a line graph. The graph has no title and no units on the vertical axis.\n\nSuggest two ways the student could improve the presentation of the rainfall data.`, marks: 2, command: 'Suggest', markScheme: `One mark each (max 2):\n• draw rainfall as bars (bar chart) rather than a line, as rainfall is discrete monthly totals (1)\n• add a title / location (1)\n• add units (mm) to the vertical axis (1)\n• add temperature as a line to make a full climate graph (1)` },
      { q: `Section A — Global Hazards.\n\nOn 16 August 2004 around 200 mm of rain fell in a few hours over the steep-sided valleys above the village of Boscastle in Cornwall. A flash flood swept through the village, destroying buildings and washing cars into the harbour.\n\nExplain one reason why intense rainfall can cause flash flooding in a place like Boscastle.`, marks: 2, command: 'Explain', markScheme: `Reason (1) + development (1), e.g.:\n• the rain falls faster than it can infiltrate / ground already saturated (1) so water runs off quickly as surface runoff into the river (1)\n• steep valley sides (1) mean water reaches the river very quickly, so the river rises in a short time (1).` },
      { q: `Section A — Global Hazards.\n\nFig. 2: the global atmospheric circulation model. At the Equator the Sun's rays are most concentrated. Air rises here, forming a belt of low pressure. The Amazon and Congo basins, near the Equator, receive over 2,000 mm of rain a year.\n\nExplain how global atmospheric circulation causes high rainfall at the Equator.`, marks: 3, command: 'Explain', markScheme: `One mark per point in a linked explanation (max 3):\n• intense heating from the Sun warms the ground and air at the Equator (1)\n• warm air rises / low pressure (1)\n• rising air cools and water vapour condenses (1)\n• forming tall cumulonimbus clouds and heavy (convectional) rain (1)\n• trade winds converge (ITCZ) bringing moist air (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 14: during the 2010–11 La Niña, Queensland in eastern Australia had some of its worst floods on record, while Peru had drier conditions than usual.\n\nExplain how La Niña affects the weather in eastern Australia.`, marks: 3, command: 'Explain', markScheme: `One mark per point in a linked explanation (max 3):\n• trade winds become stronger than usual (1)\n• warm water is pushed further west / builds up in the western Pacific near Australia (1)\n• more evaporation and rising air / lower pressure over eastern Australia (1)\n• leading to more cloud and heavier rainfall / floods (1)\n• cold water upwells off Peru so it is drier there (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 15: an extract from a report on Hurricane Katrina. 'Katrina hit the coast of Louisiana on 29 August 2005. The storm surge broke through the levees protecting New Orleans and about 80% of the city flooded. Over 1,800 people died. Thousands sheltered in the Superdome for days with little food or clean water. Many residents never returned to the city.'\n\nUsing Fig. 15 and your own understanding, explain why the secondary impacts of Hurricane Katrina were severe.`, marks: 3, command: 'Explain', markScheme: `One mark per point in a linked explanation; max 2 if no use of Fig. 15:\n• levees failed so 80% of the city flooded for weeks (1)\n• much of New Orleans is below sea level so water could not drain away (1)\n• poorer residents without cars could not evacuate (1)\n• shortage of food and clean water in shelters such as the Superdome (1)\n• slow government response / aid slow to arrive (1)\n• people displaced long-term / many never returned (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 16: during the California drought of 2012–2016, a large area of high pressure stayed off the west coast of the USA for many months. Rain-bearing storms from the Pacific Ocean were pushed north, away from California.\n\nExplain how drought can develop in a place.`, marks: 3, command: 'Explain', markScheme: `One mark per point in a linked explanation (max 3):\n• a persistent area of high pressure (anticyclone) forms / blocks (1)\n• sinking air means few clouds form and little rain falls (1)\n• rain-bearing low-pressure systems are diverted away (1)\n• over months or years rainfall is well below average (1)\n• high temperatures increase evaporation so soils and reservoirs dry out (1)\n• El Niño / La Niña can shift rainfall patterns (1)\n• human use of water (over-abstraction) can make the shortage worse (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 17: the US National Hurricane Center publishes a forecast map for each hurricane. It shows a 'cone' of the most likely path over the next five days, and is updated every six hours using satellite images and data from aircraft that fly into the storm.\n\nExplain how predicting and monitoring tropical storms can reduce their impacts.`, marks: 3, command: 'Explain', markScheme: `One mark per point in a linked explanation (max 3):\n• satellites / aircraft track the storm's path and strength (1)\n• warnings can be issued days in advance (1)\n• people can evacuate along planned routes before it arrives (1)\n• property can be protected, e.g. boarding windows, moving boats (1)\n• emergency services and supplies can be put in place (1)\n• so fewer deaths and injuries (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 6: a scatter graph of the number of reported extreme weather events in the world each year, 1990–2020. The points rise from about 200 events in 1990 to about 400 events by 2020. There is a lot of variation from year to year: the highest point is 2007 with about 430 events, and several years after 2010 are below 350.\n\nDescribe the trend shown in Fig. 6.`, marks: 3, command: 'Describe', markScheme: `One mark per point (max 3):\n• overall increase / positive trend (1)\n• use of data, e.g. from about 200 in 1990 to about 400 in 2020 / roughly doubled (1)\n• fluctuation from year to year (1)\n• anomaly / peak named, e.g. about 430 in 2007 (1)\n• some years after 2010 are lower than 2007 (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 18: a photograph taken from space of a tropical storm in the Bay of Bengal, showing a central eye surrounded by a ring of tall cloud and spiralling bands of cloud.\n\nDraw an annotated cross-section through a tropical storm. Label the eye, the eye wall and the rain bands, and show the direction of air movement.`, marks: 4, command: 'Draw', diagram: true, markScheme: `One mark per correctly shown and labelled feature (max 4):\n• eye in the centre with sinking air / calm, clear (1)\n• eye wall either side of the eye with tall cumulonimbus clouds, rising air, strongest winds and heaviest rain (1)\n• rain bands / spiral bands of cloud further out (1)\n• arrows showing warm moist air drawn in at the surface and rising (1)\n• outflow of air at the top of the storm (1)\n• warm ocean surface (above 26–27 °C) shown at the base (1)` },
      { q: `Section A — Global Hazards.\n\nFig. 19: conditions recorded as a tropical storm formed over the western Atlantic Ocean, 15° N: sea surface temperature 28 °C; ocean water above 26 °C to a depth of 60 m; low wind shear; air pressure at the centre falling from 1,008 mb to 950 mb in 48 hours.\n\nUsing Fig. 19, explain how tropical storms form.`, marks: 4, command: 'Explain', markScheme: `One mark per point in a linked explanation; max 3 if no use of Fig. 19:\n• sea temperature of at least 26–27 °C (28 °C in Fig. 19) heats the air above (1)\n• warm, moist air rises rapidly, creating low pressure (falling to 950 mb) (1)\n• air cools and condenses, releasing latent heat which powers the storm (1)\n• more air is drawn in at the surface to replace the rising air (1)\n• the Coriolis effect at 15° N makes the air spin (1)\n• low wind shear lets the storm grow tall without being torn apart (1)\n• the deep layer of warm water (60 m) keeps supplying energy (1)` },
      { q: `Section A — Global Hazards.\n\nCASE STUDY — a tropical storm or drought.\n\nFor a named tropical storm or drought you have studied, explain the causes of the event.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough, well-developed explanation of the causes, with accurate and detailed case study knowledge (named place, dates, specific physical conditions).\nLevel 2 (3–4 marks): Clear explanation of some causes, with some case study detail.\nLevel 1 (1–2 marks): Basic, mostly descriptive points; little or no case study detail.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. Typhoon Haiyan, 2013):\n• formed over the western Pacific where sea temperatures were above 26–27 °C\n• warm moist air rose rapidly, condensed and released latent heat\n• low wind shear allowed it to intensify to winds over 300 km/h\n• Coriolis effect at about 6–10° N caused it to spin\n• tracked west across the Philippines with the trade winds; shallow seas and the funnel shape of Leyte Gulf increased the storm surge at Tacloban\nOr (e.g. California drought, 2012–16):\n• a persistent high-pressure ridge off the west coast blocked Pacific storms\n• several years of rainfall well below average; very low snowpack in the Sierra Nevada\n• record high temperatures increased evaporation\n• human over-abstraction of groundwater and river water for farming made the shortage worse` },
      { q: `Section A — Global Hazards.\n\nFig. 20: facts about Typhoon Haiyan, Philippines, November 2013. Over 6,000 deaths; about 4 million people displaced; about 1 million homes damaged or destroyed; coconut and rice crops destroyed across the Visayas islands; Tacloban airport destroyed; shortages of food and clean water for weeks; GDP per capita of the Philippines about US$2,800 (2013).\n\nUsing Fig. 20 and your own understanding, examine the impacts of a tropical storm on people in a contrasting place you have studied.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): Thorough examination of a range of social, economic and environmental impacts, with a clear consideration of which were most significant and why; good use of Fig. 20 and own case study knowledge.\nLevel 2 (3–4 marks): Clear but less balanced consideration of impacts with some use of Fig. 20 or case study detail.\nLevel 1 (1–2 marks): Basic list of impacts, mostly lifted from Fig. 20.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• primary impacts: deaths from the storm surge, homes destroyed, infrastructure (airport, roads, power lines) destroyed\n• secondary impacts: food and water shortages, disease risk, looting, loss of income for farmers and fishers\n• economic: coconut and rice farming livelihoods lost for years (coconut trees take years to regrow)\n• low GDP per capita meant many lived in weak housing and relied on international aid\n• short-term versus long-term impacts; most significant impact justified\n• comparison with an AC storm (e.g. Hurricane Katrina 2005) for contrast` },
      { q: `Section A — Global Hazards.\n\nFig. 21: a map of the Pacific Ocean during an El Niño year. Arrows show the trade winds weakening and warm surface water moving east from Indonesia towards Peru. Labels show: 'drought and forest fires' over Indonesia and eastern Australia; 'heavy rain and floods' over Peru and Ecuador; 'fewer Atlantic hurricanes' in the Caribbean.\n\nUsing Fig. 21, explain how El Niño affects weather in different parts of the world.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of the processes of El Niño and how they lead to contrasting weather in at least two named places; detailed use of Fig. 21.\nLevel 2 (3–4 marks): Clear explanation with some links between the change in ocean/winds and weather.\nLevel 1 (1–2 marks): Basic description of effects, mainly from Fig. 21, with little explanation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• normal year: trade winds push warm water west; low pressure and rain over Indonesia/Australia; cold upwelling off Peru\n• El Niño: trade winds weaken or reverse; warm water spreads east\n• rising air and low pressure move east, so heavy rain and flooding in Peru and Ecuador\n• high pressure and sinking air over Indonesia/Australia, so drought and forest fires\n• effects beyond the Pacific, e.g. fewer Atlantic hurricanes due to stronger wind shear; drought in parts of southern Africa\n• impacts on people, e.g. collapse of anchovy fishing off Peru, crop failure in Australia` },
      { q: `Section A — Global Hazards.\n\nFig. 13: deaths caused by major tropical cyclones in Bangladesh: 1970 (Bhola) about 300,000; 1991 about 138,000; 2007 (Sidr) about 3,400. Since the 1970s Bangladesh has built thousands of raised concrete cyclone shelters, planted mangrove forests along the coast and trained tens of thousands of volunteers to spread warnings by megaphone and radio.\n\nUsing Fig. 13, assess how effective planning and protection have been in reducing the impacts of tropical storms in Bangladesh.`, marks: 6, command: 'Assess', markScheme: `Level 3 (5–6 marks): Thorough assessment of several strategies using data from Fig. 13 accurately, with a clear and supported judgement on effectiveness, recognising limitations.\nLevel 2 (3–4 marks): Clear assessment of some strategies with some use of data; judgement may be implied.\nLevel 1 (1–2 marks): Basic description of strategies or data with no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• deaths fell from about 300,000 (1970) to about 3,400 (2007): a fall of about 99%\n• shelters protect people from the storm surge; warnings by volunteers reach rural areas without TV/internet\n• mangroves absorb wave energy and reduce surge\n• limitations: shelters may be overcrowded or far away; people are reluctant to leave livestock and property\n• economic losses and loss of homes and crops still high; deaths are only one measure\n• other factors: better forecasting, storms vary in strength and landfall location\n• judgement: highly effective at reducing deaths, less effective at reducing economic losses` },
      { q: `Section A — Global Hazards.\n\nCASE STUDY — a tropical storm in contrasting places. Hurricane Katrina hit Louisiana, USA, in August 2005 (over 1,800 deaths; damage about US$125 billion). Typhoon Haiyan hit the Philippines in November 2013 (over 6,000 deaths; damage about US$2–3 billion).\n\nExamine why the impacts of tropical storms differ between places at different levels of development.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): Thorough examination of a range of reasons, linked to development, with accurate use of both examples and recognition that both social and economic impacts differ.\nLevel 2 (3–4 marks): Clear reasons with some use of examples; may be unbalanced.\nLevel 1 (1–2 marks): Basic points; little use of examples.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• ACs have higher economic losses because buildings, infrastructure and property are worth more (US$125 bn vs about US$2–3 bn)\n• LIDCs/EDCs often have more deaths: weaker housing, less effective warnings, fewer resources to evacuate\n• ACs can afford forecasting, levees and insurance, but these can fail (New Orleans levees)\n• ability to respond: emergency services, aid, rebuilding funds\n• other factors: storm strength, storm surge height, population density, time of day, governance\n• inequality within an AC: poorer New Orleans residents without cars were most affected` },
      { q: `Section A — Global Hazards.\n\nFig. 22: a world map showing areas at high risk of drought and of tropical storms. High drought risk is shaded in the Sahel and the Horn of Africa, southern Africa, the Middle East, central Australia and the south-western USA. Tropical storm risk is shaded along coasts between about 5° and 30° north and south of the Equator.\n\nUsing Fig. 22 and your own understanding, explain how global atmospheric circulation influences the distribution of extreme weather.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation linking the circulation model (cells, pressure belts, winds) to the distribution of both droughts and tropical storms, with accurate use of Fig. 22.\nLevel 2 (3–4 marks): Clear explanation of links for one hazard or partial links for both.\nLevel 1 (1–2 marks): Basic description of distribution with little explanation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• sinking air in the Hadley cell at about 30° N and S gives high pressure, clear skies and little rain, so droughts are common in the subtropics (Sahel margins, Australia, south-west USA)\n• rising air and low pressure at the Equator / ITCZ give heavy rain; seasonal shifts of the ITCZ mean rain can fail at its edges (Sahel)\n• trade winds steer tropical storms westwards across oceans\n• warm oceans in the tropics and Coriolis effect beyond 5° allow storms to form\n• El Niño/La Niña can shift these patterns from year to year` },
      { q: `Section A — Global Hazards.\n\nCASE STUDY — a drought. During the California drought of 2012–2016, in April 2015 the state governor ordered towns and cities to cut water use by 25%. Farmers in the Central Valley pumped more groundwater, and some fields were left unplanted. Hosepipe use was restricted, and people were paid to replace lawns with drought-tolerant plants.\n\nAnalyse the effectiveness of the responses to a drought you have studied.`, marks: 6, command: 'Analyse', markScheme: `Level 3 (5–6 marks): Thorough analysis of a range of responses, weighing short- and long-term effectiveness, with accurate case study detail and a supported conclusion.\nLevel 2 (3–4 marks): Clear analysis of some responses with some case study detail; some comment on effectiveness.\nLevel 1 (1–2 marks): Basic description of responses with little comment on effectiveness.\n0 marks: No response worthy of credit.\n\nIndicative content (California):\n• urban water cut target largely met (about 24% saving by 2016), showing restrictions can work\n• lawn replacement and hosepipe bans reduce demand long-term\n• extra groundwater pumping kept farms going but caused aquifers to fall and the land to sink (subsidence): unsustainable\n• fallowing land reduced farm jobs and income\n• new desalination plant (Carlsbad, 2015) increases supply but is expensive and uses energy\n• drought ended with heavy rain in winter 2016–17, not because of responses\nAccept other drought case studies, e.g. Ethiopia 2015–16 (food aid, Productive Safety Net Programme, water trucking).` },
      { q: `Section A — Global Hazards.\n\nFig. 23: information about the Philippines. About 20 tropical storms enter the area around the Philippines each year. The country is made up of over 7,000 islands with a long, low-lying coastline. Around 60% of the population lives in coastal areas. Many homes in rural and informal settlements are built of wood and corrugated iron.\n\nUsing Fig. 23, explain why some places are more at risk from tropical storms than others.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of both physical and human factors increasing risk, with detailed and accurate use of Fig. 23 and own understanding.\nLevel 2 (3–4 marks): Clear explanation of some factors with some use of Fig. 23.\nLevel 1 (1–2 marks): Basic points lifted from Fig. 23 with little explanation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• physical: location in the tropics on the main typhoon track of the north-west Pacific; warm seas; about 20 storms a year so high frequency\n• long, low-lying coastline exposed to storm surges\n• human: high coastal population density means more people exposed\n• weak housing materials easily destroyed by wind\n• poverty limits money for defences, warnings and recovery\n• contrast with places at higher latitudes or inland, or with ACs that can afford protection` },
      { q: `Section A — Global Hazards.\n\nCASE STUDY — a tropical storm or drought in contrasting places.\n\n'The impacts of extreme weather depend more on a country's level of development than on the strength of the event.'\n\nTo what extent do you agree with this statement? Use examples you have studied. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): Thorough evaluation of both development and the physical strength of events, using detailed, accurate case studies from contrasting places; a clear, well-supported judgement on the extent of agreement.\nLevel 2 (3–5 marks): Clear discussion of both sides with some case study detail; judgement may be limited or not fully supported.\nLevel 1 (1–2 marks): Basic, one-sided points; little case study support; no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• agree: similar-strength storms kill far more in LIDCs/EDCs, e.g. Bhola cyclone 1970 (about 300,000 deaths) vs US storms; Haiyan over 6,000 deaths\n• ACs can afford forecasting, warnings, building codes, insurance and quick emergency responses\n• drought: Ethiopia 2015–16 food crisis vs California 2012–16 with no famine\n• disagree: very strong events overwhelm even ACs, e.g. Katrina levee failures and over 1,800 deaths\n• economic losses are greater in ACs\n• other factors: population density, storm surge height, governance, inequality within a country, preparation (Bangladesh reduced deaths despite low income)\n• judgement on how far development is the main factor\n\nSPaG:\nHigh performance (3 marks): spelling and punctuation consistently accurate; rules of grammar used with effective control of meaning; wide range of specialist terms used precisely.\nIntermediate performance (2 marks): spelling and punctuation considerable accuracy; general control of meaning; good range of specialist terms.\nThreshold performance (1 mark): reasonable accuracy; meaning not seriously obstructed; limited range of specialist terms.\n0 marks: no response, or response does not relate to the question, or errors severely hinder meaning.` },
      { q: `Section A — Global Hazards.\n\nFig. 24: ways of reducing the impacts of tropical storms. Prediction: satellites and hurricane-hunter aircraft track storms. Planning: evacuation routes, cyclone shelters, building codes and education programmes. Protection: sea walls, storm-surge barriers, raised houses and mangrove planting. Fig. 24 also notes that New Orleans' levees failed in 2005 and that Typhoon Haiyan's storm surge in 2013 was higher than many people expected.\n\nUsing Fig. 24 and your own understanding, evaluate how effectively people can reduce the impacts of tropical storms.`, marks: 8, command: 'Evaluate', markScheme: `Level 3 (6–8 marks): Thorough evaluation of prediction, planning and protection, with detailed located examples and use of Fig. 24; clear, supported judgement on how far impacts can be reduced.\nLevel 2 (3–5 marks): Clear evaluation of some strategies, with some examples; judgement may be partial.\nLevel 1 (1–2 marks): Basic description of strategies with little evaluation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• prediction gives days of warning, allowing evacuation; deaths in ACs are now usually low\n• planning: Bangladesh shelters and volunteers cut deaths from about 300,000 (1970) to about 3,400 (2007)\n• protection can fail or be exceeded: New Orleans levees 2005; Haiyan surge in Tacloban\n• warnings only work if understood: in 2013 many people did not understand the term 'storm surge'\n• cost: LIDCs may not afford protection, depend on aid\n• strategies reduce deaths more than economic damage; damage costs are rising\n• cannot prevent storms; climate change may increase intensity\n• judgement: impacts can be reduced a great deal but not removed` },
      { q: `Section A — Global Hazards.\n\nFig. 25 (data written for this practice question): number of Category 4 and 5 tropical storms per decade worldwide: 1980s 171; 1990s 220; 2000s 269; 2010s 284. A scientist quoted in Fig. 25 says: 'Warmer oceans give storms more energy, but we have better satellites than in the 1980s, so we also see more of them.'\n\nAssess the extent to which extreme weather events are becoming more intense and more frequent.`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): Thorough assessment of evidence for and against, using Fig. 25 data accurately and a range of extreme weather types; clear supported judgement on the extent.\nLevel 2 (3–5 marks): Clear assessment with some use of data; may focus on one type of event or one side.\nLevel 1 (1–2 marks): Basic description of the data or general points with no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• Fig. 25: intense storms rose from 171 to 284 per decade, an increase of about 66%\n• warmer oceans and atmosphere (climate change) give storms more energy and moisture; heavier rainfall\n• heatwaves more frequent, e.g. UK first 40 °C in July 2022; Europe 2003\n• droughts more severe in some regions, e.g. California 2012–16\n• limitations: better observation (satellites since the 1970s) means more events are recorded; short records; natural variability (El Niño/La Niña) affects individual years\n• the total number of tropical storms has not clearly increased; intensity changes clearer than frequency\n• judgement on how far the statement is supported` },
      { q: `Resource Booklet — reducing typhoon risk in the Philippines.\n\nFig. 26: the Philippines is an EDC; about 20 tropical storms enter its area each year. Typhoon Haiyan (2013) killed over 6,000 people, many in the coastal city of Tacloban, where the storm surge was over 5 m.\nFig. 27: three options for the Philippines government.\nOption 1 — Build a 27 km storm-surge sea wall and raised road along the coast near Tacloban (cost about US$150 million; protects the city centre but not rural villages).\nOption 2 — Expand early warning and evacuation: more weather radar, text-message warnings, community drills and new evacuation centres in every coastal district (moderate cost; relies on people acting on warnings).\nOption 3 — Create 'no-build zones' within 40 m of the shore, relocate coastal families inland and replant mangroves (low construction cost; families may lose fishing livelihoods).\n\nUsing Figs. 26 and 27, and your own understanding, choose which option you think is the best way to reduce the impacts of future typhoons in the Philippines. Justify your choice.`, marks: 12, command: 'Justify', markScheme: `Level 4 (10–12 marks): Comprehensive, well-reasoned justification of the chosen option, using the resources thoroughly and accurate own understanding of hazard management; evaluates the rejected options; considers social, economic and environmental factors and short- and long-term sustainability; well-supported conclusion.\nLevel 3 (7–9 marks): Clear justification with good use of resources; some evaluation of other options; conclusion supported.\nLevel 2 (4–6 marks): Some justification, mainly of the chosen option; some use of resources; limited evaluation.\nLevel 1 (1–3 marks): Basic choice with little justification; resources copied.\n0 marks: No response worthy of credit.\nNo option is 'correct'; credit any choice that is well justified.\n\nIndicative content:\n• Option 1: protects a dense urban population from surges like Haiyan's; expensive for an EDC; does not protect rural people; may be overtopped by bigger surges; can give false security\n• Option 2: saves lives widely across 7,000 islands; lower cost; Bangladesh evidence that warnings and shelters cut deaths; does not reduce damage to homes and crops; needs people to understand warnings (e.g. 'storm surge' misunderstood in 2013)\n• Option 3: removes people from the most dangerous zone; mangroves absorb wave energy and are sustainable; social conflict and loss of livelihoods; land inland needed\n• links to frequency (about 20 storms a year) and possible increasing intensity with climate change\n• combination of approaches may be suggested but one option must be chosen` },
      { q: `Resource Booklet — drought in the Horn of Africa.\n\nFig. 28: in 2011 the Horn of Africa (Somalia, Ethiopia and Kenya) had its worst drought for 60 years. Two rainy seasons failed in a row, linked to La Niña. About 13 million people needed food aid, and famine was declared in parts of southern Somalia, where around 260,000 people died between 2010 and 2012.\nFig. 29: other information. Many people in the region are pastoralists who rely on cattle and goats. The population of the region has grown rapidly. Conflict in southern Somalia made it difficult for aid agencies to reach people. Global food prices were high in 2011. Overgrazing and deforestation had reduced soil quality in some areas.\n\nUsing Figs. 28 and 29, and your own understanding, assess the extent to which the impacts of drought are caused by human factors rather than physical factors.`, marks: 12, command: 'Assess', markScheme: `Level 4 (10–12 marks): Comprehensive assessment of both physical and human factors, interlinked, with thorough and accurate use of Figs. 28 and 29 and own understanding of drought; reaches a well-supported, substantiated judgement on the extent.\nLevel 3 (7–9 marks): Clear assessment of both sets of factors with good use of resources; judgement supported.\nLevel 2 (4–6 marks): Some assessment, may be unbalanced or rely on the resources; judgement limited.\nLevel 1 (1–3 marks): Basic points copied from resources; no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• physical: two failed rainy seasons; La Niña shifting rainfall; high temperatures and evaporation; subtropical high pressure and the ITCZ failing to bring rain\n• human: dependence on rain-fed farming and herding; rapid population growth increasing demand; overgrazing and deforestation making land less able to hold water; conflict blocking aid in southern Somalia; high global food prices; poverty limiting ability to buy food or store water\n• famine was declared only in conflict areas, suggesting human factors turned a drought into a disaster\n• in ACs (e.g. California 2012–16) similar rainfall shortages did not cause deaths\n• the drought is the trigger (physical) but the scale of impact is shaped by vulnerability (human)\n• judgement on the extent` }
    ]
  },
  '1.2': {
    name: 'Global Hazards: Tectonic Hazards',
    questions: [
      { q: `Section A — Global Hazards.\nFig. 1 is a world map showing the location of active volcanoes and major earthquakes. The symbols form a narrow, almost continuous band around the edges of the Pacific Ocean, through the Andes, western North America, the Aleutian Islands, Japan, the Philippines, Indonesia and New Zealand.\n\nIdentify the name given to this zone of tectonic activity around the Pacific Ocean.`, marks: 1, command: 'Identify', markScheme: `Pacific Ring of Fire / Ring of Fire (1).` },
      { q: `Section A — Global Hazards.\nFig. 2 is a cross-section through the Earth. Layer C is labelled: "liquid iron and nickel, approximately 2,900 km to 5,150 km below the surface; it surrounds a solid centre."\n\nIdentify layer C.`, marks: 1, command: 'Identify', markScheme: `Outer core (1).\nDo not accept "core" on its own or "inner core".` },
      { q: `Section A — Global Hazards.\nThe table shows the depth of focus of seven earthquakes recorded along a destructive plate boundary in one year (data written for this practice question).\nDepth of focus (km): 12, 35, 70, 140, 210, 300, 520\n\nIdentify the median depth of focus.`, marks: 1, command: 'Identify', markScheme: `140 km (1).\nUnits not required.` },
      { q: `Section A — Global Hazards.\nA newspaper report states: "The earthquake that struck the region on Monday measured magnitude 7.0. A smaller earthquake in the same area last year measured magnitude 5.0." The magnitude scale is logarithmic: each whole number increase represents a tenfold increase in the size (amplitude) of the seismic waves recorded.\n\nCalculate how many times greater the amplitude of the seismic waves was in the magnitude 7.0 earthquake than in the magnitude 5.0 earthquake.`, marks: 1, command: 'Calculate', markScheme: `100 times (1).\n(10 × 10 = 100.)` },
      { q: `Section A — Global Hazards.\nFig. 3 is a photograph of the San Andreas Fault in California, USA. It shows a long straight line across dry farmland where two plates, the Pacific Plate and the North American Plate, slide past each other. Streams crossing the fault have been offset sideways. There are no volcanoes in the photograph.\n\nGive the type of plate boundary shown in Fig. 3.`, marks: 1, command: 'Give', markScheme: `Conservative (plate boundary/margin) (1).\nAccept transform / transform fault boundary.` },
      { q: `Section A — Global Hazards.\nSince 1995 scientists at the Montserrat Volcano Observatory have studied the Soufrière Hills volcano in the Caribbean. Their work includes measuring changes in the shape of the volcano and the gases it releases.\n\nGive one piece of equipment that could be used to monitor a volcano such as the Soufrière Hills.`, marks: 1, command: 'Give', markScheme: `One from (1):\n• seismometer/seismograph\n• tiltmeter\n• GPS receiver/satellite positioning\n• gas sensor/spectrometer (e.g. measuring sulfur dioxide)\n• thermal/infrared camera or satellite thermal imaging\n• laser/EDM distance measurement\n• drone/remote camera.\nAccept other valid monitoring equipment.` },
      { q: `Section A — Global Hazards.\nOn 11 March 2011 a magnitude 9.0 earthquake occurred about 70 km off the north-east coast of Honshu, Japan (the Tōhoku earthquake). Most of the roughly 18,000 people who died or went missing were killed in the hours after the earthquake rather than by the ground shaking itself.\n\nState one secondary effect of the 2011 Tōhoku earthquake.`, marks: 1, command: 'State', markScheme: `One from (1):\n• tsunami flooding coastal towns (e.g. waves over 10 m high)\n• meltdown/explosions at the Fukushima Daiichi nuclear power station / radiation leak\n• evacuation of people from the area around Fukushima\n• fires\n• shortages of electricity/power cuts\n• disruption to supply chains/factories closed\n• landslides.\nDo not credit primary effects such as buildings shaking/collapsing from the shaking.` },
      { q: `Section A — Global Hazards.\nThe table shows the depth of focus of seven earthquakes recorded along a destructive plate boundary in one year (data written for this practice question).\nDepth of focus (km): 12, 35, 70, 140, 210, 300, 520\n\nCalculate the mean depth of focus. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `12 + 35 + 70 + 140 + 210 + 300 + 520 = 1287; 1287 ÷ 7 (1)\n= 183.9 km (1).\nCorrect answer with no working = 1 mark only. Accept 183.86 for the working mark.` },
      { q: `Section A — Global Hazards.\nThe table shows the depth of focus of seven earthquakes recorded along a destructive plate boundary in one year (data written for this practice question).\nDepth of focus (km): 12, 35, 70, 140, 210, 300, 520\n\nCalculate the interquartile range of the depth of focus. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Lower quartile = 35 km and upper quartile = 300 km (1)\nInterquartile range = 300 − 35 = 265 km (1).\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Global Hazards.\nA country on the Pacific Ring of Fire expanded its earthquake monitoring network. In 2005 it had 40 seismometers; by 2020 it had 115 seismometers (data written for this practice question).\n\nCalculate the percentage increase in the number of seismometers between 2005 and 2020. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `(115 − 40) ÷ 40 × 100 or 75 ÷ 40 × 100 (1)\n= 187.5% (1).\nCorrect answer with no working = 1 mark only. Accept 188%.` },
      { q: `Section A — Global Hazards.\nFig. 4 is a world map of active volcanoes. Most volcanoes lie along plate boundaries: there is a dense line along the west coast of South and North America, a chain through Japan, the Philippines and Indonesia, and a line along the middle of the Atlantic Ocean through Iceland. A few volcanoes, such as those in Hawaii, lie in the middle of the Pacific Plate. There are almost none in Australia, northern Europe, Brazil or most of Africa except East Africa.\n\nDescribe the global distribution of volcanoes shown in Fig. 4.`, marks: 2, command: 'Describe', markScheme: `Two descriptive points, or one developed point (1 + 1):\n• mostly found along plate boundaries/margins (1)\n• concentrated around the edge of the Pacific Ocean / Ring of Fire, e.g. west coast of the Americas, Japan, Indonesia (1)\n• line down the middle of the Atlantic Ocean / Mid-Atlantic Ridge, e.g. Iceland (1)\n• a few found away from boundaries, e.g. Hawaii in the middle of the Pacific (1)\n• largely absent from the centre of continents, e.g. Australia, Brazil (1)\n• some in East Africa (1).\nUse of named locations from the figure can be credited. No credit for explanation.` },
      { q: `Section A — Global Hazards.\nOff the west coast of South America the Nazca Plate (oceanic crust) is moving towards the South American Plate (continental crust). The Andes mountains and volcanoes such as Cotopaxi lie along this boundary.\n\nExplain one reason why the Nazca Plate sinks beneath the South American Plate.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development:\n• oceanic crust is denser/heavier than continental crust (1) so when the plates collide the denser oceanic plate is forced down/subducted into the mantle (1).\n• oceanic crust is made of denser basaltic rock (1) while continental crust is lighter granitic rock that is too buoyant to sink (1).\nAccept reference to slab pull as development.` },
      { q: `Section A — Global Hazards.\nFig. 2 is a cross-section through the Earth. Arrows drawn in the mantle form circular loops: hot material rises beneath a mid-ocean ridge, moves sideways under the crust, then cools and sinks back down.\n\nExplain one way that the movement shown by the arrows in Fig. 2 causes tectonic plates to move.`, marks: 2, command: 'Explain', markScheme: `1 mark for the process, 1 mark for development:\n• heat from the core causes convection currents in the mantle (1); as the material moves sideways beneath the crust it drags the plates along with it (1).\n• rising magma at the ridge pushes the plates apart (ridge push) (1) as new crust is formed and the plates slide away from the ridge (1).\nAccept slab pull (sinking edge of a dense plate pulls the rest of the plate) if linked to the sinking limb of the current.` },
      { q: `Section A — Global Hazards.\nFig. 5 is a map of Japan. The epicentre of the 2011 Tōhoku earthquake is marked in the Pacific Ocean at about 38°N, 142°E, roughly 70 km east of the Oshika Peninsula on the island of Honshu and about 130 km east of the city of Sendai. Tokyo is about 370 km to the south-west of the epicentre.\n\nDescribe the location of the epicentre shown in Fig. 5.`, marks: 2, command: 'Describe', markScheme: `Two points (1 + 1):\n• in the Pacific Ocean / offshore (1)\n• off the (north-)east coast of Honshu/Japan (1)\n• about 70 km east of the Oshika Peninsula / about 130 km east of Sendai (1)\n• about 38°N, 142°E (1)\n• north-east of Tokyo (by about 370 km) (1).\nUse of distance, direction or coordinates needed for full marks.` },
      { q: `Section A — Global Hazards.\nOn 12 January 2010 a magnitude 7.0 earthquake struck about 25 km from Port-au-Prince, the capital of Haiti, an LIDC. Estimates of deaths range from about 220,000 to over 300,000. Many buildings in the city were made of concrete without steel reinforcement.\n\nExplain one reason why earthquakes in LIDCs such as Haiti often cause large numbers of deaths.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development:\n• poorly built buildings/no enforced building codes (1) so they collapse and crush people inside (1)\n• lack of money for emergency services/hospitals (1) so injured people are not treated quickly and die (1)\n• dense informal settlements/shanty towns (1) on unstable slopes so many people are affected at once (1)\n• poor infrastructure/damaged ports, airports and roads (1) delaying the arrival of rescue teams and aid (1)\n• no preparation/education or drills (1) so people do not know how to protect themselves (1).` },
      { q: `Section A — Global Hazards.\nFig. 6 is a photograph of an office block in Tokyo, Japan. A label shows that the building rests on large rubber and steel pads at its base. Another label points to diagonal steel beams on the outside of the building.\n\nSuggest how one of the features shown in Fig. 6 helps the building withstand an earthquake.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a feature, 1 mark for how it works:\n• rubber/steel pads / base isolators (1) absorb the shaking/allow the ground to move without moving the building as much (1)\n• diagonal steel beams / cross-bracing (1) hold the frame together/stop the building twisting or collapsing as it sways (1).\nAccept other credible earthquake-proof features only if described as in Fig. 6.` },
      { q: `Section A — Global Hazards.\nThe Soufrière Hills volcano on Montserrat began erupting in 1995. Scientists at the Montserrat Volcano Observatory recorded swarms of small earthquakes and swelling of the volcano before major eruptions. An exclusion zone was set up across the south of the island.\n\nExplain one way that monitoring a volcano can reduce the risk to people.`, marks: 2, command: 'Explain', markScheme: `1 mark for a way, 1 mark for development:\n• monitoring detects warning signs such as small earthquakes, ground swelling or gas release (1) so scientists can warn/evacuate people before an eruption (1)\n• monitoring shows which areas are most likely to be affected (1) so an exclusion zone can be set up and people kept out of danger (1)\n• it gives time to prepare emergency services/shelters (1) reducing deaths and injuries (1).` },
      { q: `Section A — Global Hazards.\nFig. 7 is a map of the continents as they are today. Fossils of Mesosaurus, a small freshwater reptile, are shown in eastern Brazil and in southern Africa. Matching coal seams and rock types of the same age are shown on both sides of the Atlantic Ocean, and the coastlines of South America and Africa appear to fit together like a jigsaw.\n\nGive two pieces of evidence shown in Fig. 7 that support the theory that the continents have moved.`, marks: 2, command: 'Give', markScheme: `Two from (1 + 1):\n• the same fossils (Mesosaurus) are found in both South America and Africa (1)\n• the coastlines of South America and Africa fit together like a jigsaw (1)\n• matching rock types/coal seams of the same age are found on both continents (1).\nDo not credit evidence not shown in the figure, e.g. palaeomagnetism.` },
      { q: `Section A — Global Hazards.\nOn 25 April 2015 a magnitude 7.8 earthquake struck the Gorkha district of Nepal, about 80 km north-west of Kathmandu. Nepal lies on the boundary where the Indian Plate is colliding with the Eurasian Plate. There are no active volcanoes in Nepal.\n\nExplain why there are no volcanoes at this plate boundary.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development:\n• it is a collision boundary between two continental plates (1) which are both of similar low density so neither is subducted (1)\n• because no crust is subducted, no crust melts to form magma (1) so there is no magma to rise to the surface (1)\n• instead the crust is pushed upwards/folded to form fold mountains (the Himalayas) (1).` },
      { q: `Section A — Global Hazards.\nFig. 8 is a scatter graph of eight earthquakes of magnitude 6.5–7.0. GDP per capita (US$) is on the x-axis and deaths per million people affected is on the y-axis. Countries with GDP per capita below US$2,000 have between 900 and 4,000 deaths per million; countries with GDP per capita above US$30,000 have between 5 and 60 deaths per million. One country with GDP per capita of about US$15,000 has 2,500 deaths per million (data written for this practice question).\n\nDescribe the relationship shown in Fig. 8.`, marks: 2, command: 'Describe', markScheme: `1 mark for the relationship, 1 mark for data use or the anomaly:\n• negative/inverse relationship: as GDP per capita increases, deaths per million decrease (1)\n• use of data, e.g. below US$2,000 there are 900–4,000 deaths per million compared with 5–60 above US$30,000 (1)\n• an anomaly at about US$15,000 with 2,500 deaths per million (1).\nNo credit for explanation.` },
      { q: `Section A — Global Hazards.\nAbout 25,000 people live on the slopes of Mount Etna in Sicily, Italy, one of the world's most active volcanoes. The lower slopes are covered with vineyards, orchards and olive groves.\n\nExplain one reason why people choose to live close to volcanoes such as Mount Etna.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development:\n• volcanic soils are very fertile/rich in minerals (1) so farmers can grow high-value crops such as grapes and olives (1)\n• tourism (1) provides jobs and income, e.g. guiding, hotels, cable car (1)\n• geothermal energy (1) can provide cheap heating/electricity (1)\n• they have lived there for generations/family ties (1) and eruptions are infrequent or mostly lava flows, so people feel the risk is low (1)\n• confidence in monitoring (1) so people believe they will be warned in time (1).` },
      { q: `Section A — Global Hazards.\nIn April 2010 the Eyjafjallajökull volcano in southern Iceland erupted. Its ash cloud drifted south-east across Europe and much of European airspace was closed for about six days, with around 100,000 flights cancelled.\n\nExplain one economic effect of the 2010 Eyjafjallajökull eruption on countries outside Iceland.`, marks: 2, command: 'Explain', markScheme: `1 mark for an effect, 1 mark for development:\n• airlines lost money/revenue (1) because flights were cancelled and planes were grounded for days (1)\n• businesses that rely on air freight lost money (1), e.g. flowers and fresh fruit from Kenya could not be flown to Europe and were wasted (1)\n• workers were stranded abroad (1) so they could not get to work, lowering productivity (1)\n• tourism businesses lost bookings (1) as holidaymakers could not travel (1).` },
      { q: `Section A — Global Hazards.\nAfter the earthquakes of 2010–2011 in Christchurch, New Zealand, the government created a "residential red zone" of about 8,000 properties where land had been badly damaged by liquefaction. Houses there were bought by the government and cleared, and the land was not rebuilt on.\n\nExplain one way that land-use planning can reduce the risk from earthquakes.`, marks: 2, command: 'Explain', markScheme: `1 mark for a way, 1 mark for development:\n• hazard maps identify the areas most at risk, e.g. land likely to suffer liquefaction (1) so homes are not built there / building is banned (1)\n• important buildings such as hospitals and fire stations are built in the safest areas (1) so they still work after an earthquake (1)\n• open spaces are left (1) so people have somewhere safe to gather away from collapsing buildings (1).` },
      { q: `Section A — Global Hazards.\nOn 26 December 2004 a magnitude 9.1 earthquake occurred under the Indian Ocean off the coast of Sumatra, Indonesia, where the Indo-Australian Plate is subducted beneath the Eurasian Plate. A tsunami reached coasts as far away as Thailand, Sri Lanka, India and Somalia.\n\nExplain how a tsunami is formed by an earthquake at a destructive plate boundary.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• pressure builds as the subducting plate sticks against the overlying plate (1)\n• when the pressure is released the overlying plate/seabed jerks upwards suddenly (1)\n• this displaces a huge volume of water above it (1)\n• the water spreads outwards as waves at high speed across the ocean (1)\n• as the waves reach shallow water near the coast they slow down and increase in height (1).\nMaximum 1 mark for a list of unlinked facts.` },
      { q: `Section A — Global Hazards.\nIceland lies on the Mid-Atlantic Ridge, where the North American Plate and the Eurasian Plate are moving apart. It has over 30 active volcanic systems, many with gently sloping sides formed by runny basalt lava.\n\nExplain how volcanoes form at constructive plate boundaries such as the one in Iceland.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• the two plates move apart (driven by convection currents/ridge push) (1)\n• this reduces pressure on the mantle below, so it melts to form magma (1)\n• magma rises to fill the gap through cracks/fissures (1)\n• it erupts as runny basaltic lava which flows a long way before cooling (1)\n• repeated eruptions build up gently sloping shield volcanoes (1).` },
      { q: `Section A — Global Hazards.\nThe table compares two earthquakes of the same magnitude (data written for this practice question).\nEarthquake A: magnitude 6.0, depth of focus 8 km, 45 buildings collapsed.\nEarthquake B: magnitude 6.0, depth of focus 300 km, no buildings collapsed.\n\nExplain why earthquake A caused more damage than earthquake B.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• earthquake A had a shallow focus/was much closer to the surface (1)\n• seismic waves from A had less distance to travel to reach the surface (1)\n• so they lost less energy before reaching the surface (1)\n• so the ground shaking at the surface was more intense/violent (1), causing buildings to collapse.\nCredit use of the data (8 km compared with 300 km).` },
      { q: `Section A — Global Hazards.\nJapan has an earthquake early warning system run by the Japan Meteorological Agency. Over 1,000 seismometers detect the first, faster seismic waves and send alerts to mobile phones, television and railways. In 2011 Tokyo received about one minute of warning before strong shaking arrived.\n\nExplain how technology such as Japan's early warning system can reduce the risk from earthquakes.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• seismometers detect the fast primary waves before the more damaging waves arrive (1)\n• computers instantly send warnings to phones/TV/radio (1)\n• people have seconds to a minute to take cover, e.g. get under tables, move away from windows (1)\n• high-speed trains brake automatically / factories and gas supplies shut down (1)\n• this reduces deaths, injuries and fires/secondary damage (1).` },
      { q: `Section A — Global Hazards.\nThe San Andreas Fault in California runs close to large cities such as San Francisco and Los Angeles. Along the fault the Pacific Plate and the North American Plate move past each other in the same general direction but at different speeds.\n\nExplain why earthquakes occur at conservative plate boundaries such as the San Andreas Fault.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• the plates slide past each other (in the same direction at different speeds, or opposite directions) (1)\n• friction causes the plates to stick/lock together (1)\n• stress/pressure builds up over time (1)\n• when the pressure is suddenly released the plates jerk past each other (1)\n• sending out seismic waves/shock waves which cause the ground to shake (1).` },
      { q: `Section A — Global Hazards.\nEyjafjallajökull in Iceland is a volcano on a constructive plate boundary, where eruptions are usually gentle. However, its 2010 eruption was explosive and produced a large ash cloud. The vent was beneath a glacier about 200 m thick.\n\nExplain why the 2010 eruption of Eyjafjallajökull produced so much ash.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for linked points:\n• hot magma met the ice of the glacier/meltwater (1)\n• the water cooled the magma very quickly (1)\n• this caused it to shatter/fragment into tiny particles of glass and rock (ash) (1)\n• water turned to steam, causing explosions that blasted ash high into the atmosphere (1)\n• the magma was more gas-rich/viscous than typical Icelandic basalt, adding to the explosive eruption (1).` },
      { q: `Section A — Global Hazards.\nThe table compares two earthquakes (figures are approximate).\nHaiti, January 2010 (LIDC): magnitude 7.0; depth of focus about 13 km; deaths about 220,000–316,000; about 1.5 million people made homeless; GDP per capita at the time under US$1,000.\nChristchurch, New Zealand, February 2011 (AC): magnitude 6.3; depth of focus about 5 km; 185 deaths; thousands of homes damaged by liquefaction; GDP per capita about US$33,000.\n\nCompare the effects of the two earthquakes. Use evidence from the table.`, marks: 4, command: 'Compare', markScheme: `Credit comparative points (up to 2 marks each: 1 for the point, 1 for data/development). Points must compare, not just describe each one.\n• Haiti had far more deaths than Christchurch (1): about 220,000+ compared with 185, over 1,000 times more (1).\n• Haiti had many more people made homeless (1): around 1.5 million compared with thousands of damaged homes in Christchurch (1).\n• Both earthquakes had shallow foci (13 km and 5 km) so both caused severe shaking and damage (1); Christchurch was even shallower yet had fewer deaths (1).\n• Haiti's earthquake was slightly stronger (7.0 compared with 6.3) (1) but the difference in effects is far greater than the difference in magnitude (1).\n• Effects were worse in the poorer country (1), with GDP per capita under US$1,000 compared with about US$33,000 (1).\nMax 2 if no data used.` },
      { q: `Section A — Global Hazards.\nThe Soufrière Hills volcano on the island of Montserrat, a British Overseas Territory in the Caribbean, began erupting in July 1995. In June 1997 pyroclastic flows killed 19 people, and the capital, Plymouth, was buried in ash and abandoned. About two-thirds of the population left the island.\n\nDescribe the responses to the eruption of the Soufrière Hills volcano.`, marks: 4, command: 'Describe', markScheme: `1 mark per descriptive point, up to 4; development of a point can earn a second mark:\n• the south of the island was evacuated and an exclusion zone was set up (1), covering about two-thirds of the island (1)\n• people were moved to temporary shelters/schools/churches in the north (1)\n• many residents were moved to the UK or neighbouring islands such as Antigua (1)\n• the UK government provided aid money (1) for emergency supplies and later new housing (1)\n• the Montserrat Volcano Observatory was set up to monitor the volcano (1) and produce hazard maps/alert levels (1)\n• long-term: new capital/town facilities, airport and port built in the north (1), e.g. at Little Bay/Brades (1).\nResponses must be credible for Montserrat.` },
      { q: `Section A — Global Hazards.\nOff the coast of Chile and Peru, the oceanic Nazca Plate is moving east towards the continental South American Plate at a destructive plate boundary. The Andes mountains and a line of volcanoes run along the coast.\n\nDraw an annotated diagram to show the processes that lead to earthquakes and volcanoes at this plate boundary.`, marks: 4, command: 'Draw', diagram: true, markScheme: `Up to 4 marks for accurate annotations (labels alone gain a maximum of 2):\n• oceanic plate and continental plate shown moving towards each other, labelled (1)\n• oceanic plate shown sinking/subducting beneath the continental plate because it is denser (1)\n• friction between the plates causes pressure to build, released as earthquakes (1)\n• subducted plate melts in the mantle to form magma (1)\n• magma rises through cracks to form explosive (composite) volcanoes on the continental plate (1)\n• ocean trench (e.g. Peru–Chile Trench) and fold mountains (Andes) shown (1).` },
      { q: `Section A — Global Hazards.\nCASE STUDY — A tectonic hazard in a lower income developing country (LIDC).\nName of LIDC: ______\n\nExamine why the effects of this tectonic hazard were so severe.`, marks: 6, command: 'Examine', markScheme: `Indicative content, e.g. Haiti 2010 or Nepal 2015:\n• Haiti: magnitude 7.0, shallow focus (about 13 km), epicentre only about 25 km from the capital Port-au-Prince; densely populated city; unreinforced concrete buildings and no enforced building codes; hospitals, port and airport damaged, delaying aid; about 220,000–316,000 deaths and 1.5 million homeless; cholera outbreak later in 2010 killed thousands; very low GDP per capita and weak government.\n• Nepal: magnitude 7.8 on 25 April 2015; about 9,000 deaths; mountainous terrain caused landslides and an avalanche on Everest; remote villages cut off; poorly built brick and stone homes; limited money for rescue.\nExamination should weigh physical factors (magnitude, depth, distance) against human factors (poverty, building quality, population density, preparedness) and reach a judgement.\n\nLevel 3 (5–6 marks): A thorough examination that is well supported by detailed, accurate case study evidence. Clear links between physical and human factors and the severity of effects; a supported judgement.\nLevel 2 (3–4 marks): A reasonable examination with some case study detail. Some links made between reasons and effects; judgement may be implied.\nLevel 1 (1–2 marks): A basic response. Generic reasons or a description of effects with little explanation of why they were severe.\n0 marks: No response or no response worthy of credit.\nA generic answer with no case study detail is limited to Level 1.` },
      { q: `Section A — Global Hazards.\nCASE STUDY — A tectonic hazard in an advanced country (AC).\nName of AC: ______\n\nExplain the causes of this tectonic hazard.`, marks: 6, command: 'Explain', markScheme: `Indicative content, e.g. Tōhoku, Japan 2011:\n• destructive plate boundary off north-east Honshu where the denser oceanic Pacific Plate is subducted beneath the plate carrying northern Japan (North American/Okhotsk Plate)\n• the plates locked; stress built up over many years; sudden release on 11 March 2011 caused a magnitude 9.0 megathrust earthquake about 70 km offshore at a shallow depth (about 30 km)\n• the sea floor was uplifted by several metres, displacing water and generating a tsunami that reached heights of over 30 m in places\n• human causes of the tsunami/nuclear disaster, e.g. sea walls too low, Fukushima Daiichi located on the coast.\nAlternatives: Christchurch 2011 (Pacific–Australian Plate boundary, shallow focus on a previously unknown fault, liquefaction of sediments); L'Aquila 2009; Eyjafjallajökull 2010 (constructive boundary, magma meeting glacier ice).\n\nLevel 3 (5–6 marks): A thorough explanation of the causes using accurate tectonic processes and detailed case study evidence. Physical processes are clearly sequenced and linked.\nLevel 2 (3–4 marks): A reasonable explanation with some case study detail; links between processes are partly developed.\nLevel 1 (1–2 marks): A basic explanation, mostly generic or descriptive, with little or no case study detail.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nCASE STUDY — A tectonic hazard in an advanced country (AC).\nName of AC: ______\n\nExplain the immediate and long-term responses to this tectonic hazard.`, marks: 6, command: 'Explain', markScheme: `Indicative content, e.g. Japan 2011:\n• immediate: early warning system gave seconds to a minute of warning; tsunami warnings issued within minutes; bullet trains stopped automatically; over 100,000 Self-Defence Force personnel deployed; evacuation centres for hundreds of thousands of people; 20 km evacuation zone around Fukushima Daiichi; international search-and-rescue teams.\n• long-term: rebuilding of towns, ports and railways; higher sea walls and relocation of some coastal communities to higher ground; review of nuclear power and safety rules; government reconstruction spending; improved tsunami hazard maps.\nAlternatives: Christchurch 2011 (search and rescue, red zone, rebuild of the city centre, new building codes), Eyjafjallajökull 2010.\nExplanation should show why responses were effective, e.g. wealth, organisation, preparedness.\n\nLevel 3 (5–6 marks): A thorough explanation of both immediate and long-term responses supported by detailed, accurate case study evidence.\nLevel 2 (3–4 marks): A reasonable explanation with some case study detail; may be unbalanced between immediate and long-term.\nLevel 1 (1–2 marks): A basic response, largely generic or a list of responses with little explanation.\n0 marks: No response or no response worthy of credit.\nAnswers covering only immediate or only long-term responses are limited to Level 2.` },
      { q: `Section A — Global Hazards.\nIn 1912 Alfred Wegener suggested that the continents were once joined together in a supercontinent called Pangaea. In the 1960s scientists discovered that rocks on the floor of the Atlantic Ocean form matching stripes of magnetic polarity on either side of the Mid-Atlantic Ridge, and that the rocks get older with distance from the ridge.\n\nExplain how evidence supports the theory of plate tectonics.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\n• jigsaw fit of the coastlines of South America and Africa suggests they were once joined\n• identical fossils (e.g. Mesosaurus, Glossopteris) found on continents now separated by oceans; these organisms could not have crossed the ocean\n• matching rock types, mountain chains and coal seams across continents\n• palaeomagnetic stripes: as new crust forms at the ridge, iron minerals line up with Earth's magnetic field; the field reverses over time, so symmetrical stripes on each side show the sea floor is spreading\n• rocks are youngest at the ridge and oldest near the continents, showing new crust is created at ridges and moves outwards\n• distribution of earthquakes and volcanoes in lines along plate boundaries\n• GPS measurements show plates moving a few centimetres per year.\n\nLevel 3 (5–6 marks): A thorough explanation of a range of evidence, clearly linking each piece of evidence to plate movement.\nLevel 2 (3–4 marks): A reasonable explanation of some evidence with some links to plate movement.\nLevel 1 (1–2 marks): A basic response that lists evidence with little or no explanation of how it supports the theory.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nThe table shows tectonic events at three types of plate boundary.\nConstructive — Iceland (Mid-Atlantic Ridge): frequent gentle fissure and shield eruptions; small, shallow earthquakes.\nDestructive — Japan and the Andes: explosive composite volcanoes; very large, shallow and deep earthquakes; tsunamis.\nConservative — San Andreas Fault, USA, and Haiti: no volcanoes; frequent shallow earthquakes, some very damaging.\n\nAnalyse how the type of plate boundary affects the tectonic hazards that occur.`, marks: 6, command: 'Analyse', markScheme: `Indicative content:\n• constructive: plates move apart, pressure falls, mantle melts; runny basalt lava with low gas content gives gentle eruptions; small shallow earthquakes as plates crack apart; generally lower hazard, though ice-covered volcanoes can be explosive (Eyjafjallajökull)\n• destructive: oceanic plate subducted, melts to form viscous, gas-rich magma; explosive composite volcanoes with pyroclastic flows and ash; locking of plates produces the largest earthquakes (e.g. magnitude 9.0 Japan 2011) and, underwater, tsunamis; earthquakes at a range of depths along the subducting plate\n• conservative: no crust created or destroyed so no magma and no volcanoes; friction builds pressure released as shallow earthquakes that can be very damaging near cities (Haiti 2010)\n• analysis: hazard level also depends on location and development, not just boundary type.\n\nLevel 3 (5–6 marks): A thorough analysis covering all three boundary types, clearly linking processes at each boundary to the type and severity of hazards, using examples from the table.\nLevel 2 (3–4 marks): A reasonable analysis of at least two boundary types with some links between processes and hazards.\nLevel 1 (1–2 marks): A basic response which mainly describes the hazards with little explanation of how boundary type affects them.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nAt Mount Etna, Italy, scientists use a network of seismometers, GPS stations, tiltmeters, gas sensors and satellite thermal images. In 1973, on the Icelandic island of Heimaey, lava flows were slowed by spraying them with millions of tonnes of seawater, which helped protect the harbour.\n\nExamine how technology can be used to reduce the risk from volcanic hazards.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\n• monitoring: seismometers detect earthquakes as magma rises; tiltmeters/GPS measure swelling of the volcano; gas sensors measure increases in sulfur dioxide; thermal imaging detects heating of the ground\n• prediction: data allow scientists to forecast eruptions and issue alert levels, giving time to evacuate (e.g. Montserrat Volcano Observatory, Mount Pinatubo 1991 where tens of thousands were evacuated)\n• protection: lava diversion with earth barriers or channels (Etna), cooling lava with water (Heimaey 1973), strengthened roofs to bear ash\n• planning: GIS hazard maps show areas at risk of lava, lahars and pyroclastic flows so land use and evacuation routes can be planned\n• examination of limits: technology is expensive for LIDCs; exact timing and size of eruptions still hard to predict; protection cannot stop pyroclastic flows; people may ignore warnings.\n\nLevel 3 (5–6 marks): A thorough examination of a range of technologies, supported by examples, with clear consideration of how far they reduce risk and their limitations.\nLevel 2 (3–4 marks): A reasonable examination with some examples; limited consideration of effectiveness.\nLevel 1 (1–2 marks): A basic response listing technologies with little explanation of how they reduce risk.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nMount Vesuvius, near the city of Naples in Italy, last erupted in 1944. In 79 CE an eruption destroyed the Roman towns of Pompeii and Herculaneum. Today more than half a million people live in the "red zone" around the volcano that would need to be evacuated before an eruption.\n\nExplain why people continue to live in areas at risk from tectonic hazards.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\n• economic: fertile volcanic soils for farming; tourism; geothermal energy; minerals; jobs and services in cities like Naples, Tokyo or San Francisco\n• social: family ties, home ownership, community and culture; cannot afford to move; LIDC residents may have no choice\n• perception: eruptions or large earthquakes are infrequent; people may not see the risk as serious, or trust monitoring and warning systems; in ACs building codes and preparation make people feel safe\n• lack of knowledge of the hazard, or other risks (poverty, unemployment) seen as more pressing.\nCredit use of examples, e.g. Vesuvius, Etna, Iceland, Japan, California.\n\nLevel 3 (5–6 marks): A thorough explanation of a range of reasons, supported by relevant examples, showing clear understanding of how benefits and perceptions outweigh risk.\nLevel 2 (3–4 marks): A reasonable explanation of some reasons with some use of examples.\nLevel 1 (1–2 marks): A basic response listing reasons with little explanation or exemplification.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nFig. 9 is a newspaper headline and extract from 2015: "Nepal quake: aid arrives slowly in remote mountain villages." The extract states that the magnitude 7.8 earthquake killed about 9,000 people, destroyed hundreds of thousands of homes, and that landslides blocked many mountain roads. International teams arrived at Kathmandu's single international airport, which quickly became congested.\n\nExamine the factors that affected the response to the 2015 Nepal earthquake.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\n• physical factors: mountainous relief and landslides blocked roads, making remote villages hard to reach; monsoon season approaching; aftershocks (including a magnitude 7.3 aftershock in May 2015) caused further damage and fear\n• economic factors: Nepal is an LIDC with limited money for emergency services, heavy machinery and helicopters\n• infrastructure: a single international airport with limited capacity caused bottlenecks; poor road network\n• political/organisational factors: delays in distributing aid; dependence on international organisations (e.g. Red Cross, UN, UK and Indian help)\n• examination should weigh which factors were most significant and how they interacted.\n\nLevel 3 (5–6 marks): A thorough examination of a range of factors, well supported by detail from Fig. 9 and own knowledge, with a judgement on the most important factors.\nLevel 2 (3–4 marks): A reasonable examination of some factors with some use of evidence.\nLevel 1 (1–2 marks): A basic response, mostly descriptive or generic, with limited use of the extract.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nUsing case studies of tectonic hazards in two countries at different levels of development, assess the extent to which level of development determines the effects of a tectonic hazard. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Indicative content, e.g. Haiti 2010 (LIDC) and Japan 2011 (AC), or Nepal 2015 and Christchurch 2011:\n• evidence that development matters: Haiti (magnitude 7.0) had about 220,000–316,000 deaths whereas Christchurch (magnitude 6.3) had 185; ACs have building codes, earthquake-resistant design, emergency services, warning systems and drills; LIDCs have poor housing, dense informal settlements, weak governance, little money for rescue or rebuilding\n• economic effects can be higher in ACs in absolute terms: Japan 2011 cost about US$235 billion (World Bank estimate) because of expensive infrastructure, but a smaller share of GDP than in Haiti or Nepal\n• other factors: magnitude, depth of focus, distance from population centres, secondary hazards (Japan tsunami killed most victims despite preparation; Fukushima nuclear accident), time of day, physical geography (Nepal landslides)\n• judgement: development strongly influences death toll and recovery, but a very large event can overwhelm even a well-prepared AC.\n\nLevel 3 (6–8 marks): A thorough assessment, well supported by detailed and accurate evidence from two contrasting case studies. Considers development alongside other factors and reaches a clear, substantiated judgement.\nLevel 2 (3–5 marks): A reasonable assessment with some case study evidence; may be unbalanced or have a partial judgement.\nLevel 1 (1–2 marks): A basic response with limited or generic evidence and little or no assessment.\n0 marks: No response or no response worthy of credit.\nOnly one case study: maximum Level 2.\n\nSPaG:\nHigh performance (3 marks): Learners spell and punctuate with consistent accuracy; use rules of grammar with effective control of meaning overall; use a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): Learners spell and punctuate with considerable accuracy; use rules of grammar with general control of meaning overall; use a good range of specialist terms as appropriate.\nThreshold performance (1 mark): Learners spell and punctuate with reasonable accuracy; use rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; use a limited range of specialist terms as appropriate.\nNo marks awarded (0 marks): Learners write nothing; or the response does not relate to the question; or errors in spelling, punctuation and grammar severely hinder meaning.` },
      { q: `Section A — Global Hazards.\nCASE STUDY — A tectonic hazard in a lower income developing country (LIDC).\nName of LIDC: ______\n\nEvaluate the effectiveness of the responses to this tectonic hazard.`, marks: 8, command: 'Evaluate', markScheme: `Indicative content, e.g. Haiti 2010:\n• immediate responses: search and rescue by local people and international teams; US military took control of the damaged airport; field hospitals, water purification and food aid from the UN, Red Cross and NGOs; tent camps for over a million people\n• limitations: damaged port, airport and roads delayed aid; government buildings destroyed and many officials killed; poor coordination; cholera outbreak from October 2010 linked to UN peacekeepers killed thousands\n• long-term: billions of US dollars pledged but slow to arrive; many people still in camps years later; some rebuilding with improved standards\n• Nepal 2015 alternative: Indian and Chinese helicopters, UK aid, villages rebuilt slowly; reconstruction authority set up months later; landslides hindered access.\n• evaluation should weigh successes against failures and consider reasons (poverty, governance, physical geography).\n\nLevel 3 (6–8 marks): A thorough evaluation, well supported by detailed and accurate case study evidence, weighing successes and limitations of both short- and long-term responses and reaching a substantiated judgement.\nLevel 2 (3–5 marks): A reasonable evaluation with some case study evidence; may be unbalanced or have a limited judgement.\nLevel 1 (1–2 marks): A basic response, mostly descriptive of responses with little evaluation.\n0 marks: No response or no response worthy of credit.\nGeneric answers with no case study detail: maximum Level 1.` },
      { q: `Section A — Global Hazards.\nA government report states: "We cannot yet predict exactly when an earthquake will strike. The best way to save lives is to make sure buildings do not fall down and people know what to do."\n\nAssess the extent to which prediction is the most effective way to reduce the risk from tectonic hazards.`, marks: 8, command: 'Assess', markScheme: `Indicative content:\n• prediction of volcanoes is often successful because of warning signs (earthquakes, swelling, gas emissions), e.g. Mount Pinatubo 1991 and Montserrat; evacuations save many lives\n• earthquakes cannot be predicted precisely; only long-term probability (e.g. hazard maps, fault studies) and short warnings (Japan's early warning system, seconds to about a minute)\n• protection: earthquake-resistant buildings (base isolators, cross-bracing, counterweights, retrofitting), sea walls, lava diversion; effective in ACs but expensive for LIDCs\n• planning: land-use zoning, hazard maps, evacuation routes, drills (e.g. Japan's Disaster Prevention Day on 1 September), emergency kits; cheaper and suited to LIDCs\n• judgement: effectiveness depends on hazard type (prediction more useful for volcanoes), on wealth, and on combining strategies; the report's view is strongest for earthquakes.\n\nLevel 3 (6–8 marks): A thorough assessment comparing prediction with protection and planning, supported by accurate examples, reaching a clear, substantiated judgement.\nLevel 2 (3–5 marks): A reasonable assessment with some examples; may focus mainly on one strategy or give a partial judgement.\nLevel 1 (1–2 marks): A basic response describing ways to reduce risk with little assessment.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Global Hazards.\nJapan has some of the strictest building codes in the world, revised after the 1995 Kobe earthquake. In 2011 relatively few buildings collapsed from the shaking of the magnitude 9.0 Tōhoku earthquake, but the tsunami that followed overtopped sea walls up to 10 m high in some towns.\n\nEvaluate how effective protection has been in reducing the risk from tectonic hazards in an advanced country (AC).`, marks: 8, command: 'Evaluate', markScheme: `Indicative content:\n• effective: building codes, base isolation, cross-bracing, shock absorbers and retrofitting meant most buildings survived intense shaking in 2011; far fewer deaths from collapse than in Haiti 2010; automatic shut-off of gas and trains reduced secondary hazards\n• less effective: sea walls were too low for the tsunami (waves reached over 30 m in places); most of the roughly 18,000 deaths or missing were caused by the tsunami; Fukushima Daiichi nuclear plant was flooded; older or wooden buildings still vulnerable; liquefaction in Christchurch 2011 damaged buildings on soft ground\n• protection works best when combined with prediction (early warning) and planning (evacuation drills, tsunami evacuation towers, hazard maps)\n• cost: protection is expensive but affordable in ACs; it reduces but cannot remove risk; complacency may result.\nOther ACs can be used, e.g. New Zealand, USA, Iceland.\n\nLevel 3 (6–8 marks): A thorough evaluation of protection, supported by accurate, detailed evidence from an AC, weighing successes against limitations and reaching a substantiated judgement.\nLevel 2 (3–5 marks): A reasonable evaluation with some evidence; may be one-sided or have a partial judgement.\nLevel 1 (1–2 marks): A basic response describing protection methods with little evaluation.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource — Volcán Sierra, a volcano in an emerging developing country (EDC) (place and data written for this practice question).\nFig. 10: Volcán Sierra is a composite volcano on a destructive plate boundary. It last erupted 60 years ago. The city of Vista, population 400,000, lies 15 km from the summit; many homes in its fast-growing informal settlements are built along river valleys where lahars (volcanic mudflows) could travel. In the past year scientists have recorded an increase in small earthquakes beneath the volcano.\nFig. 11: The city council has US$20 million and is considering three options.\nOption 1 — Monitoring and warning: install seismometers, GPS stations and gas sensors on the volcano and a siren and mobile-phone warning system for the city (US$12 million).\nOption 2 — Protection: build concrete barriers and channels to divert lahars away from the city and strengthen school and hospital roofs to carry ash (US$18 million).\nOption 3 — Planning and education: produce hazard maps, ban new building in valleys at risk, mark evacuation routes and run evacuation drills in schools and communities every year (US$6 million).\n\nChoose which option you think is the best way to reduce the risk from Volcán Sierra for the people of Vista. Justify your decision. Using Figs. 10 and 11 and your own understanding, explain why you rejected the other options.`, marks: 12, command: 'Justify', markScheme: `No single correct answer; credit any option justified with evidence from the resources and own understanding.\nIndicative content:\n• Option 1: increase in small earthquakes suggests magma rising, so monitoring could detect warning signs and allow evacuation (as at Pinatubo 1991 or Montserrat); affordable within budget, leaving US$8 million; but needs trained staff, maintenance and trust in warnings; does not protect property.\n• Option 2: protects buildings and key services; lahars travel along valleys where informal settlements lie; but uses 90% of the budget, cannot stop pyroclastic flows, barriers may fail or encourage more building in risky areas; no warning.\n• Option 3: cheapest; hazard maps and land-use rules reduce exposure; drills help people respond; can be combined with part of Option 1 within budget; but bans are hard to enforce in fast-growing informal settlements and planning without warnings may not give time to evacuate.\n• Strong answers consider timescale (activity increasing now), sustainability, costs, who benefits, and may suggest combinations within the US$20 million.\n\nLevel 4 (10–12 marks): A thorough and well-justified decision, using detailed and accurate evidence from Figs. 10 and 11 and own understanding. Clear, reasoned rejection of both other options. Substantiated conclusion.\nLevel 3 (7–9 marks): A clear decision with sound justification using some resource evidence and own understanding. Rejection of the other options is reasonable but may be uneven.\nLevel 2 (4–6 marks): A decision with some justification; limited use of resources; rejection of other options is partial or superficial.\nLevel 1 (1–3 marks): A basic response; decision stated with little justification; little use of the resources.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource — Tectonic hazards and development.\nFig. 12 (table, figures approximate):\nHaiti earthquake, 2010 (LIDC): magnitude 7.0; about 220,000–316,000 deaths; aid pledged by other countries in billions of US dollars, but many people still lived in camps several years later.\nNepal earthquake, 2015 (LIDC): magnitude 7.8; about 9,000 deaths; government estimate of about US$7 billion of damage and losses; many school buildings strengthened before 2015 had survived.\nJapan earthquake and tsunami, 2011 (AC): magnitude 9.0; about 18,000 dead or missing; damage estimated at about US$235 billion.\nFig. 13 (quotes): A charity worker in Kathmandu: "Simple, cheap measures like teaching people to 'drop, cover and hold on' and training local masons to build safer homes saved lives." An economist: "Countries that cannot afford monitoring networks and earthquake-proof buildings will always suffer the most."\n\n'Lower income developing countries (LIDCs) cannot effectively reduce the risk from tectonic hazards.' Using Figs. 12 and 13 and your own understanding, evaluate this statement.`, marks: 12, command: 'Evaluate', markScheme: `Indicative content:\n• agree: high death tolls in Haiti and Nepal compared with the size of the events; lack of money for monitoring networks, enforced building codes, retrofitting and emergency services; dependence on international aid that is slow and poorly coordinated; rapid urbanisation and informal settlements increase exposure; damage as a share of GDP is very high (US$7 billion is a large share of Nepal's economy, while Japan's US$235 billion is a much smaller share of its economy)\n• disagree: low-cost strategies can work: education and drills, community training of builders, hazard mapping, strengthening schools (Nepal school-safety programmes), local disaster committees, mobile-phone warnings; international partnerships and NGOs provide technology and expertise\n• comparison: even an AC such as Japan suffered heavy losses in 2011, so risk cannot be removed anywhere; ACs reduce deaths more effectively but suffer higher absolute economic losses\n• judgement: LIDCs can reduce risk to some extent through planning and education, though less effectively than ACs without investment and good governance.\n\nLevel 4 (10–12 marks): A thorough evaluation using detailed and accurate evidence from Figs. 12 and 13 and own understanding; considers both sides with well-developed arguments and reaches a substantiated, balanced conclusion.\nLevel 3 (7–9 marks): A clear evaluation using resource evidence and own understanding; both sides considered though not equally developed; reasoned conclusion.\nLevel 2 (4–6 marks): Some evaluation; limited use of resources or mostly one-sided; conclusion simple or implied.\nLevel 1 (1–3 marks): A basic response with limited understanding; descriptive use of the resources and little or no evaluation.\n0 marks: No response or no response worthy of credit.` }
    ]
  },
  '1.3': {
    name: 'Changing Climate',
    questions: [
      { q: `Section A — Changing Climate.\nFig. 1 is a table of data from an Antarctic ice core (data written for this practice question, based on the pattern in real ice-core records):\nYears before present | CO₂ (ppm) | Temperature compared with today (°C)\n400 000 | 285 | +1.5\n340 000 | 195 | −7.5\n240 000 | 270 | +0.5\n140 000 | 190 | −8.0\n20 000 | 185 | −8.5\n\nIdentify the time in Fig. 1 when the temperature was lowest.`, marks: 1, command: 'Identify', markScheme: `20 000 years before present (1).\nAccept the last glacial maximum / about 20 000 years ago.` },
      { q: `Section A — Changing Climate.\nFig. 2 shows the annual mean concentration of carbon dioxide measured at Mauna Loa Observatory, Hawaii (values rounded):\nYear | CO₂ (ppm)\n1960 | 317\n1980 | 339\n2000 | 370\n2020 | 414\n\nState the concentration of carbon dioxide at Mauna Loa in 2000.`, marks: 1, command: 'State', markScheme: `370 ppm (1).\nUnits not required.` },
      { q: `Section A — Changing Climate.\nScientists studying climate change during the Quaternary period (the last 2.6 million years) use several sources of evidence. One of these is ice cores drilled from Antarctica and Greenland.\n\nGive one other source of evidence for climate change during the Quaternary period.`, marks: 1, command: 'Give', markScheme: `1 mark for one valid source, e.g.:\n• tree rings (dendrochronology)\n• pollen preserved in peat bogs or lake sediments\n• ocean / sea-floor sediment cores (fossil shells / foraminifera)\n• glacial landforms and deposits left by former ice sheets, e.g. moraines and erratics in the UK\n• fossils of animals or plants found outside their present range.\nDo not accept ice cores.` },
      { q: `Section A — Changing Climate.\nFig. 3 is a pie chart showing the UK's greenhouse gas emissions by gas, 2021 (percentages rounded): carbon dioxide 79%; methane 13%; nitrous oxide 5%; fluorinated gases 3%.\n\nIdentify the gas that makes up the second largest share of UK greenhouse gas emissions.`, marks: 1, command: 'Identify', markScheme: `Methane / CH₄ (1).` },
      { q: `Section A — Changing Climate.\nFig. 4 is an isoline map of an island in the Maldives, Indian Ocean. Isolines are drawn at 0.5 m intervals. The coastline is at 0 m. The highest isoline, in the centre of the island, is 2.0 m. Point P is on the western coast; point Q is on the 1.5 m isoline.\n\nCalculate the difference in height between point P and point Q.`, marks: 1, command: 'Calculate', markScheme: `1.5 m (1).\nUnits required.` },
      { q: `Section A — Changing Climate.\nFig. 5 is a line graph of global mean surface temperature compared with the 1850–1900 average, 1850–2020. The line stays between −0.3 °C and +0.2 °C until about 1930, rises slightly to about +0.3 °C by 1945, stays roughly level until about 1975, and then rises steeply to about +1.2 °C by 2020. The highest point on the graph is 2016.\n\nIdentify the year with the highest temperature shown on Fig. 5.`, marks: 1, command: 'Identify', markScheme: `2016 (1).` },
      { q: `Section A — Changing Climate.\nFig. 2 shows the annual mean concentration of carbon dioxide measured at Mauna Loa Observatory, Hawaii (values rounded): 1959 — 316 ppm; 2023 — 421 ppm.\n\nCalculate the percentage increase in carbon dioxide concentration between 1959 and 2023. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for correct working: (421 − 316) ÷ 316 × 100 or 105 ÷ 316 × 100.\n1 mark for the answer: 33.2% (accept 33.2 without %).\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Changing Climate.\nFig. 6 shows the global mean temperature anomaly (°C, compared with the 1850–1900 average) for six years (data written for this practice question):\n2015 — 1.08; 2016 — 1.20; 2017 — 1.14; 2018 — 1.03; 2019 — 1.17; 2020 — 1.18.\n\nCalculate the mean temperature anomaly for 2015–2020. Give your answer to two decimal places. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (1.08 + 1.20 + 1.14 + 1.03 + 1.17 + 1.18) ÷ 6 or 6.80 ÷ 6.\n1 mark for the answer: 1.13 °C.\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Changing Climate.\nA glacier in the European Alps has been measured since 1950 (data written for this practice question). In 1950 its snout was 0 km from a fixed marker; by 2020 the snout had retreated 1.8 km up the valley from the marker.\n\nCalculate the mean rate of retreat of the glacier in metres per year between 1950 and 2020. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 1800 m ÷ 70 years (converting km to m and finding the number of years).\n1 mark for the answer: 25.7 m per year.\nCorrect answer with no working = 1 mark only. Accept 0.026 km per year for 1 mark only (wrong units asked).` },
      { q: `Section A — Changing Climate.\nFig. 5 is a line graph of global mean surface temperature compared with the 1850–1900 average, 1850–2020. The line stays between −0.3 °C and +0.2 °C until about 1930, rises slightly to about +0.3 °C by 1945, stays roughly level until about 1975, and then rises steeply to about +1.2 °C by 2020.\n\nDescribe the trend shown in Fig. 5.`, marks: 2, command: 'Describe', markScheme: `1 mark for the overall trend: temperature has increased / overall rising trend.\n1 mark for detail using data or a change in rate, e.g.:\n• rise of about 1.2–1.5 °C over the period\n• little change until about 1930, then the rise speeds up after about 1975\n• from about +0.3 °C in 1975 to about +1.2 °C in 2020.\nMax 1 if no data or no reference to the change in rate.` },
      { q: `Section A — Changing Climate.\nSome bristlecone pine trees in California are more than 4000 years old. Scientists take thin cores from the trunks to study the rings.\n\nExplain one way that tree rings can provide evidence of past climate.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Each ring represents one year of growth (1) so the rings can be dated by counting back from the present (1).\n• Wide rings show years of good growing conditions (1), such as warm and wet years, while narrow rings show cold or dry years (1).` },
      { q: `Section A — Changing Climate.\nIn June 1991 Mount Pinatubo in the Philippines erupted, releasing about 15 million tonnes of sulphur dioxide into the stratosphere. Average global temperatures fell by about 0.5 °C over the following year.\n\nExplain how volcanic eruptions such as Mount Pinatubo can cause climate change.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Sulphur dioxide / ash forms aerosols in the stratosphere (1) which reflect incoming solar radiation back into space, cooling the Earth's surface (1).\n• The cooling is short-term (1) because the aerosols fall out of the atmosphere within one to three years (1).` },
      { q: `Section A — Changing Climate.\nBetween about 1645 and 1715, astronomers recorded very few sunspots. This period, called the Maunder Minimum, came during the 'Little Ice Age', when the River Thames in London sometimes froze over in winter.\n\nExplain how changes in solar output can cause climate change.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Fewer sunspots means the Sun gives out slightly less energy (1) so less solar radiation reaches the Earth and temperatures fall, e.g. the Little Ice Age (1).\n• Solar output varies in cycles of about 11 years (1); periods of high activity bring slightly more energy and warming (1).` },
      { q: `Section A — Changing Climate.\nLarge areas of the Amazon rainforest in Brazil have been cleared for cattle ranching and soya farming. Much of the forest is cleared by burning.\n\nExplain one way that deforestation increases the amount of greenhouse gases in the atmosphere.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Burning trees releases the carbon stored in them (1) as carbon dioxide into the atmosphere (1).\n• Fewer trees means less photosynthesis (1) so less carbon dioxide is removed from the atmosphere / the forest is no longer a carbon sink (1).\nAlso credit: cattle that replace forest release methane (1) as they digest food (1).` },
      { q: `Section A — Changing Climate.\nWorld meat consumption and rice production have both increased greatly since 1960, as the global population has grown from about 3 billion to over 8 billion.\n\nExplain one way that farming increases the amount of methane in the atmosphere.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Cattle and sheep produce methane during digestion (1) and the number of livestock has increased with demand for meat (1).\n• Flooded rice paddies have waterlogged soils with little oxygen (1) where bacteria break down organic matter and release methane (1).` },
      { q: `Section A — Changing Climate.\nA world map shows temperature change per decade, 1990–2020. The Arctic is shaded +0.6 to +0.8 °C per decade. The UK is shaded +0.2 to +0.3 °C per decade.\n\nSuggest one reason why the Arctic has warmed faster than the UK.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a valid reason; 1 mark for development. E.g.:\n• Melting sea ice and snow exposes darker ocean and land (1) which absorbs more of the Sun's energy instead of reflecting it, causing further warming / lower albedo (1).\n• Thawing permafrost releases methane and carbon dioxide (1) which adds to warming locally (1).` },
      { q: `Section A — Changing Climate.\nThe number of commercial vineyards in England and Wales grew from about 400 in 2010 to over 900 in 2023, mainly in south-east England.\n\nExplain one positive effect of climate change on people in the UK.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid effect; 1 mark for development. E.g.:\n• Warmer summers allow new crops such as grapes to be grown in southern England (1), creating jobs and income for farmers and wine producers (1).\n• Milder winters may reduce heating bills (1) and reduce the number of cold-related deaths among elderly people (1).\n• Hotter summers may increase domestic tourism in UK seaside resorts (1), boosting local businesses (1).` },
      { q: `Section A — Changing Climate.\nBangladesh is a low-lying country built mostly on the delta of the Ganges, Brahmaputra and Meghna rivers. Much of its coastline is less than 5 m above sea level.\n\nExplain one negative effect of climate change on people in Bangladesh.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid effect; 1 mark for development. E.g.:\n• Rising sea levels flood coastal land (1), forcing people to migrate to cities such as Dhaka / loss of homes (1).\n• Salt water gets into soils and water supplies (1), so rice crops fail and drinking water is contaminated (1).\n• More intense tropical cyclones bring storm surges (1), damaging homes and killing people (1).\n• Faster melting of Himalayan glaciers increases river flooding (1), destroying crops and farmland (1).` },
      { q: `Section A — Changing Climate.\nThe Thames Barrier, opened in 1982, protects London from tidal flooding. It was closed 4 times in the 1980s but more than 50 times in the 2010s.\n\nGive two ways that people in the UK could adapt to the effects of climate change.`, marks: 2, command: 'Give', markScheme: `1 mark for each valid adaptation, up to 2. E.g.:\n• build or raise flood defences such as sea walls / tidal barriers\n• managed retreat / realignment of coastlines\n• plant drought-resistant crops / change crops grown\n• build reservoirs or reduce water use, e.g. hosepipe bans and water meters\n• design buildings to stay cool, e.g. shading, green roofs\n• stop building homes on floodplains.\nDo not credit mitigation (e.g. renewable energy) as these reduce causes, not effects.` },
      { q: `Section A — Changing Climate.\nIn 2023 renewable sources, such as offshore wind farms in the North Sea, generated about 47% of the UK's electricity. In 2010 the figure was about 7%.\n\nExplain one way that this change helps to mitigate climate change.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point; 1 mark for development. E.g.:\n• Wind turbines generate electricity without burning fossil fuels (1), so less carbon dioxide is released into the atmosphere, reducing the enhanced greenhouse effect (1).\n• It replaces coal- and gas-fired power stations (1), cutting the UK's greenhouse gas emissions towards its net zero by 2050 target (1).` },
      { q: `Section A — Changing Climate.\nPaintings and diaries record 'frost fairs' held on the frozen River Thames in London between the 1600s and 1814.\n\nSuggest one limitation of using historical sources such as paintings and diaries as evidence of past climate.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a valid limitation; 1 mark for development. E.g.:\n• They are not precise measurements (1) so they cannot show exact temperatures / only describe conditions in words or pictures (1).\n• They may be exaggerated or biased by the writer or artist (1) so they may not be reliable (1).\n• They only cover a short period / one place (1) so they cannot show global climate over long timescales (1).\nAlso credit: the old London Bridge slowed the river, so freezing may not only be due to climate (1+1).` },
      { q: `Section A — Changing Climate.\nThe EPICA Dome C ice core, drilled in Antarctica, is over 3 km long and contains ice about 800 000 years old.\n\nExplain how ice cores provide evidence of climate change during the Quaternary period.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3. E.g.:\n• Snow builds up in layers each year and is compressed into ice (1), so deeper ice is older and can be dated (1).\n• Bubbles of air are trapped in the ice (1), so scientists can measure past concentrations of carbon dioxide and methane (1).\n• The ratio of oxygen isotopes in the ice (1) shows the temperature when the snow fell (1).\n• Results show repeated glacial and interglacial periods (1) and that CO₂ and temperature rise and fall together (1).` },
      { q: `Section A — Changing Climate.\nWithout the greenhouse effect, the average temperature of the Earth's surface would be about −18 °C instead of about +15 °C.\n\nExplain how the natural greenhouse effect keeps the Earth warm.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3. E.g.:\n• Short-wave radiation from the Sun passes through the atmosphere and heats the Earth's surface (1).\n• The Earth's surface gives off long-wave (infrared) radiation (1).\n• Greenhouse gases such as carbon dioxide, methane and water vapour absorb this long-wave radiation (1) and re-emit some of it back towards the surface, trapping heat (1).\n• This keeps the Earth warm enough for life (1).` },
      { q: `Section A — Changing Climate.\nDuring the Quaternary period, ice ages (glacials) and warmer interglacials have followed each other roughly every 100 000 years.\n\nExplain how changes in the Earth's orbit can cause climate change.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3. E.g.:\n• The shape of the Earth's orbit changes from more circular to more elliptical (eccentricity) over about 100 000 years (1), changing how much solar energy reaches the Earth (1).\n• The tilt of the Earth's axis varies between about 22° and 24.5° over about 41 000 years (1), changing how strong the seasons are (1).\n• The Earth wobbles on its axis (precession) over about 26 000 years (1).\n• Together these Milankovitch cycles change the amount of solar radiation reaching high latitudes, triggering glacials and interglacials (1).` },
      { q: `Section A — Changing Climate.\nThe Maldives is a country of about 1200 coral islands in the Indian Ocean. About 80% of its land is less than 1 m above sea level. Tourism is the largest part of its economy.\n\nExplain why rising sea levels are a threat to people in the Maldives.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3. E.g.:\n• Most land is less than 1 m above sea level (1), so even a small rise could flood homes and whole islands (1).\n• Salt water could contaminate the limited freshwater supplies / soils (1), making drinking water and farming difficult (1).\n• Beaches and coral reefs could be eroded or damaged (1), reducing tourism income and jobs (1).\n• People may be forced to move to other islands or countries (environmental refugees) (1).` },
      { q: `Section A — Changing Climate.\nGlobal carbon dioxide emissions from burning fossil fuels rose from about 9 billion tonnes in 1960 to about 37 billion tonnes in 2022.\n\nExplain how burning fossil fuels has enhanced the greenhouse effect.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3. E.g.:\n• Burning coal, oil and gas in power stations, vehicles and factories releases carbon dioxide (1).\n• This increases the concentration of greenhouse gases in the atmosphere, e.g. from about 280 ppm before the Industrial Revolution to over 420 ppm today (1).\n• More long-wave radiation from the Earth's surface is absorbed and re-emitted back (1), so more heat is trapped and global temperatures rise (1).` },
      { q: `Section A — Changing Climate.\nIn the UK, the comma butterfly has moved its range northwards by more than 200 km since the 1970s and is now found in southern Scotland.\n\nExplain one effect of climate change on the environment in the UK.`, marks: 3, command: 'Explain', markScheme: `1 mark for a valid effect; up to 2 further marks for development. E.g.:\n• Species are shifting their ranges northwards (1) because warmer temperatures make northern areas suitable (1); species that need cold conditions, such as mountain plants in the Scottish Highlands, may lose their habitats (1).\n• Rising sea levels increase coastal flooding and erosion (1), e.g. along the Norfolk coast (1), destroying salt marsh and coastal habitats (1).\n• Hotter, drier summers cause droughts (1), lowering river levels (1) and increasing the risk of wildfires on moorland (1).` },
      { q: `Section A — Changing Climate.\nFig. 1 is a table of data from an Antarctic ice core (data written for this practice question, based on the pattern in real ice-core records):\nYears before present | CO₂ (ppm) | Temperature compared with today (°C)\n400 000 | 285 | +1.5\n340 000 | 195 | −7.5\n240 000 | 270 | +0.5\n140 000 | 190 | −8.0\n20 000 | 185 | −8.5\nToday | 420 | 0\n\nUsing Fig. 1, describe the relationship between carbon dioxide and temperature over the last 400 000 years.`, marks: 4, command: 'Describe', markScheme: `Up to 4 marks for description using data:\n• Positive relationship / when CO₂ is high, temperature is high (1).\n• Use of data for a warm period, e.g. 400 000 years ago CO₂ 285 ppm and temperature +1.5 °C (1).\n• Use of data for a cold period, e.g. 20 000 years ago CO₂ 185 ppm and temperature −8.5 °C (1).\n• CO₂ varied naturally between about 185 and 285 ppm in glacials and interglacials (1).\n• Anomaly: today's CO₂ (420 ppm) is far higher than at any time in the record (1) but temperature (0 °C) is lower than 400 000 years ago (1).\nMax 2 if no data used.` },
      { q: `Section A — Changing Climate.\nFig. 7 shows the average extent of Arctic sea ice in September (the yearly minimum), in million km² (values approximate, based on records from the US National Snow and Ice Data Center):\n1980 — 7.7; 1990 — 6.1; 2000 — 6.3; 2007 — 4.3; 2012 — 3.6; 2020 — 3.9; 2023 — 4.4.\n\nDescribe the changes in Arctic sea-ice extent shown in Fig. 7.`, marks: 4, command: 'Describe', markScheme: `Up to 4 marks for description:\n• Overall decrease in sea-ice extent (1).\n• Use of data, e.g. from 7.7 million km² in 1980 to 4.4 million km² in 2023 / a fall of 3.3 million km² (1).\n• The lowest value was in 2012 at 3.6 million km² (1).\n• The decline is not steady: small increase 1990–2000 and from 2012 to 2023 (1).\n• Sharp fall between 2000 and 2007 (2.0 million km²) (1).\nMax 2 if no data used.` },
      { q: `Section A — Changing Climate.\nThe Quaternary period covers the last 2.6 million years. In the UK, landforms such as corries in the Lake District and boulder clay in East Anglia show that ice once covered much of the country.\n\nExplain how evidence shows that the climate has changed during the Quaternary period.`, marks: 6, command: 'Explain', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of a range of evidence (AO1). Well-developed explanation of how each type of evidence shows changes in past climate (AO2). Uses accurate examples or timescales.\nLevel 2 (3–4 marks): Reasonable knowledge of some evidence. Some explanation of how it shows climate change, but may be uneven or lack examples.\nLevel 1 (1–2 marks): Basic knowledge of one or two types of evidence, mostly described rather than explained.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• Ice cores: trapped air bubbles show CO₂ levels; oxygen isotopes show temperature; records go back 800 000 years and show repeated glacials and interglacials.\n• Ocean sediment cores: fossil shells (foraminifera) show changes in ocean temperature over millions of years.\n• Pollen in peat and lake sediments: shows which plants grew, so indicates temperature, e.g. tundra species in the UK during cold periods.\n• Tree rings: width shows growing conditions over thousands of years.\n• Glacial landforms (corries, U-shaped valleys, moraines, erratics) show ice reached as far south as the Thames valley.\n• Fossils of animals such as woolly mammoths found in the UK show colder periods.` },
      { q: `Section A — Changing Climate.\nThe Earth's climate has changed many times without human influence, for example during the ice ages of the Quaternary period and the Little Ice Age (about 1300–1850).\n\nExplain the natural causes of climate change.`, marks: 6, command: 'Explain', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of orbital change, volcanic activity and solar output (AO1). Detailed explanation of how each changes the amount of energy reaching or retained by the Earth, with timescales or examples (AO2).\nLevel 2 (3–4 marks): Reasonable knowledge of two causes, with some explanation.\nLevel 1 (1–2 marks): Basic knowledge; causes are named or simply described with little explanation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• Orbital change (Milankovitch cycles): eccentricity (~100 000 years), axial tilt (~41 000 years) and precession (~26 000 years) change the amount and distribution of solar radiation, triggering glacials and interglacials.\n• Volcanic activity: SO₂ forms aerosols that reflect solar radiation and cause short-term cooling, e.g. Mount Pinatubo 1991 (~0.5 °C), Tambora 1815 ('year without a summer' in 1816).\n• Solar output: sunspot activity varies in ~11-year cycles; the Maunder Minimum (1645–1715) coincided with the coldest part of the Little Ice Age.\n• Credit: these causes work over different timescales — volcanoes over years, solar over decades, orbits over tens of thousands of years.` },
      { q: `Section A — Changing Climate.\nThe concentration of carbon dioxide in the atmosphere has risen from about 280 ppm before the Industrial Revolution to over 420 ppm today. Methane concentrations have more than doubled over the same period.\n\nExplain how human activities have caused the enhanced greenhouse effect.`, marks: 6, command: 'Explain', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of human activities and the gases they release (AO1). Clear, well-developed explanation of how extra greenhouse gases trap more long-wave radiation and lead to warming (AO2).\nLevel 2 (3–4 marks): Reasonable knowledge of some human activities; some explanation of the link to the greenhouse effect.\nLevel 1 (1–2 marks): Basic knowledge; activities listed with little or no explanation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• Burning fossil fuels for energy, transport and industry releases CO₂.\n• Deforestation, e.g. in the Amazon, releases stored carbon and reduces CO₂ absorption.\n• Agriculture: livestock and rice paddies release methane; fertilisers release nitrous oxide.\n• Landfill sites release methane as waste decomposes.\n• Industry and refrigeration release fluorinated gases.\n• More greenhouse gases absorb and re-emit more long-wave radiation back to the surface, so global temperatures rise by about 1.1–1.2 °C since 1850–1900.\n• Population growth and rising wealth increase demand for energy and food.` },
      { q: `Section A — Changing Climate.\nIn July 2022, a temperature of 40.3 °C was recorded at Coningsby, Lincolnshire — the highest ever measured in the UK. Winters in the UK have also become wetter, with storms such as Storm Desmond (2015) causing severe flooding in Cumbria.\n\nExamine the effects of climate change on the UK.`, marks: 6, command: 'Examine', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of positive and negative effects on people and the environment in the UK (AO1). Examines the effects in detail, e.g. considers who is affected, how significant the effects are, or how they vary across the UK (AO2). Uses specific UK places or data.\nLevel 2 (3–4 marks): Reasonable knowledge of some effects; some examination but may focus on only negative or only positive effects.\nLevel 1 (1–2 marks): Basic knowledge; effects stated with little development.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nNegative: more frequent heatwaves increase heat-related deaths (e.g. 2022); more flooding from intense rainfall and storms (Cumbria 2015); rising sea levels increase coastal erosion and flooding (e.g. Norfolk, Thames Estuary); droughts and hosepipe bans in south-east England; species lose habitats.\nPositive: longer growing season; new crops such as grapes in southern England; increased domestic tourism; lower winter heating costs.\nExamination: effects are greater in the south-east (drier, hotter) and in low-lying coastal areas; negative effects likely to outweigh positive in the long term.` },
      { q: `Section A — Changing Climate.\nBangladesh has a population of over 170 million people. Around a quarter of its land is less than 2 m above sea level, and many people depend on farming in the Ganges–Brahmaputra delta.\n\nExamine the effects of climate change on one country other than the UK.`, marks: 6, command: 'Examine', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of effects on people and the environment in a named country (AO1). Detailed examination of how serious the effects are and who is most affected, with accurate place-specific detail (AO2).\nLevel 2 (3–4 marks): Reasonable knowledge of some effects in the named country; some examination.\nLevel 1 (1–2 marks): Basic knowledge; general effects of climate change not clearly linked to a country.\n0 marks: No response or no response worthy of credit.\n\nIndicative content (Bangladesh; credit any appropriate country, e.g. Maldives, Kiribati, Kenya):\n• Sea level rise floods coastal land and the Sundarbans mangrove forest, threatening Bengal tigers.\n• Salt water intrusion reduces rice yields and contaminates drinking water.\n• More intense tropical cyclones and storm surges, e.g. Cyclone Amphan (2020).\n• Increased river flooding from heavier monsoon rain and Himalayan glacier melt.\n• Migration from rural coastal areas into Dhaka, increasing slum growth.\n• Poorer people are affected most because they cannot afford to move or protect property.\n• Possible positive: longer growing seasons in some areas (limited).` },
      { q: `Section A — Changing Climate.\nUnder the Climate Change Act (2008, amended 2019), the UK has a legal target to reach net zero greenhouse gas emissions by 2050. The UK's emissions fell by about 50% between 1990 and 2022.\n\nUsing a named country, explain how mitigation strategies can reduce the causes of climate change.`, marks: 6, command: 'Explain', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of mitigation strategies in a named country (AO1). Well-developed explanation of how each strategy reduces greenhouse gas emissions or removes them from the atmosphere (AO2).\nLevel 2 (3–4 marks): Reasonable knowledge of some strategies with some explanation.\nLevel 1 (1–2 marks): Basic knowledge; strategies listed, or adaptation confused with mitigation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content (UK example; credit any appropriate country):\n• Renewable energy: offshore wind farms (e.g. Hornsea in the North Sea), solar, replacing coal (last UK coal power station closed in 2024) — less CO₂ released.\n• Nuclear power, e.g. Hinkley Point C under construction.\n• Electric vehicles and the planned end of sales of new petrol and diesel cars; improved public transport.\n• Afforestation / tree planting acts as a carbon sink.\n• Carbon capture and storage.\n• Home insulation reduces energy demand.\n• International agreements, e.g. the Paris Agreement (2015) to limit warming to well below 2 °C.` },
      { q: `Section A — Changing Climate.\nIn Bangladesh, more than 4000 raised cyclone shelters have been built along the coast. Some farmers have switched from rice to salt-tolerant crops or to shrimp farming.\n\nExplain how adaptation can help people to cope with the effects of climate change.`, marks: 6, command: 'Explain', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of adaptation strategies, with named examples (AO1). Well-developed explanation of how each one reduces the impact of climate change on people (AO2).\nLevel 2 (3–4 marks): Reasonable knowledge of some strategies with some explanation.\nLevel 1 (1–2 marks): Basic knowledge; strategies listed, or mitigation confused with adaptation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• Cyclone shelters and early-warning systems in Bangladesh reduce deaths from storm surges.\n• Salt-tolerant rice varieties and floating gardens allow farming on flooded or salty land.\n• Raised homes, embankments and coastal mangrove planting reduce flood damage.\n• Hard engineering such as the Thames Barrier protects London from tidal surges.\n• Water management: reservoirs, water meters, hosepipe bans for drought.\n• Hulhumalé in the Maldives — an artificial island built about 2 m above sea level.\n• Limits: adaptation can be expensive for LICs and may only delay the impacts.` },
      { q: `Section A — Changing Climate.\nScientists use different sources of evidence for climate change, including: thermometer records since about 1850; satellite images of ice sheets since the 1970s; ice cores going back 800 000 years; and historical sources such as paintings and diaries.\n\nExamine the reliability of different sources of evidence for climate change.`, marks: 6, command: 'Examine', markScheme: `Levels of response.\nLevel 3 (5–6 marks): Thorough knowledge of a range of sources of evidence (AO1). Detailed examination of the strengths and limitations of each, reaching a reasoned view on which are most reliable (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge of some sources; some comment on reliability.\nLevel 1 (1–2 marks): Basic knowledge; sources described with little comment on reliability.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• Thermometer records: accurate and direct, but only since about 1850; early records mostly from Europe and North America; urban heat islands can bias some stations.\n• Satellites: global coverage and very accurate, but only since the 1970s.\n• Ice cores: very long record and measure CO₂ directly, but only from polar areas; temperature is estimated indirectly from isotopes.\n• Tree rings and pollen: long records but affected by other factors such as rainfall or disease; only show local conditions.\n• Historical sources: show human experience but are not measurements; may be exaggerated.\n• Reliability increases when several independent sources show the same trend.` },
      { q: `Section A — Changing Climate.\nA scientist said: "Natural factors such as volcanoes and the Sun have always changed the climate. But since 1950, they cannot explain the warming we have measured."\n\nEvaluate the view that recent climate change is mainly caused by human activity.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response.\nLevel 3 (6–8 marks): Thorough knowledge and understanding of natural and human causes (AO1/AO2). Thorough evaluation of the evidence for each, weighing up their relative importance over different timescales, and reaching a well-supported judgement (AO3).\nLevel 2 (3–5 marks): Reasonable knowledge of natural and human causes. Some evaluation, but the judgement may be partly supported or one side is underdeveloped.\nLevel 1 (1–2 marks): Basic knowledge of causes, mostly described; little or no evaluation or judgement.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nFor human causes being most important:\n• CO₂ has risen from about 280 ppm to over 420 ppm — higher than any time in the 800 000-year ice-core record.\n• Rate of warming since 1975 is much faster than natural changes during the Quaternary.\n• Solar output has stayed roughly level or fallen slightly since the 1980s while temperatures rose.\n• Fossil fuels, deforestation and farming have greatly increased greenhouse gases.\nFor natural causes:\n• Climate changed many times in the Quaternary before humans, e.g. glacials and interglacials linked to Milankovitch cycles.\n• Volcanic eruptions (Pinatubo 1991) and solar minima (Maunder Minimum) have caused clear changes.\n• Natural factors still cause year-to-year variation.\nJudgement: e.g. natural factors explain long-term change, but human activity is the main cause of warming since the mid-20th century.` },
      { q: `Section A — Changing Climate.\nSome farmers in southern England have planted vineyards as summers have become warmer. However, the UK has also experienced record heatwaves, drought and more frequent flooding in recent years.\n\nAssess whether climate change will have more positive than negative effects for the UK. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Levels of response.\nLevel 3 (6–8 marks): Thorough knowledge and understanding of positive and negative effects on people and the environment in the UK (AO1/AO2). Thorough assessment of the scale and significance of the effects, possibly considering different places, groups and timescales, leading to a well-supported judgement (AO3).\nLevel 2 (3–5 marks): Reasonable knowledge of positive and negative effects. Some assessment, but the judgement is partly supported or unbalanced.\nLevel 1 (1–2 marks): Basic knowledge of effects; little or no assessment.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nPositive: longer growing season; new crops (vineyards, maize) in southern England; fewer cold-related deaths; lower heating costs; more domestic tourism; possible new shipping routes through the Arctic.\nNegative: heatwaves (40.3 °C in 2022) and heat-related deaths; droughts and water shortages in the south-east; flooding from intense storms (Cumbria 2015) and rising sea levels threatening London and the east coast; coastal erosion (e.g. Holderness, Norfolk); loss of habitats and species; cost of defences.\nJudgement: e.g. short-term benefits for some farmers and tourism, but negative effects are likely to grow and outweigh them, especially for vulnerable people and low-lying areas.\n\nSPaG (3 marks):\nHigh performance (3): spells and punctuates with consistent accuracy; consistently uses rules of grammar with effective control of meaning; uses a wide range of specialist terms precisely.\nIntermediate performance (2): spells and punctuates with considerable accuracy; uses rules of grammar with general control of meaning; uses a good range of specialist terms.\nThreshold performance (1): spells and punctuates with reasonable accuracy; uses rules of grammar with some control of meaning; any errors do not significantly hinder meaning; uses a limited range of specialist terms.\n0 marks: writes nothing, or the response does not relate to the question, or errors severely hinder meaning.` },
      { q: `Section A — Changing Climate.\nThe UK spends billions of pounds on reducing emissions to reach net zero by 2050. It also spends money on flood defences such as the Thames Barrier and the Thames Estuary 2100 plan.\n\nEvaluate whether mitigation is more important than adaptation in responding to climate change.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response.\nLevel 3 (6–8 marks): Thorough knowledge and understanding of mitigation and adaptation strategies with examples (AO1/AO2). Thorough evaluation of the benefits and limitations of each, considering timescales, costs and who benefits, leading to a well-supported judgement (AO3).\nLevel 2 (3–5 marks): Reasonable knowledge of both approaches. Some evaluation, but the judgement is partly supported.\nLevel 1 (1–2 marks): Basic knowledge; may confuse mitigation and adaptation; little or no judgement.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nMitigation (reducing causes): renewable energy, electric vehicles, afforestation, carbon capture, Paris Agreement. Tackles the root cause and benefits everyone globally, but needs international co-operation; effects take decades because CO₂ stays in the atmosphere a long time; one country alone has limited impact.\nAdaptation (reducing effects): flood defences, drought-resistant crops, cyclone shelters in Bangladesh, Hulhumalé in the Maldives. Gives immediate local protection, but can be very expensive, may be unaffordable for LICs and does not stop warming.\nJudgement: e.g. both are needed — mitigation is more important in the long term, but adaptation is essential now because some warming is already unavoidable; for small LICs with low emissions, adaptation may matter more.` },
      { q: `Section A — Changing Climate.\nThe UK is a high-income country with a long coastline and a temperate climate. Bangladesh is a lower-income country on a low-lying river delta, affected by monsoon rains and tropical cyclones.\n\nAssess the extent to which the effects of climate change are more serious for one other country you have studied than for the UK.`, marks: 8, command: 'Assess', markScheme: `Levels of response.\nLevel 3 (6–8 marks): Thorough knowledge and understanding of the effects of climate change in the UK and in a named other country (AO1/AO2). Thorough assessment comparing the scale of effects and the ability of each country to cope, leading to a well-supported judgement (AO3).\nLevel 2 (3–5 marks): Reasonable knowledge of effects in both countries. Some assessment, but comparison may be limited or one country underdeveloped.\nLevel 1 (1–2 marks): Basic knowledge of effects in one or both countries; little or no comparison.\n0 marks: No response or no response worthy of credit.\n\nIndicative content (Bangladesh as example):\n• Bangladesh: large areas of land at risk from sea level rise; salt water intrusion; stronger cyclones and storm surges; millions may be displaced; heavy reliance on farming; less money for defences.\n• UK: heatwaves, flooding and coastal erosion, but a smaller proportion of land and people at risk; wealth to build defences (Thames Barrier) and insurance; some positive effects for farming and tourism.\n• Assessment: effects are more serious for Bangladesh because of physical exposure and lower capacity to adapt, though some UK communities (e.g. on the Norfolk coast) face severe local impacts.\n• Credit any appropriate other country, e.g. Maldives, Kiribati, Kenya.` },
      { q: `Resource Booklet — The Maldives.\nFig. 8: The Maldives is a country of about 1200 low-lying coral islands in the Indian Ocean, with a population of just over 500 000. About 80% of the land is less than 1 m above sea level and the highest natural point is about 2.4 m. Tourism, based on beaches and coral reefs, is the largest part of the economy.\nFig. 9: Responses to climate change in the Maldives:\n• Malé, the capital, is surrounded by a sea wall about 3 m high, built after flooding in 1987.\n• Hulhumalé is an artificial island built on reclaimed land about 2 m above sea level, to house tens of thousands of people.\n• The government has set a target to increase the use of solar energy and reduce reliance on imported diesel.\n• The Maldives produces less than 0.01% of global carbon dioxide emissions.\n• Coral reef restoration projects replant heat-resistant coral fragments.\n\nUsing Figs. 8 and 9, and your own understanding, evaluate the view that the Maldives should focus on adaptation rather than mitigation.`, marks: 12, command: 'Evaluate', markScheme: `Levels of response.\nLevel 4 (10–12 marks): Thorough knowledge and understanding of mitigation and adaptation and of the Maldives' vulnerability (AO1/AO2). Makes full use of Figs. 8 and 9 and own understanding. Thorough evaluation of both approaches, considering costs, timescales, effectiveness and global context, leading to a well-supported, substantiated judgement (AO3).\nLevel 3 (7–9 marks): Good knowledge and understanding. Makes good use of the resources. Clear evaluation with a supported judgement, though some points less developed.\nLevel 2 (4–6 marks): Reasonable knowledge and understanding. Some use of resources. Some evaluation, but the judgement is partly supported or unbalanced.\nLevel 1 (1–3 marks): Basic knowledge, mainly descriptive or copied from the resources. Little or no evaluation or judgement.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nFor adaptation:\n• Most land is below 1 m, so the threat of sea level rise is immediate — sea walls and Hulhumalé protect people now.\n• The Maldives produces less than 0.01% of global CO₂, so its own mitigation will hardly affect global warming.\n• Protecting reefs and beaches protects tourism, the main source of income and jobs.\nAgainst / for mitigation:\n• Adaptation is expensive and may only buy time; sea walls cannot protect all 1200 islands; Hulhumalé is only 2 m above sea level.\n• Solar energy reduces costly diesel imports, giving economic as well as environmental benefits.\n• Mitigation sets an example and strengthens the Maldives' voice in international agreements such as the Paris Agreement; global mitigation is the only long-term solution.\nJudgement: e.g. adaptation should be the priority because of the immediate threat and tiny emissions, but some mitigation is still worthwhile, and the country depends on global mitigation by high emitters.` },
      { q: `Resource Booklet — London and climate change.\nFig. 10: London is built on the floodplain and estuary of the River Thames. About 1.4 million people and 500 000 properties are in the Thames tidal floodplain.\nFig. 11: Facts about climate change and London:\n• The Thames Barrier opened in 1982. It closed 4 times in the 1980s and more than 50 times in the 2010s.\n• The Thames Estuary 2100 plan will raise and improve flood defences and may need a new barrier later this century.\n• On 19 July 2022 London Heathrow recorded 40.2 °C. Wildfires destroyed homes in Wennington, east London, on the same day.\n• Over 60% of London is classed as 'green' (parks, gardens, green roofs and water), which helps keep the city cooler.\n• The Ultra Low Emission Zone (ULEZ) was expanded to cover all of London in 2023.\n• Average sea level at the Thames Estuary is projected to rise by between about 0.5 m and 1.2 m by 2100 (projections vary with future emissions).\n\nUsing Figs. 10 and 11, and your own understanding, assess how well prepared London is for the effects of climate change.`, marks: 12, command: 'Assess', markScheme: `Levels of response.\nLevel 4 (10–12 marks): Thorough knowledge and understanding of the effects of climate change on the UK and of responses (AO1/AO2). Makes full use of Figs. 10 and 11 and own understanding. Thorough assessment of the strengths and weaknesses of London's preparation, considering different hazards and timescales, leading to a well-supported, substantiated judgement (AO3).\nLevel 3 (7–9 marks): Good knowledge and understanding. Makes good use of the resources. Clear assessment with a supported judgement, though some points less developed.\nLevel 2 (4–6 marks): Reasonable knowledge and understanding. Some use of resources. Some assessment, but the judgement is partly supported or one-sided.\nLevel 1 (1–3 marks): Basic knowledge, mainly descriptive or copied from the resources. Little or no assessment or judgement.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nWell prepared:\n• The Thames Barrier has protected London from tidal flooding since 1982.\n• The Thames Estuary 2100 plan is a long-term adaptation strategy planning for sea level rise.\n• Green space and green roofs reduce the urban heat island effect during heatwaves.\n• ULEZ and other policies help mitigation and cleaner air.\n• The UK has the wealth, technology and early-warning systems (Environment Agency, Met Office) to respond.\nLess well prepared:\n• Rising number of barrier closures suggests it is nearing its design limits; a new barrier would be very costly.\n• Sea level projections are uncertain (0.5–1.2 m); 1.4 million people remain at risk.\n• The 2022 heatwave caused wildfires and pressure on health services and transport — the city was not fully prepared for 40 °C.\n• Surface water flooding from intense rainfall (e.g. July 2021) is a separate risk not solved by the barrier.\n• Older housing is not designed to stay cool; poorer and elderly residents are most vulnerable.\nJudgement: e.g. London is well prepared for tidal flooding in the short to medium term, but less prepared for extreme heat and surface flooding, and long-term preparation depends on future funding and global emissions.` }
    ]
  },
  '1.4': {
    name: 'Distinctive Landscapes: UK Landscapes and Coasts',
    questions: [
      { q: `Section A — Distinctive Landscapes.\nFig. 1 is a description of a 1:25 000 OS map extract of a chalk coastline (written for this practice question). Easting lines 20 to 24 run left to right and northing lines 78 to 81 run bottom to top. A stack, marked by the cliff symbol surrounded by sea, lies in the grid square whose bottom-left corner is where easting 23 meets northing 80.\n\nGive the four-figure grid reference of the grid square containing the stack.`, marks: 1, command: 'Give', markScheme: `2380 (1)\nDo not accept 8023 (northing given first).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 1 is a description of a 1:25 000 OS map extract of a coastal town (written for this practice question). A lighthouse symbol lies in the grid square whose bottom-left corner is where easting 22 meets northing 79. The lighthouse is three-tenths of the way east across the square and seven-tenths of the way north up the square.\n\nGive the six-figure grid reference of the lighthouse.`, marks: 1, command: 'Give', markScheme: `223797 (1)\nAllow 223 797. Do not accept 797223.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 1 is a description of an OS map extract of part of the Holderness coast. The village of Mappleton is on the coast. The town of Hornsea lies about 4 km directly north of Mappleton along the coast road (B1242).\n\nState the compass direction of Mappleton from Hornsea.`, marks: 1, command: 'State', markScheme: `South (1)\nDo not accept north (direction reversed).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 2 is a table of rock types found in three UK landscapes.\nDartmoor (south-west England) — granite, formed from cooled magma.\nThe South Downs (south-east England) — chalk, formed from the remains of tiny marine organisms.\nThe Lake District (north-west England) — slate, formed when mudstone was changed by heat and pressure.\n\nIdentify the landscape in Fig. 2 that is formed from igneous rock.`, marks: 1, command: 'Identify', markScheme: `Dartmoor (1)\nAllow granite / Dartmoor granite.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 3 shows mean annual rainfall at four UK locations (data written for this practice question).\nFort William (west Scotland) 2 000 mm\nKeswick (Lake District) 1 450 mm\nYork (north-east England) 620 mm\nCambridge (east England) 560 mm\n\nIdentify the location in Fig. 3 with the highest mean annual rainfall.`, marks: 1, command: 'Identify', markScheme: `Fort William (1)` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students measured the long axis of 11 pebbles at one point on a beach in Dorset. Their results, in mm, were (data written for this practice question):\n22, 35, 41, 18, 56, 30, 47, 25, 38, 62, 29\n\nCalculate the range of the pebble sizes.`, marks: 1, command: 'Calculate', markScheme: `44 mm (1)\n(62 − 18 = 44)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 4 is a description of a photograph of Lulworth Cove, Dorset. It shows an almost circular bay with a narrow entrance between two rocky headlands. A shingle beach curves around the back of the cove. Behind the beach rise steep grassy chalk slopes. There is a car park, a slipway with small boats and a row of cottages and cafés at the eastern end of the village.\n\nGive one human feature shown in Fig. 4.`, marks: 1, command: 'Give', markScheme: `One from: car park / slipway / boats / cottages / houses / cafés (1)\nDo not credit natural features (beach, headland, chalk slopes).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 1 is a description of a 1:25 000 OS map extract of the coast near Swanage, Dorset. On the map the distance along the coast path from the end of the pier to the stacks at Old Harry Rocks measures 6.4 cm.\n\nCalculate the actual distance in kilometres between the pier and Old Harry Rocks. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 6.4 × 25 000 = 160 000 cm / 1 cm = 0.25 km so 6.4 × 0.25 (1)\n1 mark for answer: 1.6 km (1)\nCorrect answer with no working = 1 mark only (working required).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 1 is a description of a 1:25 000 OS map extract of a cliffed coast (written for this practice question). The cliff top is on the 100 m contour. A straight line from the cliff top to the high-water mark (0 m) measures 2 cm on the map.\n\nCalculate the gradient of the slope from the cliff top to the high-water mark. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: horizontal distance 2 × 250 m = 500 m; height difference 100 m; 100 ÷ 500 (1)\n1 mark for answer: 1 in 5 / 1:5 / 0.2 / 20% (1)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 5 shows the cliff retreat measured at five sites along the Holderness coast in one year (data written for this practice question).\nSite 1: 1.2 m\nSite 2: 2.6 m\nSite 3: 0.3 m\nSite 4: 3.1 m\nSite 5: 1.8 m\n\nCalculate the mean cliff retreat for the five sites. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 1.2 + 2.6 + 0.3 + 3.1 + 1.8 = 9.0; 9.0 ÷ 5 (1)\n1 mark for answer: 1.8 m (1)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 6 shows the number of visitors to a stretch of the Jurassic Coast in Dorset (data written for this practice question).\n2014: 420 000 visitors\n2024: 567 000 visitors\n\nCalculate the percentage change in visitors between 2014 and 2024. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 567 000 − 420 000 = 147 000; 147 000 ÷ 420 000 × 100 (1)\n1 mark for answer: 35% (increase) (1)` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students measured the long axis of 11 pebbles at one point on a beach in Dorset. Their results, in mm, were (data written for this practice question):\n22, 35, 41, 18, 56, 30, 47, 25, 38, 62, 29\n\nCalculate the interquartile range of the pebble sizes. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: data ordered 18, 22, 25, 29, 30, 35, 38, 41, 47, 56, 62; lower quartile = 25 mm (3rd value) and upper quartile = 47 mm (9th value) (1)\n1 mark for answer: 47 − 25 = 22 mm (1)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 7 is a description of a map of the relief of the UK. Land over 500 m is shaded brown. It covers most of the Scottish Highlands and Southern Uplands, the Lake District, the Pennines running north–south through northern England, and much of central and north Wales. Land below 200 m is shaded green and covers most of East Anglia, the Midlands and south-east England.\n\nDescribe the distribution of upland areas shown in Fig. 7.`, marks: 2, command: 'Describe', markScheme: `1 mark per valid point, e.g.:\nmainly in the north and west of the UK (1)\nmost of Scotland / Scottish Highlands (1)\nPennines form a north–south spine through northern England (1)\nfew uplands in the south and east / east of England is mainly lowland (1)\nnamed examples e.g. Lake District, Snowdonia / Wales (1)\nMax 2. Allow reference to a Tees–Exe line dividing upland north-west from lowland south-east.` },
      { q: `Section A — Distinctive Landscapes.\nDartmoor in south-west England is an upland landscape of high moorland with granite tors, thin acidic soils and boggy hollows.\n\nExplain one way that geology has influenced the landscape of Dartmoor.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\ngranite is a hard / resistant igneous rock (1) so it is eroded slowly and remains as high upland (1)\ngranite is impermeable (1) so water lies on the surface creating bogs / many streams (1)\njoints in the granite are weathered more quickly (1) leaving blocks of solid rock standing as tors (1)\nweathered granite forms thin, acidic soils (1) so the land is used for rough grazing / moorland rather than crops (1)` },
      { q: `Section A — Distinctive Landscapes.\nThe Cairngorms in north-east Scotland have winter temperatures that regularly fall below 0 °C at night and rise above 0 °C during the day. Slopes below many summits are covered in angular, broken rock fragments (scree).\n\nExplain one way that climate has influenced the landscape of the Cairngorms.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\nfreeze–thaw weathering (1) water in cracks freezes and expands by about 9%, widening cracks until rock breaks off, forming scree (1)\nhigh precipitation / snow (1) increases runoff and erosion by streams, cutting into slopes (1)\nlow temperatures shorten the growing season (1) so the land is open moorland with little tree cover / little farming (1)\nAllow reference to glaciation in the past shaping corries and U-shaped valleys (1) as climate was colder (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 8 is a description of a photograph of a lowland landscape in East Anglia. It shows large flat fields of wheat separated by drainage ditches, a few hedgerows, a straight road, a small village with a church and a line of wind turbines in the distance.\n\nUsing Fig. 8, explain one way human activity has shaped this landscape.`, marks: 2, command: 'Explain', markScheme: `1 mark for the activity identified from Fig. 8, 1 mark for development, e.g.:\narable farming (1) hedgerows removed to create large fields for machinery, giving an open landscape (1)\ndrainage ditches dug (1) to drain marshy land / fens so it can be farmed (1)\nenergy generation (1) wind turbines built on flat, exposed land change the skyline (1)\nsettlement / roads (1) villages and straight roads built across the flat land (1)` },
      { q: `Section A — Distinctive Landscapes.\nIn a storm in February 2014, large waves broke against the cliffs of the Jurassic Coast and many rockfalls were recorded in the following weeks.\n\nExplain how hydraulic action erodes a cliff.`, marks: 2, command: 'Explain', markScheme: `1 mark per valid point, e.g.:\nforce of the waves hitting the cliff (1)\nwaves trap / compress air in cracks / joints in the rock (1)\nas the wave retreats the air expands explosively / pressure is released (1)\nrepeated over time this widens cracks and breaks off pieces of rock (1)\nMax 2.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 9 shows observations of waves made by GCSE students on the same beach on two days (data written for this practice question).\nDay 1 (after a storm): 13 waves per minute; tall, steep waves; strong backwash; sand dragged down the beach.\nDay 2 (calm weather): 7 waves per minute; low, gently sloping waves; strong swash; sand and shingle pushed up the beach.\n\nExplain one difference between the waves on Day 1 and Day 2.`, marks: 2, command: 'Explain', markScheme: `1 mark for the difference, 1 mark for explanation, e.g.:\nDay 1 waves are destructive and Day 2 waves are constructive (1) because Day 1 backwash is stronger than swash so material is removed, while Day 2 swash is stronger so material is deposited (1)\nDay 1 waves are more frequent (13 compared with 7 per minute) (1) as storm winds are stronger / blow over a long fetch, giving waves more energy (1)\nDay 1 waves erode the beach whereas Day 2 waves build it up (1) because of the difference in swash and backwash strength (1)\nThe difference must be comparative for the first mark.` },
      { q: `Section A — Distinctive Landscapes.\nThe cliffs of the Holderness coast in East Yorkshire are made of boulder clay (glacial till), a soft mixture of clay, sand and stones. After several days of heavy rain in winter, large sections of cliff near Skipsea slumped onto the beach.\n\nExplain why heavy rain can cause slumping on the Holderness cliffs.`, marks: 2, command: 'Explain', markScheme: `1 mark per valid point, e.g.:\nrain soaks into / saturates the boulder clay (1)\nthis makes the cliff heavier and the water lubricates the clay (1)\nclay becomes unstable and slides down a curved slip plane in a rotational movement (1)\nwaves at the base remove the slumped material, so the process repeats (1)\nMax 2.` },
      { q: `Section A — Distinctive Landscapes.\nThe chalk cliffs at Flamborough Head, East Yorkshire, are cut by many joints and cracks. Rock falls are most common after cold winters.\n\nExplain how mechanical weathering can cause rock falls from the cliffs at Flamborough Head.`, marks: 2, command: 'Explain', markScheme: `1 mark per valid point, e.g.:\nfreeze–thaw weathering: rainwater enters joints / cracks in the chalk (1)\nwater freezes at night and expands, putting pressure on the rock (1)\nrepeated freezing and thawing widens the crack until a piece of rock breaks off and falls (1)\nAllow salt weathering: salt crystals growing in cracks from sea spray (1) exert pressure and break the rock (1)\nMax 2.` },
      { q: `Section A — Distinctive Landscapes.\nLimestone and chalk are found along much of the Dorset coast. Both rocks are made mainly of calcium carbonate.\n\nExplain how chemical weathering affects these rocks.`, marks: 2, command: 'Explain', markScheme: `1 mark per valid point, e.g.:\nrainwater is a weak carbonic acid as it absorbs carbon dioxide (1)\nthe acid reacts with calcium carbonate and dissolves it (carbonation) (1)\nthis widens joints / bedding planes, weakening the rock so it is more easily eroded (1)\nMax 2.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students investigated longshore drift on a beach in Norfolk. Their method was:\n1. Place one painted pebble at the water's edge.\n2. Wait 5 minutes.\n3. Measure how far along the beach the pebble has moved using a tape measure.\n4. Do this once at one point on the beach.\n\nSuggest two ways the students could improve their method.`, marks: 2, command: 'Suggest', markScheme: `1 mark for each valid improvement, max 2, e.g.:\nrepeat the measurement several times and calculate a mean (1)\nuse several pebbles / floats at once in case one is lost (1)\nrecord the direction of movement using a compass (1)\nmeasure at several sites along the beach / at different times of day or tide (1)\nleave the pebble for longer, e.g. 10–15 minutes, so movement is easier to measure (1)\nrecord the wind direction / wave angle at the same time (1)\nuse a larger sample to make results more reliable (1)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 10 is a description of a 1:50 000 OS map extract of Spurn Point at the southern end of the Holderness coast. A narrow strip of land, shown in yellow (sand) with a road along it, extends south from the mainland across the mouth of the Humber estuary. The southern end curves to the west. On the sheltered estuary side there are areas marked with the mud and salt marsh symbol.\n\nUsing Fig. 10, give two pieces of evidence that Spurn Point is a spit.`, marks: 2, command: 'Give', markScheme: `1 mark for each piece of map evidence, max 2:\nlong, narrow strip of sand / deposited material (1)\nattached to the land at one end and extending into the sea / across an estuary mouth (1)\ncurved / hooked end (1)\nsalt marsh / mud behind it on the sheltered side (1)` },
      { q: `Section A — Distinctive Landscapes.\nSwanage in Dorset is a seaside resort with a sandy beach. Timber groynes have been built at right angles to the beach.\n\nExplain one advantage of groynes for Swanage.`, marks: 2, command: 'Explain', markScheme: `1 mark for the advantage, 1 mark for development, e.g.:\ngroynes trap sediment moved by longshore drift (1) so the beach becomes wider, protecting the sea wall / cliffs behind from wave attack (1)\na wider beach attracts more tourists (1) supporting jobs in hotels, cafés and shops (1)\nthey are cheaper than a sea wall (1) so the council can protect more of the coast for the money available (1)` },
      { q: `Section A — Distinctive Landscapes.\nAt Handfast Point in Dorset, the chalk stack known as Old Harry stands in the sea close to the end of the headland. A smaller stump, Old Harry's Wife, lies nearby.\n\nExplain how an arch becomes a stack.`, marks: 2, command: 'Explain', markScheme: `1 mark per valid point, e.g.:\nwaves erode the base / sides of the arch by hydraulic action and abrasion, widening it (1)\nweathering (e.g. freeze–thaw) weakens the roof of the arch from above (1)\nthe roof becomes too heavy / unsupported and collapses (1)\nleaving an isolated pillar of rock (the stack) separated from the headland (1)\nMax 2.` },
      { q: `Section A — Distinctive Landscapes.\nOn the Holderness coast the prevailing wind blows from the north-east. Sand and shingle eroded from the cliffs near Hornsea is later found on the beaches at Withernsea and Spurn Point, further south.\n\nExplain how longshore drift moves sediment along the Holderness coast.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point, max 3, e.g.:\nwaves approach the beach at an angle, in the direction of the prevailing (north-east) wind (1)\nthe swash carries sediment up the beach at this angle (1)\nthe backwash returns sediment straight down the beach at right angles to the coast, due to gravity (1)\nsediment moves in a zig-zag pattern (1)\nso it is transported southwards along the coast over time (1)\nA labelled diagram can gain full credit.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 11 is a description of a photograph taken at low tide below the cliffs at Kimmeridge Bay, Dorset. A flat, rocky surface with rock pools stretches out about 200 m from the foot of the cliffs towards the sea. At the base of the cliff there is a deep groove just above the level of the high tide.\n\nExplain how the flat, rocky surface shown in Fig. 11 was formed.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point, max 3:\nwaves erode the base of the cliff between high and low tide by hydraulic action / abrasion (1)\nforming a wave-cut notch (the groove in Fig. 11) (1)\nthe overhanging cliff above becomes unsupported and collapses (1)\nthe cliff retreats inland and the process repeats (1)\nleaving a flat area of rock – a wave-cut platform – exposed at low tide (1)\nSequence must be logical for 3 marks.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 5 shows the cliff retreat measured at five sites along the Holderness coast in one year (data written for this practice question).\nSite 1 (north of Hornsea, beach in front of cliff): 1.2 m\nSite 2 (narrow beach): 2.6 m\nSite 3 (Hornsea, behind a sea wall): 0.3 m\nSite 4 (just south of rock groynes at Mappleton): 3.1 m\nSite 5 (narrow beach): 1.8 m\n\nSuggest reasons why the rate of cliff retreat varies between the sites in Fig. 5.`, marks: 3, command: 'Suggest', markScheme: `1 mark per valid reason, max 3, credit use of data, e.g.:\nSite 3 retreats least (0.3 m) because the sea wall protects the cliff from wave attack (1)\nSite 4 retreats most (3.1 m) because groynes upstream trap sediment, starving the beach south of them (terminal groyne effect) (1)\nnarrow beaches (Sites 2 and 5) absorb less wave energy, so more erosion (1)\na wider beach (Site 1) absorbs wave energy and protects the cliff (1)\nvariations in the boulder clay / drainage / cliff height (1)\nAllow other valid reasons.` },
      { q: `Section A — Distinctive Landscapes.\nThe Holderness coast in East Yorkshire is one of the fastest-eroding coastlines in Europe, losing on average around 1.5 to 2 m of land a year.\n\nExplain why the Holderness coast is eroding so rapidly.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point, max 3, e.g.:\ncliffs are made of soft boulder clay that is easily eroded (1)\nlong fetch from the north-east across the North Sea gives powerful destructive waves (1)\nbeaches are narrow because longshore drift carries sediment south, so they give little protection (1)\nheavy rain saturates the clay, causing slumping (1)\nhard defences at places such as Mappleton and Hornsea trap sediment, increasing erosion further south (1)\nsea level rise / storm surges increase wave attack (1)` },
      { q: `Section A — Distinctive Landscapes.\nFig. 3 shows mean annual rainfall at four UK locations (data written for this practice question).\nFort William (west Scotland) 2 000 mm\nKeswick (Lake District) 1 450 mm\nYork (north-east England) 620 mm\nCambridge (east England) 560 mm\n\nDescribe the pattern of rainfall shown in Fig. 3. Use data in your answer.`, marks: 3, command: 'Describe', markScheme: `1 mark per valid point, max 3, data must be used for full marks:\nrainfall is higher in the west than the east (1)\nrainfall is higher in the north / upland areas (1)\nFort William has the highest rainfall at 2 000 mm (1)\nCambridge, in the east, has the lowest at 560 mm (1)\nFort William receives 1 440 mm more than Cambridge / over three and a half times as much (1)\nMax 2 if no data used.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 12 describes a geology map of the coast at Swanage, Dorset. The coastline runs north to south. From north to south the rocks reaching the coast are: chalk (Ballard Point headland), then soft clays and sands (Swanage Bay), then hard Purbeck and Portland limestone (Peveril Point and Durlston Head headlands).\n\nExplain how the headlands and bay shown in Fig. 12 were formed.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point, max 3:\nthis is a discordant coastline where bands of rock run at right angles to the coast (1)\nthe soft clays and sands are eroded more quickly by hydraulic action / abrasion (1)\nforming Swanage Bay (1)\nthe hard chalk and limestone are more resistant, eroding more slowly (1)\nso they stick out into the sea as headlands (Ballard Point / Durlston Head) (1)` },
      { q: `CASE STUDY — A UK coastal landscape.\nCoastal landscapes are shaped by the interaction of physical and human processes.\n\nFor a named UK coastal landscape you have studied, explain one way physical processes and human activity interact.`, marks: 3, command: 'Explain', markScheme: `1 mark for identifying the interaction, up to 2 further marks for development with place detail, e.g.:\nAt Mappleton (Holderness) rock groynes built in 1991 trap sediment moved south by longshore drift (1) this protects the village but starves beaches to the south of sediment (1) so erosion of the cliffs at Great Cowden has increased (1)\nOR at Lulworth Cove large numbers of visitors walk on the cliff paths (1) trampling vegetation and exposing soil (1) so rainwater runoff and erosion of the slopes increase (1)\nMax 1 if no named place.` },
      { q: `Section A — Distinctive Landscapes.\nFlamborough Head in East Yorkshire is a chalk headland with caves, arches and stacks, such as those at Selwicks Bay.\n\nDraw an annotated diagram to show how caves, arches and stacks form on a headland.`, marks: 4, command: 'Draw', diagram: true, markScheme: `1 mark per valid annotation linked to the correct feature, max 4:\nwaves erode a line of weakness (joint / fault) in the headland by hydraulic action / abrasion (1)\ncrack is widened into a cave (1)\ncave is eroded through the headland, often from both sides, forming an arch (1)\narch roof is weakened by weathering and erosion and collapses (1)\nleaving a stack separated from the headland (1)\nstack is eroded at its base and collapses to form a stump (1)\nA diagram without annotations max 1.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 13 describes two photographs.\nPhotograph A, Snowdonia (north Wales): steep, rocky mountains rising over 1 000 m; thin soils; bare rock and scree; a lake in a deep valley; sheep grazing; very few buildings.\nPhotograph B, the Fens (East Anglia): flat land only a few metres above sea level; dark, deep soils; large arable fields of vegetables; straight drainage channels; farms and a village spread across the land.\n\nCompare the landscapes shown in Photographs A and B.`, marks: 4, command: 'Compare', markScheme: `1 mark per valid comparative point, max 4. Points must compare (e.g. "whereas", "higher than"):\nA is upland / mountainous whereas B is lowland and flat (1)\nA has steep slopes whereas B has almost no relief (1)\nA has thin soils / bare rock while B has deep, fertile soils (1)\nA is used for sheep grazing whereas B is used for arable farming (1)\nA has very few settlements while B has more farms and villages (1)\nA has natural drainage (lakes, streams) while B has artificial straight drainage channels (1)\nSingle descriptions of one photo only = max 2.` },
      { q: `Section A — Distinctive Landscapes.\nSpurn Point is a spit about 5 km long, stretching from the southern end of the Holderness coast across the mouth of the Humber estuary. Its tip curves towards the west, and salt marsh has formed behind it.\n\nExplain how Spurn Point was formed.`, marks: 4, command: 'Explain', markScheme: `1 mark per valid point, max 4:\nlongshore drift carries sediment (eroded from the Holderness cliffs) south along the coast (1)\nwhere the coastline changes direction at the Humber estuary, the sediment continues to be carried out into the sea (1)\nwave energy falls in the more sheltered / deeper water, so sediment is deposited (1)\nthe deposits build up above sea level into a long, narrow ridge (1)\nchanges in wind / wave direction and the river current curve the end to form a hook (1)\nsheltered, calm water behind the spit allows mud to be deposited, forming salt marsh (1)` },
      { q: `Section A — Distinctive Landscapes.\nThe UK contains a wide range of rock types. North and west of an imaginary line from the mouth of the River Tees to the mouth of the River Exe, most rocks are old, hard igneous and metamorphic rocks. South and east of this line, most rocks are younger, softer sedimentary rocks such as chalk and clay.\n\nExamine how geology has influenced the distinctive landscapes of the UK.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\nHard igneous / metamorphic rocks (granite, slate, volcanic rocks) resist erosion, forming upland areas such as the Scottish Highlands, Lake District and Snowdonia.\nGranite on Dartmoor weathers along joints to form tors; impermeable rocks give boggy moorland and many surface streams.\nSoft sedimentary rocks erode more easily, forming lowland plains and vales, e.g. clay vales in the Midlands and south-east.\nChalk is permeable, forming rolling escarpments such as the South Downs and Chilterns with dry valleys; at the coast it forms white cliffs, stacks (Old Harry Rocks).\nAlternating hard and soft rocks at the coast produce headlands and bays (Swanage), or coves where hard rock is breached (Lulworth).\nGeology influences soils and land use: thin acidic soils on granite for rough grazing; fertile soils on clay / alluvium for arable farming; slate and granite quarried.\nExamination may recognise that geology interacts with climate, past glaciation and human activity.\n\nLevel 3 (5–6 marks): A thorough examination of how geology influences UK landscapes. Detailed, accurate knowledge and understanding, with well-chosen located examples. Uses geographical terminology accurately; well-developed, logical line of reasoning.\nLevel 2 (3–4 marks): A reasonable examination with some located examples. Some links between rock type and landscape are developed. Reasoning is partly developed.\nLevel 1 (1–2 marks): A basic examination with limited knowledge. Few or no examples; links between geology and landscape are simple or implied.\n0 marks: no response or no response worthy of credit.` },
      { q: `CASE STUDY — A UK coastal landscape.\nGeomorphic processes include weathering, mass movement, erosion, transportation and deposition.\n\nFor a named UK coastal landscape you have studied, explain how geomorphic processes have shaped its landforms.`, marks: 6, command: 'Explain', markScheme: `Indicative content (Dorset / Jurassic Coast example; credit any valid UK coastal landscape, e.g. Holderness, North Norfolk):\nDifferential erosion of alternating hard and soft rock at Swanage: soft clays eroded into Swanage Bay; chalk and limestone left as headlands (Ballard Point, Durlston Head).\nAt Lulworth Cove waves broke through the narrow band of hard Portland limestone, then rapidly eroded the soft clays behind, forming a circular cove backed by resistant chalk.\nHydraulic action and abrasion widen joints in the chalk at Handfast Point, forming caves, arches, the stack Old Harry and stumps.\nDurdle Door is an arch eroded in Portland limestone.\nWeathering (freeze–thaw, carbonation of limestone/chalk) weakens cliffs; rock falls and landslides / slumping on clay cliffs (e.g. Charmouth) cause cliff retreat.\nLongshore drift transports sediment, forming beaches, the sand spits at Studland and the shingle barrier of Chesil Beach where wave energy is low.\n\nLevel 3 (5–6 marks): Thorough explanation of several processes, clearly linked to specific landforms in the named landscape. Detailed and accurate place knowledge. Well-developed, logical line of reasoning.\nLevel 2 (3–4 marks): Reasonable explanation of some processes linked to landforms. Some place detail. Reasoning partly developed.\nLevel 1 (1–2 marks): Basic explanation; processes or landforms described with little linking. Little or no place detail.\n0 marks: no response or no response worthy of credit.\nAnswers without a named UK coastal landscape: max Level 2 (4 marks).` },
      { q: `CASE STUDY — A UK coastal landscape.\nLulworth Cove and Durdle Door on the Jurassic Coast attract large numbers of visitors each year. The area is also used for farming, and the Ministry of Defence uses land to the east as an army training range.\n\nFor a named UK coastal landscape you have studied, examine the impact of human activity on the landscape.`, marks: 6, command: 'Examine', markScheme: `Indicative content (credit any named UK coastal landscape):\nTourism: footpath erosion and trampling of vegetation on the cliff tops (e.g. the path from Lulworth to Durdle Door), increasing runoff and gullying; litter and congestion; car parks and visitor centres change the landscape.\nPositive impacts: income from tourism pays for path repair, conservation and education; World Heritage Site status (2001) protects the landscape.\nSettlement and coastal defences: sea walls, groynes and rock armour (e.g. Swanage, Lyme Regis) alter natural processes and may interrupt longshore drift, increasing erosion elsewhere.\nAt Holderness, rock groynes at Mappleton protect the village but have increased erosion at Great Cowden to the south.\nFarming and military use restrict development and can conserve habitats.\nExamination weighs up the scale and significance of impacts and recognises that some are positive.\n\nLevel 3 (5–6 marks): Thorough examination of a range of impacts, both positive and negative, with detailed place knowledge. Well-developed line of reasoning that weighs significance.\nLevel 2 (3–4 marks): Reasonable examination of some impacts with some place detail. Reasoning partly developed; may be one-sided.\nLevel 1 (1–2 marks): Basic description of impacts with little place detail. Little or no examination.\n0 marks: no response or no response worthy of credit.\nNo named place: max Level 2.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 14 gives information about coastal defences at Mappleton on the Holderness coast.\nIn 1991, a rock revetment and two rock groynes were built at a cost of about £2 million to protect the village and the B1242 road.\nBefore 1991, the cliffs at Mappleton were retreating at about 2 m a year.\nSince 1991, the cliffs at Mappleton have been stable, and the beach between the groynes has widened.\nSouth of the groynes, cliff retreat at Great Cowden increased to over 3 m a year in some years, and some farmland and properties were lost (data partly written for this practice question).\n\nUsing Fig. 14, assess the effectiveness of the hard engineering at Mappleton.`, marks: 6, command: 'Assess', markScheme: `Indicative content:\nEffective: the village and the B1242, an important road for the area, are protected; cliffs stable since 1991 compared with 2 m a year retreat before; wider beach absorbs wave energy; defences have lasted over 30 years.\nLess effective: groynes trap sediment moving south by longshore drift, so beaches south of Mappleton are starved; erosion at Great Cowden increased (over 3 m a year) – terminal groyne effect; farmland and properties lost; costly (£2 million) for a small village; rock armour may need maintenance and is visually intrusive.\nJudgement: effective locally / in the short term but has moved the problem rather than solving it; effectiveness depends on whose viewpoint is considered.\n\nLevel 3 (5–6 marks): Thorough assessment using Fig. 14 and own understanding, considering both effectiveness and limitations, leading to a clear, supported judgement. Well-developed reasoning.\nLevel 2 (3–4 marks): Reasonable assessment with some use of Fig. 14. May be unbalanced or give an implied judgement.\nLevel 1 (1–2 marks): Basic description of the defences or their effects with limited use of Fig. 14. No judgement.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section A — Distinctive Landscapes.\nDuring the winter of 2013–14 a series of storms hit the UK coast. At Dawlish in Devon, waves destroyed the sea wall carrying the main railway line, and along the Dorset coast there were many cliff falls and landslides.\n\nExplain how weather and climate influence the processes that shape UK coastal landscapes.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\nStorms: strong winds over a long fetch produce large destructive waves, increasing erosion by hydraulic action and abrasion; storm surges raise sea level so waves reach higher up cliffs.\nSeasonal change: winter storms remove beach sediment (destructive waves); calmer summer conditions with constructive waves rebuild beaches.\nPrevailing wind direction (south-westerly in the south-west; north-easterly waves in Holderness) controls the direction of longshore drift.\nRainfall: heavy or prolonged rain saturates cliffs (e.g. clay at Holderness or Charmouth), causing slumping and landslides; rainwater causes chemical weathering (carbonation) of chalk and limestone.\nTemperature: freeze–thaw weathering in cold winters loosens rock; hot, dry summers can crack clay cliffs, which then slump when wet.\nClimate change: rising sea levels and more frequent storms may increase erosion.\n\nLevel 3 (5–6 marks): Thorough explanation of how several aspects of weather and climate influence coastal processes, with well-chosen examples. Well-developed, logical reasoning.\nLevel 2 (3–4 marks): Reasonable explanation of some influences, with some examples. Reasoning partly developed.\nLevel 1 (1–2 marks): Basic explanation; may list weather types and processes with little linking.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section A — Distinctive Landscapes.\nOn the coast between Ventnor and Blackgang on the Isle of Wight, the cliffs are made of permeable sandstone and chalk resting on a layer of impermeable clay. The coast road has been lost several times to landslides.\n\nExplain how weathering and mass movement contribute to cliff retreat.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\nWeathering weakens rock in situ: mechanical (freeze–thaw, salt crystal growth), chemical (carbonation of chalk; oxidation), biological (plant roots, burrowing animals).\nWeakened material falls or slides more easily.\nMass movement types: rockfall from steep, jointed cliffs; sliding / landslides along bedding planes; slumping (rotational movement) of saturated clay.\nOn the Isle of Wight, rainwater passes through permeable sandstone and chalk and builds up on the impermeable clay, which becomes lubricated; overlying rock slides seawards.\nWaves at the foot of the cliff remove the debris and undercut the cliff, so the slope becomes unstable again – the process repeats and the cliff retreats.\nHuman activity (building on cliff tops, leaking drains) can add weight and water.\n\nLevel 3 (5–6 marks): Thorough explanation of how weathering and mass movement lead to cliff retreat, with clear links and use of the example. Well-developed reasoning.\nLevel 2 (3–4 marks): Reasonable explanation; weathering or mass movement may be less developed. Some use of the example.\nLevel 1 (1–2 marks): Basic description of processes with little explanation of cliff retreat.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section A — Distinctive Landscapes.\nAt Medmerry in West Sussex, the Environment Agency completed a managed realignment scheme in 2013 at a cost of about £28 million. A new clay embankment was built inland and the old shingle bank was allowed to breach, creating about 180 hectares of new intertidal habitat. Elsewhere in the UK, beaches such as Swanage and Bournemouth have been replenished with sand dredged from offshore.\n\nExamine the advantages and disadvantages of soft engineering for managing UK coastlines.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\nAdvantages: works with natural processes; looks natural and keeps beaches for tourism (beach nourishment at Swanage / Bournemouth); wider beaches absorb wave energy; managed realignment creates salt marsh and mudflat habitat for wildlife (Medmerry is an RSPB reserve), and salt marsh acts as a natural buffer against floods; often cheaper to maintain than hard defences in the long term; does not cause terminal groyne effect.\nDisadvantages: beach nourishment must be repeated as sediment is moved away, so ongoing cost; dredging can damage offshore ecosystems; managed realignment means loss of farmland and some properties, with compensation issues; may not protect high-value areas; large up-front cost (£28 million at Medmerry).\nExamination may weigh which method suits which kind of coastline.\n\nLevel 3 (5–6 marks): Thorough examination of both advantages and disadvantages, with detailed use of examples. Well-developed reasoning, may reach a conclusion.\nLevel 2 (3–4 marks): Reasonable examination; may be unbalanced. Some use of examples.\nLevel 1 (1–2 marks): Basic points about soft engineering with little development.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students investigated whether beach profiles change along a beach in Dorset. Their method was:\n1. Choose three sites along the beach that were easy to reach from the car park.\n2. At each site, place one ranging pole at the water's edge and another 5 m up the beach.\n3. Measure the angle between the poles with a clinometer.\n4. Move both poles 5 m further up the beach and repeat until the back of the beach is reached.\n5. Each student recorded readings in their own notebook. The survey was done once, at high tide.\n\nEvaluate the reliability of the students' method.`, marks: 6, command: 'Evaluate', markScheme: `Indicative content:\nStrengths: systematic method with fixed 5 m intervals along each profile; clinometer and ranging poles give quantitative data that can be compared; three sites allow comparison along the beach.\nWeaknesses: sites chosen for convenience (near car park), so sampling may be biased – systematic or stratified sampling along the whole beach would be more representative; only three sites is a small sample; done once only, at high tide, so much of the beach was underwater / results may not be typical; readings in separate notebooks could lead to recording errors – use a single recording sheet; clinometer readings may vary between users – the same person should read them; ranging poles may sink into sand or shingle.\nImprovements: repeat at low tide / on different days; more sites; standard recording sheet; calculate mean values.\nJudgement on overall reliability required for Level 3.\n\nLevel 3 (5–6 marks): Thorough evaluation of strengths and weaknesses of the method, with a clear judgement about reliability, supported by suggested improvements.\nLevel 2 (3–4 marks): Reasonable evaluation; may focus mainly on weaknesses. Judgement may be implied.\nLevel 1 (1–2 marks): Basic comments on the method with little evaluation.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section A — Distinctive Landscapes.\nThe Lake District in north-west England is a National Park and a UNESCO World Heritage Site. Its landscape includes hill farms with dry-stone walls, conifer plantations, reservoirs such as Thirlmere which supply water to Manchester, slate quarries and busy tourist villages such as Ambleside.\n\nExamine how human activity has shaped one distinctive UK landscape.`, marks: 6, command: 'Examine', markScheme: `Indicative content (credit any distinctive UK landscape, upland or lowland):\nFarming: centuries of sheep grazing have kept fells open and treeless; dry-stone walls and field patterns; in lowlands, hedgerow removal and drainage (e.g. the Fens).\nForestry: conifer plantations (e.g. Whinlatter, Grizedale) change colour and texture of slopes.\nWater supply: Thirlmere dammed and raised in the 1890s, drowning farmland; reservoirs and pipelines change valleys.\nQuarrying and mining: slate quarries (e.g. Honister) leave spoil heaps and scars.\nTourism and settlement: footpath erosion (e.g. on Helvellyn / Scafell Pike), car parks, holiday homes, roads.\nConservation: National Park planning controls limit development and preserve the landscape.\nExamination weighs which activities have had the greatest effect.\n\nLevel 3 (5–6 marks): Thorough examination of a range of human activities, linked clearly to features of a named landscape, with detailed place knowledge and well-developed reasoning.\nLevel 2 (3–4 marks): Reasonable examination of some activities with some place detail.\nLevel 1 (1–2 marks): Basic description of activities with little link to landscape features.\n0 marks: no response or no response worthy of credit.` },
      { q: `Section A — Distinctive Landscapes.\nThe UK's distinctive landscapes are the result of geology, climate, geomorphic processes and human activity.\n\n'Geology is the most important factor in creating the distinctive landscapes of the UK.'\nTo what extent do you agree with this statement? Use examples in your answer. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'To what extent', markScheme: `Indicative content:\nAgree: rock type controls relief – hard igneous and metamorphic rocks in the north and west form uplands (Highlands, Lake District, Snowdonia); soft sedimentary rocks form lowlands in the south and east; chalk forms downland escarpments; granite tors on Dartmoor; at the coast, differential erosion of hard and soft rock forms headlands and bays (Swanage) and coves (Lulworth).\nDisagree / other factors: climate – past glaciation carved corries, arêtes and U-shaped valleys (Lake District); present-day high rainfall in the west and freeze–thaw shape uplands; geomorphic processes such as erosion, longshore drift and deposition create beaches and spits (Spurn Point) regardless of rock; human activity – farming, forestry, reservoirs, settlement and coastal defences have greatly altered many landscapes (Fens drainage, Holderness defences).\nFactors interact: geology provides the foundation but climate and processes act on it, and humans modify it.\nA clear, supported judgement on the extent of agreement is needed for Level 3.\n\nLevel 3 (6–8 marks): A thorough and well-balanced assessment of the importance of geology compared with other factors, using detailed, accurate located examples. Reaches a well-supported conclusion on the extent of agreement.\nLevel 2 (3–5 marks): A reasonable assessment with some located examples; may focus mainly on geology or be unbalanced. Conclusion may be partial or implied.\nLevel 1 (1–2 marks): A basic answer describing factors with little assessment. Few or no examples. No conclusion.\n0 marks: no response or no response worthy of credit.\n\nSPaG:\nHigh performance (3 marks): Learners spell and punctuate with consistent accuracy; use rules of grammar with effective control of meaning overall; use a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): Learners spell and punctuate with considerable accuracy; use rules of grammar with general control of meaning overall; use a good range of specialist terms as appropriate.\nThreshold performance (1 mark): Learners spell and punctuate with reasonable accuracy; use rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; use a limited range of specialist terms as appropriate.\n0 marks: Learners do not reach the threshold performance level, or the response does not relate to the question.` },
      { q: `CASE STUDY — A UK coastal landscape.\n'Coastal landscapes in the UK are shaped more by physical processes than by human activity.'\n\nDiscuss this statement with reference to a named UK coastal landscape you have studied.`, marks: 8, command: 'Discuss', markScheme: `Indicative content (credit any named UK coastal landscape; Holderness used as example):\nPhysical processes: soft boulder clay cliffs eroded by powerful waves from the North Sea (long fetch); slumping after heavy rain; longshore drift carries sediment south to form Spurn Point; average retreat of around 1.5–2 m a year; many villages lost since Roman times.\nHuman activity: sea walls and groynes at Hornsea, Mappleton and Withernsea have stopped erosion locally but increased it further south (terminal groyne effect at Great Cowden); defences at the Easington gas terminal; farming and settlement on cliff tops; Shoreline Management Plan decisions (hold the line vs no active intervention) influence where the landscape changes.\nOn the Jurassic Coast: landforms such as Durdle Door and Old Harry are physically formed; human impacts are mainly footpath erosion and local defences.\nDiscussion: physical processes dominate over most of the coast and the long term; human activity has strong local effects and can change sediment budgets along the whole coast.\n\nLevel 3 (6–8 marks): A thorough discussion of both physical and human influences with detailed, accurate knowledge of a named coastal landscape. Well-developed, balanced reasoning leading to a substantiated conclusion.\nLevel 2 (3–5 marks): A reasonable discussion with some place detail; may be unbalanced. Conclusion may be implied.\nLevel 1 (1–2 marks): A basic answer with limited knowledge and little or no place detail. Little discussion.\n0 marks: no response or no response worthy of credit.\nNo named place: max Level 2.` },
      { q: `CASE STUDY — A UK coastal landscape.\nShoreline Management Plans divide the coast into sections and give each one of four policies: hold the line, advance the line, managed realignment, or no active intervention.\n\nFor a named UK coastal landscape you have studied, evaluate the strategies used to manage the coast.`, marks: 8, command: 'Evaluate', markScheme: `Indicative content (credit any named UK coastal landscape):\nHolderness: hold the line at Hornsea, Withernsea and Bridlington with sea walls, groynes and rock armour – protects towns, tourism and infrastructure, but expensive and may increase erosion downdrift; Mappleton rock groynes and revetment (1991, about £2 million) protected the village but caused the terminal groyne effect at Great Cowden; Easington gas terminal protected by rock revetment; no active intervention on most farmland – cheap and allows sediment to supply beaches and Spurn Point, but farmers and residents lose land and homes, often without compensation.\nJurassic Coast: Swanage sea wall, groynes and beach replenishment protect the resort; most of the coast left to natural processes to protect the World Heritage Site geology.\nCriteria: cost, effectiveness, sustainability, environmental impact, impact on different stakeholders.\nA supported judgement on how successful the strategies are overall is needed for Level 3.\n\nLevel 3 (6–8 marks): A thorough evaluation of a range of strategies against clear criteria, with detailed and accurate place knowledge. Reaches a well-supported judgement.\nLevel 2 (3–5 marks): A reasonable evaluation of some strategies with some place detail. Judgement may be partial.\nLevel 1 (1–2 marks): Basic description of strategies with little evaluation or place detail.\n0 marks: no response or no response worthy of credit.\nNo named place: max Level 2.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 15 describes a geology map of the Dorset coast near Lulworth. The rocks run parallel to the coast. From the sea inland they are: a narrow band of hard Portland and Purbeck limestone forming the coastline; a band of soft Wealden clays and sands; then a wide band of chalk forming the hills behind. At Lulworth Cove the limestone has been breached and a circular cove has formed behind it. Stair Hole, just to the west, is a small inlet where the sea has only just broken through the limestone. Durdle Door, 2 km west, is an arch in Portland limestone.\n\nUsing Fig. 15 and your own understanding, assess the extent to which the landforms of this coast are the result of differences in rock type.`, marks: 8, command: 'Assess', markScheme: `Indicative content:\nRock type: concordant coast – hard limestone parallel to the coast protects soft clays behind; once breached (Stair Hole as an early stage) the soft Wealden beds are eroded rapidly, forming the wide, circular Lulworth Cove; the more resistant chalk at the back limits further erosion; Durdle Door arch forms in resistant Portland limestone.\nOther factors: lines of weakness (joints, faults, folding of the rocks) allow the sea to break through; wave processes – hydraulic action and abrasion; wave refraction through the narrow entrance spreads wave energy in a circular pattern, shaping the cove; weathering and mass movement on cliffs; sea level rise after the last glacial period; human activity (footpaths, tourism) has a minor effect.\nJudgement: rock type and structure are the main control, but marine processes and weaknesses in the rock are needed to create the landforms.\n\nLevel 3 (6–8 marks): A thorough assessment using Fig. 15 and own understanding, weighing rock type against other factors with detailed explanation. Reaches a well-supported conclusion.\nLevel 2 (3–5 marks): A reasonable assessment with some use of Fig. 15; may focus mainly on rock type. Conclusion may be implied.\nLevel 1 (1–2 marks): Basic description of landforms or rocks with little assessment.\n0 marks: no response or no response worthy of credit.` },
      { q: `Resource — Managing the coast at Skipsea, Holderness.\nFig. 16 gives information about Skipsea, a village on the Holderness coast (figures partly written for this practice question).\nThe cliffs are boulder clay about 10 m high and retreat by an average of about 2 m a year.\nThe Shoreline Management Plan policy for Skipsea is no active intervention.\nAbout 25 holiday chalets and several homes on Southfield Lane are within 50 m of the cliff edge.\nOption 1 — Hold the line: build a 1 km rock revetment. Cost about £4 million; would need maintenance; may increase erosion to the south.\nOption 2 — Managed retreat (no active intervention): allow erosion to continue; help move chalets and homes inland; cost about £600 000 in relocation support.\nViews:\nResident: "My house will be gone in a few years. I've paid my taxes and deserve protection."\nCaravan park owner: "Tourism brings jobs. If the cliffs go, so does the business."\nEnvironment Agency officer: "Sediment from these cliffs feeds the beaches to the south and Spurn Point. Defending every village is not sustainable."\nLocal farmer: "I lose a field every few years, but a wall here would only move the problem to my neighbours."\n\nUsing Fig. 16 and your own understanding, evaluate which option would be the more sustainable choice for Skipsea. Justify your decision.`, marks: 12, command: 'Evaluate', markScheme: `Indicative content:\nOption 1 (hold the line): protects homes, chalets and tourist income in the short term; supports residents and caravan park owner; but high cost (£4 million) for a small number of properties; ongoing maintenance; interrupts sediment supply, increasing erosion further south (as at Mappleton / Great Cowden) and starving Spurn Point; not consistent with the Shoreline Management Plan; may not be economically justified (cost–benefit).\nOption 2 (managed retreat): much cheaper (£600 000); works with natural processes; maintains sediment supply to beaches and Spurn; consistent with SMP; supported by Environment Agency and farmer; but residents lose homes and land, emotional and economic costs; loss of tourism income and jobs; compensation may be limited.\nSustainability: economic (cost, jobs), social (community, wellbeing), environmental (sediment budget, habitats); short-term vs long-term; climate change and sea level rise will increase erosion making defence more costly.\nAny decision is acceptable if justified; strongest answers weigh both options, use Fig. 16 data and views, and refer to examples elsewhere on Holderness.\n\nLevel 4 (10–12 marks): A thorough evaluation of both options using Fig. 16 and own understanding, with detailed application of the idea of sustainability (economic, social, environmental). A clear decision is fully justified, with counter-arguments considered.\nLevel 3 (7–9 marks): A clear evaluation of both options with good use of Fig. 16. Sustainability is considered. A decision is made and justified, but may be less balanced.\nLevel 2 (4–6 marks): A reasonable attempt with some use of Fig. 16; may focus mainly on one option. A decision is made with partial justification.\nLevel 1 (1–3 marks): A basic answer that mainly describes the options or copies from Fig. 16. Decision unsupported or absent.\n0 marks: no response or no response worthy of credit.` },
      { q: `Resource — Tourism on the Jurassic Coast.\nFig. 17 gives information about the Dorset and East Devon coast (figures partly written for this practice question).\nThe Jurassic Coast was made England's first natural World Heritage Site in 2001. It stretches about 150 km from Exmouth to Studland Bay and shows rocks from the Triassic, Jurassic and Cretaceous periods.\nLulworth Cove and Durdle Door receive about 700 000 visitors a year; on busy summer days the car parks are full by 10 am and cars park on verges.\nThe path from Lulworth Cove to Durdle Door has been badly eroded and gullied; the estate spends money every year repairing it.\nTourism supports thousands of jobs in Dorset, many seasonal.\nFossil collecting on beaches at Charmouth is encouraged, but hammering of cliffs is discouraged because of rock falls.\nSome local residents complain of congestion, litter and second homes pushing up house prices.\n\nUsing Fig. 17 and your own understanding, discuss whether tourism has more positive than negative effects on the landscape and people of the Jurassic Coast.`, marks: 12, command: 'Discuss', markScheme: `Indicative content:\nPositive: income and jobs in hotels, cafés, transport, guiding; money from car parks and visitors funds path repairs, conservation and visitor centres (e.g. Lulworth Heritage Centre); World Heritage status raises awareness and encourages protection of the landscape; education about geology and fossils; fossil collecting removes fossils from beaches before the sea destroys them.\nNegative: footpath erosion, trampling and gullying on cliffs (Lulworth to Durdle Door); congestion, verge parking and pollution from cars; litter; pressure on the cove and beaches; seasonal, low-paid jobs; second homes increase house prices for locals; people climbing cliffs or hammering increase rock-fall risk.\nDiscussion: many landscape impacts are local and can be managed (surfaced paths, park-and-ride, visitor education), whereas economic benefits are widespread; effects differ for different groups (business owners vs residents) and by season.\nA supported conclusion is required for the top levels.\n\nLevel 4 (10–12 marks): A thorough discussion of positive and negative effects on both landscape and people, using Fig. 17 and detailed own understanding. Arguments are well developed and balanced, leading to a well-substantiated conclusion.\nLevel 3 (7–9 marks): A clear discussion of positive and negative effects with good use of Fig. 17. Some development; conclusion is supported.\nLevel 2 (4–6 marks): A reasonable discussion with some use of Fig. 17; may be unbalanced or focus on people or landscape only. Conclusion may be implied.\nLevel 1 (1–3 marks): A basic answer that mainly lists effects from Fig. 17 with little discussion. No conclusion.\n0 marks: no response or no response worthy of credit.` }
    ]
  },
  '1.5': {
    name: 'Distinctive Landscapes: Rivers',
    questions: [
      { q: `Section A — Distinctive Landscapes.\nFig. 1 (data written for this practice question): a 1:25 000 OS map extract of an upland river valley. The river flows through grid square 8828. A waterfall symbol (the word "Waterfall" with a short line across the river) lies 3/10 of the way east across the square from easting 88 and 7/10 of the way north from northing 28.\n\nGive the six-figure grid reference of the waterfall.`, marks: 1, command: 'Give', markScheme: `1 mark: 883287.\nAllow 882287–884288 (one figure tolerance on the third and sixth figures).\nDo not credit a four-figure reference.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 1 (data written for this practice question): an OS map extract of a river valley. The river crosses the 300 m contour in grid square 7542 and the 200 m contour in grid square 7840. Easting numbers increase to the east and northing numbers increase to the north.\n\nIdentify the direction in which the river is flowing.`, marks: 1, command: 'Identify', markScheme: `1 mark: south-east (SE).\nAccept "towards the south-east" / "downhill to the south-east". Do not accept north-west.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 2 (data written for this practice question): river discharge measured every 3 hours at a gauging station after a storm.\nTime: 00:00 | 03:00 | 06:00 | 09:00 | 12:00 | 15:00 | 18:00 | 21:00\nDischarge (cumecs): 12 | 14 | 22 | 41 | 57 | 49 | 33 | 21\n\nIdentify the peak discharge shown in Fig. 2.`, marks: 1, command: 'Identify', markScheme: `1 mark: 57 cumecs (m³/s). Units not required.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 3: a photograph of the upper course of a river in the Lake District in winter. The steep valley sides are covered with angular rock fragments (scree) beneath bare rock faces. Water has collected in cracks in the rock and the temperature is shown as falling below 0 °C most nights.\n\nIdentify the type of weathering most likely to have produced the scree shown in Fig. 3.`, marks: 1, command: 'Identify', markScheme: `1 mark: freeze-thaw weathering.\nAccept frost shattering / mechanical (physical) weathering by freeze-thaw. Do not accept chemical weathering or "erosion".` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — the River Tees.\nAt High Force in Upper Teesdale, the River Tees drops about 21 m over a band of hard igneous rock that lies on top of softer layers of limestone, sandstone and shale.\n\nState the name of the hard igneous rock that forms the lip of High Force.`, marks: 1, command: 'State', markScheme: `1 mark: Whin Sill (dolerite).\nAccept "dolerite" or "Whin Sill" alone. Accept "whinstone".` },
      { q: `Section A — Distinctive Landscapes.\nFig. 4 (data written for this practice question): an OS map extract of the lower course of a river on a wide, flat flood plain below the 10 m contour. The river has large loops. In grid square 4612 there is a crescent-shaped blue water feature that is not connected to the river, with marsh symbols around its edge, lying next to a meander loop.\n\nIdentify the landform shown in grid square 4612.`, marks: 1, command: 'Identify', markScheme: `1 mark: ox-bow lake.\nAccept "cut-off" / "mortlake" / "billabong". Do not accept "meander" or "lake" alone.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students investigated how the cross-section of a small river changes downstream. They measured the width and depth of the channel at five sites.\n\nSuggest one piece of equipment the students could use to measure the depth of the river.`, marks: 1, command: 'Suggest', markScheme: `1 mark for one of:\n• metre rule / metre stick\n• ranging pole marked in centimetres\n• depth gauge / measuring staff.\nDo not accept "tape measure" on its own (this measures width).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 5 (data written for this practice question): a storm hydrograph for the River Ash. Rainfall began at 02:00 and peak rainfall (14 mm in one hour) was at 06:00. Discharge rose from a base flow of 12 cumecs and reached its peak of 57 cumecs at 18:00 on the same day.\n\nCalculate the lag time. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 18:00 − 06:00 (time of peak discharge minus time of peak rainfall).\n1 mark for answer: 12 hours.\nCorrect answer with no working = 2 marks. Using the start of rainfall (16 hours) = 0 marks for the answer but may get 1 for correct method if peak discharge is used.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 6 (data written for this practice question): an OS map extract of an upland valley. The river rises at a spring at a height of 400 m. It flows down the valley and crosses the 250 m contour at a bridge. The distance along the river from the spring to the bridge, measured on the map, is 3 km.\n\nCalculate the average gradient of the river between the spring and the bridge. Give your answer as a ratio, 1 in ___. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: height difference 400 − 250 = 150 m; horizontal distance 3000 m; 3000 ÷ 150.\n1 mark for answer: 1 in 20.\nAccept 0.05 or 5% if expressed correctly but the ratio form is required for full marks.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 7 (data written for this practice question): an OS map extract at a scale of 1:25 000 (4 cm on the map represents 1 km on the ground). A student measures the straight-line distance between a weir and a road bridge on the river as 6.4 cm on the map.\n\nCalculate the actual distance between the weir and the bridge in kilometres. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 6.4 × 25 000 = 160 000 cm, or 6.4 ÷ 4.\n1 mark for answer: 1.6 km.\nCorrect answer with no working = 2 marks.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students measured the surface speed of a river. They timed how long it took a float to travel 10 m downstream and repeated this three times.\nFig. 8 (data written for this practice question): times taken — trial 1: 24 seconds; trial 2: 26 seconds; trial 3: 25 seconds.\n\nCalculate the mean speed of the river. Give your answer in m/s. (Speed = distance ÷ time.) You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: mean time (24 + 26 + 25) ÷ 3 = 25 s, then 10 ÷ 25.\n1 mark for answer: 0.4 m/s.\nAllow calculating each speed (0.42, 0.38, 0.40) and finding the mean ≈ 0.4 m/s.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 2 (data written for this practice question): discharge of the River Ash after a storm.\nTime: 00:00 | 03:00 | 06:00 | 09:00 | 12:00 | 15:00 | 18:00 | 21:00\nDischarge (cumecs): 12 | 14 | 22 | 41 | 57 | 49 | 33 | 21\n\nCalculate the percentage increase in discharge from 00:00 to the peak discharge. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (57 − 12) ÷ 12 × 100.\n1 mark for answer: 375%.\nCorrect answer with no working = 2 marks.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 9: a storm hydrograph for a river draining a rapidly growing town. Since 1990 fields around the town have been replaced by housing estates, car parks and roads drained by storm drains.\n\nExplain one way that urbanisation can reduce the lag time of a river.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid way + 1 mark for development. e.g.\n• Tarmac and concrete are impermeable (1) so rain cannot infiltrate and flows quickly over the surface to the river as surface runoff (1).\n• Storm drains and gutters carry water directly into the river (1) so it reaches the channel much faster than by throughflow (1).\nMax 2.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 10: a cross-section of a meander on the River Wye. On the inside of the bend the water is shallow and there is a gently sloping bank of sand and pebbles. On the outside of the bend the water is deep and there is a steep bank.\n\nExplain one reason why deposition takes place on the inside of the meander bend.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason + 1 mark for development. e.g.\n• The water is shallower and there is more friction with the bed (1) so the river flows more slowly and loses energy, dropping its load to form a slip-off slope / point bar (1).\n• The thalweg (fastest flow) swings to the outside of the bend (1) so velocity on the inside is low and sediment is deposited (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 11 (data written for this practice question): two OS map extracts of the same river. Extract A (upper course) shows the river crossing closely spaced contours, between 450 m and 300 m, with steep valley sides, a narrow channel and no settlements. Extract B (lower course) shows a wide river with large meanders, no contours crossing the river for several kilometres, a flood plain below 20 m and the town of Riverford built close to the channel.\n\nUsing Fig. 11, describe two differences between the upper and lower course of the river.`, marks: 2, command: 'Describe', markScheme: `1 mark for each difference, comparative and using map evidence, e.g.\n• Upper course is steep (contours close together, 450–300 m) whereas the lower course is flat / below 20 m (1).\n• River is narrow in the upper course but wide in the lower course (1).\n• Lower course has meanders / a flood plain; upper course has a steep narrow valley (1).\n• Upper course is unsettled; lower course has a town beside the river (1).\nMax 2. Do not credit points that only describe one extract.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 12: a photograph of pebbles collected from a river bed. Pebbles collected near the source are large and angular; pebbles collected near the mouth are small and well rounded.\n\nExplain how the process of attrition causes this change in the river's load downstream.`, marks: 2, command: 'Explain', markScheme: `1 mark for the process + 1 mark for the outcome.\n• Attrition is when pieces of load carried by the river knock against each other (1).\n• Corners and edges are chipped off so the stones become smaller and more rounded with distance downstream (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 13: a description of how a river carries its load. Large boulders are rolled along the bed; small pebbles bounce along the bed; fine silt and clay are carried within the water, making it look brown; dissolved minerals cannot be seen.\n\nGive the names of two processes of transportation described in Fig. 13.`, marks: 2, command: 'Give', markScheme: `1 mark each, max 2:\n• traction (boulders rolled along the bed)\n• saltation (pebbles bouncing)\n• suspension (silt and clay carried in the water)\n• solution (dissolved minerals).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 14 (data written for this practice question): an OS map extract of a town on a river. Along both banks of the river through the town centre there is a black line labelled "Flood Wall". Upstream of the town, a large area of flat land beside the river is labelled "Flood Storage Area" with an embankment along its edge. A small reservoir with a dam is shown on a tributary.\n\nUsing Fig. 14, identify two pieces of map evidence that flood management has taken place on this river.`, marks: 2, command: 'Identify', markScheme: `1 mark each, max 2:\n• flood walls along the banks in the town centre\n• flood storage area (washland) upstream with embankment\n• dam / reservoir on the tributary.` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\nUpper Teesdale is made of layers of rock of different hardness, including hard dolerite (the Whin Sill) on top of softer limestone and shale.\n\nExplain one way that geology has influenced a landform in your chosen UK river basin.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid influence + 1 mark for development linked to a landform. e.g.\n• At High Force the hard Whin Sill dolerite resists erosion while the softer shale and limestone below are eroded more quickly (1), so the river drops vertically over the hard rock, forming a waterfall which retreats upstream to form a gorge (1).\n• Impermeable rock / peat in the upper basin causes rapid surface runoff (1) increasing erosion and flood risk downstream (1).\nCredit valid points from any named UK river basin.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 15: a photograph of the steep valley side of a river after several days of heavy rain. A section of saturated soil has slipped downhill in a curved movement, leaving a curved scar at the top of the slope and a mound of soil at the bottom next to the river.\n\nExplain one way that mass movement can affect the shape of a river valley.`, marks: 2, command: 'Explain', markScheme: `1 mark for the process + 1 mark for effect on the valley. e.g.\n• Slumping of saturated soil down the valley sides (1) delivers material into the river which is then transported away, so the valley sides are worn back and the valley becomes wider (1).\n• Soil creep / sliding moves material downslope (1) making the valley sides less steep and widening the V-shape over time (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 16 (data written for this practice question): storm hydrographs for two rivers after the same storm. River X drains a small, steep basin of impermeable granite and moorland; its lag time is 4 hours and its peak discharge is 85 cumecs. River Y drains a basin of permeable chalk with woodland; its lag time is 14 hours and its peak discharge is 30 cumecs.\n\nSuggest one reason why the lag time of River Y is longer than the lag time of River X.`, marks: 2, command: 'Suggest', markScheme: `1 mark for reason + 1 for development. e.g.\n• Chalk is permeable (1) so rain infiltrates and percolates into groundwater and reaches the river slowly by groundwater flow (1).\n• Woodland intercepts rainfall (1) and trees take up water, so less water reaches the river and it arrives more slowly (1).\n• River X's steep slopes / impermeable granite cause fast surface runoff (1) — accept if contrasted with Y.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 17: a photograph of the River Severn in Shropshire. The flat fields next to the river are used for grazing sheep; houses, schools and a hospital have been built on higher ground away from the river. A local plan forbids new building on land that floods.\n\nExplain one way that land-use zoning on a flood plain can reduce the impacts of flooding.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way + 1 mark for development. e.g.\n• Expensive or important buildings are kept away from land at high risk of flooding (1) so fewer properties are damaged and costs of flooding are lower (1).\n• Land closest to the river is left as grazing / parks that can flood safely (1) giving the river space to store water, which reduces flooding downstream (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 18: a photograph of the upper course of a river in the Yorkshire Dales. The river winds between steep hillsides that jut out alternately from each side of a narrow V-shaped valley, so it is not possible to see far up the valley.\n\nExplain how the landform shown in Fig. 18 is formed.`, marks: 3, command: 'Explain', markScheme: `1 mark per explanatory point, max 3. e.g.\n• The river in the upper course has a lot of energy and erodes mainly vertically (downwards) by hydraulic action and abrasion (1).\n• The river is not powerful enough to erode laterally through hard rock, so it winds around areas of more resistant rock (1).\n• This leaves spurs of land that interlock / alternate from each side of the valley (1).\n• Weathering and mass movement on the valley sides create the V-shape (1).\nName of landform (interlocking spurs) alone = 0.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 19: a cross-section of the lower course of a river. The river channel is bordered on each side by raised banks of sediment about 1–2 m higher than the flat flood plain beyond them. The sediment in the banks is coarser than the fine silt further from the river.\n\nExplain how the raised banks shown in Fig. 19 are formed.`, marks: 3, command: 'Explain', markScheme: `1 mark per point, max 3:\n• When the river floods it spreads out over the flood plain (1).\n• As it leaves the channel, the water slows down / friction increases and it loses energy (1).\n• The heaviest / coarsest material is deposited first, closest to the channel (1); finer silt is carried further.\n• Repeated floods build up the banks to form levées (1).` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\nFig. 20: a description of the River Tees estuary at Middlesbrough. In the nineteenth century the channel was straightened by cutting through meander loops; the Tees Barrage was completed upstream in the 1990s; port, steelworks and chemical industries line the banks; large areas of former mudflat at Seal Sands have been reclaimed for industry.\n\nExplain how human activity has affected the geomorphic processes in your chosen UK river basin.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point; development may be credited, max 3. e.g.\n• Straightening the channel (cuts through meanders) increased velocity so less deposition occurs in that section and sediment is carried further downstream (1).\n• The Tees Barrage holds back water so tidal flow is controlled upstream; sediment that would have been deposited upstream is trapped / deposition changes (1).\n• Reclaiming mudflats for industry removed areas where deposition took place and narrowed the estuary (1).\n• Dredging of the shipping channel removes deposited sediment (1).\n• Upland reservoir (Cow Green) regulates flow, reducing peak discharges and erosion downstream (1).\nCredit valid points for any named UK river basin.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 21 (data written for this practice question): a storm hydrograph for the River Ash. Base flow was 12 cumecs at 00:00. Discharge rose slowly to 22 cumecs at 06:00 and then steeply to a peak of 57 cumecs at 12:00. It then fell to 21 cumecs by 21:00.\n\nDescribe the shape of the hydrograph shown in Fig. 21. Use data in your answer.`, marks: 3, command: 'Describe', markScheme: `1 mark per descriptive point, max 3; at least one must use data for full marks.\n• Starts at a base flow of 12 cumecs (1).\n• Rising limb is gentle at first (12 to 22 cumecs, 00:00–06:00) then steep (22 to 57 cumecs in 6 hours) (1).\n• Peaks at 57 cumecs at 12:00 (1).\n• Falling limb is less steep than the rising limb, falling to 21 cumecs by 21:00, still above base flow (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 22: a photograph of a moorland river basin in the Pennines. The hillsides are steep and covered with thin soils and peat that are already waterlogged after a wet week. Heavy rain is falling.\n\nExplain how one physical factor shown in Fig. 22 could increase the risk of the river flooding.`, marks: 3, command: 'Explain', markScheme: `1 mark for a factor + up to 2 marks for development of how it increases flood risk. e.g.\n• The soil is already saturated (1) so no more water can infiltrate (1) and rainfall runs quickly over the surface into the river, raising discharge quickly / shortening lag time (1).\n• Steep slopes (1) cause water to flow quickly downhill as surface runoff (1) so it reaches the channel rapidly and discharge exceeds bankfull capacity (1).\n• Heavy rainfall intensity (1) exceeds the infiltration capacity (1) so overland flow increases (1).\nMax 3 — only one factor credited.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 23: a photograph of the mouth of the River Exe at low tide. Wide areas of mud and sand are exposed where the river meets the sea. Plants grow on the higher parts of the mud, and birds are feeding.\n\nExplain why deposition takes place where a river enters an estuary.`, marks: 3, command: 'Explain', markScheme: `1 mark per point, max 3:\n• The river meets the sea / incoming tide so its flow is slowed (1).\n• It loses energy and can no longer carry its load, so sediment is deposited (1).\n• The estuary is wide and shallow, increasing friction (1).\n• Fine clay particles stick together (flocculate) in salt water and sink (1).\n• Deposition at low tide exposes mudflats; plants trap more sediment to form salt marsh (1).` },
      { q: `Section A — Distinctive Landscapes.\nFig. 24: a photograph of a waterfall where a river flows over a band of hard rock lying on top of softer rock. There is a deep pool at the foot of the waterfall and a steep-sided narrow valley stretches downstream.\n\nUsing an annotated diagram, explain how a waterfall and a gorge are formed.`, marks: 4, command: 'Explain', diagram: true, markScheme: `1 mark per explanatory point; credit points made in annotations, max 4.\n• River flows over a band of hard (resistant) rock on top of soft (less resistant) rock (1).\n• Soft rock is eroded more quickly (hydraulic action / abrasion) creating a step (1).\n• A plunge pool is eroded at the base by hydraulic action and abrasion (1).\n• The soft rock is undercut, leaving an overhang of hard rock (1).\n• The overhang collapses as it is unsupported; the rocks fall into the plunge pool (1).\n• Repeated undercutting and collapse makes the waterfall retreat upstream, leaving a steep-sided gorge (1).\nA diagram without annotations = max 1.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 16 (data written for this practice question): storm hydrographs for two rivers after the same storm. River X drains a small, steep basin of impermeable granite and moorland; its lag time is 4 hours and its peak discharge is 85 cumecs. River Y drains a basin of permeable chalk with woodland; its lag time is 14 hours and its peak discharge is 30 cumecs. Both rivers had a base flow of 10 cumecs.\n\nCompare the storm hydrographs of River X and River Y. Use data in your answer.`, marks: 4, command: 'Compare', markScheme: `1 mark per comparative point; data must be used for full marks, max 4.\n• River X has a shorter lag time than River Y (4 hours compared with 14 hours) (1).\n• River X has a higher peak discharge (85 compared with 30 cumecs) — 55 cumecs higher / almost three times higher (1).\n• River X's rising limb is steeper than River Y's (rises 75 cumecs compared with 20 cumecs above base flow) (1).\n• River X is likely to return to base flow more quickly / has a steeper falling limb (1).\n• Both rivers started at the same base flow (10 cumecs) (1).\nPoints must be comparative; separate descriptions of each river = max 2.` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\n\nExamine how geology and climate have influenced the geomorphic processes in your chosen UK river basin.`, marks: 6, command: 'Examine', markScheme: `Levels of response (AO1 3, AO2 3).\nLevel 3 (5–6 marks): thorough, accurate knowledge of the named river basin; well-developed examination of how BOTH geology and climate influence processes, with clear links to specific landforms or places.\nLevel 2 (3–4 marks): reasonable knowledge with some place detail; explanation of how geology and/or climate influence processes is partly developed.\nLevel 1 (1–2 marks): basic knowledge; generic statements with limited links to processes or place.\n0 marks: no response worthy of credit.\n\nIndicative content (River Tees; credit any UK river basin):\nGeology –\n• hard Whin Sill dolerite over softer limestone and shale: differential erosion forms High Force (about 21 m) and the gorge below it; Cauldron Snout and Low Force also on the dolerite\n• impermeable rocks and peat in the North Pennines encourage surface runoff and rapid rises in discharge\n• carboniferous limestone weathered by solution (carbonation)\n• softer clays and glacial deposits in the lower Tees valley allow lateral erosion and meanders (Yarm, Stockton)\nClimate –\n• very high rainfall on Cross Fell / upland Teesdale (well over 1,500 mm a year) gives high discharge and energy for erosion\n• cold winters cause freeze-thaw weathering on valley sides producing scree; snowmelt raises discharge\n• intense rain storms cause flash floods and slumping\n• drier lowlands: lower energy, more deposition towards the estuary\nExamination may consider which factor is more important at different points in the basin.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 25: a sequence of three sketches of a river on a flood plain. Sketch 1 shows a meander with a narrow neck of land between two bends. Sketch 2 shows the neck narrowed further after erosion. Sketch 3 shows the river flowing straight across the old neck, with a horseshoe-shaped lake left beside it.\n\nExplain how the processes of erosion and deposition interact to form the landforms shown in Fig. 25.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 2, AO2 4).\nLevel 3 (5–6 marks): detailed, sequenced explanation of how erosion AND deposition interact to form meanders and ox-bow lakes; accurate terminology; clearly linked to Fig. 25.\nLevel 2 (3–4 marks): clear explanation of some stages; erosion and deposition both mentioned but links may be less developed.\nLevel 1 (1–2 marks): basic description of the landforms or isolated processes.\n0 marks: no response worthy of credit.\n\nIndicative content:\n• fastest flow (thalweg) on the outside of bends causes lateral erosion by hydraulic action and abrasion, forming a river cliff\n• slower flow on the inside of bends causes deposition, forming a slip-off slope / point bar\n• helicoidal flow carries eroded material from the outside to the inside of the next bend\n• erosion on outer bends narrows the meander neck (Sketch 2)\n• during a flood, the river cuts through the neck, taking the shortest, steepest route (Sketch 3)\n• deposition seals off the old loop from the new channel, forming an ox-bow lake\n• the ox-bow lake may dry out over time to form a meander scar.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 26 (data written for this practice question): a table of factors in the drainage basin of the River Brent.\nBasin size: small (40 km²) | Relief: steep valley sides | Rock: impermeable clay | Land use: 45% urban | Soil: saturated after rain the previous week | Rainfall: 48 mm in 6 hours\n\nUsing Fig. 26, examine the factors that increase the flood risk in this drainage basin.`, marks: 6, command: 'Examine', markScheme: `Levels of response (AO2 3, AO3 3).\nLevel 3 (5–6 marks): thorough examination of several factors from Fig. 26, explaining clearly how each changes the movement of water through the basin, with some judgement about their relative importance or how they combine.\nLevel 2 (3–4 marks): reasonable explanation of some factors with use of Fig. 26; limited judgement.\nLevel 1 (1–2 marks): basic list or description of factors with little explanation.\n0 marks: no response worthy of credit.\n\nIndicative content:\n• small basin: water reaches the river quickly, short lag time\n• steep slopes: rapid surface runoff\n• impermeable clay: little infiltration or percolation, so more overland flow\n• 45% urban: tarmac and concrete are impermeable; drains deliver water directly to the channel\n• saturated soil: no capacity to store more water, so rain runs off\n• intense rainfall (48 mm in 6 hours, 8 mm per hour) may exceed infiltration capacity\n• factors combine: saturated soil and impermeable surfaces together mean almost all rainfall becomes runoff\nJudgement: e.g. human (urban) factors are significant but the intense rainfall on already saturated ground is the trigger.` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\nFig. 27: a list of human activities in a UK river basin — conifer plantations in the uplands; a reservoir; quarrying; farming on the flood plain; towns built beside the river; flood walls and embankments; channel straightening near the mouth.\n\nExplain how human activity has changed the landscape of your chosen UK river basin.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 3, AO2 3).\nLevel 3 (5–6 marks): detailed, accurate knowledge of the named basin; well-developed explanation of how a range of human activities change the landscape and/or the processes acting on it.\nLevel 2 (3–4 marks): some place detail; explanation partly developed.\nLevel 1 (1–2 marks): basic, generic points with little place detail.\n0 marks: no response worthy of credit.\n\nIndicative content (River Tees; credit any UK basin):\n• Cow Green Reservoir in Upper Teesdale (built early 1970s) flooded part of the valley and regulates flow, reducing high discharges and erosion downstream\n• grazing and moorland drainage (grips) in the uplands speed runoff, increasing erosion and peat loss\n• quarrying of dolerite and limestone in Teesdale changes valley sides\n• towns (Barnard Castle, Darlington, Yarm, Stockton) — urban surfaces increase runoff; flood walls in Yarm fix the channel\n• the lower Tees was straightened with cuts through meander loops; the estuary has been dredged and mudflats reclaimed for industry (Seal Sands)\n• Tees Barrage (1995) controls tidal flow and created a non-tidal stretch used for water sports\nExplanation should link activity to its effect on processes or landforms.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 28: an extract from an Environment Agency leaflet about a town in Yorkshire. "After repeated flooding, the town chose a scheme upstream rather than higher walls in the town. Leaky wooden dams were placed in small streams on the moors, thousands of trees were planted, moorland drains were blocked with heather bales, and a large earth embankment (bund) was built to hold back up to about 120,000 m³ of floodwater, releasing it slowly."\n\nAssess the effectiveness of one flood management scheme you have studied.`, marks: 6, command: 'Assess', markScheme: `Levels of response (AO1 2, AO2 4).\nLevel 3 (5–6 marks): accurate, detailed knowledge of a named scheme; thorough assessment of effectiveness using evidence (e.g. performance in a later flood, costs, environmental effects), with a supported judgement.\nLevel 2 (3–4 marks): reasonable knowledge; some assessment, judgement partly supported.\nLevel 1 (1–2 marks): basic description of the scheme; little or no assessment.\n0 marks: no response worthy of credit.\n\nIndicative content (Pickering "Slowing the Flow"; credit any named scheme, e.g. Carlisle, Leeds, Morpeth, Shrewsbury):\n• soft engineering in the upper basin: leaky (large woody debris) dams, heather-bale dams in drains, tree planting – increase interception and storage and lengthen lag time\n• bund stores about 120,000 m³ of water upstream of the town\n• relatively low cost (about £2 million) compared with the cost of large walls in the town\n• Pickering did not flood in the Boxing Day 2015 storms, when other nearby places did\n• environmental benefits: habitats, reduced sediment, little visual impact in the town\n• limitations: may not cope with an extreme event; benefits depend on maintenance; takes years for trees to grow\nJudgement about effectiveness should be supported by evidence.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 29 (data written for this practice question): two storm hydrographs for the same river in the same month after storms of the same size (30 mm of rain). In 1975, before a new housing estate was built, the lag time was 10 hours and the peak discharge was 18 cumecs. In 2020 the lag time was 5 hours and the peak discharge was 34 cumecs. The base flow was 6 cumecs in both years.\n\nAnalyse the changes in the river's storm hydrograph shown in Fig. 29.`, marks: 6, command: 'Analyse', markScheme: `Levels of response (AO3 6: interpret, analyse, explain).\nLevel 3 (5–6 marks): accurate, precise use of data from Fig. 29 (e.g. lag time halved from 10 to 5 hours; peak discharge rose by 16 cumecs / about 89%); well-developed explanation of why the hydrograph changed, linked to the new housing.\nLevel 2 (3–4 marks): some correct use of data; reasonable explanation of the changes.\nLevel 1 (1–2 marks): basic description with little or no data; limited explanation.\n0 marks: no response worthy of credit.\n\nIndicative content:\n• lag time has halved (10 → 5 hours); peak discharge has risen from 18 to 34 cumecs (+16, about 89%)\n• rising limb is steeper in 2020; the hydrograph is more "flashy"\n• base flow unchanged, so the change is due to storm response not overall flow\n• explanation: impermeable roofs, roads and pavements reduce infiltration; drains and gutters carry water directly to the channel; fewer trees / less interception\n• higher peak means a greater flood risk for the town if channel capacity is exceeded\n• limitations: only two storms compared; rainfall intensity or soil moisture may have differed.` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\nFig. 30: a sketch of the lower course of a UK river showing a wide flat flood plain, raised banks along the channel, large meanders and an estuary with mudflats and salt marsh at the mouth.\n\nExplain how the processes in the lower course of your chosen UK river basin have created distinctive landforms.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 3, AO2 3).\nLevel 3 (5–6 marks): detailed explanation of how processes (lateral erosion, deposition during floods, tidal deposition) form several lower-course landforms, with accurate place detail from a named basin.\nLevel 2 (3–4 marks): some explanation of processes and landforms; some place detail.\nLevel 1 (1–2 marks): basic description of landforms; generic.\n0 marks: no response worthy of credit.\n\nIndicative content (River Tees; credit any UK basin):\n• lateral erosion on outer bends and deposition on inner bends form meanders, e.g. the loop at Yarm and near Stockton\n• meander migration and flooding widen the valley floor, building a flood plain of alluvium\n• when the river floods it loses energy and deposits coarse sediment by the channel, forming levées\n• neck cut-through forms ox-bow lakes / meander scars in the lower Tees valley\n• at the estuary, the river meets the tide; flocculation and slow flow deposit mud, forming mudflats and salt marsh at Seal Sands / Teesmouth\n• links to low gradient, large discharge and load carried in suspension.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 31: a newspaper extract from December 2015. "Storm Desmond brought record rainfall to Cumbria — 341 mm fell in 24 hours at Honister Pass. The River Eden burst its banks in Carlisle, flooding thousands of homes. Flood defences built after the 2005 floods were overtopped. Roads and bridges were closed and many homes lost power."\n\nExplain the social and economic impacts of a UK river flood you have studied.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 3, AO2 3).\nLevel 3 (5–6 marks): detailed explanation of both social and economic impacts with accurate details of a named flood; impacts clearly explained, not just listed.\nLevel 2 (3–4 marks): some explanation of social and/or economic impacts with some place detail.\nLevel 1 (1–2 marks): basic list of impacts; generic.\n0 marks: no response worthy of credit.\n\nIndicative content (Storm Desmond, Cumbria 2015; credit any named UK river flood):\nSocial –\n• thousands of homes flooded in Carlisle, Appleby, Keswick and Cockermouth; people evacuated and living in temporary accommodation for months\n• power cuts; schools closed; stress and mental health problems; loss of possessions\n• roads and bridges closed or destroyed (e.g. Pooley Bridge washed away) isolating communities\nEconomic –\n• insurance claims and repair costs in the hundreds of millions of pounds\n• businesses closed, lost trade and jobs; damage to farmland and livestock\n• tourism in the Lake District affected; cost of repairing roads, bridges and defences\nExplanation may link impacts (e.g. bridge loss causing long detours and lost trade).` },
      { q: `Section A — Distinctive Landscapes. CASE STUDY — a river basin landscape in the UK.\n\n'Physical processes are more important than human activity in shaping the landscape of a UK river basin.'\n\nAssess the extent to which you agree with this statement. Use your case study of a UK river basin in your answer.\n[8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Levels of response (AO1 2, AO2 2, AO3 4). Spelling, punctuation and grammar and the use of specialist terminology are assessed in this question.\nLevel 3 (6–8 marks): thorough, accurate knowledge of the named river basin; well-developed assessment of both physical processes and human activity; a clear, substantiated judgement about the extent of agreement.\nLevel 2 (3–5 marks): reasonable knowledge with some place detail; some assessment of both sides; judgement may be unsupported.\nLevel 1 (1–2 marks): basic knowledge; one-sided or descriptive; no clear judgement.\n0 marks: no response worthy of credit.\n\nIndicative content (River Tees; credit any UK basin):\nPhysical processes –\n• differential erosion of Whin Sill and shale forms High Force and its gorge over thousands of years\n• freeze-thaw, mass movement and vertical erosion form V-shaped valleys and interlocking spurs in Upper Teesdale\n• lateral erosion and deposition form meanders, flood plains, levées and the estuary mudflats\n• glaciation shaped the wider valley before the present river\nHuman activity –\n• Cow Green Reservoir regulates flow; moorland drainage and grazing alter runoff\n• channel straightening, dredging, reclamation of Seal Sands and the Tees Barrage have transformed the estuary\n• urbanisation (Darlington, Stockton, Middlesbrough) and flood walls fix the channel and increase runoff\nJudgement: e.g. physical processes dominate in the upper basin and over long timescales, whereas human activity is more important in the lower basin and estuary today.\n\nSPaG (3 marks):\nHigh performance (3 marks): learners spell and punctuate with consistent accuracy; learners use rules of grammar with effective control of meaning overall; learners use a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): learners spell and punctuate with considerable accuracy; learners use rules of grammar with general control of meaning overall; learners use a good range of specialist terms as appropriate.\nThreshold performance (1 mark): learners spell and punctuate with reasonable accuracy; learners use rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; learners use a limited range of specialist terms as appropriate.\n0 marks: the learner writes nothing, or the response does not relate to the question, or errors seriously hinder meaning.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 32: two photographs of flood management in English towns. Photograph A shows a concrete flood wall about 2 m high with a steel flood gate across a road beside the river. Photograph B shows a wide grassy flood plain upstream of a town where the river has been allowed to spill over into a wetland area with ponds, reeds and new trees.\n\n'Soft engineering is more sustainable than hard engineering for managing river flooding.'\n\nUsing Fig. 32 and your own understanding, evaluate this statement.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response (AO2 4, AO3 4).\nLevel 3 (6–8 marks): thorough evaluation of both hard and soft engineering against social, economic and environmental aspects of sustainability; good use of Fig. 32 and examples; well-supported judgement.\nLevel 2 (3–5 marks): reasonable evaluation of both approaches with some use of Fig. 32; judgement partly supported.\nLevel 1 (1–2 marks): basic description of strategies; little evaluation; little use of Fig. 32.\n0 marks: no response worthy of credit.\n\nIndicative content:\nHard engineering (Photograph A) –\n• flood walls and gates give reliable protection to a defined standard and protect high-value property in towns\n• expensive to build and maintain; can be overtopped (e.g. Carlisle 2015); pass water faster downstream; visual impact; no benefit to wildlife\nSoft engineering (Photograph B) –\n• river restoration, washland and wetlands store water and lengthen lag time; create habitats; lower cost; work with natural processes\n• need large areas of land; farmers may lose land; may not protect a town against extreme floods on their own; take time (trees grow slowly)\n• examples: Pickering "Slowing the Flow"; Ripon; River Quaggy (Sutcliffe Park)\nJudgement: e.g. soft engineering is generally more sustainable environmentally and economically, but in densely built-up areas a combination with hard engineering is often needed.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 33 (data written for this practice question): rainfall and river level data for a town on a UK river during a flood in winter. In the week before the flood, 95 mm of rain fell. On the day of the flood, 60 mm fell in 12 hours. Snow on the hills melted as temperatures rose to 9 °C. Since 1980, 30% of the farmland in the basin has been built on and moorland drains have been dug to improve grazing.\n\nAssess the relative importance of physical and human factors in causing this flood.`, marks: 8, command: 'Assess', markScheme: `Levels of response (AO2 4, AO3 4).\nLevel 3 (6–8 marks): thorough assessment of both physical and human factors using Fig. 33 data, explaining clearly how each affects runoff and discharge; well-supported judgement on relative importance.\nLevel 2 (3–5 marks): reasonable assessment of both types of factor with some data; judgement partly supported.\nLevel 1 (1–2 marks): basic identification of factors; little use of Fig. 33; no judgement.\n0 marks: no response worthy of credit.\n\nIndicative content:\nPhysical –\n• 95 mm in the previous week saturated the soil, so infiltration was very low\n• 60 mm in 12 hours (5 mm per hour) is intense rainfall that exceeds infiltration capacity\n• snowmelt added extra water quickly as temperatures rose to 9 °C\n• frozen or saturated ground acts as an impermeable surface\nHuman –\n• 30% of farmland built on: impermeable surfaces and drains speed water to the river, shortening lag time\n• moorland drains (grips) carry water quickly off the hills\n• building on the flood plain increases the impact of the flood\nJudgement: e.g. physical factors triggered the flood and would have caused high discharge anyway; human factors made the flood peak higher and quicker and increased the damage.` },
      { q: `Section A — Distinctive Landscapes.\nFig. 34: a description of a UK river from source to mouth. In its upper course the river flows over hard rock in a steep, narrow valley with waterfalls and interlocking spurs. In its middle course it flows over softer rock in a wider valley with meanders. Near the mouth it flows across a wide flood plain of alluvium into an estuary.\n\nTo what extent is geology the most important factor in creating distinctive river landforms in the UK?`, marks: 8, command: 'To what extent', markScheme: `Levels of response (AO1 2, AO2 2, AO3 4).\nLevel 3 (6–8 marks): thorough assessment of geology and other factors (climate, gradient, discharge, human activity) with accurate examples; well-supported conclusion about the extent.\nLevel 2 (3–5 marks): some assessment of geology and at least one other factor; partial judgement.\nLevel 1 (1–2 marks): basic points; mostly descriptive; no judgement.\n0 marks: no response worthy of credit.\n\nIndicative content:\nGeology –\n• differences in rock hardness cause differential erosion: High Force (Whin Sill dolerite over shale), Aysgarth Falls (limestone)\n• permeable rocks (chalk) give fewer surface rivers and gentler hydrographs; impermeable rocks give dense drainage and flashy rivers\n• soft rocks in lowlands allow lateral erosion and wide flood plains\nOther factors –\n• climate: high upland rainfall gives energy for vertical erosion; freeze-thaw supplies load; storms cause floods that build levées\n• gradient and distance from source affect energy and whether erosion or deposition dominates\n• past glaciation shaped many UK valleys\n• human activity: straightening, dredging, reservoirs and flood walls alter landforms (e.g. Tees estuary)\nJudgement: e.g. geology is most important for erosional landforms in the upper course, but energy, climate and human activity are more important for depositional landforms in the lower course.` },
      { q: `Resource Booklet — flood risk at Ashby Bridge (data written for this practice question).\nFig. 35: Ashby Bridge is a market town of 12,000 people on a meander of the River Ash. The town centre, a primary school and 420 homes lie on the flood plain. The town flooded in 2007, 2012 and 2020; the 2020 flood damaged 180 homes and cost an estimated £9 million. Upstream, the basin is steep moorland and sheep pasture.\nFig. 36: three options proposed by the local council.\nOption 1 — Flood walls and embankments through the town centre. Cost £14 million. Protects to a 1-in-100-year flood standard. Walls 1.5 m high will block views of the river; construction would take two years.\nOption 2 — Natural flood management upstream: 400 leaky dams, blocking moorland drains, 150 hectares of new woodland and a flood storage area on farmland. Cost £4 million. Expected to reduce peak flow by 15–20%; takes 10 years for trees to mature; farmers would be paid compensation.\nOption 3 — Managed retreat: move the primary school and buy 60 of the most at-risk homes, turning the land into a riverside park that can flood. Cost £8 million. Some families do not want to move.\n\nChoose which option you think is the best for Ashby Bridge. Justify your choice. Use Figs. 35 and 36 and your own understanding.`, marks: 12, command: 'Justify', markScheme: `Levels of response (AO2 4, AO3 8). No option is better than another; credit is for the quality of justification.\nLevel 4 (10–12 marks): thorough, well-balanced justification of the chosen option using detailed evidence from Figs. 35 and 36 and wider understanding; clear, reasoned consideration of why the other options were rejected; considers social, economic and environmental dimensions and sustainability over time; coherent, logical conclusion.\nLevel 3 (7–9 marks): clear justification with good use of the resources; some consideration of the rejected options; mostly balanced.\nLevel 2 (4–6 marks): some justification with some use of the resources; limited reference to other options; may be one-sided.\nLevel 1 (1–3 marks): basic choice with limited justification; little or no use of the resources.\n0 marks: no response worthy of credit.\n\nIndicative content:\nOption 1 – reliable protection for 420 homes and the town centre; £14 million is less than two floods like 2020 (£9 million each); but expensive, visual impact on views of the river, may move flooding downstream, could be overtopped as climate change increases rainfall.\nOption 2 – cheapest (£4 million); works with natural processes; increases interception and storage, lengthening lag time; biodiversity and carbon storage benefits; but a 15–20% reduction may not prevent flooding; 10 years for trees to mature; farmers lose land.\nOption 3 – removes the most vulnerable people and the school from risk permanently; creates green space that stores floodwater; but only 60 of 420 homes moved; social conflict over forced moves; loss of community.\nCombination – credit candidates who argue for a combination (e.g. Option 2 with smaller walls) if justified.\nEvaluation may consider cost-benefit (flooding three times since 2007), climate change, equity and long-term sustainability.` },
      { q: `Resource Booklet — the River Tees basin.\nFig. 37: a description of the River Tees. The river rises at about 800 m on the slopes of Cross Fell in the North Pennines, an area of peat moorland with high rainfall. It flows east for about 130 km through Upper Teesdale (Cow Green Reservoir, Cauldron Snout, High Force), past Barnard Castle and Darlington, meandering through the lowlands to Yarm and Stockton, and reaches the North Sea at Teesmouth near Middlesbrough.\nFig. 38: a list of views about the future of the Tees basin.\nConservation officer: "Upper Teesdale has rare arctic-alpine plants and peat bogs that store carbon. Restoring the peat would slow the flow of floodwater."\nFarmer in Teesdale: "Sheep farming keeps people living in the dale. If drains are blocked my land will be wetter."\nResident of Yarm: "Yarm has flooded before. We need stronger defences in the town."\nPort manager at Teesport: "The estuary must be dredged so large ships can reach the port and new industry can grow."\n\nUsing Figs. 37 and 38 and your own understanding, assess the extent to which human activity in the Tees basin can be managed sustainably in the future.`, marks: 12, command: 'Assess', markScheme: `Levels of response (AO1 2, AO2 4, AO3 6).\nLevel 4 (10–12 marks): thorough, accurate knowledge of the Tees basin; detailed, balanced assessment of different human activities and stakeholder views from Fig. 38, considering social, economic and environmental sustainability and links between upper and lower basin; well-substantiated judgement.\nLevel 3 (7–9 marks): clear knowledge; good use of the resources; reasonable assessment of several activities; judgement mostly supported.\nLevel 2 (4–6 marks): some knowledge and use of resources; assessment limited or one-sided.\nLevel 1 (1–3 marks): basic points; limited use of resources; no judgement.\n0 marks: no response worthy of credit.\n\nIndicative content:\n• upper basin: peat restoration and blocking drains slow runoff, store carbon and protect rare plants, reducing flood risk downstream at Yarm and Stockton — but conflicts with farming income; possible payments to farmers for land management\n• Cow Green Reservoir already regulates flow and supplies water to Teesside industry\n• middle/lower basin: Yarm flood walls protect property but are costly and may increase flows downstream; soft measures upstream could reduce the height needed\n• estuary: dredging and port growth bring jobs, but disturb sediment and habitats; Seal Sands mudflats and salt marsh are important for birds and seals\n• Tees Barrage manages water levels and supports regeneration and leisure\n• climate change may increase winter rainfall and sea-level rise at the estuary, making management harder\nJudgement: e.g. human activity can be managed more sustainably if the whole basin is managed together (upstream storage, compensation for farmers, protecting key habitats), but some conflicts between economic growth and conservation cannot be fully resolved.` }
    ]
  },
  '1.6': {
    name: 'Sustaining Ecosystems: Tropical Rainforests',
    questions: [
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 1: a world map showing the distribution of tropical rainforests. Rainforest is shaded in the Amazon basin of South America, the Congo basin of central Africa, and South-East Asia (Indonesia, Malaysia and Papua New Guinea). Almost all of the shaded areas lie between two dashed lines of latitude at 23.5°N and 23.5°S, and the largest areas sit on a solid line at 0°.\n\nIdentify the line of latitude at 0° that runs through the largest areas of tropical rainforest shown on Fig. 1.`, marks: 1, command: 'Identify', markScheme: `Equator (1)\nDo not credit Tropic of Cancer / Tropic of Capricorn.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 2: a climate table for Manaus, Brazil, in the Amazon rainforest (data written for this practice question).\n\nMonth | J | F | M | A | M | J | J | A | S | O | N | D\nTemperature (°C) | 26.5 | 26.4 | 26.6 | 26.8 | 27.0 | 27.1 | 27.3 | 28.0 | 28.4 | 28.3 | 27.8 | 27.2\nRainfall (mm) | 260 | 290 | 315 | 300 | 255 | 115 | 90 | 60 | 85 | 125 | 185 | 220\n\nUsing Fig. 2, calculate the annual temperature range for Manaus.`, marks: 1, command: 'Calculate', markScheme: `2 °C / 2.0 °C (1)\n(28.4 − 26.4 = 2.0)\nUnits not required.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 3: a photograph of a leaf from a tree in the understorey of the Borneo rainforest, Malaysia. The leaf is large, smooth and waxy, and narrows at the end into a long, pointed tip from which water droplets are dripping.\n\nIdentify the name given to the pointed end of the leaf shown in Fig. 3.`, marks: 1, command: 'Identify', markScheme: `drip tip (1)\nAllow drip-tip leaf.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 4: a table showing the area of forest cleared each year in the Brazilian Amazon (figures rounded from Brazil's national satellite monitoring programme, PRODES).\n\nYear | Area deforested (km²)\n2004 | 27,800\n2008 | 12,900\n2012 | 4,600\n2016 | 7,900\n2019 | 10,100\n2021 | 13,000\n2023 | 9,000\n\nIdentify the year shown in Fig. 4 with the lowest area of deforestation.`, marks: 1, command: 'Identify', markScheme: `2012 (1)` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 5: a nutrient cycle (Gersmehl) diagram for a tropical rainforest. It has three circles labelled biomass, litter and soil. The biomass circle is very large, the litter circle is small and the soil circle is small. The arrow from litter to soil is very thick and the arrow from soil to biomass is very thick.\n\nIdentify the store in Fig. 5 which holds the most nutrients in a tropical rainforest.`, marks: 1, command: 'Identify', markScheme: `biomass (1)\nAllow plants / trees / vegetation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn the Amazon rainforest, the canopy layer forms an almost continuous roof of leaves about 30 m above the ground, and less than 2% of sunlight reaches the forest floor.\n\nGive one way in which plants on the forest floor are adapted to the low light levels.`, marks: 1, command: 'Give', markScheme: `Any one from:\n• large / broad leaves to capture as much light as possible (1)\n• dark green leaves / extra chlorophyll to absorb more light (1)\n• leaves that can turn / angle to face the light (1)\n• fast growth up into gaps when a tree falls (1)\n• grow as epiphytes or lianas to reach light higher up (1)\nAllow any other valid adaptation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 2: a climate table for Manaus, Brazil, in the Amazon rainforest (data written for this practice question).\n\nMonth | J | F | M | A | M | J | J | A | S | O | N | D\nTemperature (°C) | 26.5 | 26.4 | 26.6 | 26.8 | 27.0 | 27.1 | 27.3 | 28.0 | 28.4 | 28.3 | 27.8 | 27.2\nRainfall (mm) | 260 | 290 | 315 | 300 | 255 | 115 | 90 | 60 | 85 | 125 | 185 | 220\n\nCalculate the total annual rainfall for Manaus. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `2300 mm (2)\n1 mark for correct working: 260 + 290 + 315 + 300 + 255 + 115 + 90 + 60 + 85 + 125 + 185 + 220\n1 mark for the correct answer 2300 (mm)\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 4: a table showing the area of forest cleared each year in the Brazilian Amazon (figures rounded from Brazil's national satellite monitoring programme, PRODES).\n\nYear | Area deforested (km²)\n2004 | 27,800\n2008 | 12,900\n2012 | 4,600\n2016 | 7,900\n2019 | 10,100\n2021 | 13,000\n2023 | 9,000\n\nCalculate the percentage change in the area deforested between 2004 and 2012. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `−83.5% / a decrease of 83.5% (2)\n1 mark for working: (4,600 − 27,800) ÷ 27,800 × 100 OR −23,200 ÷ 27,800 × 100\n1 mark for −83.5 (allow 83.5% decrease)\nCorrect answer with no working = 1 mark only.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 1: a world map showing the distribution of tropical rainforests. Rainforest is shaded in the Amazon basin of South America, the Congo basin of central Africa, and South-East Asia (Indonesia, Malaysia and Papua New Guinea). Smaller areas are shaded in Central America, eastern Madagascar and along the west coast of India. Almost all of the shaded areas lie between 23.5°N and 23.5°S.\n\nUsing Fig. 1, describe the global distribution of tropical rainforests.`, marks: 2, command: 'Describe', markScheme: `Up to 2 marks from:\n• found between the Tropics of Cancer and Capricorn / within about 23.5° of the Equator (1)\n• mostly along / either side of the Equator (1)\n• largest area in South America / the Amazon basin (1)\n• also in central Africa (Congo basin) and South-East Asia, e.g. Indonesia / Malaysia (1)\n• smaller areas in Central America / Madagascar / India (1)\nMaximum 1 mark for a list of continents with no reference to latitude or pattern.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 6: a photograph of a kapok tree in the Amazon rainforest. The tree is about 50 m tall and towers above the canopy. At its base, large triangular roots spread out above the ground, up to 3 m high, like walls supporting the trunk.\n\nExplain one way the roots shown in Fig. 6 help the tree to survive in the tropical rainforest.`, marks: 2, command: 'Explain', markScheme: `1 mark for identifying the adaptation, 1 mark for development.\ne.g.\n• buttress roots support / stabilise a very tall tree (1) because the soil is thin / roots are shallow, so the tree would otherwise blow over (1)\n• the roots spread out over a large area near the surface (1) to absorb nutrients from the thin, nutrient-rich top layer of the soil (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nThe three-toed sloth lives in the canopy of the Amazon rainforest. It moves very slowly, hangs upside down from branches using long curved claws, and green algae grow in its fur.\n\nExplain one way the sloth is adapted to life in the tropical rainforest.`, marks: 2, command: 'Explain', markScheme: `1 mark for the adaptation, 1 mark for development.\ne.g.\n• algae make its fur green (1) which camouflages it among the leaves so it is hidden from predators such as harpy eagles / jaguars (1)\n• it moves slowly / has a slow metabolism (1) so it uses little energy on a low-energy diet of leaves (1)\n• long curved claws (1) let it hang from / grip branches high in the canopy where its food is (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nThe Amazon rainforest covers about 5.5 million km² and is home to around 10% of the world's known species.\n\nExplain one reason why tropical rainforests have such high biodiversity.`, marks: 2, command: 'Explain', markScheme: `1 mark for the reason, 1 mark for development.\ne.g.\n• hot, wet climate all year (1) so plants can grow continuously / there is a constant supply of food (1)\n• many layers of vegetation (emergent, canopy, understorey, shrub layer) (1) provide many different habitats / niches for species (1)\n• the forest has existed for millions of years without major disruption (e.g. glaciation) (1) so species have had a long time to evolve (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nScientists estimate that the Amazon rainforest stores about 150 billion tonnes of carbon in its trees and soils.\n\nExplain one way tropical rainforests are important at a global scale.`, marks: 2, command: 'Explain', markScheme: `1 mark for the point, 1 mark for development.\ne.g.\n• they are a carbon sink / store (1) because trees absorb CO₂ in photosynthesis, which reduces the enhanced greenhouse effect / climate change (1)\n• they release large amounts of water vapour through transpiration (1) which affects rainfall patterns far beyond the forest (1)\n• they are a source of medicines (1) e.g. the rosy periwinkle (Madagascar) is used to treat leukaemia (1)\n• they contain a huge gene pool / biodiversity (1) which may provide future foods / medicines (1)\nAllow any other valid explanation. Do not credit purely local benefits (e.g. jobs for local people).` },
      { q: `Section A — Sustaining Ecosystems.\n\nThe Yanomami people live in the Amazon rainforest on the border of Brazil and Venezuela. They clear small plots of forest, grow crops such as manioc and plantain for a few years, then move on and let the forest grow back.\n\nExplain one way this way of life is sustainable.`, marks: 2, command: 'Explain', markScheme: `1 mark for the point, 1 mark for development.\ne.g.\n• plots are small and abandoned after a few years (1) so the forest can regenerate / nutrients return to the soil before the land is used again (1)\n• they only take what they need from the forest (1) so resources such as animals and plants are not used up for future generations (1)\n• ash from burning adds nutrients to the soil (1) so no chemical fertilisers are needed (1)\nAllow any other valid explanation. Do not credit a description of shifting cultivation without explaining why it is sustainable for the second mark.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 7: a pie chart showing the causes of deforestation in the Brazilian Amazon (data written for this practice question): cattle ranching 70%; small-scale farming 12%; large-scale commercial farming (soya) 8%; logging 5%; mining, roads and dams 5%.\n\nUsing Fig. 7, describe the causes of deforestation in the Brazilian Amazon.`, marks: 2, command: 'Describe', markScheme: `Up to 2 marks from:\n• cattle ranching is the main cause / the largest cause (1)\n• cattle ranching causes 70% / over two-thirds of deforestation (1)\n• farming as a whole (ranching, small-scale and commercial) accounts for 90% (1)\n• logging and mining/roads/dams are the smallest causes at 5% each (1)\nMaximum 1 mark for a list of causes without use of the data.` },
      { q: `Section A — Sustaining Ecosystems.\n\nAfter forest in Rondônia state, Brazil, was cleared for cattle pasture, farmers found that the grass grew poorly after only a few years.\n\nExplain one impact of deforestation on rainforest soils.`, marks: 2, command: 'Explain', markScheme: `1 mark for the impact, 1 mark for development.\ne.g.\n• the soil loses its nutrients (1) because there is no leaf litter to replace them / the nutrient cycle is broken (1)\n• heavy rain leaches nutrients out of the soil (1) because there is no canopy to intercept the rain / no roots to take up nutrients (1)\n• soil erosion increases (1) because there are no roots to bind the soil and rain hits the ground directly (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 2: a climate table for Manaus, Brazil, in the Amazon rainforest (data written for this practice question). Monthly temperatures are between 26.4 °C and 28.4 °C. Rainfall is over 100 mm in every month except July (90 mm), August (60 mm) and September (85 mm), with a peak of 315 mm in March.\n\nSuggest one reason why Manaus has heavy rainfall in most months of the year.`, marks: 2, command: 'Suggest', markScheme: `1 mark for the reason, 1 mark for development.\ne.g.\n• high temperatures / intense sun near the Equator heat the ground (1) so warm, moist air rises, cools and condenses, giving convectional rainfall (1)\n• the rainforest transpires large amounts of water (1) which is recycled into clouds and falls again as rain (1)\n• Manaus is near the Equator where air rises in a low pressure zone / the ITCZ (1) so clouds form and rain falls on most days (1)\nAllow any other valid suggestion.` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn the Amazon rainforest, the Brazil nut tree can only be pollinated by large orchid bees. Its hard seed pods are opened by agoutis (a rodent), which eat some seeds and bury others, some of which grow into new trees.\n\nExplain one way the Brazil nut tree would be affected if agoutis were removed from the forest.`, marks: 2, command: 'Explain', markScheme: `1 mark for the effect, 1 mark for development.\ne.g.\n• fewer seed pods would be opened / seeds would not be buried (1) so fewer new Brazil nut trees would grow / the tree population would decline (1)\n• seeds would not be spread away from the parent tree (1) so seedlings would compete with the parent for light and nutrients (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 8: an advertisement for a lodge on the Rio Negro near Manaus, Brazil. "Stay in our eco-lodge built from local materials. Guided canoe trips with local guides. Groups of no more than 12. Part of every booking pays for local schools and forest rangers."\n\nUsing Fig. 8, explain one way ecotourism can help to manage the tropical rainforest sustainably.`, marks: 2, command: 'Explain', markScheme: `1 mark for the point (linked to Fig. 8), 1 mark for development.\ne.g.\n• local people are employed as guides (1) so they earn money from keeping the forest rather than cutting it down (1)\n• small group sizes (1) reduce damage / disturbance to wildlife and habitats (1)\n• money from bookings pays for forest rangers (1) who protect the forest from illegal logging / poaching (1)\n• lodge built from local materials (1) so less environmental impact / fewer resources transported (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nThe Amazon Fund was set up by Brazil in 2008. Norway has been its largest donor, giving money for projects that reduce deforestation and support sustainable use of the forest.\n\nExplain one way international agreements or funds can help to protect tropical rainforests.`, marks: 2, command: 'Explain', markScheme: `1 mark for the point, 1 mark for development.\ne.g.\n• richer countries pay rainforest countries to keep forest standing (1) so there is an economic incentive not to deforest / it replaces lost income (1)\n• money pays for monitoring, e.g. satellite surveillance and enforcement (1) so illegal clearance can be detected and stopped (1)\n• REDD+ schemes reward countries for reducing emissions from deforestation (1) which helps the global fight against climate change (1)\n• debt-for-nature swaps cancel part of a country's debt (1) in return for money being spent on conservation (1)\nAllow any other valid explanation.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 9: a climate table for two global ecosystems (data written for this practice question).\n\n | Tropical rainforest (Manaus, Brazil) | Hot desert (Riyadh, Saudi Arabia)\nAnnual rainfall (mm) | 2300 | 100\nMean temperature of warmest month (°C) | 28.4 | 36.0\nMean temperature of coolest month (°C) | 26.4 | 14.5\n\nUsing Fig. 9, compare the climate of the tropical rainforest and the hot desert.`, marks: 2, command: 'Compare', markScheme: `Up to 2 marks for comparative statements using the data:\n• the rainforest is much wetter / has 2200 mm more rain / 23 times as much rain as the desert (1)\n• the desert has a much larger temperature range (21.5 °C) than the rainforest (2 °C) (1)\n• the desert has a hotter warmest month (36 °C v 28.4 °C) / a cooler coolest month (14.5 °C v 26.4 °C) (1)\nMaximum 1 mark if only one place is described / no comparative language.` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn the Amazon rainforest, toucans eat fruit from canopy trees and pass the seeds out in their droppings, often far from the parent tree. Fallen leaves are broken down by fungi, termites and bacteria on the forest floor.\n\nExplain how plants and animals are interdependent in tropical rainforest ecosystems.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation. 1 mark per valid point, with further marks for development.\ne.g.\n• plants provide food (fruit, leaves, nectar) and habitats / shelter for animals (1)\n• animals such as toucans disperse seeds (1), allowing new trees to grow away from the parent (1)\n• animals such as bees / bats pollinate flowers (1) so plants can reproduce (1)\n• decomposers break down dead leaves (1) releasing nutrients into the soil which plants take up (1)\n• if one species is lost, others that depend on it are affected (1)\nMaximum 2 marks if no clear two-way link between plants and animals.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 10: a world map of global ecosystems. Tropical rainforest is shown along the Equator; savanna grassland lies to the north and south of it; hot deserts are found at about 15°–30° north and south of the Equator, such as the Sahara; temperate deciduous forest covers western Europe at about 45°–55°N; tundra lies around the Arctic Ocean north of about 65°N.\n\nUsing Fig. 10, explain how climate influences the global distribution of ecosystems.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation.\ne.g.\n• near the Equator the sun is overhead, giving high temperatures and rising air (low pressure) (1) which brings heavy rain all year, so tropical rainforest grows (1)\n• at about 30° N and S air sinks (high pressure) (1) so there is little rain / cloud, giving hot deserts (1)\n• at high latitudes temperatures are low / the growing season is short (1) so only small, low-growing plants survive, giving tundra (1)\n• savanna lies between rainforest and desert because it has a wet and a dry season (1)\nMaximum 1 mark for description of the pattern with no explanation using climate.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 5: a nutrient cycle (Gersmehl) diagram for a tropical rainforest. The biomass store is very large while the litter and soil stores are small. The transfers from litter to soil and from soil to biomass are shown by very thick arrows; the loss of nutrients by leaching from the soil is shown by a medium arrow.\n\nUsing Fig. 5, explain why nutrients cycle so rapidly in tropical rainforests.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation.\ne.g.\n• the hot, wet climate allows decomposers (fungi, bacteria, insects) to work all year (1) so leaf litter breaks down in a few weeks / the litter store is small (1)\n• leaves fall all year because there is no distinct season (1) so there is a constant supply of litter (1)\n• plants grow fast and have shallow roots (1) so nutrients released into the soil are quickly taken back up into the biomass (1)\n• heavy rain leaches nutrients (1) so plants must absorb them quickly before they are lost (1)\nCredit reference to Fig. 5 (e.g. thick arrows, small litter store).` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn August 2019, satellite images showed thousands of fires burning across the Brazilian Amazon, many started deliberately to clear land for cattle pasture.\n\nExplain how deforestation in tropical rainforests can contribute to climate change.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation.\ne.g.\n• burning trees releases the carbon they store as CO₂ (1) which adds to the greenhouse gases in the atmosphere (1) and enhances the greenhouse effect / traps more heat (1)\n• fewer trees remain to absorb CO₂ through photosynthesis (1) so the forest is a smaller carbon sink (1)\n• cattle ranching on cleared land releases methane (1), a powerful greenhouse gas (1)\n• less transpiration means less cloud / rainfall (1), which can lead to drought and more fires (1)\nMaximum 2 marks for points that do not link to the greenhouse effect / climate.` },
      { q: `Section A — Sustaining Ecosystems.\n\nLianas are woody vines rooted in the soil of the rainforest floor that climb up tree trunks to the canopy. Epiphytes, such as orchids and bromeliads, grow on the branches of canopy trees and are not rooted in the soil at all.\n\nExplain how lianas and epiphytes are adapted to the conditions in the tropical rainforest.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation; must refer to both plant types for full marks.\ne.g.\n• lianas climb trees using other trees for support (1) so they can reach sunlight in the canopy without growing a thick trunk (1)\n• epiphytes grow high on branches (1) to reach light that does not reach the dark forest floor (1)\n• epiphytes collect water and nutrients from rain and from debris in their leaves / aerial roots (1) because they have no access to the soil (1)\nMaximum 2 marks if only one plant type is addressed.` },
      { q: `Section A — Sustaining Ecosystems.\n\nConstruction of the Trans-Amazonian Highway (BR-230) began in Brazil in 1970. Satellite images now show a "fishbone" pattern of clearings branching out from the road.\n\nExplain how road building can lead to further deforestation of tropical rainforests.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed explanation.\ne.g.\n• forest is cleared directly to build the road (1)\n• roads give access to areas that were remote (1), so loggers, miners and farmers can move in (1)\n• side roads branch off the main road (1) giving the fishbone pattern of clearance (1)\n• roads make it cheaper to transport timber / cattle / soya to market (1) so clearing land becomes more profitable (1)\n• settlers are encouraged to migrate along the road (1) and clear land for farms (1)` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 4: a table showing the area of forest cleared each year in the Brazilian Amazon (figures rounded from Brazil's national satellite monitoring programme, PRODES).\n\nYear | Area deforested (km²)\n2004 | 27,800\n2008 | 12,900\n2012 | 4,600\n2016 | 7,900\n2019 | 10,100\n2021 | 13,000\n2023 | 9,000\n\nDescribe the trend shown in Fig. 4 and suggest reasons for it.`, marks: 4, command: 'Describe', markScheme: `Up to 2 marks for description using data, up to 2 marks for reasons.\nDescription:\n• deforestation fell sharply from 27,800 km² in 2004 to 4,600 km² in 2012 / by 83.5% (1)\n• it then rose again to 13,000 km² in 2021, nearly three times the 2012 figure (1)\n• it fell again to 9,000 km² in 2023 (1)\nReasons (suggestions):\n• the fall to 2012 due to more satellite monitoring / enforcement / new protected areas / the soya moratorium (2006) / the Amazon Fund (1)\n• the rise after 2012 due to weaker enforcement / government support for farming and mining / high global demand for beef and soya (1)\n• the fall after 2021 due to a change in government policy / renewed enforcement and international funding (1)\nAllow any other valid suggestion.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 11: information about the Bolsa Floresta (Forest Allowance) programme in Amazonas state, Brazil, run by the Amazonas Sustainable Foundation since 2007.\n• Families living in reserves receive a small monthly payment if they agree not to clear primary forest.\n• Communities receive money for schools, health posts and boats.\n• Funding helps families sell sustainable products such as Brazil nuts and fish.\n• Some funding comes from companies and governments abroad.\n\nUsing Fig. 11, explain how this programme manages the rainforest sustainably at both a local and a global scale.`, marks: 4, command: 'Explain', markScheme: `Up to 2 marks for the local scale and up to 2 marks for the global scale (1 for a point from Fig. 11, 1 for development).\nLocal:\n• families are paid not to clear forest (1) so they gain income while the forest is kept for future generations (1)\n• money for schools / health posts improves quality of life (1) so people are less likely to leave or turn to illegal logging (1)\n• selling Brazil nuts / fish (1) gives an income from the standing forest rather than from cutting it down (1)\nGlobal:\n• funding from abroad (1) shows the rest of the world sharing the cost of protecting a global resource (1)\n• keeping forest standing keeps carbon stored (1) which reduces global CO₂ emissions / climate change (1)\n• protects biodiversity of global value (1)\nMaximum 2 marks if only one scale is addressed.` },
      { q: `Section A — Sustaining Ecosystems.\n\nTropical rainforests are made up of climate, soils, water, plants, animals and people, all linked together.\n\nExplain how the characteristics of tropical rainforests are interdependent.`, marks: 6, command: 'Explain', markScheme: `Levels of response. AO1 (2 marks): knowledge of rainforest characteristics. AO2 (4 marks): understanding of the links between them.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of the characteristics. A thorough explanation of the interdependence between several components, with a well-developed line of reasoning which is clear and logically structured. Information is relevant and substantiated.\nLevel 2 (3–4 marks): Reasonable knowledge and understanding. A reasonable explanation of some links between components, with a line of reasoning that has some structure.\nLevel 1 (1–2 marks): Basic knowledge. A basic explanation, mostly describing separate characteristics, with limited links.\n0 marks: no response worthy of credit.\nIndicative content:\n• climate–plants: hot, wet climate allows fast, year-round growth; transpiration from trees returns moisture that falls as rain (up to half of Amazon rainfall is recycled)\n• plants–soil: leaf litter decomposes rapidly to give nutrients; roots bind soil; canopy protects soil from heavy rain; remove trees and the soil is leached / eroded\n• plants–animals: food and habitat; animals pollinate and disperse seeds (e.g. agoutis and Brazil nut trees)\n• people: indigenous people depend on forest for food, medicine, shelter; shifting cultivation lets forest recover; large-scale clearance breaks the links\n• a change to one component (e.g. deforestation) affects all the others\nTo reach Level 3, answers must explain links in both directions between at least three components.` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn Malaysia, the area of oil palm plantations grew rapidly from the 1970s onwards, much of it on land that was once tropical rainforest in Sabah and Sarawak on the island of Borneo.\n\nExamine the threats to tropical rainforests from human activity.`, marks: 6, command: 'Examine', markScheme: `Levels of response. AO1 (2 marks): knowledge of threats. AO2 (4 marks): examining their causes and significance.\nLevel 3 (5–6 marks): Thorough knowledge of a range of human threats. A thorough examination of how and why each threatens the rainforest, with well-supported evidence from named examples and a well-developed line of reasoning.\nLevel 2 (3–4 marks): Reasonable knowledge of some threats. A reasonable examination with some use of examples and some structure.\nLevel 1 (1–2 marks): Basic knowledge of threats. A basic, mainly descriptive response with little use of examples.\n0 marks: no response worthy of credit.\nIndicative content:\n• commercial farming: oil palm in Malaysia / Indonesia; cattle ranching and soya in Brazil — large areas cleared, driven by global demand\n• logging: legal and illegal, for valuable hardwoods such as mahogany; opens up the forest with roads\n• mining: e.g. Carajás iron ore mine in Brazil; gold mining polluting rivers with mercury\n• road building: e.g. Trans-Amazonian Highway, opening remote areas to settlers\n• HEP dams: e.g. Belo Monte dam on the Xingu River flooded forest and displaced people\n• population pressure / resettlement schemes; fires used to clear land\n• climate change as an indirect human threat: drought increases fire risk\n• examination may weigh which threats are most significant, or local v global drivers\nLevel 3 requires use of at least one named example.` },
      { q: `Section A — Sustaining Ecosystems.\n\nCASE STUDY — A tropical rainforest.\n\nExamine how one strategy has been used to manage your named tropical rainforest sustainably.`, marks: 6, command: 'Examine', markScheme: `Levels of response. AO1 (2 marks): knowledge of the case study and strategy. AO2 (4 marks): examining how it achieves sustainability.\nLevel 3 (5–6 marks): Thorough, accurate knowledge of a named rainforest and one strategy. A thorough examination of how the strategy works and how far it meets the needs of people today without compromising future generations, with case-study detail and a well-developed line of reasoning.\nLevel 2 (3–4 marks): Reasonable knowledge of a strategy, with some case-study detail and some examination of sustainability.\nLevel 1 (1–2 marks): Basic knowledge; generic description of a strategy with little or no case-study detail.\n0 marks: no response worthy of credit.\nIndicative content (e.g. Amazon, Brazil):\n• protected areas: Amazon Region Protected Areas (ARPA) programme, launched 2002, aiming to protect about 60 million hectares\n• Bolsa Floresta / Juma Sustainable Development Reserve: payments to families for zero deforestation; sustainable products such as Brazil nuts\n• satellite monitoring and enforcement by IBAMA; soya moratorium (2006)\n• international funding: Amazon Fund (2008), REDD+\n• ecotourism on the Rio Negro near Manaus\nOR (e.g. Sabah, Malaysia): Deramakot Forest Reserve selective logging with FSC certification; Danum Valley Conservation Area; ecotourism in the Kinabatangan valley\n• examination: environmental, economic and social sustainability; local and global benefits; limitations (illegal logging, enforcement, funding)\nCredit any valid named tropical rainforest case study.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 12: a list of goods and services provided by tropical rainforests: timber and Brazil nuts; medicines such as quinine; homes for indigenous peoples; storing carbon; producing water vapour which forms rain clouds; protecting soils from erosion; a habitat for around half of the world's land species.\n\nUsing Fig. 12, explain why tropical rainforests matter at both a local and a global scale.`, marks: 6, command: 'Explain', markScheme: `Levels of response. AO2 (4 marks): explaining importance. AO3 (2 marks): using Fig. 12.\nLevel 3 (5–6 marks): A thorough explanation of the importance of rainforests at both local and global scales, with a well-developed line of reasoning. Makes effective use of Fig. 12 and own understanding.\nLevel 2 (3–4 marks): A reasonable explanation, possibly unbalanced between scales, with some use of Fig. 12.\nLevel 1 (1–2 marks): A basic explanation, mostly listing items from Fig. 12.\n0 marks: no response worthy of credit.\nIndicative content:\nLocal: food, building materials, medicine and homes for indigenous people (e.g. Yanomami); income from timber and Brazil nuts; protecting soils keeps farmland productive; rainfall for local crops and rivers\nGlobal: carbon store / sink reducing climate change; regulates regional and global rainfall patterns; biodiversity and gene pool; medicines used worldwide (e.g. quinine for malaria); products traded globally\nLevel 3 requires explanation at both scales.` },
      { q: `Section A — Sustaining Ecosystems.\n\nBetween 1985 and 2023 large areas of the Brazilian Amazon were cleared for cattle ranching, soya farming, mining and dams such as Belo Monte on the Xingu River.\n\nAnalyse the impacts of deforestation on people and the environment in a named tropical rainforest.`, marks: 6, command: 'Analyse', markScheme: `Levels of response. AO1 (2 marks): knowledge of impacts. AO2 (4 marks): analysing them.\nLevel 3 (5–6 marks): Thorough knowledge of a range of impacts on both people and the environment in a named rainforest. A thorough analysis (e.g. of positive and negative, short and long term, local and global impacts) with a well-developed line of reasoning.\nLevel 2 (3–4 marks): Reasonable knowledge of some impacts, with some analysis and some reference to a named place.\nLevel 1 (1–2 marks): Basic knowledge of impacts, mostly descriptive and generic.\n0 marks: no response worthy of credit.\nIndicative content:\nPeople (positive): jobs in farming, logging and mining; export income for Brazil (beef, soya, iron ore); HEP electricity\nPeople (negative): indigenous peoples displaced (e.g. by Belo Monte); loss of traditional ways of life; conflict over land; disease brought by settlers; smoke from fires harming health\nEnvironment: loss of biodiversity and habitats; soil erosion and leaching; rivers silted / polluted by mercury from gold mining; less transpiration so less rainfall / more drought; CO₂ released, contributing to climate change\nAnalysis may weigh short-term economic gains against long-term environmental costs.` },
      { q: `Section A — Sustaining Ecosystems.\n\nFig. 13: views about the future of the Amazon rainforest in Pará state, Brazil.\nCattle rancher: "Beef exports bring money into Brazil. We need more land to feed a growing world."\nIndigenous leader: "The forest is our home and our food. When it is cut, our people lose everything."\nGovernment official: "We must create jobs, but we also want to reach zero illegal deforestation."\nConservation charity worker: "The Amazon helps to control the world's climate. Once it is gone, it will not come back."\n\nUsing Fig. 13, examine why people have different views about the use of tropical rainforests.`, marks: 6, command: 'Examine', markScheme: `Levels of response. AO2 (3 marks): understanding of reasons for differing views. AO3 (3 marks): use of Fig. 13 to examine.\nLevel 3 (5–6 marks): A thorough examination of why views differ, linking each view to the person's economic, social or environmental priorities and to local or global scale. Makes effective use of Fig. 13 with a well-developed line of reasoning.\nLevel 2 (3–4 marks): A reasonable examination of some views with some reasons, and some use of Fig. 13.\nLevel 1 (1–2 marks): A basic response which mostly repeats the views from Fig. 13.\n0 marks: no response worthy of credit.\nIndicative content:\n• the rancher's income depends on clearing land: an economic, short-term view; global demand for beef\n• the indigenous leader depends directly on the forest: a social and cultural, local view; rights to land\n• the government must balance economic development and jobs with environmental laws and international pressure\n• the charity takes a global, long-term environmental view: carbon store, biodiversity, irreversible loss\n• views depend on who benefits and who loses, on wealth and power, and on time scale\nCredit own understanding beyond Fig. 13.` },
      { q: `Section A — Sustaining Ecosystems.\n\nIn the Amazon rainforest mean monthly temperatures are about 27 °C, annual rainfall is over 2000 mm, the canopy blocks most light from the forest floor, and the soils are thin and low in nutrients below the surface.\n\nExplain how plants and animals are adapted to the conditions in tropical rainforests.`, marks: 6, command: 'Explain', markScheme: `Levels of response. AO1 (2 marks): knowledge of adaptations. AO2 (4 marks): explaining how they suit the conditions.\nLevel 3 (5–6 marks): Thorough knowledge of a range of plant AND animal adaptations, each clearly linked to a specific condition (heat, rain, light, soils, competition, predators), with a well-developed line of reasoning.\nLevel 2 (3–4 marks): Reasonable knowledge of some adaptations with some explanation; may be unbalanced between plants and animals.\nLevel 1 (1–2 marks): Basic knowledge; adaptations listed with little explanation.\n0 marks: no response worthy of credit.\nIndicative content:\nPlants: drip tips shed heavy rain to stop mould / algae; buttress roots support tall trees in shallow soils; shallow, widespread roots take nutrients from the top layer; thin, smooth bark (no need for insulation, sheds epiphytes); lianas and epiphytes reach light; emergents grow tall to reach sunlight\nAnimals: sloth camouflaged by algae and slow metabolism; spider monkey's prehensile tail for moving through the canopy; toucan's large beak to reach and break fruit; poison dart frog's bright colours warn predators; jaguar's spotted coat for camouflage in dappled light; many nocturnal species avoid heat and predators\nLevel 3 requires both plants and animals.` },
      { q: `Section A — Sustaining Ecosystems.\n\nTropical rainforests store large amounts of carbon and contain great biodiversity, but they are also cleared for farming, logging and mining which bring jobs and income to rainforest countries such as Brazil and Malaysia.\n\nAssess the extent to which the global benefits of protecting tropical rainforests are more important than the local benefits of using them. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Levels of response. AO2 (4 marks): understanding of benefits. AO3 (4 marks): assessing and reaching a judgement.\nLevel 3 (6–8 marks): Thorough understanding of both global and local benefits. A thorough assessment, weighing evidence from named examples, leading to a well-supported conclusion on the extent to which global benefits are more important. A well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Reasonable understanding of some benefits; a reasonable assessment that may be unbalanced, with a partial conclusion.\nLevel 1 (1–2 marks): Basic understanding; a basic, mainly descriptive response with little or no judgement.\n0 marks: no response worthy of credit.\nIndicative content:\nGlobal benefits of protection: carbon store reduces climate change; rainfall regulation; biodiversity and medicines; benefits are shared by everyone\nLocal benefits of use: jobs and income in ranching, oil palm, logging, mining; export earnings help LIDCs/EDCs develop; roads and HEP improve services\nAssessment: sustainable use (e.g. Bolsa Floresta, FSC logging, ecotourism) can give local income while keeping global benefits; who should pay (Amazon Fund, REDD+); local people may lose out if protection gives no income; climate change will also harm local people\nSPaG (3 marks):\nHigh performance (3 marks): spells and punctuates with consistent accuracy; consistently uses rules of grammar with effective control of meaning; uses a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): spells and punctuates with considerable accuracy; uses rules of grammar with general control of meaning; uses a good range of specialist terms as appropriate.\nThreshold performance (1 mark): spells and punctuates with reasonable accuracy; uses rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; uses a limited range of specialist terms as appropriate.\nNo marks awarded (0 marks): the learner writes nothing / the response does not relate to the question / errors severely hinder meaning.` },
      { q: `Section A — Sustaining Ecosystems.\n\nCASE STUDY — A tropical rainforest.\n\nEvaluate how successfully your named tropical rainforest is being managed sustainably at local and global scales.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response. AO1 (2 marks): case-study knowledge. AO2 (2 marks): understanding of sustainable management. AO3 (4 marks): evaluation and judgement.\nLevel 3 (6–8 marks): Thorough, accurate case-study knowledge of management at both local and global scales. A thorough evaluation of successes and limitations, supported by evidence, leading to a clear, substantiated judgement. A well-developed line of reasoning.\nLevel 2 (3–5 marks): Reasonable case-study knowledge with a reasonable evaluation, which may focus mainly on one scale; judgement partly supported.\nLevel 1 (1–2 marks): Basic, mostly generic knowledge; little evaluation or judgement.\n0 marks: no response worthy of credit.\nIndicative content (e.g. Amazon, Brazil):\nLocal: Bolsa Floresta / Juma Reserve payments and sustainable products; ecotourism near Manaus; indigenous reserves where deforestation is much lower; community forest management\nGlobal: Amazon Fund (Norway, Germany); REDD+; consumer pressure and certification (FSC, soya moratorium 2006); international agreements on climate\nSuccesses: deforestation fell by over 80% between 2004 and 2012; protected areas now cover a large share of the Brazilian Amazon\nLimitations: deforestation rose again to about 13,000 km² in 2021; illegal logging and mining continue; enforcement depends on government policy; payments may be too small to compete with ranching\nCredit any valid named tropical rainforest (e.g. Sabah, Malaysia; Costa Rica).` },
      { q: `Section A — Sustaining Ecosystems.\n\nWhen an area of rainforest in Rondônia, Brazil, was cleared and burned for cattle pasture, local rainfall fell, the soil was eroded within a few years, and many animal species disappeared from the area.\n\nAssess the extent to which deforestation breaks down the interdependence of tropical rainforest ecosystems.`, marks: 8, command: 'Assess', markScheme: `Levels of response. AO2 (4 marks): understanding of interdependence and how deforestation affects it. AO3 (4 marks): assessing extent and reaching a judgement.\nLevel 3 (6–8 marks): Thorough understanding of the links between climate, soils, water, plants, animals and people. A thorough assessment of how far deforestation disrupts them, considering scale and type of clearance, leading to a well-supported conclusion. Well-developed line of reasoning.\nLevel 2 (3–5 marks): Reasonable understanding of some links; reasonable assessment with a partial conclusion.\nLevel 1 (1–2 marks): Basic understanding; describes effects of deforestation with little reference to interdependence; no judgement.\n0 marks: no response worthy of credit.\nIndicative content:\n• removing trees ends the supply of leaf litter, so the nutrient cycle breaks and soils become infertile\n• no canopy or roots: rain hits soil directly, causing leaching and erosion; rivers silt up\n• less transpiration: less local rainfall, drier conditions, more fire risk\n• loss of plants removes food and habitat; loss of animals stops pollination and seed dispersal, so regrowth is slower\n• indigenous people lose food, medicine and homes\nExtent: small-scale shifting cultivation or selective logging may allow recovery; large-scale clear-felling and burning may be irreversible; scientists warn of a "tipping point" where parts of the Amazon could turn to savanna\nA conclusion should state how far the interdependence is broken and under what conditions.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Manaus and the Amazon rainforest.\n\nFig. 14: the BR-319 highway. The road was built in the 1970s to link Manaus, in the centre of the Amazon rainforest, with Porto Velho about 900 km to the south. By the late 1980s much of it had become impassable because heavy rain washed away the surface. The Brazilian government has plans to rebuild and pave the middle section, about 400 km long, which passes through largely undisturbed forest.\nFig. 15: views about the plan.\nManaus business owner: "Goods can only reach Manaus by river or air. A road would cut costs and bring jobs."\nResident of a village on the road: "In the wet season we cannot reach a hospital. We need a road that works all year."\nScientist: "Other Amazon roads have led to clearance spreading out for tens of kilometres on each side. Paving BR-319 could open the central Amazon to land-grabbers."\nIndigenous leader: "Our territory lies near the road. More people will bring illegal logging and disease."\n\nUsing Figs. 14 and 15, and your own understanding, evaluate whether rebuilding the BR-319 highway would be a sustainable development for the Amazon rainforest.`, marks: 12, command: 'Evaluate', markScheme: `Levels of response. AO2 (4 marks): understanding of rainforest threats and sustainability. AO3 (8 marks): application of understanding to the resources to evaluate and make a judgement.\nLevel 4 (10–12 marks): Thorough understanding of sustainability (economic, social, environmental; present and future). A thorough, balanced evaluation of the plan using Figs. 14 and 15 and own understanding, leading to a well-substantiated judgement. A well-developed line of reasoning which is clear and logically structured.\nLevel 3 (7–9 marks): Good understanding; a good evaluation using the resources, with a judgement that is mostly supported. Line of reasoning is clear and structured.\nLevel 2 (4–6 marks): Reasonable understanding; a reasonable but unbalanced evaluation, with some use of the resources and a partial judgement.\nLevel 1 (1–3 marks): Basic understanding; a basic, mainly descriptive response which lifts material from the resources with little or no judgement.\n0 marks: no response worthy of credit.\nIndicative content:\nFor (sustainable aspects): economic benefits for Manaus (cheaper goods, jobs, trade); social benefits — year-round access to hospitals and schools for road communities; could be built with protected areas along it, monitoring and enforcement\nAgainst: the scientist's evidence that roads cause fishbone clearance tens of km either side (e.g. Trans-Amazonian Highway); opens remote forest to illegal logging, ranching and land-grabbing; threats to indigenous territories and health; carbon release and biodiversity loss with global impacts; benefits for today may compromise future generations\nEvaluation: sustainability depends on conditions — whether protected areas, policing and satellite monitoring are funded and enforced; alternatives such as improved river transport\nJudgement must be supported: e.g. not sustainable unless strong protection is put in place first.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Sabah, Malaysian Borneo.\n\nFig. 16: three options for an area of 10,000 hectares of rainforest owned by the state government of Sabah (data written for this practice question).\nOption 1 — Oil palm plantation: clear the forest and plant oil palm. Income about US$2,500 per hectare per year once trees mature after 3 years. 1,500 plantation jobs, many filled by migrant workers. Orangutan and pygmy elephant habitat lost.\nOption 2 — Certified selective logging: cut only a few large trees per hectare every 40 years, following Forest Stewardship Council (FSC) rules, as in Sabah's Deramakot Forest Reserve. Income about US$150 per hectare per year. 200 forestry jobs. Most wildlife remains.\nOption 3 — Protected area with ecotourism: no logging; build a small rainforest lodge and canopy walkway. Income about US$80 per hectare per year, plus payments for keeping carbon stored. 120 jobs as guides, rangers and lodge staff, mostly for local people.\n\nWhich option do you think is the most sustainable for this area of rainforest? Using Fig. 16 and your own understanding, justify your choice.`, marks: 12, command: 'Justify', markScheme: `Levels of response. AO2 (4 marks): understanding of sustainable management of rainforests. AO3 (8 marks): applying understanding to Fig. 16 to make and justify a decision.\nLevel 4 (10–12 marks): Thorough understanding of sustainability. A clear decision, thoroughly justified using evidence from Fig. 16 and own understanding, considering economic, social and environmental factors at local and global scales, and explaining why the other options were rejected. A well-developed line of reasoning which is clear and logically structured.\nLevel 3 (7–9 marks): Good understanding; a clear decision, well justified with good use of Fig. 16; some consideration of the other options.\nLevel 2 (4–6 marks): Reasonable understanding; a decision with reasonable justification, mainly from Fig. 16; little consideration of other options.\nLevel 1 (1–3 marks): Basic understanding; a decision with basic justification, mostly lifted from Fig. 16.\n0 marks: no response worthy of credit.\nNo option is correct; credit any well-justified choice.\nIndicative content:\nOption 1: highest income (US$25 million a year from 10,000 ha once mature) and most jobs; but clear-felling destroys habitat for endangered species, releases carbon, soils degrade; jobs may go to migrants; least sustainable environmentally\nOption 2: moderate income (US$1.5 million a year) and jobs; forest cover and most wildlife kept; long 40-year cycle allows regrowth; FSC certification gives access to markets; some disturbance from roads and felling\nOption 3: lowest direct income (US$0.8 million a year plus carbon payments) but jobs mainly for local people; forest and carbon fully protected; global benefits; income depends on tourist numbers and on carbon payments continuing\nJustification may refer to sustainable development meeting present needs without compromising future generations, local v global benefits, and the success of real examples (e.g. Deramakot, Danum Valley, Kinabatangan ecotourism).` }
    ]
  },
  '1.7': {
    name: 'Sustaining Ecosystems: Polar Environments',
    questions: [
      { q: `Section A — Sustaining Ecosystems.\nFig. 1 (data written for this practice question): mean monthly temperature (°C) at Station X, a weather station on the Arctic coast of northern Alaska.\nJan −26 | Feb −27 | Mar −25 | Apr −17 | May −6 | Jun 2 | Jul 5 | Aug 4 | Sep −1 | Oct −9 | Nov −18 | Dec −23\n\nIdentify the warmest month at Station X.`, marks: 1, command: 'Identify', markScheme: `1 mark: July (5 °C).\nDo not accept a temperature on its own.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 1 (data written for this practice question): mean monthly temperature (°C) at Station X on the Arctic coast of northern Alaska.\nJan −26 | Feb −27 | Mar −25 | Apr −17 | May −6 | Jun 2 | Jul 5 | Aug 4 | Sep −1 | Oct −9 | Nov −18 | Dec −23\n\nCalculate the annual temperature range at Station X.`, marks: 1, command: 'Calculate', markScheme: `1 mark: 32 °C (5 − (−27) = 32).\nAllow 32 without units. Do not accept −32 or 22.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 2 (approximate values): the number of hours of daylight on the 21st of each month at Longyearbyen, Svalbard (78°N).\nJan 0 | Feb 4 | Mar 12 | Apr 24 | May 24 | Jun 24 | Jul 24 | Aug 24 | Sep 13 | Oct 3 | Nov 0 | Dec 0\n\nIdentify one month when the sun does not rise above the horizon at Longyearbyen.`, marks: 1, command: 'Identify', markScheme: `1 mark for any one of: November, December, January.\nDo not accept a month with daylight shown.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 3: a world map centred on the North Pole. The Arctic Ocean is in the centre, surrounded by the northern coasts of Russia, Alaska (USA), Canada, Greenland and Norway. A dashed line of latitude encircles the region, passing through northern Norway, Russia, Alaska, Canada and Greenland.\n\nState the name of the dashed line of latitude that marks the southern boundary of the Arctic shown on Fig. 3.`, marks: 1, command: 'State', markScheme: `1 mark: the Arctic Circle.\nAllow 66.5°N / 66°33′N. Do not accept Tropic of Cancer or equator.` },
      { q: `Section A — Sustaining Ecosystems.\nEmperor penguins breed on the sea ice around Antarctica during the polar winter, when air temperatures can fall below −40 °C and winds can exceed 150 km/h.\n\nGive one way the emperor penguin is adapted to survive these conditions.`, marks: 1, command: 'Give', markScheme: `1 mark for one adaptation, e.g.:\n• huddles in large groups to share body heat / shelter from wind\n• thick layer of fat (blubber) for insulation\n• dense, overlapping waterproof feathers\n• small bill and flippers reduce heat loss\n• male holds the egg on its feet under a fold of skin (brood pouch)\nAllow other valid adaptations.` },
      { q: `Section A — Sustaining Ecosystems.\nOnly two species of flowering plant grow naturally in Antarctica — Antarctic hair grass and Antarctic pearlwort — and they are found only on the Antarctic Peninsula and nearby islands. The Arctic has several hundred flowering plant species.\n\nGive one reason why so few flowering plants grow in Antarctica.`, marks: 1, command: 'Give', markScheme: `1 mark for one reason, e.g.:\n• about 98% of the land is covered by thick ice, so there is very little exposed ground/soil\n• temperatures are too cold for most of the year / very short growing season\n• very low precipitation — it is a cold desert / water is frozen\n• isolated by the Southern Ocean, so seeds rarely arrive\n• strong katabatic winds\nAllow other valid reasons.` },
      { q: `Section A — Sustaining Ecosystems.\nSvalbard is a Norwegian archipelago in the Arctic with a land area of about 61,000 km² and a population of about 2,500 people, most of whom live in Longyearbyen.\n\nCalculate the population density of Svalbard. Give your answer to two decimal places.`, marks: 1, command: 'Calculate', markScheme: `1 mark: 0.04 people per km² (2,500 ÷ 61,000 = 0.041).\nAllow 0.04 without units.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 4: a map of the Southern Hemisphere centred on the South Pole. Antarctica is a roughly circular continent covering the South Pole, almost entirely inside the Antarctic Circle (66.5°S). It is surrounded by the Southern Ocean. The Antarctic Peninsula extends north towards the southern tip of South America, about 1,000 km away. Australia and New Zealand lie to the north, beyond the Southern Ocean.\n\nUsing Fig. 4, describe the location of Antarctica.`, marks: 2, command: 'Describe', markScheme: `1 mark per valid locational point, up to 2:\n• in the Southern Hemisphere / around the South Pole\n• mostly within/south of the Antarctic Circle (66.5°S)\n• surrounded by the Southern Ocean\n• the Antarctic Peninsula points towards South America / about 1,000 km south of South America\n• south of Australia and New Zealand\nDo not credit "at the bottom of the world" without further detail.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 1 (data written for this practice question): mean monthly temperature (°C) at Station X on the Arctic coast of northern Alaska.\nJan −26 | Feb −27 | Mar −25 | Apr −17 | May −6 | Jun 2 | Jul 5 | Aug 4 | Sep −1 | Oct −9 | Nov −18 | Dec −23\n\nCalculate the mean temperature for the summer months of June, July and August. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (2 + 5 + 4) ÷ 3 or 11 ÷ 3\n1 mark for answer: 3.7 °C\nAllow 3.7 with no working for 2 marks. Allow 1 mark for 3.67 or 3.6 (rounding error).` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 5 (rounded values based on satellite records, written for this practice question): mean September Arctic sea ice extent.\n1980: 7.7 million km² | 1990: 6.1 million km² | 2000: 6.3 million km² | 2007: 4.3 million km² | 2012: 3.6 million km² | 2020: 3.9 million km²\n\nCalculate the percentage change in September Arctic sea ice extent between 1980 and 2020. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (3.9 − 7.7) ÷ 7.7 × 100 or 3.8 ÷ 7.7 × 100\n1 mark for answer: −49.4% (a decrease of 49.4%)\nAllow −49% or a 49.35% decrease. Allow 1 mark for 49.4 without indicating a decrease if working is shown.` },
      { q: `Section A — Sustaining Ecosystems.\nIn much of the Arctic tundra the ground below about 0.5 m stays frozen all year round. Only the top layer, the active layer, thaws in the short summer.\n\nExplain one way the permafrost affects the plants that can grow in the Arctic.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid effect + 1 mark for development, e.g.:\n• plants have shallow roots (1) because roots cannot penetrate the frozen ground below the active layer (1)\n• no tall trees grow (1) because they cannot anchor deep roots in the thin active layer (1)\n• plants must tolerate waterlogging (1) because meltwater cannot drain through the impermeable permafrost, so the active layer becomes boggy in summer (1)\n• nutrients are limited (1) because cold, frozen soil slows decomposition (1)` },
      { q: `Section A — Sustaining Ecosystems.\nThe polar bear lives on the Arctic sea ice, where winter temperatures can fall to −40 °C. It hunts seals at holes in the ice and swims long distances between ice floes.\n\nExplain one way the polar bear is adapted to the Arctic environment.`, marks: 2, command: 'Explain', markScheme: `1 mark for adaptation + 1 mark for explanation, e.g.:\n• thick layer of blubber (up to about 10 cm) (1) insulates against cold air and water and stores energy (1)\n• white/translucent fur (1) camouflages it against the snow and ice when hunting seals (1)\n• black skin (1) absorbs heat from the sun (1)\n• large, wide paws (1) spread its weight on thin ice and snow / act as paddles for swimming (1)\n• small ears and tail (1) reduce surface area so less heat is lost (1)\n• hollow, water-repellent guard hairs (1) trap air for insulation (1)` },
      { q: `Section A — Sustaining Ecosystems.\nThe Arctic willow grows across the Arctic tundra. It rarely grows taller than 15 cm, spreads its branches along the ground and has leaves covered in fine, silky hairs.\n\nExplain one way the Arctic willow is adapted to the Arctic climate.`, marks: 2, command: 'Explain', markScheme: `1 mark for adaptation + 1 mark for explanation, e.g.:\n• grows low to the ground (1) so it is sheltered from strong, cold winds / insulated by snow cover in winter (1)\n• hairy leaves (1) trap a layer of warmer air / reduce moisture loss in the wind (1)\n• shallow, spreading roots (1) because only the thin active layer thaws (1)\n• grows and flowers quickly in summer (1) to make use of the short growing season / 24-hour daylight (1)` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 6 (data written for this practice question): climate data for Station X on the Arctic coast of northern Alaska.\nMean temperature (°C): Jan −26 | Feb −27 | Mar −25 | Apr −17 | May −6 | Jun 2 | Jul 5 | Aug 4 | Sep −1 | Oct −9 | Nov −18 | Dec −23\nPrecipitation (mm): Jan 4 | Feb 4 | Mar 3 | Apr 4 | May 4 | Jun 8 | Jul 25 | Aug 25 | Sep 15 | Oct 11 | Nov 6 | Dec 4\nTotal annual precipitation: 113 mm\n\nDescribe the climate of Station X shown in Fig. 6.`, marks: 2, command: 'Describe', markScheme: `1 mark per descriptive point, up to 2; at least one must use data for full marks:\n• very cold — temperatures below freezing for nine months / Sep to May\n• only three months above 0 °C (Jun–Aug), maximum 5 °C in July\n• coldest month February at −27 °C / large annual range of 32 °C\n• very low precipitation — 113 mm a year (a cold desert)\n• most precipitation falls in July and August (25 mm each)\nNo credit for explanation.` },
      { q: `Section A — Sustaining Ecosystems.\nThe lowest air temperature ever recorded on Earth, −89.2 °C, was measured at Vostok Station in the interior of Antarctica in July 1983. Winter temperatures at the North Pole are usually between −30 °C and −40 °C.\n\nExplain one reason why Antarctica is colder than the Arctic.`, marks: 2, command: 'Explain', markScheme: `1 mark for reason + 1 mark for development, e.g.:\n• Antarctica is a high continent / ice sheet over 2 km thick (1), and temperature falls with altitude (1)\n• Antarctica is land, while the Arctic is mainly ocean (1); the ocean beneath the sea ice stores heat and releases it, keeping the Arctic warmer (1)\n• the Antarctic Circumpolar Current/Southern Ocean isolates Antarctica (1), so warmer water and air from lower latitudes are kept away (1)\n• the larger ice sheet has a high albedo (1), so more incoming solar radiation is reflected (1)` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 7 (approximate figures written for this practice question, based on IAATO reports): visitors to Antarctica per season.\n1992–93: 6,700 | 2010–11: 34,000 | 2019–20: 74,000 | 2023–24: 122,000\n\nCalculate the percentage increase in visitors to Antarctica between 2010–11 and 2023–24. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (122,000 − 34,000) ÷ 34,000 × 100 or 88,000 ÷ 34,000 × 100\n1 mark for answer: 258.8% (allow 259%)\nAllow 2 marks for a correct answer with no working.` },
      { q: `Section A — Sustaining Ecosystems.\nFor thousands of years Inuit communities in northern Canada and Greenland have hunted seals, whales and caribou, and fished in the Arctic Ocean.\n\nExplain one way Inuit people are interdependent with the Arctic ecosystem.`, marks: 2, command: 'Explain', markScheme: `1 mark for a link + 1 mark for development, e.g.:\n• seals provide food, skins for clothing and oil for fuel (1), so Inuit depend on healthy seal populations / sea ice where seals live (1)\n• hunting is controlled by quotas and traditional knowledge (1), which keeps animal numbers sustainable so the ecosystem continues to support people (1)\n• loss of sea ice due to climate change makes hunting routes dangerous (1), so changes in the ecosystem threaten traditional ways of life (1)\nThe answer must show a two-way or dependent link for 2 marks.` },
      { q: `Section A — Sustaining Ecosystems.\nIn March 1989 the oil tanker Exxon Valdez ran aground in Prince William Sound, Alaska, spilling about 41 million litres of crude oil, which polluted around 2,000 km of coastline.\n\nExplain one threat that oil extraction and transport pose to polar ecosystems.`, marks: 2, command: 'Explain', markScheme: `1 mark for threat + 1 mark for development, e.g.:\n• oil spills (1) coat birds' feathers and mammals' fur so they lose insulation and die / poison fish and shellfish (1)\n• oil breaks down very slowly in cold water (1), so damage lasts for decades — oil from the Exxon Valdez can still be found on some beaches (1)\n• construction of roads and pipelines (1) disrupts caribou migration routes / damages fragile tundra vegetation (1)\n• heat from buildings and pipelines (1) melts permafrost, causing subsidence (1)\nAllow other valid threats.` },
      { q: `Section A — Sustaining Ecosystems.\nThe Trans-Alaska Pipeline carries oil 1,287 km from Prudhoe Bay on the Arctic coast to the port of Valdez in southern Alaska. Oil in the pipe is warm. Along much of its route the pipeline is raised above the ground on supports and built in a zigzag pattern.\n\nExplain one way the design of the Trans-Alaska Pipeline reduces its impact on the environment.`, marks: 2, command: 'Explain', markScheme: `1 mark for design feature + 1 mark for explanation, e.g.:\n• raised on supports above the ground (1) so heat from the warm oil does not melt the permafrost and cause subsidence (1)\n• supports contain heat pipes/radiators (1) which draw heat out of the ground to keep it frozen (1)\n• zigzag shape (1) lets the pipe expand, contract and move in earthquakes without breaking, reducing the risk of spills (1)\n• raised or buried sections (1) let caribou migrate under/over the pipeline (1)\n• automatic shut-off valves (1) limit the size of any leak (1)` },
      { q: `Section A — Sustaining Ecosystems.\nIAATO (the International Association of Antarctica Tour Operators) guidelines say that no more than 100 passengers may be ashore at one landing site at a time, and that there must be at least one guide for every 20 passengers.\n\nSuggest two reasons why IAATO limits the number of tourists ashore.`, marks: 2, command: 'Suggest', markScheme: `1 mark per reason, up to 2:\n• to reduce trampling of fragile mosses and lichens, which grow very slowly\n• to reduce disturbance to breeding penguins and seals\n• so guides can supervise visitors and make sure they keep a safe distance from wildlife\n• to reduce the risk of introducing non-native seeds or diseases\n• to reduce litter/waste and erosion of paths\n• for safety — easier to evacuate small groups if weather changes` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 5 (rounded values based on satellite records, written for this practice question): mean September Arctic sea ice extent fell from 7.7 million km² in 1980 to 3.9 million km² in 2020.\n\nExplain one way that the loss of sea ice could lead to further warming in the Arctic.`, marks: 2, command: 'Explain', markScheme: `1 mark for point + 1 mark for development:\n• white sea ice has a high albedo/reflects most sunlight, but dark open ocean absorbs more (1), so the water warms and melts more ice — a positive feedback loop (1)\nAlternative: thawing permafrost on land releases methane/carbon dioxide (1), which enhances the greenhouse effect and increases warming (1).` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 5 (rounded values based on satellite records, written for this practice question): mean September Arctic sea ice extent.\n1980: 7.7 | 1990: 6.1 | 2000: 6.3 | 2007: 4.3 | 2012: 3.6 | 2020: 3.9 (million km²)\nThe data is shown as a table.\n\nSuggest one other way of presenting this data and give a reason for your choice.`, marks: 2, command: 'Suggest', markScheme: `1 mark for appropriate method + 1 mark for justification, e.g.:\n• line graph (1) because the data is continuous over time and shows the trend clearly (1)\n• bar chart (1) so the extent in each year can be compared easily (1)\nDo not credit pie chart (data is not parts of a whole).` },
      { q: `Section A — Sustaining Ecosystems.\nAbout two-thirds of Svalbard's land area is protected in national parks and nature reserves. Visitors who travel outside the main settlements must follow strict rules, and since 2022 ships using heavy fuel oil have been banned from Svalbard's territorial waters.\n\nExplain one way Svalbard is protecting its environment.`, marks: 2, command: 'Explain', markScheme: `1 mark for method + 1 mark for explanation, e.g.:\n• large protected areas/national parks (1) limit building and activity, so habitats for polar bears, walruses and seabirds are conserved (1)\n• ban on heavy fuel oil (1) reduces the risk of a damaging oil spill / black carbon pollution that speeds ice melt (1)\n• rules for visitors, e.g. registering trips and not disturbing wildlife (1), reduce disturbance to animals and trampling of tundra (1)\n• limits on the size of cruise ships allowed in protected areas (1) reduce the number of people landing at fragile sites (1)` },
      { q: `Section A — Sustaining Ecosystems.\nIn the Arctic, many animals such as caribou and Arctic terns migrate, while others such as the Arctic ground squirrel hibernate for up to eight months.\n\nExplain how climate and animals are interdependent in polar environments.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid explained point, up to 3, e.g.:\n• the long, dark, very cold winter means little food is available (1), so animals migrate south or hibernate (1)\n• the short summer with 24-hour daylight produces a burst of plant growth and insects (1), so animals breed at this time and migrating birds return (1)\n• animals depend on sea ice formed by the cold climate to hunt / breed, e.g. polar bears hunt seals from the ice (1)\n• animals affect climate/environment: grazing caribou keep vegetation low, which affects snow cover and how much the ground is insulated (1)\nFor full marks the answer must show how climate affects animals AND some sense of the relationship.` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 8: a simplified Southern Ocean food web. Phytoplankton → Antarctic krill. Krill → penguins, seals (crabeater), baleen whales and fish. Fish → penguins and Weddell seals. Penguins and seals → leopard seals and orcas.\n\nUsing Fig. 8, explain how the Antarctic marine ecosystem is interdependent.`, marks: 3, command: 'Explain', markScheme: `1 mark per explained point, up to 3, e.g.:\n• krill are the key link — they feed on phytoplankton and are eaten by penguins, seals, whales and fish (1)\n• a fall in krill (e.g. due to overfishing or loss of sea ice where krill feed on algae) (1) would reduce food for penguins and whales, so their numbers would fall (1)\n• a fall in penguins and seals would then reduce food for top predators such as leopard seals and orcas (1)\n• phytoplankton depend on sunlight and nutrients in cold water, so changes in climate affect the whole web (1)\nMust use Fig. 8 for full marks.` },
      { q: `Section A — Sustaining Ecosystems.\nFootprints left in moss on parts of the Antarctic Peninsula can still be seen many years later. Some lichens there grow less than 1 mm a year.\n\nExplain why polar ecosystems are fragile.`, marks: 3, command: 'Explain', markScheme: `1 mark per explained point, up to 3, e.g.:\n• low temperatures and a short growing season mean plants grow very slowly (1), so damage takes decades to recover (1)\n• low biodiversity / simple food webs (1) mean the loss of one species, e.g. krill, affects many others (1)\n• decomposition is very slow in the cold (1), so pollution and waste persist for a long time (1)\n• permafrost is easily melted by heat or removal of vegetation (1), leading to subsidence and erosion (1)` },
      { q: `Section A — Sustaining Ecosystems.\nThe Antarctic Treaty was signed in 1959 by 12 countries and came into force in 1961. More than 50 countries have now joined it.\n\nExplain how the Antarctic Treaty helps to protect Antarctica.`, marks: 3, command: 'Explain', markScheme: `1 mark per explained point, up to 3, e.g.:\n• Antarctica may be used only for peaceful purposes — military activity and nuclear explosions are banned (1)\n• territorial claims are frozen (1), so no country can take control and exploit resources (1)\n• it promotes scientific research and sharing of results (1), helping understanding of the environment and climate change (1)\n• inspections of bases are allowed (1), so countries must follow the rules (1)\n• the Madrid Protocol (1991, added to the Treaty system) bans mining and requires environmental impact assessments (1)` },
      { q: `Section A — Sustaining Ecosystems.\nIn parts of northern Russia and Alaska, buildings, roads and pipelines have cracked and tilted as average temperatures have risen.\n\nExplain how the thawing of permafrost affects people living in polar areas.`, marks: 3, command: 'Explain', markScheme: `1 mark per explained point, up to 3, e.g.:\n• ice in the ground melts, so the ground subsides (1), causing buildings and roads to crack/collapse (1)\n• pipelines can break (1), causing oil spills and costly repairs (1)\n• coastal erosion increases as frozen cliffs thaw (1), so some villages, e.g. in Alaska, have to relocate (1)\n• ice roads and frozen ground used for winter travel are available for less time (1), cutting off remote communities (1)\nAllow release of methane leading to further warming if linked to people.` },
      { q: `Section A — Sustaining Ecosystems.\nEmperor penguins lay their eggs in May or June, at the start of the Antarctic winter. The male holds the egg on his feet for about two months without eating, while the female returns to the sea to feed.\n\nExplain how emperor penguins are adapted to breeding in the Antarctic winter.`, marks: 3, command: 'Explain', markScheme: `1 mark per explained point, up to 3, e.g.:\n• the egg sits on the male's feet under a fold of feathered skin (brood pouch) (1), keeping it off the ice and warm (1)\n• males huddle in large groups and take turns on the outside (1), reducing heat loss and sheltering from wind (1)\n• thick fat reserves (1) let the male fast for many weeks while incubating (1)\n• breeding in winter means chicks are ready to feed independently in summer (1), when food (krill/fish) is most plentiful (1)` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 5 (rounded values based on satellite records, written for this practice question): mean September Arctic sea ice extent.\n1980: 7.7 | 1990: 6.1 | 2000: 6.3 | 2007: 4.3 | 2012: 3.6 | 2020: 3.9 (million km²)\n\nDescribe and explain the trend shown in Fig. 5.`, marks: 4, command: 'Describe', markScheme: `Up to 2 marks for description using data:\n• overall decrease from 7.7 to 3.9 million km² / nearly halved (1)\n• not a steady fall — small rise 1990–2000 (6.1 to 6.3) / lowest value in 2012 at 3.6 million km² (1)\nUp to 2 marks for explanation:\n• rising global temperatures from the enhanced greenhouse effect melt more ice in summer (1)\n• albedo feedback — open water absorbs more heat, melting more ice (1)\n• warmer ocean water melts ice from below (1)\n• year-to-year variation due to natural factors such as weather and wind patterns (1)` },
      { q: `Section A — Sustaining Ecosystems.\nAbout 4 million people live in the Arctic. Some, such as the Inuit of Canada and Greenland and the Sámi of northern Scandinavia, have lived there for thousands of years.\n\nExplain two ways that indigenous people have adapted to life in the Arctic.`, marks: 4, command: 'Explain', markScheme: `2 × 2 marks: 1 mark for each adaptation + 1 mark for explanation, e.g.:\n• clothing made from animal skins/fur, e.g. caribou or seal (1), traps warm air and keeps out wind and water (1)\n• diet rich in fat and protein from seals, whales and fish (1), provides energy to cope with the cold where few crops grow (1)\n• nomadic lifestyle / following reindeer herds (Sámi) (1), so people move with food supplies through the seasons (1)\n• traditional knowledge of sea ice and weather (1), allowing safe hunting and travel (1)\n• building temporary igloos/snow shelters (1), as snow is a good insulator and is available everywhere (1)\n• modern adaptations such as snowmobiles and houses built on stilts (1) to avoid melting the permafrost (1)` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 9 (data written for this practice question): mean monthly temperatures (°C).\nStation A (Antarctic plateau, 3,400 m above sea level): Jan −32 | Feb −44 | Mar −57 | Apr −65 | May −66 | Jun −66 | Jul −68 | Aug −69 | Sep −66 | Oct −58 | Nov −44 | Dec −32\nStation X (Arctic coast of Alaska, 10 m above sea level): Jan −26 | Feb −27 | Mar −25 | Apr −17 | May −6 | Jun 2 | Jul 5 | Aug 4 | Sep −1 | Oct −9 | Nov −18 | Dec −23\n\nCompare the temperatures at Station A and Station X.`, marks: 4, command: 'Compare', markScheme: `1 mark per valid comparative point, up to 4; data use required for full marks:\n• Station A is colder all year round / never rises above −32 °C, while Station X reaches 5 °C (1)\n• Station X has three months above freezing; Station A has none (1)\n• the warmest months are at opposite times of year — Dec/Jan at Station A, July at Station X (Southern vs Northern Hemisphere summer) (1)\n• Station A has a slightly larger annual range: 37 °C (−32 to −69) compared with 32 °C (5 to −27) (1)\n• Station A's coldest month is August (−69 °C), Station X's is February (−27 °C) (1)\n• Station A has a long, flat 'coreless' winter of about −65 °C to −69 °C from April to September (1)\nPoints must be comparative; separate descriptions max 2.` },
      { q: `Section A — Sustaining Ecosystems.\nIn the Arctic tundra the ground is frozen below the active layer, plants are low-growing and grow in summer only, and animals such as lemmings, Arctic foxes and caribou depend on these plants directly or indirectly.\n\nExplain the interdependence of climate, permafrost, plants and animals in the Arctic.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): A thorough explanation of several interconnected links between climate, permafrost, plants and animals, showing two-way relationships (e.g. vegetation insulates permafrost, which controls drainage and plant type). Uses accurate terminology and specific examples.\nLevel 2 (3–4 marks): A reasonable explanation of some links, mostly one-way, with some detail.\nLevel 1 (1–2 marks): A basic explanation of one or two links, or a description of features with limited linkage.\n0 marks: No response or no response worthy of credit.\nIndicative content:\n• cold climate keeps the ground frozen — permafrost; only the active layer thaws in summer\n• permafrost is impermeable, so summer meltwater waterlogs the active layer → bogs and mosses\n• shallow active layer means plants have shallow roots and stay low; no trees\n• vegetation and peat insulate the ground, keeping permafrost frozen; removing vegetation causes thaw and subsidence\n• slow decomposition in the cold → nutrient-poor soils and slow plant growth\n• lemmings feed on plants; Arctic foxes and snowy owls feed on lemmings — population cycles\n• caribou migrate to graze summer growth; grazing and trampling affect vegetation\n• people depend on caribou and seals; climate warming thaws permafrost and changes the whole system` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 7 (approximate figures written for this practice question, based on IAATO reports): visitors to Antarctica per season rose from 6,700 in 1992–93 to 122,000 in 2023–24. Most arrive by cruise ship from Ushuaia in Argentina and visit the Antarctic Peninsula.\n\nExamine the impacts of tourism on Antarctica.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): A thorough examination of a range of positive and negative impacts, well developed and supported with detailed evidence, with some weighing of their significance (e.g. impacts are concentrated at a few Peninsula landing sites).\nLevel 2 (3–4 marks): A reasonable examination of some impacts with some development; may be mainly negative.\nLevel 1 (1–2 marks): A basic description of one or two impacts.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nNegative: trampling of slow-growing mosses and lichens; disturbance of penguin and seal colonies during breeding season; risk of introducing non-native species/seeds on clothing; fuel spills and shipwrecks (e.g. MS Explorer sank in 2007); air pollution and black carbon from ships; carbon emissions from flights and cruises; pressure concentrated at a small number of ice-free sites.\nPositive: tourists become 'ambassadors' for conservation; income for gateway ports such as Ushuaia; IAATO rules (100 ashore, 1 guide per 20, no ships over 500 passengers landing) reduce impacts; visitors help fund/assist scientific monitoring.` },
      { q: `Section A — Sustaining Ecosystems.\nPolar environments have very low temperatures, strong winds, long periods of darkness in winter and 24-hour daylight in summer.\n\nExplain how plants and animals are adapted to polar environments.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): A thorough explanation of a range of plant AND animal adaptations, clearly linked to specific polar conditions, with named species from the Arctic and/or Antarctic.\nLevel 2 (3–4 marks): A reasonable explanation of some adaptations, with some links to conditions; may be unbalanced between plants and animals.\nLevel 1 (1–2 marks): A basic description of one or two adaptations with little explanation.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nPlants: low growth / cushion shape (moss campion) out of wind and under insulating snow; shallow roots because of permafrost; hairy stems and leaves (Arctic willow); dark leaves absorb heat; rapid flowering in 24-hour summer daylight; lichens survive freezing and drying; Antarctic hair grass and pearlwort grow only in sheltered Peninsula sites.\nAnimals: blubber and dense fur (polar bear, seals); white camouflage (Arctic fox, Arctic hare); small ears and short limbs reduce heat loss; huddling (emperor penguin); migration (caribou, Arctic tern); hibernation (Arctic ground squirrel); changing coat colour with seasons (Arctic fox).` },
      { q: `Section A — Sustaining Ecosystems.\nCASE STUDY — Polar environments: small-scale sustainable management.\n\nUsing a named example, examine how a polar area has been managed sustainably at a small scale.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): A thorough examination of a named small-scale example, with accurate, place-specific detail of several management strategies and clear assessment of how far they are sustainable (environmental, social and economic).\nLevel 2 (3–4 marks): A reasonable examination with some place-specific detail; some reference to sustainability.\nLevel 1 (1–2 marks): A basic, generic description of management; little or no place-specific detail.\n0 marks: No response or no response worthy of credit.\nIndicative content (Svalbard, Norway):\n• Svalbard Environmental Protection Act (2001) aims to keep Svalbard one of the best-managed wilderness areas\n• about two-thirds of land in national parks and nature reserves\n• heavy fuel oil banned in territorial waters (from 2022); limits on cruise ship size in protected areas\n• visitors outside settlements must register and follow wildlife rules; ban on disturbing polar bears\n• shift away from coal mining towards tourism and research (e.g. Ny-Ålesund research village)\n• limitations: growing cruise tourism, carbon emissions from flights, climate change cannot be managed locally.\nCredit other valid small-scale examples, e.g. an Alaskan community-run fishing quota, an Inuit hunting quota scheme, Port Lockroy (UK Antarctic Heritage Trust).` },
      { q: `Section A — Sustaining Ecosystems.\nThe Arctic is thought to hold about 13% of the world's undiscovered oil and about 30% of its undiscovered natural gas. Oil has been produced at Prudhoe Bay in northern Alaska since 1977.\n\nAnalyse the threats that resource extraction poses to polar environments.`, marks: 6, command: 'Analyse', markScheme: `Level 3 (5–6 marks): A thorough analysis of a range of threats, explaining how and why each damages the environment, with supporting place-specific evidence (e.g. Alaska), and some judgement of which threats are most serious or long-lasting.\nLevel 2 (3–4 marks): A reasonable analysis of some threats, with some explanation and evidence.\nLevel 1 (1–2 marks): A basic description of one or two threats.\n0 marks: No response or no response worthy of credit.\nIndicative content:\n• oil spills — Exxon Valdez 1989 (about 41 million litres, about 2,000 km of coast polluted, hundreds of thousands of seabirds killed); oil breaks down slowly in cold water\n• heat from buildings, roads and pipes melts permafrost → subsidence and damage\n• roads, pipelines and drilling sites fragment habitats and disrupt caribou migration\n• noise from ships, seismic surveys and drilling disturbs whales and seals\n• extraction and burning of fossil fuels adds to climate change, which melts sea ice\n• mining waste (e.g. coal mining in Svalbard) pollutes soils and water\n• limited ability to clean up in remote, icy conditions makes threats more serious` },
      { q: `Section A — Sustaining Ecosystems.\nScientists report that the Arctic is warming about four times faster than the global average.\n\nExplain how climate change is threatening polar ecosystems.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): A thorough explanation of several threats, showing chains of cause and effect through the ecosystem (e.g. sea ice loss → krill/seals → predators) with examples from the Arctic and/or Antarctic.\nLevel 2 (3–4 marks): A reasonable explanation of some threats with some development.\nLevel 1 (1–2 marks): A basic description of one or two effects of warming.\n0 marks: No response or no response worthy of credit.\nIndicative content:\n• loss of Arctic sea ice reduces polar bears' hunting platform → starvation, lower cub survival\n• less sea ice → fewer ice algae → fewer krill in the Southern Ocean → impacts on penguins, seals and whales\n• thawing permafrost releases methane and CO₂ → positive feedback; ground subsides; lakes drain\n• warmer conditions allow southern species (e.g. red fox, shrubs) to move north and compete with Arctic species\n• albedo feedback speeds warming\n• collapse of ice shelves on the Antarctic Peninsula (e.g. Larsen B, 2002) changes coastal habitats\n• ocean acidification affects shell-forming plankton at the base of food webs` },
      { q: `Section A — Sustaining Ecosystems.\nCASE STUDY — Polar environments: global-scale sustainable management.\n\nExamine how one global agreement helps to manage a polar environment sustainably.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): A thorough examination of a named global-scale agreement, with accurate detail of what it does and a clear assessment of how far it achieves sustainable management, including limitations.\nLevel 2 (3–4 marks): A reasonable examination with some accurate detail and some assessment.\nLevel 1 (1–2 marks): A basic description of an agreement with little detail.\n0 marks: No response or no response worthy of credit.\nIndicative content (Antarctic Treaty System):\n• Antarctic Treaty 1959 (in force 1961): peaceful use only, science, freezes territorial claims, inspections\n• Madrid Protocol (signed 1991, in force 1998): Antarctica a 'natural reserve devoted to peace and science', bans mining, environmental impact assessments, waste must be removed\n• CCAMLR (1980) manages fishing, e.g. krill catch limits; Ross Sea Marine Protected Area (2016)\n• success: no mining or military conflict; more than 50 countries involved\n• limitations: relies on agreement between countries; illegal fishing; cannot control tourism growth directly (IAATO is voluntary); cannot stop climate change; the Protocol could be reviewed after 2048.\nCredit other valid global agreements, e.g. the Arctic Council (1996), the Paris Agreement, the International Whaling Commission moratorium (1986).` },
      { q: `Section A — Sustaining Ecosystems.\nFig. 10: uses of polar environments — Inuit hunting and fishing; Sámi reindeer herding; oil and gas extraction in Alaska and Siberia; coal mining in Svalbard; scientific research stations such as Rothera (UK) in Antarctica; cruise tourism; commercial fishing for krill and toothfish; shipping routes such as the Northern Sea Route.\n\nUsing Fig. 10, explain how humans use polar environments.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): A thorough explanation of a range of human uses, explaining why polar areas are used in these ways (resources, unique environment, location), with place-specific detail and reference to both Arctic and Antarctic.\nLevel 2 (3–4 marks): A reasonable explanation of some uses with some detail; may rely heavily on Fig. 10.\nLevel 1 (1–2 marks): A basic list or description of uses from Fig. 10 with little explanation.\n0 marks: No response or no response worthy of credit.\nIndicative content:\n• indigenous people use the land and sea for food, clothing and fuel (seals, whales, caribou, reindeer)\n• large reserves of oil, gas and coal (e.g. Prudhoe Bay) are exploited for energy and income\n• Antarctica is used for science because it is unpolluted and ice cores record past climates; the Treaty limits use to peaceful science\n• tourists visit for wilderness and wildlife; growth due to cheaper cruises\n• rich cold waters support fisheries (krill, toothfish, cod)\n• melting sea ice is opening shorter shipping routes between Europe and Asia\nCredit own understanding beyond Fig. 10.` },
      { q: `Section A — Sustaining Ecosystems.\nIn 1991 members of the Antarctic Treaty signed the Madrid Protocol, which bans all mining in Antarctica. Since then the number of tourists, research stations and fishing vessels in the region has increased.\n\nAssess the extent to which the Antarctic Treaty System has been successful in protecting Antarctica. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): A thorough assessment, weighing successes against limitations, with accurate, detailed knowledge of the Treaty System. A clear, well-supported judgement on the extent of success is reached.\nLevel 2 (3–5 marks): A reasonable assessment with some detail on successes and/or limitations; a judgement may be stated but is only partly supported.\nLevel 1 (1–2 marks): A basic description of the Treaty with little assessment; no clear judgement.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nSuccess: no military conflict or nuclear testing since 1959; territorial claims frozen; mining banned by the Madrid Protocol; environmental impact assessments required; waste removed from bases; CCAMLR krill and toothfish limits; Ross Sea Marine Protected Area; international scientific cooperation (e.g. discovery of the ozone hole in 1985 by the British Antarctic Survey).\nLimitations: decisions need consensus, so new protected areas are slow to agree; illegal, unreported fishing; tourism managed mainly by voluntary IAATO rules; growth of research stations adds footprint; cannot prevent climate change and ice-shelf collapse; mining ban could be reviewed after 2048.\nJudgement: e.g. very successful against direct exploitation, but less able to deal with global threats.\n\nSPaG (3 marks):\nHigh performance (3 marks): spelling and punctuation are consistently accurate; grammar is used with effective control of meaning; a wide range of specialist terms is used appropriately.\nIntermediate performance (2 marks): spelling and punctuation are considerably accurate; general control of meaning; a good range of specialist terms.\nThreshold performance (1 mark): spelling and punctuation are reasonably accurate; errors do not significantly hinder meaning; a limited range of specialist terms.\n0 marks: writing does not reach threshold performance, or no response.` },
      { q: `Section A — Sustaining Ecosystems.\nThe Trans-Alaska Pipeline has carried more than 18 billion barrels of oil since 1977. Oil provides much of the Alaskan state government's income, and every resident receives an annual payment from the Alaska Permanent Fund, which is funded by oil money.\n\nEvaluate the sustainability of oil extraction in Alaska.`, marks: 8, command: 'Evaluate', markScheme: `Level 3 (6–8 marks): A thorough evaluation of environmental, economic and social sustainability, with detailed, accurate evidence from Alaska, and a well-supported conclusion on how sustainable oil extraction is.\nLevel 2 (3–5 marks): A reasonable evaluation of some aspects, with some evidence; a conclusion may be partly supported.\nLevel 1 (1–2 marks): A basic description of impacts with little evaluation; no clear conclusion.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nMore sustainable: pipeline raised on supports with heat pipes to protect permafrost; zigzag design for earthquakes; caribou crossings; automatic shut-off valves; stricter tanker rules after Exxon Valdez (double-hulled tankers required by the Oil Pollution Act 1990); Permanent Fund saves oil wealth for future generations; jobs and taxes.\nLess sustainable: oil is non-renewable — production at Prudhoe Bay has fallen from its 1980s peak; spills (Exxon Valdez 1989); habitat fragmentation; burning oil adds to climate change, which is thawing Alaska's permafrost; debate over drilling in the Arctic National Wildlife Refuge; economy over-dependent on oil.\nConclusion: e.g. well managed locally but unsustainable in the long term because it is finite and contributes to climate change.` },
      { q: `Section A — Sustaining Ecosystems.\n"Tourism is the biggest threat to Antarctica."\n\nTo what extent do you agree with this statement?`, marks: 8, command: 'To what extent', markScheme: `Level 3 (6–8 marks): A thorough discussion comparing tourism with other threats (e.g. climate change, fishing, research activity), using accurate detailed evidence, and reaching a well-supported judgement on the extent of agreement.\nLevel 2 (3–5 marks): A reasonable discussion of tourism and at least one other threat, with some evidence; a judgement is partly supported.\nLevel 1 (1–2 marks): A basic description of the impacts of tourism or another threat; no clear judgement.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nAgree: rapid growth to over 100,000 visitors a season; trampling and disturbance at a few Peninsula landing sites; non-native species; ship accidents and fuel spills (MS Explorer, 2007); emissions from ships and flights.\nDisagree: tourism is managed by IAATO (limits ashore, guides, biosecurity checks) and the Madrid Protocol; impacts are local and seasonal; climate change has larger, continent-wide effects — ice-shelf collapse, loss of sea ice, falling krill and changes in penguin populations (e.g. Adélie decline on the Peninsula); fishing for krill competes with wildlife; research stations have a permanent footprint.\nJudgement: e.g. tourism is a growing local threat but climate change is the biggest threat.` },
      { q: `Section A — Sustaining Ecosystems.\nCASE STUDY — Polar environments: small-scale sustainable management.\nSvalbard has moved from coal mining towards tourism and research. The number of cruise passengers visiting has risen sharply since 2000.\n\nAssess how successful one small-scale example has been in managing a polar environment sustainably.`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): A thorough assessment of a named small-scale example, with detailed, place-specific evidence of strategies and their outcomes, weighing successes against limitations across environmental, economic and social sustainability, and reaching a well-supported judgement.\nLevel 2 (3–5 marks): A reasonable assessment of a named example with some place-specific detail and some judgement.\nLevel 1 (1–2 marks): A basic, mostly generic description of management; little or no assessment.\n0 marks: No response or no response worthy of credit.\nIndicative content (Svalbard):\nSuccess: about two-thirds of land protected; Environmental Protection Act (2001); heavy fuel oil ban; visitors must register trips and follow wildlife rules; walrus numbers have recovered since hunting was banned (1952); move from coal to tourism and research (Ny-Ålesund, University Centre in Svalbard) provides more sustainable jobs; Svalbard Global Seed Vault (2008) shows global value.\nLimitations: cruise passenger numbers have risen; flights add carbon emissions; Longyearbyen still had a coal power station for many years; climate change (Svalbard warming very rapidly) causes avalanches and permafrost thaw that local management cannot stop.\nCredit other valid small-scale examples.` },
      { q: `Resource Booklet — Svalbard.\nFig. 11: Svalbard is an archipelago in the Arctic Ocean, about midway between mainland Norway and the North Pole (74°N–81°N). Its main settlement, Longyearbyen, has about 2,500 people.\nFig. 12 (data written for this practice question): cruise passengers visiting Svalbard — 2000: 25,000 | 2010: 40,000 | 2019: 80,000.\nFig. 13: views about tourism in Svalbard.\n• Hotel owner, Longyearbyen: "Since the coal mines closed, tourism is what keeps this town alive. We need more visitors, all year round."\n• Wildlife guide: "Large cruise ships land hundreds of people on beaches where walruses rest. The new limits on ship size are long overdue."\n• Research scientist, Ny-Ålesund: "Svalbard is warming faster than almost anywhere on Earth. Flights and ships bring the very emissions that are melting the glaciers we study."\n• Norwegian government official: "Our aim is for Svalbard to remain one of the best-managed wilderness areas in the world."\n\nUsing Figs. 11, 12 and 13, and your own understanding, assess whether tourism in Svalbard should be allowed to continue to grow.`, marks: 12, command: 'Assess', markScheme: `Level 4 (10–12 marks): A comprehensive assessment that makes detailed, effective use of all the Figs. and wide-ranging own understanding of polar environments. Arguments for and against growth are well balanced and weighed against sustainability (environmental, social, economic). A clear, well-substantiated judgement is reached.\nLevel 3 (7–9 marks): A thorough assessment using the Figs. and own understanding, with both sides considered; a supported judgement is reached but may lack full balance.\nLevel 2 (4–6 marks): A reasonable assessment with some use of the Figs.; mainly one-sided or descriptive; judgement is limited.\nLevel 1 (1–3 marks): A basic response, mostly lifting material from the Figs. with little own understanding; no clear judgement.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nFor growth: cruise passengers rose from 25,000 to 80,000 (220% increase); replaces coal mining jobs; income supports services in a remote town; tourists may become advocates for Arctic conservation; can be managed by rules — two-thirds of land protected, registration of trips, heavy fuel oil ban, limits on large cruise ships in protected areas.\nAgainst growth: disturbance of walruses, polar bears, nesting seabirds; trampling of slow-growing tundra; risk of oil spills in remote waters; carbon emissions add to rapid warming of Svalbard; pressure on housing and services in a town of 2,500; safety risks (polar bears, avalanches).\nJudgement: e.g. growth only if carefully limited — smaller ships, year-round low-impact tourism, local benefits — to remain sustainable.` },
      { q: `Resource Booklet — The Arctic.\nFig. 14: a map of the Arctic showing the Arctic Ocean surrounded by Russia, Norway, Greenland (Denmark), Canada and the USA (Alaska). The September sea ice edge in 2020 is shown well north of the 1980 sea ice edge. Shaded areas mark large oil and gas fields off northern Russia and Alaska, and a new shipping route (the Northern Sea Route) runs along Russia's north coast.\nFig. 15: facts about the Arctic.\n• The Arctic is estimated to hold about 13% of the world's undiscovered oil and 30% of its undiscovered natural gas.\n• About 4 million people live in the Arctic, including indigenous peoples such as the Inuit and Sámi.\n• Mean September sea ice extent fell from about 7.7 million km² in 1980 to about 3.9 million km² in 2020.\n• The Northern Sea Route can cut the sea journey between Rotterdam and Shanghai by about a third compared with the route via the Suez Canal.\n• Eight countries are members of the Arctic Council (set up in 1996), with indigenous peoples' organisations as permanent participants.\n\n"The benefits of developing the Arctic outweigh the costs."\nUsing Figs. 14 and 15, and your own understanding, evaluate this statement.`, marks: 12, command: 'Evaluate', markScheme: `Level 4 (10–12 marks): A comprehensive evaluation that makes detailed, effective use of both Figs. and wide-ranging own understanding. Economic, social and environmental benefits and costs are weighed, at local and global scales, and the role of management is considered. A clear, well-substantiated conclusion is reached.\nLevel 3 (7–9 marks): A thorough evaluation using the Figs. and own understanding, with benefits and costs considered; a supported conclusion that may lack full balance.\nLevel 2 (4–6 marks): A reasonable evaluation with some use of the Figs.; mainly one-sided or descriptive; limited conclusion.\nLevel 1 (1–3 marks): A basic response, mostly lifting material from the Figs.; no clear conclusion.\n0 marks: No response or no response worthy of credit.\nIndicative content:\nBenefits: large oil and gas reserves (13%/30%) bring energy security, jobs and tax income (e.g. Alaska Permanent Fund); shorter shipping routes save fuel and time; investment in remote communities (services, infrastructure); some indigenous groups benefit from revenue sharing.\nCosts: oil spills in icy, remote waters are very hard to clean up (Exxon Valdez); habitat fragmentation and disturbance to whales, caribou, polar bears; burning more fossil fuels accelerates climate change, which is already halving summer sea ice and thawing permafrost — a global cost; threats to indigenous ways of life; increased shipping risks pollution and accidents.\nManagement: Arctic Council cooperation, stricter pipeline and tanker design (Trans-Alaska Pipeline), protected areas (e.g. Svalbard), Polar Code for shipping.\nConclusion: e.g. short-term economic benefits are outweighed by long-term global environmental costs unless development is strictly managed.` }
    ]
  },
  '2.1': {
    name: 'Urban Futures',
    questions: [
      { q: `Section A — Urban Futures.\nFig. 1 (based on UN estimates, rounded): the percentage of the world's population living in urban areas.\n1950: 30%\n1970: 37%\n1990: 43%\n2010: 52%\n2020: 56%\n2050 (forecast): 68%\n\nUsing Fig. 1, identify the first year shown in which more than half of the world's population lived in urban areas.`, marks: 1, command: 'Identify', markScheme: `2010 (1)` },
      { q: `Section A — Urban Futures.\nFig. 2 (based on UN estimates): the number of megacities in the world (cities with more than 10 million people).\n1950: 2 (New York and Tokyo)\n1990: 10\n2018: 33\n2030 (forecast): 43\n\nUsing Fig. 2, calculate the increase in the number of megacities between 1990 and 2018.`, marks: 1, command: 'Calculate', markScheme: `23 (1)` },
      { q: `Section A — Urban Futures.\nFig. 3: population of five cities in 2020 and forecast population in 2035, in millions (data written for this practice question, close to UN estimates).\nTokyo (Japan, AC): 2020 — 37.4; 2035 — 36.0\nDelhi (India, EDC): 2020 — 30.3; 2035 — 43.3\nLagos (Nigeria, LIDC): 2020 — 14.4; 2035 — 24.4\nKinshasa (DR Congo, LIDC): 2020 — 14.3; 2035 — 26.7\nLondon (UK, AC): 2020 — 9.3; 2035 — 10.8\n\nUsing Fig. 3, identify the city whose population is forecast to decrease between 2020 and 2035.`, marks: 1, command: 'Identify', markScheme: `Tokyo (1)` },
      { q: `Section A — Urban Futures.\nTokyo in Japan has a population of about 37 million people, making it the largest urban area in the world. It is described as a megacity.\n\nWhat is meant by the term 'megacity'?`, marks: 1, command: 'Define', markScheme: `A city (urban area) with a population of more than 10 million people (1).` },
      { q: `Section A — Urban Futures.\nIn the 1920s and 1930s new railway lines were built north-west of London. Thousands of semi-detached houses were built around the new stations at places such as Harrow and Wembley, and families moved out from the crowded inner city to live there.\n\nGive the term used to describe this movement of people from the inner city to the edge of the urban area.`, marks: 1, command: 'Give', markScheme: `Suburbanisation (1).` },
      { q: `Section A — Urban Futures.\nBetween 2001 and 2021 the number of people living in Manchester city centre increased rapidly. Old cotton warehouses were converted into flats and new apartment blocks were built near the universities and offices.\n\nIdentify the process that describes people moving back to live in the city centre.`, marks: 1, command: 'Identify', markScheme: `Re-urbanisation (1).` },
      { q: `Section A — Urban Futures.\nIn Lagos, Nigeria, many people earn a living as street traders, okada (motorbike taxi) riders and market stall holders. Most of this work is not registered with the government.\n\nState what is meant by the term 'informal economy'.`, marks: 1, command: 'State', markScheme: `Work that is not officially registered or taxed / not regulated by the government (1).\nAccept: jobs without contracts, tax or legal protection.` },
      { q: `Section A — Urban Futures.\nFig. 4: the results of a survey of 50 recent migrants to Lagos, Nigeria, asked for their main reason for moving to the city (data written for this practice question).\nTo find a job: 22\nTo join family members: 9\nTo go to school or college: 8\nFarming income too low / land shortage: 7\nConflict in home area: 4\n\nUsing Fig. 4, identify the most common reason for moving to Lagos.`, marks: 1, command: 'Identify', markScheme: `To find a job (22 migrants) (1)` },
      { q: `Section A — Urban Futures.\nIn Lagos, Nigeria, a large share of the city's population growth now comes from natural increase rather than from migration.\n\nGive one reason why rates of natural increase are high in cities in LIDCs such as Lagos.`, marks: 1, command: 'Give', markScheme: `One from (1):\n• Many rural–urban migrants are young adults of child-bearing age\n• Death rates have fallen due to better healthcare in the city, while birth rates remain high\n• Cultural / religious reasons for large families\n• Limited access to contraception or family planning` },
      { q: `Section A — Urban Futures.\nLondon is one of a small number of 'world cities', alongside New York, Tokyo and Paris. It is home to the headquarters of many global banks and companies.\n\nGive one other characteristic that makes London a world city.`, marks: 1, command: 'Give', markScheme: `One from (1):\n• A major global financial centre (e.g. the City of London, Canary Wharf)\n• A global transport hub, e.g. Heathrow, one of the world's busiest airports\n• An international centre of culture, media, fashion or tourism\n• A multicultural population from all over the world (over 300 languages spoken)\n• Home to world-leading universities and international organisations\nDo not credit 'headquarters of companies' as it is given in the stem.` },
      { q: `Section A — Urban Futures.\nFig. 3: population of five cities in 2020 and forecast population in 2035, in millions (data written for this practice question, close to UN estimates).\nTokyo (Japan, AC): 2020 — 37.4; 2035 — 36.0\nDelhi (India, EDC): 2020 — 30.3; 2035 — 43.3\nLagos (Nigeria, LIDC): 2020 — 14.4; 2035 — 24.4\nKinshasa (DR Congo, LIDC): 2020 — 14.3; 2035 — 26.7\nLondon (UK, AC): 2020 — 9.3; 2035 — 10.8\n\nUsing Fig. 3, calculate the forecast percentage increase in population for Lagos between 2020 and 2035. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `(24.4 − 14.4) ÷ 14.4 × 100 or 10.0 ÷ 14.4 × 100 (1)\n= 69.4% (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nFig. 3: population of five cities in 2020 and forecast population in 2035, in millions (data written for this practice question, close to UN estimates).\nTokyo (Japan, AC): 2020 — 37.4; 2035 — 36.0\nDelhi (India, EDC): 2020 — 30.3; 2035 — 43.3\nLagos (Nigeria, LIDC): 2020 — 14.4; 2035 — 24.4\nKinshasa (DR Congo, LIDC): 2020 — 14.3; 2035 — 26.7\nLondon (UK, AC): 2020 — 9.3; 2035 — 10.8\n\nUsing Fig. 3, calculate the forecast percentage change in population for Tokyo between 2020 and 2035. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `(36.0 − 37.4) ÷ 37.4 × 100 or −1.4 ÷ 37.4 × 100 (1)\n= −3.7% (a decrease of 3.7%) (1)\nAward 2 marks for the correct answer with or without working. Accept 3.7% if it is clearly described as a decrease.` },
      { q: `Section A — Urban Futures.\nThe UN estimates that the world's urban population grew from about 0.75 billion people in 1950 to about 4.2 billion people in 2018.\n\nCalculate how many times larger the world's urban population was in 2018 than in 1950. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `4.2 ÷ 0.75 (1)\n= 5.6 times larger (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nA ward in inner London has a population of 18,450 people and an area of 1.5 km² (data written for this practice question).\n\nCalculate the population density of the ward in people per km². You must show your working.`, marks: 2, command: 'Calculate', markScheme: `18,450 ÷ 1.5 (1)\n= 12,300 people per km² (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nFig. 4: the results of a survey of 50 recent migrants to Lagos, Nigeria, asked for their main reason for moving to the city (data written for this practice question).\nTo find a job: 22\nTo join family members: 9\nTo go to school or college: 8\nFarming income too low / land shortage: 7\nConflict in home area: 4\n\nUsing Fig. 4, calculate the percentage of migrants surveyed who moved to Lagos to find a job. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `22 ÷ 50 × 100 (1)\n= 44% (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nPopulation of Inner London (data written for this practice question, close to census values): 1981 — 2.55 million; 2021 — 3.40 million.\n\nCalculate the percentage increase in the population of Inner London between 1981 and 2021. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `(3.40 − 2.55) ÷ 2.55 × 100 or 0.85 ÷ 2.55 × 100 (1)\n= 33.3% (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nFig. 6: monthly rents (£) for 11 one-bedroom flats advertised in a ward in east London (data written for this practice question): 1500, 1250, 1900, 1150, 1450, 2400, 1300, 1750, 1200, 1600, 1400.\n\nCalculate the interquartile range of the rents. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `Values in order: 1150, 1200, 1250, 1300, 1400, 1450, 1500, 1600, 1750, 1900, 2400; lower quartile = £1250 and upper quartile = £1750 (1)\n1750 − 1250 = £500 (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nSome GCSE students counted pedestrians for 10 minutes at five sites along a high street in a city centre (data written for this practice question).\nSite 1: 45; Site 2: 62; Site 3: 38; Site 4: 71; Site 5: 54\n\nCalculate the mean number of pedestrians counted per site. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `(45 + 62 + 38 + 71 + 54) ÷ 5 or 270 ÷ 5 (1)\n= 54 pedestrians (1)\nAward 2 marks for the correct answer with or without working.` },
      { q: `Section A — Urban Futures.\nIn northern Nigeria many families farm small plots of land. In recent years droughts have become more frequent and the population of rural villages has grown.\n\nExplain one push factor that causes people to migrate from rural areas of Nigeria to Lagos.`, marks: 2, command: 'Explain', markScheme: `1 mark for a push factor, 1 mark for development, e.g.:\n• Drought causes crops to fail (1) so farmers cannot earn enough money or feed their families and leave to find paid work (1)\n• Shortage of farmland as the rural population grows (1) so young people have no land to inherit and move to the city (1)\n• Lack of services such as schools and hospitals (1) so families move to give their children an education (1)\n• Conflict / insecurity in rural areas (1) forces people to flee to the safety of the city (1)` },
      { q: `Section A — Urban Futures.\nFig. 4: the results of a survey of 50 recent migrants to Lagos, Nigeria, asked for their main reason for moving to the city (data written for this practice question).\nTo find a job: 22\nTo join family members: 9\nTo go to school or college: 8\nFarming income too low / land shortage: 7\nConflict in home area: 4\n\nUsing Fig. 4 and your own understanding, explain one pull factor that attracts people to Lagos.`, marks: 2, command: 'Explain', markScheme: `1 mark for a pull factor, 1 mark for development, e.g.:\n• More jobs in Lagos, e.g. at the port, in factories or in trading (1) which pay more than subsistence farming, so migrants can send money home (1)\n• Better access to education, e.g. schools and universities (1) which improve future job prospects (1)\n• Family members already live there (1) and can provide somewhere to stay and help to find work (1)\n• Better access to healthcare / clean water / electricity (1) improving quality of life (1)` },
      { q: `Section A — Urban Futures.\nFig. 5 (rounded, based on World Bank data for about 2022): percentage of the population living in urban areas and average annual rate of urban population growth.\nUK (AC): 84% urban; urban population growing by about 0.8% per year\nBrazil (EDC): 87% urban; about 0.9% per year\nNigeria (LIDC): 54% urban; about 3.9% per year\nNiger (LIDC): 17% urban; about 4.3% per year\n\nUsing Fig. 5, explain one reason why the rate of urban growth in the UK is much lower than in Nigeria.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development, e.g.:\n• The UK is already highly urbanised (84%) (1) so there are few rural people left to move to cities (1)\n• The UK urbanised during the Industrial Revolution in the 19th century (1) so most rural–urban migration happened long ago (1)\n• Natural increase in the UK is low (1) because birth rates are low in an AC (1)\n• Counter-urbanisation in the UK (1) means some people are leaving cities for rural areas (1)` },
      { q: `Section A — Urban Futures.\nLondon produces more than one-fifth of the UK's total economic output (GDP) and is the centre of the UK's government and transport networks.\n\nExplain one way in which London influences the rest of the UK.`, marks: 2, command: 'Explain', markScheme: `1 mark for an influence, 1 mark for development, e.g.:\n• It is the seat of government, Parliament at Westminster (1) so decisions made there affect laws and spending across the whole UK (1)\n• Its large economy creates jobs and taxes (1) which pay for services in other regions (1)\n• It is the hub of transport networks, e.g. rail lines and motorways radiate from London (1) so it attracts commuters and visitors from across the South East and beyond (1)\n• It is the base of national media, e.g. the BBC (1) which influences culture across the country (1)` },
      { q: `Section A — Urban Futures.\nLagos has one of the busiest container ports in West Africa at Apapa. It is home to the Nigerian Exchange (stock exchange) and to much of Nigeria's film industry, known as 'Nollywood'.\n\nExplain one way in which Lagos influences places beyond Nigeria.`, marks: 2, command: 'Explain', markScheme: `1 mark for an influence, 1 mark for development, e.g.:\n• Its port handles imports and exports for West Africa (1) including goods for land-locked countries such as Niger, linking the region to world trade (1)\n• It is a financial centre (1) attracting investment from transnational corporations into West Africa (1)\n• Nollywood films are watched across Africa and by the diaspora (1) spreading Nigerian culture internationally (1)\n• It attracts migrants from neighbouring countries such as Benin and Ghana (1) changing the populations of both places (1)` },
      { q: `Section A — Urban Futures.\nMakoko is an informal settlement on the edge of Lagos Lagoon in Lagos, Nigeria. Many homes stand on wooden stilts over the water and people travel between them by canoe.\n\nGive two characteristics of informal settlements such as Makoko.`, marks: 2, command: 'Give', markScheme: `Two from (1 mark each):\n• Homes built by residents from cheap or scavenged materials, e.g. wood, corrugated iron\n• Built on land that the residents do not legally own / no land rights\n• Lack of clean piped water and sanitation\n• Little or no legal electricity supply\n• Very high population density / overcrowding\n• Built on hazardous land, e.g. flood-prone lagoon edges\n• Few formal services such as schools and clinics` },
      { q: `Section A — Urban Futures.\nIt is estimated that more than half of all workers in Lagos work in the informal economy, for example as street traders or danfo (minibus) drivers.\n\nExplain one challenge that the informal economy creates for the Lagos state government.`, marks: 2, command: 'Explain', markScheme: `1 mark for a challenge, 1 mark for development, e.g.:\n• Informal workers do not pay income tax (1) so the government has less money to spend on infrastructure such as roads and drainage (1)\n• Street trading on roads and pavements (1) adds to traffic congestion in the city (1)\n• Work is unregulated (1) so it is hard to enforce safety standards, e.g. in unlicensed workshops (1)` },
      { q: `Section A — Urban Futures.\nComputer Village in Ikeja, Lagos, is a huge market where thousands of traders, many of them working informally, sell and repair mobile phones and computers.\n\nExplain one opportunity that the informal economy provides for people living in Lagos.`, marks: 2, command: 'Explain', markScheme: `1 mark for an opportunity, 1 mark for development, e.g.:\n• It provides work for people without qualifications (1) so new migrants can earn money as soon as they arrive (1)\n• Little money is needed to start a business (1) so people can become self-employed, e.g. repairing phones (1)\n• Workers gain skills (1) which may later help them to find formal jobs (1)\n• Provides cheap goods and services (1) which poorer residents can afford (1)` },
      { q: `Section A — Urban Futures.\nEko Atlantic is a new city district being built on land reclaimed from the Atlantic Ocean next to Victoria Island, Lagos. It is planned to include luxury apartments, offices and its own power supply, protected by a sea wall.\n\nExplain one reason why Eko Atlantic might increase inequality in Lagos.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development, e.g.:\n• Homes and offices are expensive (1) so only wealthy residents and companies can afford to live or work there, while the poor remain in informal settlements (1)\n• It has its own power and water supply (1) so services improve for the rich while the rest of the city still suffers power cuts (1)\n• Investment is focused on one district (1) instead of on improving areas such as Makoko (1)\n• Concerns that the sea wall may divert storm surges onto nearby poorer coastal areas (1) increasing flood risk for poorer communities (1)` },
      { q: `Section A — Urban Futures.\nOlusosun, in north Lagos, is one of the largest rubbish dumps in Africa. Thousands of tonnes of waste arrive every day, and fires on the site have caused clouds of smoke over nearby homes.\n\nExplain one environmental challenge caused by the rapid growth of Lagos.`, marks: 2, command: 'Explain', markScheme: `1 mark for a challenge, 1 mark for development, e.g.:\n• Waste disposal — rapid growth produces more waste than can be collected (1) so it is dumped or burned, polluting air, soil and water (1)\n• Air pollution from traffic congestion and generators (1) causing respiratory illness (1)\n• Flooding — new building covers ground and blocks drains (1) so heavy rain floods low-lying areas (1)\n• Water pollution — untreated sewage enters Lagos Lagoon (1) harming fish and health (1)` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\nCommunity groups and charities often work alongside local people to improve their neighbourhoods. This is known as a bottom-up approach.\n\nOutline one bottom-up initiative that has improved lives in a city you have studied in an LIDC or EDC.`, marks: 2, command: 'Outline', markScheme: `1 mark for a named / described initiative, 1 mark for how it improved lives, e.g.:\n• Makoko Floating School, Lagos — a school built by the community on floating barrels in 2013 (1) gave children a place to learn without needing land, before it collapsed in 2016 (1)\n• Community-led waste collection / recycling groups (1) clean up neighbourhoods and provide income (1)\n• Residents' self-help housing improvements, e.g. replacing wooden walls with blocks (1) make homes safer (1)\nCredit any valid bottom-up initiative from the learner's chosen city.` },
      { q: `Section A — Urban Futures.\nIn 2003 London introduced a daily Congestion Charge for driving into central London. In 2019 it introduced the Ultra Low Emission Zone (ULEZ), which was expanded to cover all of Greater London in 2023. Drivers of older, more polluting vehicles must pay a daily charge.\n\nExplain one way in which the ULEZ aims to make London more sustainable.`, marks: 2, command: 'Explain', markScheme: `1 mark for a way, 1 mark for development, e.g.:\n• It discourages the use of polluting vehicles (1) which reduces nitrogen dioxide and particulates, improving people's health (1)\n• Encourages people to switch to public transport, cycling or walking (1) reducing congestion and carbon emissions (1)\n• Money from charges is reinvested in public transport (1) making it a better alternative to driving (1)` },
      { q: `Section A — Urban Futures.\nSince the 1970s many villages in Devon and Cornwall have grown as families and retired people have moved there from large cities such as Birmingham and London.\n\nExplain one consequence of counter-urbanisation for rural villages.`, marks: 2, command: 'Explain', markScheme: `1 mark for a consequence, 1 mark for development, e.g.:\n• House prices rise (1) so young local people cannot afford to buy homes and move away (1)\n• Many new residents commute or own second homes (1) so village shops and pubs lose trade and close (1)\n• More traffic on narrow country lanes (1) as residents drive to work in towns (1)\n• Some services are kept open (1) because the population grows, e.g. schools gain pupils (1)` },
      { q: `Section A — Urban Futures.\nLondon's Docklands were once a busy port. After the docks closed in the 1960s–1980s, the area was redeveloped by the London Docklands Development Corporation (1981–1998). Canary Wharf now has tall office blocks for global banks.\n\nExplain one way in which the redevelopment of London's Docklands changed the area.`, marks: 2, command: 'Explain', markScheme: `1 mark for a change, 1 mark for development, e.g.:\n• Derelict docks were replaced by offices, e.g. at Canary Wharf (1) creating many new jobs in finance and services (1)\n• New transport, e.g. the Docklands Light Railway and London City Airport (1) improved links to the rest of London (1)\n• New expensive housing was built (1) bringing in wealthier residents / gentrification, which some original residents could not afford (1)\n• Former dockworkers lacked the skills for new office jobs (1) so some local unemployment remained (1)` },
      { q: `Section A — Urban Futures.\nSome GCSE students investigated how pedestrian numbers change with distance from the centre of a city. They counted pedestrians for 10 minutes at each of five sites along one high street, once, on a weekday morning.\n\nSuggest two ways in which the students could improve the reliability of their pedestrian counts.`, marks: 2, command: 'Suggest', markScheme: `Two from (1 mark each):\n• Repeat the counts at each site several times and calculate a mean\n• Count at different times of day / on different days, including weekends\n• Count at all sites at the same time, using several groups\n• Use a tally counter / clicker and agree in advance what counts as a pedestrian (e.g. both directions)\n• Increase the number of sites or the length of each count` },
      { q: `Section A — Urban Futures.\nLagos produces more than 10,000 tonnes of solid waste each day. Much of it is taken to open dumps such as Olusosun, while some is burned or dumped in drains (data rounded, written for this practice question).\n\nSuggest two ways in which waste management in Lagos could be made more sustainable.`, marks: 2, command: 'Suggest', markScheme: `Two from (1 mark each):\n• Expand recycling, e.g. support waste-picker cooperatives or recycling collection schemes\n• Separate organic waste for composting\n• Generate energy from waste or capture methane from landfill sites\n• Improve regular collection in informal settlements so waste is not dumped in drains\n• Education campaigns / reduce plastic packaging, e.g. a charge or ban on single-use plastics` },
      { q: `Section A — Urban Futures.\nFig. 1 (based on UN estimates, rounded): the percentage of the world's population living in urban areas.\n1950: 30%\n1970: 37%\n1990: 43%\n2010: 52%\n2020: 56%\n2050 (forecast): 68%\n\nDescribe the trend in the percentage of the world's population living in urban areas shown in Fig. 1.`, marks: 3, command: 'Describe', markScheme: `1 mark for each valid descriptive point, up to 3 marks. Credit use of data, e.g.:\n• The percentage living in urban areas increases throughout (1)\n• From 30% in 1950 to 56% in 2020 (1)\n• More than half of the world's population is urban by 2010 (52%) (1)\n• It is forecast to keep rising, to 68% by 2050 (1)\n• Steady rate of increase of about 6–9 percentage points every 20 years (1)\nMaximum 2 marks if no data is used.` },
      { q: `Section A — Urban Futures.\nFig. 3: population of five cities in 2020 and forecast population in 2035, in millions (data written for this practice question, close to UN estimates).\nTokyo (Japan, AC): 2020 — 37.4; 2035 — 36.0\nDelhi (India, EDC): 2020 — 30.3; 2035 — 43.3\nLagos (Nigeria, LIDC): 2020 — 14.4; 2035 — 24.4\nKinshasa (DR Congo, LIDC): 2020 — 14.3; 2035 — 26.7\nLondon (UK, AC): 2020 — 9.3; 2035 — 10.8\n\nUsing Fig. 3, compare the forecast population changes of Kinshasa and Tokyo between 2020 and 2035.`, marks: 3, command: 'Compare', markScheme: `1 mark for each valid comparative point, up to 3 marks, e.g.:\n• Kinshasa's population is forecast to grow but Tokyo's is forecast to fall (1)\n• Kinshasa grows by 12.4 million, Tokyo falls by 1.4 million (1)\n• Kinshasa's population almost doubles (+86.7%) whereas Tokyo falls by 3.7% (1)\n• In 2020 Tokyo is over two and a half times larger than Kinshasa, but the gap narrows by 2035 (1)\nCredit valid manipulated data. Statements about one city only receive no marks.` },
      { q: `Section A — Urban Futures.\nIn the 1950s and 1960s many people in UK cities such as Birmingham moved out of the inner city to new housing estates on the edge of the city, while new shopping centres and business parks were built on the outskirts.\n\nExplain the consequences of suburbanisation for a city in an AC.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• Urban sprawl onto greenfield land (1) leads to loss of farmland and habitats (1)\n• More people commute by car into the city (1) causing congestion and air pollution (1)\n• The inner city loses population and wealthier residents (1) so shops close and some areas become run-down / deprived (1)\n• Pressure to protect the countryside, e.g. green belts (1)` },
      { q: `Section A — Urban Futures.\nMakoko, an informal settlement in Lagos, Nigeria, is built on the edge of Lagos Lagoon. Parts of it are flooded every rainy season.\n\nExplain why informal settlements in LIDC cities often develop on land at risk of flooding.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• Migrants cannot afford to buy or rent formal housing (1)\n• Flood-prone land (lagoon edges, floodplains, steep slopes) is unwanted by developers or the government (1) so it is free / cheap to build on (1)\n• Land is often close to jobs, e.g. Makoko is near the city centre and fishing grounds (1)\n• Government cannot build housing fast enough for the rapidly growing population (1)` },
      { q: `Section A — Urban Futures.\nThe population of Lagos is growing by hundreds of thousands of people each year. About half of this growth is caused by natural increase.\n\nExplain how natural increase contributes to the growth of cities in LIDCs.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• Natural increase is when the birth rate is higher than the death rate (1)\n• Most rural–urban migrants are young adults (1) who then have children in the city (1)\n• Death rates in cities are lower due to better healthcare and clean water (1) while birth rates stay high, so the population grows quickly (1)` },
      { q: `Section A — Urban Futures.\nSince the 1990s the population of central Liverpool has grown. Former docks at the Albert Dock have been converted into flats, shops and museums, and new student accommodation has been built.\n\nExplain why some cities in ACs have experienced re-urbanisation.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• Regeneration of run-down brownfield sites (1) has created attractive new housing in the city centre (1)\n• Young professionals and students want to live close to work, universities and nightlife (1)\n• Government / council policies and investment encourage building on brownfield land (1)\n• Living centrally avoids long commutes and transport costs (1)` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\nIn London the average house price is many times higher than average earnings, and some boroughs have high levels of child poverty close to some of the richest areas of the UK.\n\nExplain how inequality is a challenge for a city you have studied in an AC.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks. Credit specific case-study detail, e.g. (London):\n• High house prices and rents (1) force lower-income key workers to live in overcrowded housing or commute long distances (1)\n• Gentrification, e.g. in Hackney or Shoreditch (1) displaces long-standing lower-income residents (1)\n• Differences in life expectancy between wealthy and deprived boroughs (1) linked to poor housing and health (1)\n• Unequal access to education and jobs (1)\nMaximum 2 marks for a generic answer with no case-study detail.` },
      { q: `Section A — Urban Futures.\nIn 2008 Lagos opened sub-Saharan Africa's first bus rapid transit (BRT) system, with buses running in their own dedicated lanes. A light rail line, the Blue Line, began operating in 2023.\n\nExplain how improved public transport could improve quality of life for people in Lagos.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• Dedicated lanes allow buses to avoid traffic jams (1) so journey times to work are shorter (1)\n• Fares are cheaper than many private taxis / danfos (1) so commuters save money (1)\n• Fewer cars and old minibuses on the road (1) reduces air pollution and improves health (1)\n• Safer and more reliable than informal transport (1)` },
      { q: `Section A — Urban Futures.\nLondon has been surrounded by a green belt since the 1940s–1950s. Building on green belt land is strictly controlled, although the city's population continues to grow.\n\nExplain how the green belt affects the growth of London.`, marks: 3, command: 'Explain', markScheme: `1 mark for each valid point or development, up to 3 marks, e.g.:\n• It limits urban sprawl (1) protecting farmland and countryside around London (1)\n• Development is pushed onto brownfield sites inside the city (1) increasing housing density, e.g. high-rise flats (1)\n• Shortage of building land (1) contributes to high house prices (1)\n• Growth 'leapfrogs' to towns beyond the green belt (1) so more people commute long distances into London (1)` },
      { q: `Section A — Urban Futures.\nFig. 7: a world map of megacities in 2018 (based on UN data). There are 33 megacities. About 20 are in Asia, including Tokyo, Delhi, Shanghai, Mumbai, Beijing, Dhaka and Karachi. Three are in Africa (Cairo, Lagos and Kinshasa) and six in South and Central America (including São Paulo, Mexico City and Buenos Aires). North America has two (New York and Los Angeles) and Europe has two (Moscow and Paris). There are none in Oceania.\n\nDescribe the distribution of megacities shown in Fig. 7.`, marks: 4, command: 'Describe', markScheme: `1 mark for each valid descriptive point, up to 4 marks, e.g.:\n• Uneven distribution (1)\n• Most megacities are in Asia — about 20 of 33 (1), especially in South and East Asia, e.g. India and China (1)\n• Few megacities in ACs, e.g. only two in Europe and two in North America (1)\n• Africa has three, all LIDCs/EDCs (Cairo, Lagos, Kinshasa) (1)\n• None in Oceania (1)\n• Many are coastal or on major rivers, e.g. Shanghai, Lagos (1)\nMaximum 3 marks if no data or named examples are used.` },
      { q: `Section A — Urban Futures.\nFig. 5 (rounded, based on World Bank data for about 2022): percentage of the population living in urban areas and average annual rate of urban population growth.\nUK (AC): 84% urban; urban population growing by about 0.8% per year\nBrazil (EDC): 87% urban; about 0.9% per year\nNigeria (LIDC): 54% urban; about 3.9% per year\nNiger (LIDC): 17% urban; about 4.3% per year\n\nUsing Fig. 5, explain two reasons why urbanisation is happening rapidly in LIDCs such as Nigeria and Niger.`, marks: 4, command: 'Explain', markScheme: `Up to 2 marks for each reason: 1 for the reason, 1 for development, e.g.:\n• Rural–urban migration (1) due to push factors such as drought and poverty and pull factors such as jobs in cities (1)\n• High natural increase (1) because young migrants have children and death rates in cities have fallen (1)\n• Low current levels of urbanisation, e.g. Niger 17% (1) mean there is a large rural population that could move (1)\n• Economic development / industrialisation (1) creates factory and service jobs in cities (1)` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\nLondon has changed a great deal since the 1980s, with new transport links, regeneration projects and a growing and more diverse population.\n\nExplain two ways in which a city you have studied in an AC is changing.`, marks: 4, command: 'Explain', markScheme: `Up to 2 marks for each way: 1 for the change, 1 for development / specific detail, e.g. (London):\n• Population growth through international migration (1) has made the city more ethnically and culturally diverse (1)\n• Regeneration of brownfield sites, e.g. the Queen Elizabeth Olympic Park in Stratford (1) has brought new homes, jobs and the Westfield shopping centre (1)\n• New transport links, e.g. the Elizabeth line opened in 2022 (1) improving journey times across the city (1)\n• Deindustrialisation and growth of finance and services (1) e.g. Canary Wharf (1)\n• Gentrification of inner areas such as Shoreditch (1)\nMaximum 2 marks for generic answers with no place-specific detail.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\nLagos, Nigeria, grew from about 0.3 million people in 1950 to well over 10 million today.\n\nExplain two challenges caused by the rapid growth of a city you have studied in an LIDC or EDC.`, marks: 4, command: 'Explain', markScheme: `Up to 2 marks for each challenge: 1 for the challenge, 1 for development / specific detail, e.g. (Lagos):\n• Housing shortage (1) so many people live in informal settlements such as Makoko without clean water or sanitation (1)\n• Traffic congestion ('go-slows') (1) leading to long commutes and air pollution (1)\n• Waste disposal (1) e.g. Olusosun dump is overloaded and fires release toxic smoke (1)\n• Unreliable electricity (1) so businesses rely on diesel generators, which are expensive and polluting (1)\n• Lack of formal jobs (1) so many work in the informal economy without security (1)` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\n\nExamine how one sustainability strategy has changed a city you have studied in an AC.`, marks: 6, command: 'Examine', markScheme: `Indicative content (credit other valid points):\nStrategies could include (London): ULEZ and Congestion Charge; Santander Cycles hire scheme (2010) and cycle superhighways; BedZED eco-village in Sutton (2002); Queen Elizabeth Olympic Park green spaces; Thames Barrier and green infrastructure; recycling targets.\n• Describe the strategy with specific detail (when, where, how)\n• Environmental changes, e.g. reduced nitrogen dioxide; more green space; lower carbon homes\n• Social changes, e.g. health benefits of cycling; affordable housing\n• Economic changes, e.g. costs for drivers and small businesses; charges reinvested in transport\n• Limitations, e.g. scale is small compared with the size of the city\nHigher levels examine both the success and the limits of the change.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed examination, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed examination, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic examination, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\n\nExplain how a city you have studied in an AC influences the region, the country and the wider world.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\n• Regional: London's commuter belt across the South East; shopping, hospitals and universities serve the region\n• National: seat of government and Parliament; about one-fifth of UK GDP; national transport hub; national media (BBC)\n• International: global financial centre (City of London, Canary Wharf); Heathrow links to the world; headquarters of transnational corporations; culture and tourism (around 20 million international visitors a year); diverse population with global links\nHigher levels explain influence at all three scales with specific detail.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\nFig. 4: the results of a survey of 50 recent migrants to Lagos, Nigeria, asked for their main reason for moving to the city (data written for this practice question).\nTo find a job: 22\nTo join family members: 9\nTo go to school or college: 8\nFarming income too low / land shortage: 7\nConflict in home area: 4\n\nUsing Fig. 4 and your own understanding, explain the causes of rapid growth of a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\n• Rural–urban migration: push factors (drought, low farm incomes, land shortage, conflict, lack of services) and pull factors (jobs, education, family, healthcare)\n• Use of Fig. 4, e.g. 44% of migrants came to find a job\n• Natural increase: young migrant population, high birth rates, falling death rates\n• Economic role of the city, e.g. Lagos as Nigeria's commercial centre and main port, attracting investment and TNCs\n• International migration from neighbouring countries\nHigher levels link migration and natural increase and use specific detail.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nAnalyse the challenges facing people who live in informal settlements in a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Analyse', markScheme: `Indicative content (credit other valid points):\nExample (Lagos — Makoko, Otodo-Gbame):\n• Housing: homes on stilts made of wood; overcrowding; fire risk\n• Lack of clean water and sanitation; waste and sewage into the lagoon; waterborne diseases such as cholera\n• Flooding during the rainy season\n• No legal land rights — risk of forced eviction, e.g. demolition of Otodo-Gbame in 2017\n• Limited access to schools and healthcare\n• Reliance on insecure informal jobs, e.g. fishing, sawmilling\nAnalysis: links between challenges (e.g. lack of land rights discourages investment in homes) and which are most significant.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed analysis, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed analysis, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic analysis, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nAssess the opportunities for people living in a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Assess', markScheme: `Indicative content (credit other valid points):\n• Economic: more jobs in formal and informal sectors, e.g. port, oil-related industries, banking, Computer Village; higher incomes than rural areas\n• Social: access to schools, universities, hospitals; entertainment, e.g. Nollywood, music industry\n• Infrastructure: BRT, Blue Line rail, electricity and water (where available)\n• Assessment: opportunities are unequal — many residents are excluded by cost, insecure informal work or living in informal settlements\nHigher levels make a supported judgement about how far opportunities are shared.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed assessment, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed assessment, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic assessment, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nFig. 5 (rounded, based on World Bank data for about 2022): percentage of the population living in urban areas and average annual rate of urban population growth.\nUK (AC): 84% urban; urban population growing by about 0.8% per year\nBrazil (EDC): 87% urban; about 0.9% per year\nNigeria (LIDC): 54% urban; about 3.9% per year\nNiger (LIDC): 17% urban; about 4.3% per year\n\nUsing Fig. 5 and your own understanding, explain why rates of urbanisation differ between countries at different levels of development.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\n• ACs (UK 84% urban, slow growth 0.8%): urbanised in the 19th century with industrialisation; low natural increase; counter-urbanisation and suburbanisation\n• EDCs (Brazil 87% urban): rapid urbanisation in the late 20th century as industry grew; now slowing\n• LIDCs (Nigeria 3.9%, Niger 4.3% per year): rapid rural–urban migration and high natural increase; large rural populations still to move\n• Link to economic development: as economies shift from farming to industry and services, people move to cities\nHigher levels use the data and link rates to stage of development.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nFig. 1 (based on UN estimates, rounded): the percentage of the world's population living in urban areas.\n1950: 30%\n1970: 37%\n1990: 43%\n2010: 52%\n2020: 56%\n2050 (forecast): 68%\nFig. 2 (based on UN estimates): the number of megacities in the world (cities with more than 10 million people).\n1950: 2 (New York and Tokyo)\n1990: 10\n2018: 33\n2030 (forecast): 43\n\nUsing Figs. 1 and 2, explain the global trends in urbanisation since 1950.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\n• Description of trend using data: urban share 30% (1950) to 56% (2020); urban population over half the world since about 2007–2010; forecast 68% by 2050\n• Megacities from 2 in 1950 to 33 in 2018 and 43 forecast by 2030\n• Growth now fastest in LIDCs and EDCs in Asia and Africa; most new megacities are there\n• Reasons: rural–urban migration, natural increase, industrialisation and globalisation\n• ACs urbanised earlier and are growing slowly\nHigher levels explain the trends rather than simply describe the data.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\n\nExamine the social and economic challenges facing a city you have studied in an AC.`, marks: 6, command: 'Examine', markScheme: `Indicative content (credit other valid points):\nExample (London):\n• Housing: high house prices and rents; shortage of affordable homes; overcrowding\n• Inequality and deprivation, e.g. contrasts between Kensington and Chelsea and parts of Tower Hamlets / Newham\n• Transport congestion and overcrowded trains\n• Pressure on services such as schools and hospitals from population growth\n• Economic: high costs for businesses; dependence on financial services; deindustrialisation left some areas with unemployment\nHigher levels examine which challenges are most significant and why.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed examination, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed examination, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic examination, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nEvaluate one top-down strategy used to improve a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Evaluate', markScheme: `Indicative content (credit other valid points):\nExample (Lagos): Lagos BRT (2008); Lagos Rail Mass Transit Blue Line (2023); Eko Atlantic; Lagos state housing schemes; demolition and relocation of informal settlements.\n• Describe the strategy (who funds/plans it, scale)\n• Successes, e.g. BRT carries large numbers of commuters, shorter journeys, cleaner buses\n• Limitations, e.g. not enough buses to meet demand; Eko Atlantic serves the wealthy; evictions harm the poorest\n• Judgement: who benefits, and how sustainable is it?\nHigher levels reach a supported evaluation of effectiveness.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed evaluation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed evaluation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic evaluation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nAnalyse how bottom-up approaches can improve the lives of people in a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Analyse', markScheme: `Indicative content (credit other valid points):\n• Definition: community-led projects, often supported by NGOs, with local decision-making\n• Examples (Lagos): Makoko Floating School (2013); community savings groups; residents' associations improving drainage; informal waste-picker and recycling cooperatives\n• Benefits: low cost, meet local needs, use local skills, give residents a voice\n• Limitations: small scale, depend on funding, lack land rights, may not survive (Floating School collapsed in 2016)\nHigher levels analyse why the approaches work and their limits compared with top-down schemes.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed analysis, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed analysis, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic analysis, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC). London hosted the Olympic Games in 2012. The Queen Elizabeth Olympic Park was built on former industrial land in Stratford, east London.\n\nExamine how changes in a city you have studied in an AC have created opportunities for people living there.`, marks: 6, command: 'Examine', markScheme: `Indicative content (credit other valid points):\n• Regeneration of Stratford: new homes (East Village), jobs, Westfield Stratford City, new university campus and cultural quarter (East Bank)\n• Transport improvements: Elizabeth line, DLR and Overground links\n• Economic: growth of finance, technology and creative industries (e.g. Tech City around Old Street)\n• Social and cultural: diverse population, festivals, museums, parks\n• Environmental: new parks and green spaces, cycle networks\n• Some opportunities are unequal, e.g. new housing too expensive for local people\nHigher levels examine who benefits from the opportunities.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed examination, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed examination, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic examination, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nExplain the environmental challenges facing a city you have studied in an LIDC or EDC.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\nExample (Lagos):\n• Waste: Olusosun dump; uncollected waste blocking drains\n• Water pollution: untreated sewage and industrial waste in Lagos Lagoon\n• Air pollution: congestion, old vehicles, diesel generators\n• Flooding: low-lying coastal city, sea-level rise, coastal erosion; heavy rain floods informal settlements\n• Loss of wetlands and mangroves through land reclamation\nHigher levels explain causes and effects with specific detail.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nSince 1945 many UK cities have experienced suburbanisation, then counter-urbanisation, and more recently re-urbanisation.\n\nExplain how these processes have changed cities in ACs.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit other valid points):\n• Suburbanisation: growth of suburbs with improved transport and car ownership; urban sprawl; out-of-town retail; decline of inner cities\n• Counter-urbanisation: movement to rural areas and small towns; commuter villages; loss of population and tax income from cities\n• Re-urbanisation: regeneration of brownfield sites, city-centre flats, students and young professionals, e.g. Manchester, Liverpool, London Docklands; gentrification\n• Effects on services, house prices, transport and the environment\nHigher levels explain all three processes and link them to change in the city.\n\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of the topic. Applies knowledge and understanding to produce a thorough and well-developed explanation, supported by accurate and specific detail. There is a well-developed line of reasoning which is clear and logically structured. The information presented is relevant and substantiated.\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding. Applies knowledge and understanding to produce a sound but partially developed explanation, with some specific detail. There is a line of reasoning presented with some structure. The information presented is in the most part relevant and supported by some evidence.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Applies limited knowledge and understanding to produce a basic explanation, which may be generic. The information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\n\nAssess the extent to which the opportunities of living in a city you have studied in an AC outweigh the challenges.`, marks: 8, command: 'Assess', markScheme: `Indicative content (credit other valid points):\nOpportunities (London): wide range of jobs and higher average wages; world-class universities, hospitals, culture; excellent public transport; diversity.\nChallenges: high cost of housing; inequality and deprivation; air pollution; congestion; pressure on services.\nJudgement: depends on who you are — opportunities are greatest for high earners; challenges fall hardest on low-income groups. Strategies (e.g. ULEZ, affordable housing targets) are reducing some challenges.\nHigher levels reach a clear, supported judgement.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough assessment with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound assessment; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic assessment with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nTo what extent have strategies improved the quality of life for people in a city you have studied in an LIDC or EDC? [8 marks + 3 marks for SPaG]`, marks: 8, command: 'To what extent', markScheme: `Indicative content (credit other valid points):\nStrategies (Lagos): BRT and Blue Line rail; Eko Atlantic; Lagos state housing schemes; waste management and recycling initiatives; Makoko Floating School and other bottom-up projects; slum clearance and relocation.\nImprovements: faster, cheaper commuting; some new housing; better waste collection; education in Makoko.\nLimitations: benefits are uneven; Eko Atlantic serves the wealthy; evictions (e.g. Otodo-Gbame, 2017) worsen life for the poor; schemes too small for the rate of growth; informal settlements still lack water and sanitation.\nHigher levels reach a balanced, supported judgement on the extent of improvement.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough assessment with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound assessment; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic assessment with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.\n\nSPaG (3 marks):\nHigh performance (3 marks): Learners spell and punctuate with consistent accuracy; use rules of grammar with effective control of meaning overall; use a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): Learners spell and punctuate with considerable accuracy; use rules of grammar with general control of meaning overall; use a good range of specialist terms as appropriate.\nThreshold performance (1 mark): Learners spell and punctuate with reasonable accuracy; use rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; use a limited range of specialist terms as appropriate.\nNo marks awarded (0 marks): The learner writes nothing, or the response does not relate to the question, or errors severely hinder meaning.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in an advanced country (AC).\n\nEvaluate how far transport strategies have made a city you have studied in an AC more sustainable.`, marks: 8, command: 'Evaluate', markScheme: `Indicative content (credit other valid points):\nStrategies (London): Congestion Charge (2003); ULEZ (2019, London-wide 2023); Santander Cycles and cycle superhighways; Elizabeth line (2022); electric and hydrogen buses; Oyster / contactless integrated ticketing.\nEnvironmental: lower nitrogen dioxide; fewer polluting vehicles; lower carbon emissions.\nSocial: better access across the city; health benefits from walking and cycling; but costs for poorer drivers and some outer-London residents.\nEconomic: revenue reinvested; cost to small businesses.\nJudgement on how sustainable overall; car use remains high in outer London.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough evaluation with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound evaluation; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic evaluation with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nFig. 4: the results of a survey of 50 recent migrants to Lagos, Nigeria, asked for their main reason for moving to the city (data written for this practice question).\nTo find a job: 22\nTo join family members: 9\nTo go to school or college: 8\nFarming income too low / land shortage: 7\nConflict in home area: 4\n\nUsing Fig. 4 and your own understanding, assess whether rural–urban migration or natural increase is the more important cause of urban growth in LIDCs and EDCs.`, marks: 8, command: 'Assess', markScheme: `Indicative content (credit other valid points):\nRural–urban migration: push/pull factors; Fig. 4 shows job opportunities (44%) as the main pull; migration dominated early rapid growth of cities such as Lagos.\nNatural increase: young migrants raise birth rates; falling death rates; now accounts for around half or more of urban growth in many LIDC cities.\nThe two are linked — migration creates a young population which increases natural increase.\nJudgement: importance varies over time and between cities.\nHigher levels make a supported judgement and use Fig. 4.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough assessment with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound assessment; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic assessment with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nFig. 2 (based on UN estimates): the number of megacities in the world (cities with more than 10 million people).\n1950: 2 (New York and Tokyo)\n1990: 10\n2018: 33\n2030 (forecast): 43\n\n'Megacities in LIDCs and EDCs bring more problems than benefits.' To what extent do you agree with this statement?`, marks: 8, command: 'To what extent', markScheme: `Indicative content (credit other valid points):\nProblems: informal settlements; congestion; pollution; waste; pressure on water, power and services; inequality.\nBenefits: economies of scale; concentration of jobs and investment; centres of innovation and culture; better access to services than rural areas; drive national economic growth (e.g. Lagos as Nigeria's commercial centre).\nFig. 2: number of megacities rising from 10 (1990) to a forecast 43 (2030), mostly in LIDCs/EDCs.\nJudgement: depends on governance and investment in infrastructure.\nHigher levels reach a clear, supported judgement using named examples.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough assessment with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound assessment; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic assessment with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Urban Futures.\nCASE STUDY — Challenges and opportunities in a major city in a low-income developing country (LIDC) or an emerging developing country (EDC).\n\nAssess the importance of the informal economy to a city you have studied in an LIDC or EDC.`, marks: 8, command: 'Assess', markScheme: `Indicative content (credit other valid points):\nImportance: employs a large share (over half) of workers in Lagos; provides work for migrants without qualifications; cheap goods and services; entrepreneurship, e.g. Computer Village, Alaba market; recycling by waste pickers.\nDrawbacks: no tax income for government; no legal protection or pensions; low and insecure incomes; street trading adds to congestion; unsafe working conditions.\nJudgement on overall importance, e.g. essential to the city's functioning but traps some people in poverty.\n\nLevel 3 (6–8 marks): Demonstrates thorough knowledge and understanding. Applies knowledge and understanding to produce a thorough assessment with a well-supported, balanced judgement or conclusion. Uses accurate, specific detail (data, named places, named schemes). There is a well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–5 marks): Demonstrates reasonable knowledge and understanding. Produces a sound assessment; a judgement may be given but is partly supported or one-sided. Some specific detail. There is a line of reasoning presented with some structure.\nLevel 1 (1–2 marks): Demonstrates basic knowledge and understanding. Produces a basic assessment with little or no judgement; detail is generic. The information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — Lagos, Nigeria.\nFig. 8 (data written for this practice question): population of Lagos — 1990: 4.8 million; 2010: 10.6 million; 2020: 14.4 million. About two-thirds of residents are estimated to live in informal settlements.\nFig. 9: Makoko, an informal settlement on Lagos Lagoon. Wooden homes on stilts; residents fish and process timber; no piped water or sewerage; the community is close to the city centre and the Third Mainland Bridge.\nFig. 10: three options for Makoko.\nOption 1 — Clear the settlement and relocate residents to new government flats 30 km away on the edge of the city.\nOption 2 — Upgrade the settlement in place: give residents legal rights to their land, build walkways, water points, toilets and floating schools, working with community groups.\nOption 3 — Sell the waterfront land to a private developer to build luxury housing, and use the money to build low-cost housing elsewhere in Lagos.\n\nUsing Figs. 8, 9 and 10, and your own understanding, justify which option would be the most sustainable for Makoko.`, marks: 12, command: 'Justify', markScheme: `Indicative content (credit other valid points):\nCredit any option if it is well justified.\nOption 1: modern housing with services; but far from jobs (fishing, city-centre work), loss of community, transport costs; evictions such as Otodo-Gbame (2017) were criticised.\nOption 2: keeps people near jobs and community; bottom-up and low cost; builds on Makoko Floating School idea; land rights encourage investment; but slower, flood risk remains, needs ongoing funding.\nOption 3: brings investment and tax income, similar to Eko Atlantic; but displaces the poor, increases inequality, uncertain whether low-cost housing is delivered.\nUse of Fig. 8: population nearly tripled 1990–2020 (4.8 to 14.4 million) — any solution must cope with continued growth.\nSustainability: social, economic and environmental pillars; future generations.\nHigher levels justify the choice and explain why the other options are less sustainable.\n\nLevel 4 (10–12 marks): Thorough knowledge and understanding of the place and the issue. Makes thorough and accurate use of the Figures, interpreting the evidence (including data) and linking it to own understanding. Produces a thorough justification with a well-justified, substantiated conclusion that considers more than one point of view. Well-developed line of reasoning, clear and logically structured.\nLevel 3 (7–9 marks): Reasonable knowledge and understanding. Makes good use of the Figures, with some interpretation of the evidence and some own understanding. Produces a clear justification with a supported conclusion, although balance may be uneven. Clear line of reasoning with some structure.\nLevel 2 (4–6 marks): Some knowledge and understanding. Uses the Figures, mostly by description or lifting of material, with limited own understanding. Produces a partial justification; any conclusion is simple or weakly supported.\nLevel 1 (1–3 marks): Basic knowledge and understanding. Limited use of the Figures, with little or no interpretation. A basic justification with no clear conclusion. Information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — Stratford, east London.\nFig. 11: before 2005 the area of the Lower Lea Valley in Stratford was mostly derelict industrial land with contaminated soil, scrapyards and polluted rivers. It lay in some of the most deprived wards in England.\nFig. 12: changes since the 2012 Olympic Games — Queen Elizabeth Olympic Park with large areas of parkland and restored rivers and wetlands; the former athletes' village converted into the East Village housing; Westfield Stratford City shopping centre; the Olympic Stadium now used by West Ham United; a new cultural and education quarter (East Bank) including university and museum buildings; new rail links including the Elizabeth line.\nFig. 13: views — a local resident: 'The park is beautiful, but I can't afford the new flats.' A business owner: 'Stratford is now one of the best-connected places in London.' A community group: 'Not enough of the new homes are genuinely affordable.'\n\nUsing Figs. 11, 12 and 13, and your own understanding, evaluate how far the regeneration of Stratford has made east London more sustainable.`, marks: 12, command: 'Evaluate', markScheme: `Indicative content (credit other valid points):\nEnvironmental: decontaminated brownfield land, new parkland, restored rivers and wetlands, good public transport reduces car use.\nEconomic: jobs in retail (Westfield), construction, education and culture; investment attracted; better connectivity.\nSocial: new housing and facilities; sports venues open to the public; but gentrification and concerns over affordable housing (Fig. 13); some local residents priced out.\nJudgement on 'how far': clear environmental gains; economic gains; social sustainability more contested.\nHigher levels interpret the Figures, use own understanding and reach a balanced, substantiated conclusion.\n\nLevel 4 (10–12 marks): Thorough knowledge and understanding of the place and the issue. Makes thorough and accurate use of the Figures, interpreting the evidence (including data) and linking it to own understanding. Produces a thorough evaluation with a well-justified, substantiated conclusion that considers more than one point of view. Well-developed line of reasoning, clear and logically structured.\nLevel 3 (7–9 marks): Reasonable knowledge and understanding. Makes good use of the Figures, with some interpretation of the evidence and some own understanding. Produces a clear evaluation with a supported conclusion, although balance may be uneven. Clear line of reasoning with some structure.\nLevel 2 (4–6 marks): Some knowledge and understanding. Uses the Figures, mostly by description or lifting of material, with limited own understanding. Produces a partial evaluation; any conclusion is simple or weakly supported.\nLevel 1 (1–3 marks): Basic knowledge and understanding. Limited use of the Figures, with little or no interpretation. A basic evaluation with no clear conclusion. Information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — Global urbanisation.\nFig. 14 (based on UN estimates, rounded): the percentage of the world's population living in urban areas.\n1950: 30%\n1970: 37%\n1990: 43%\n2010: 52%\n2020: 56%\n2050 (forecast): 68%\nFig. 15 (based on UN estimates): the number of megacities in the world (cities with more than 10 million people).\n1950: 2 (New York and Tokyo)\n1990: 10\n2018: 33\n2030 (forecast): 43\nFig. 16: adapted from a UN report (2018) — 'Close to 90% of the increase in the world's urban population by 2050 is expected to take place in Asia and Africa. Well-managed urbanisation can help to reduce poverty, but cities that grow without planning face severe shortages of housing, water and transport.'\n\n'The rapid growth of cities in LIDCs and EDCs cannot be sustainable.' Using Figs. 14, 15 and 16, and your own understanding, discuss this statement.`, marks: 12, command: 'Discuss', markScheme: `Indicative content (credit other valid points):\nAgree: rate of growth (urban share 30% to 68%; megacities 2 to 43) outpaces provision of housing, water, sanitation and transport; informal settlements; pollution and waste; climate risks for coastal megacities, e.g. Lagos.\nDisagree: cities offer economies of scale; higher incomes and services than rural areas; examples of sustainable strategies, e.g. Lagos BRT and Blue Line, bottom-up upgrading, Curitiba-style planning; Fig. 16 says well-managed urbanisation can reduce poverty.\nComparison with ACs, where growth is slow and cities have invested in sustainability over time.\nHigher levels use the Figures and named examples and reach a substantiated conclusion about whether sustainability depends on management.\n\nLevel 4 (10–12 marks): Thorough knowledge and understanding of the place and the issue. Makes thorough and accurate use of the Figures, interpreting the evidence (including data) and linking it to own understanding. Produces a thorough discussion with a well-justified, substantiated conclusion that considers more than one point of view. Well-developed line of reasoning, clear and logically structured.\nLevel 3 (7–9 marks): Reasonable knowledge and understanding. Makes good use of the Figures, with some interpretation of the evidence and some own understanding. Produces a clear discussion with a supported conclusion, although balance may be uneven. Clear line of reasoning with some structure.\nLevel 2 (4–6 marks): Some knowledge and understanding. Uses the Figures, mostly by description or lifting of material, with limited own understanding. Produces a partial discussion; any conclusion is simple or weakly supported.\nLevel 1 (1–3 marks): Basic knowledge and understanding. Limited use of the Figures, with little or no interpretation. A basic discussion with no clear conclusion. Information is communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` }
    ]
  },
  '2.2': {
    name: 'Dynamic Development',
    questions: [
      { q: `Section A — Dynamic Development.\nFig. 1 is a table of development indicators for five countries (data written for this practice question).\nNorway — GNI per capita US$84 990; life expectancy 83.2 years; adult literacy 99%; HDI 0.966\nUK — GNI per capita US$49 240; life expectancy 81.3 years; adult literacy 99%; HDI 0.940\nBrazil — GNI per capita US$9 140; life expectancy 75.9 years; adult literacy 94%; HDI 0.760\nZambia — GNI per capita US$1 240; life expectancy 61.8 years; adult literacy 87%; HDI 0.569\nEthiopia — GNI per capita US$1 020; life expectancy 65.0 years; adult literacy 52%; HDI 0.497\n\nIdentify the country in Fig. 1 with the lowest Human Development Index (HDI).`, marks: 1, command: 'Identify', markScheme: `Ethiopia (1)` },
      { q: `Section A — Dynamic Development.\nFig. 1 lists four indicators used to compare the development of countries: GNI per capita; life expectancy at birth; percentage of adults who can read and write; number of doctors per 1 000 people.\n\nIdentify the economic indicator of development in Fig. 1.`, marks: 1, command: 'Identify', markScheme: `GNI per capita (1)\nDo not credit any of the social indicators.` },
      { q: `Section A — Dynamic Development.\nFig. 2 is a description of a map of southern Africa. Zambia is a landlocked country. It is bordered by the Democratic Republic of the Congo to the north, Tanzania to the north-east, Malawi to the east, Mozambique to the south-east, Zimbabwe and Botswana to the south, Namibia to the south-west and Angola to the west. The Zambezi River forms much of its southern border.\n\nName one country in Fig. 2 that borders Zambia to the south.`, marks: 1, command: 'Give', markScheme: `One from: Zimbabwe / Botswana (1)\nAllow Namibia (south-west) or Mozambique (south-east).` },
      { q: `Section A — Dynamic Development.\nFig. 3 is a description of a diagram of Rostow's model of economic development. Five steps rise from left to right. Step 2 is labelled 'Pre-conditions for take-off', step 3 'Take-off', step 4 'Drive to maturity' and step 5 'Age of high mass consumption'. The label for step 1 is missing.\n\nState the name of step 1 of Rostow's model.`, marks: 1, command: 'State', markScheme: `Traditional society (1)\nAllow 'traditional subsistence society'.` },
      { q: `Section A — Dynamic Development.\nFig. 4 is a pie chart showing the value of Zambia's exports by type in one year (data written for this practice question): copper 74%; other minerals (cobalt, gold, gemstones) 12%; agricultural products (sugar, tobacco, maize, cotton) 6%; manufactured goods and other 8%.\n\nWhat percentage of the value of Zambia's exports came from copper?`, marks: 1, command: 'State', markScheme: `74% (1)` },
      { q: `Section A — Dynamic Development.\nFig. 5 shows life expectancy at birth for five LIDCs in sub-Saharan Africa (data written for this practice question): Zambia 61.8 years; Ethiopia 65.0 years; Malawi 62.9 years; Mozambique 59.3 years; Uganda 63.7 years.\n\nCalculate the range of life expectancy shown in Fig. 5.`, marks: 1, command: 'Calculate', markScheme: `5.7 years (1)\n(65.0 − 59.3 = 5.7)` },
      { q: `Section A — Dynamic Development.\nA student used one bar chart to show the HDI of 30 countries from every continent, with the countries listed in alphabetical order along the x-axis.\n\nSuggest an alternative way of displaying this data that would show the global pattern of development more clearly.`, marks: 1, command: 'Suggest', markScheme: `Choropleth map / shaded world map of HDI (1)\nAllow proportional symbols on a world map. Do not credit pie chart or line graph.` },
      { q: `Section A — Dynamic Development.\nFig. 1 shows the population of Zambia from its national censuses: 2010 — 13.09 million; 2022 — 19.61 million.\n\nCalculate the percentage change in Zambia's population between 2010 and 2022. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (19.61 − 13.09) ÷ 13.09 × 100 / 6.52 ÷ 13.09 × 100 (1)\n1 mark for answer: 49.8% (increase) (1)\nAllow 50% if working shown. Correct answer with no working = 1 mark.` },
      { q: `Section A — Dynamic Development.\nFig. 2 shows GNI per capita for five LIDCs (data written for this practice question): Zambia US$1 240; Ethiopia US$1 020; Malawi US$640; Mozambique US$530; Uganda US$970.\n\nCalculate the mean GNI per capita of the five countries in Fig. 2. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (1 240 + 1 020 + 640 + 530 + 970) ÷ 5 / 4 400 ÷ 5 (1)\n1 mark for answer: US$880 (1)` },
      { q: `Section A — Dynamic Development.\nFig. 3 shows GNI per capita for two countries (data written for this practice question): UK US$49 240; Zambia US$1 240.\n\nCalculate how many times greater the GNI per capita of the UK is than that of Zambia. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 49 240 ÷ 1 240 (1)\n1 mark for answer: 39.7 (times greater) (1)` },
      { q: `Section A — Dynamic Development.\nFig. 4 shows the HDI of seven LIDCs (data written for this practice question): 0.569, 0.497, 0.508, 0.461, 0.550, 0.394, 0.525.\n\nCalculate the median HDI of the seven countries. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: values placed in rank order 0.394, 0.461, 0.497, 0.508, 0.525, 0.550, 0.569 / identifies the 4th value (1)\n1 mark for answer: 0.508 (1)` },
      { q: `Section A — Dynamic Development.\nFig. 5 shows the average world price of copper (data written for this practice question): 2011 — US$8 800 per tonne; 2016 — US$4 900 per tonne. Copper makes up about three-quarters of the value of Zambia's exports.\n\nCalculate the percentage change in the price of copper between 2011 and 2016. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (4 900 − 8 800) ÷ 8 800 × 100 / −3 900 ÷ 8 800 × 100 (1)\n1 mark for answer: −44.3% / a decrease of 44.3% (1)\nAllow −44% if working shown.` },
      { q: `Section A — Dynamic Development.\nFig. 1 is a table of development indicators (data written for this practice question).\nUK — life expectancy 81.3 years; adult literacy 99%\nEthiopia — life expectancy 65.0 years; adult literacy 52%\n\nUsing Fig. 1, compare the social development of the UK and Ethiopia.`, marks: 2, command: 'Compare', markScheme: `1 mark per valid comparison, up to 2 marks:\nLife expectancy in the UK is higher than in Ethiopia / 16.3 years longer (1)\nAdult literacy is higher in the UK / almost twice as high / 47 percentage points higher (1)\nAllow overall statement that the UK is more socially developed only if supported by data.` },
      { q: `Section A — Dynamic Development.\nFig. 2 is a description of a map showing that Zambia is landlocked in south-central Africa. Its copper exports travel about 2 000 km by rail or road to ports such as Dar es Salaam in Tanzania or Durban in South Africa.\n\nExplain one way that being landlocked may slow the development of Zambia.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nExports must travel long distances to the coast / through other countries (1) which raises transport costs so Zambian goods are less competitive / profits are lower (1)\nOR relies on neighbours' ports and roads (1) so trade can be disrupted by border delays or political problems in those countries (1)\nOR imports such as fuel and machinery cost more (1) which raises the cost of production / living (1)` },
      { q: `Section A — Dynamic Development.\nIn 2024 a severe drought in southern Africa reduced the water level behind the Kariba Dam on the Zambezi River. Zambia gets most of its electricity from hydro-electric power, and many homes and businesses had power cuts for most of the day.\n\nExplain one way that a physical factor such as drought can affect the development of a country.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nDrought reduces HEP generation / causes power cuts (1) so factories and mines produce less, reducing income and jobs (1)\nOR crop failure (1) leads to food shortages / malnutrition / loss of farm income (1)\nOR government must spend money on food aid / imports (1) leaving less to spend on schools, health or infrastructure (1)` },
      { q: `Section A — Dynamic Development.\nZambia was ruled by Britain as Northern Rhodesia until independence in 1964. During that time railways were built to carry copper from the Copperbelt to ports for export to Europe.\n\nExplain one way that colonialism has contributed to uneven development.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nColonies were set up to export raw materials / primary products (1) so the economy still depends on low-value exports such as copper rather than manufacturing (1)\nOR profits from resources went to the colonial power (1) so little was invested in local education, health or industry (1)\nOR infrastructure was built only to link mines to ports (1) so other regions were left undeveloped / unequal (1)` },
      { q: `Section A — Dynamic Development.\nFirst Quantum Minerals is a TNC with its headquarters in Canada. It runs the Kansanshi and Sentinel copper mines in north-west Zambia, which together employ thousands of Zambian workers.\n\nExplain one way that a TNC such as First Quantum Minerals may benefit the development of Zambia.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nCreates jobs (1) giving workers a regular wage which increases spending in the local economy (multiplier effect) (1)\nOR pays taxes / mining royalties to the government (1) which can be spent on schools, hospitals or roads (1)\nOR brings investment and new technology / skills training (1) improving the skills of the workforce (1)\nOR builds infrastructure such as roads, power lines, clinics or housing (1) which local people can also use (1)` },
      { q: `Section A — Dynamic Development.\nA donor country gives an LIDC a loan to build a new road. The aid is tied: the LIDC must use construction companies and equipment from the donor country.\n\nExplain one disadvantage of tied aid for the LIDC.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nMoney flows back to the donor's companies (1) so fewer local jobs / less money stays in the LIDC economy (1)\nOR goods and services may be more expensive than buying locally / on the open market (1) so less is achieved with the aid (1)\nOR a loan must be repaid with interest (1) adding to the country's debt (1)` },
      { q: `Section A — Dynamic Development.\nThe UK gives aid to Zambia in two ways: directly from the UK government to the Zambian government, and through the World Bank, which pools money from many countries.\n\nExplain the difference between bilateral and multilateral aid.`, marks: 2, command: 'Explain', markScheme: `Bilateral aid is given directly from one country's government to another (1)\nMultilateral aid is given by several countries through an international organisation such as the World Bank / UN / IMF (1)` },
      { q: `Section A — Dynamic Development.\nFig. 6 describes two projects in Ethiopia. Project A: a large dam on the Blue Nile planned and funded by the national government to generate electricity for the whole country. Project B: a charity helps villagers dig and manage their own wells and hand pumps.\n\nOutline one difference between top-down and bottom-up development, using Fig. 6.`, marks: 2, command: 'Outline', markScheme: `1 mark for the difference, 1 mark for use of Fig. 6:\nTop-down is planned by governments / large organisations and usually large-scale and expensive, whereas bottom-up involves local communities in small-scale projects (1)\nProject A (dam) is top-down / Project B (wells run by villagers) is bottom-up (1)` },
      { q: `Section A — Dynamic Development.\nFig. 1 is a table of development indicators for Zambia (data written for this practice question): GNI per capita US$1 240; infant mortality 40 per 1 000 live births; adult literacy 87%; people with access to electricity 47%; HDI 0.569.\n\nGive two social indicators of development shown in Fig. 1.`, marks: 2, command: 'Give', markScheme: `1 mark each, up to 2 marks:\nInfant mortality (1)\nAdult literacy (1)\nAllow access to electricity as a social / quality-of-life indicator.\nDo not credit GNI per capita (economic) or HDI (composite).` },
      { q: `Section A — Dynamic Development.\nZambia's HDI is about 0.57 but its GNI per capita has risen faster than its life expectancy over the last twenty years. Some people argue that HDI is a better measure of development than GNI per capita alone.\n\nExplain one limitation of HDI as a measure of development.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nIt is an average for the whole country (1) so it hides inequalities between rich and poor / urban and rural areas (1)\nOR it does not include other factors such as political freedom, gender equality or environmental quality (1) so it gives an incomplete picture of quality of life (1)\nOR data from LIDCs may be inaccurate or out of date (1) because censuses are expensive / informal work is not recorded (1)` },
      { q: `Section A — Dynamic Development.\nFig. 2 is a description of a world map of HDI. The highest values (above 0.9) are in North America, western Europe, Japan and Australia. The lowest values (below 0.55) are mostly in sub-Saharan Africa, including Chad, Niger and South Sudan, and in Afghanistan and Yemen.\n\nUsing Fig. 2, describe what is meant by the 'development gap'.`, marks: 2, command: 'Describe', markScheme: `1 mark for meaning, 1 mark for use of Fig. 2:\nThe difference in levels of wealth / quality of life between the most and least developed countries (1)\ne.g. ACs such as those in North America / western Europe have HDI above 0.9 while many countries in sub-Saharan Africa are below 0.55 (1)` },
      { q: `Section A — Dynamic Development.\nFig. 4 describes a graph of world copper prices from 2000 to 2022. The price rose from under US$2 000 per tonne in 2002 to almost US$9 000 in 2011, fell to under US$5 000 in 2016, then rose again to over US$9 000 in 2021 (data written for this practice question).\n\nExplain why Zambia's economy is vulnerable to the changes shown in Fig. 4.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid point, 1 mark for development:\nZambia depends on copper for most of its export earnings (1) so when the price falls (e.g. 2011 to 2016) government income and foreign currency fall sharply (1)\nOR mines cut production / jobs when prices fall (1) causing unemployment in the Copperbelt (1)\nAllow reference to difficulty repaying debt when export income falls.` },
      { q: `Section A — Dynamic Development.\nFig. 1 shows two indicators for Zambia (data written for this practice question): GNI per capita US$1 240; HDI 0.569 (life expectancy 61.8 years, mean years of schooling 7.2).\n\nExplain why HDI may give a more accurate picture of development than GNI per capita.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, up to 3 marks:\nHDI is a composite measure combining income, health (life expectancy) and education (years of schooling) (1)\nso it shows quality of life, not just wealth (1)\nGNI per capita is only an average of income and can be high even when most people are poor / wealth is unequally shared (1)\nGNI does not show whether money is spent on health or education (1)\nIt does not record subsistence or informal work, which is common in LIDCs (1)` },
      { q: `Section A — Dynamic Development.\nZambia gained independence in 1964. Its economy grew rapidly while copper prices were high, but most people still work in small-scale farming, and there is little manufacturing. Many people in towns now own mobile phones.\n\nExplain where Zambia might be placed on Rostow's model of economic development.`, marks: 3, command: 'Explain', markScheme: `1 mark for the stage, up to 2 marks for explanation:\nPre-conditions for take-off / early take-off (1)\nThere is investment in mining and some infrastructure and trade, showing it has moved beyond traditional society (1)\nbut most people still farm and manufacturing is small, so it has not yet reached the drive to maturity (1)\nAllow argument that Zambia does not fit the model neatly because growth depends on one export (1)` },
      { q: `Section A — Dynamic Development.\nMany LIDCs export primary products such as copper, coffee or cotton and import manufactured goods such as vehicles, machinery and medicines.\n\nExplain how this pattern of trade can widen the development gap.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, up to 3 marks:\nPrimary products earn low prices compared with manufactured goods (1)\nPrices of primary products fluctuate on world markets, so income is unreliable (1)\nACs add value by processing / manufacturing, so profits and skilled jobs stay in ACs (1)\nLIDCs may run a trade deficit and borrow, leading to debt (1)\nTrade barriers / tariffs on processed goods discourage LIDCs from manufacturing (1)` },
      { q: `Section A — Dynamic Development.\nChina is now one of Zambia's largest trading partners and lenders. In the 1970s China funded the TAZARA railway from Zambia to Dar es Salaam in Tanzania. Chinese companies operate copper mines in the Copperbelt, such as at Chambishi, and have built roads and airports funded by loans.\n\nExplain how Zambia's relationship with China has affected its development.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, up to 3 marks, credit positive and/or negative:\nInfrastructure such as roads, railways and airports reduces transport costs and helps trade (1)\nThe TAZARA railway gave a route to the sea that did not pass through white-minority-ruled neighbours (1)\nChinese investment in mines creates jobs and export income (1)\nLarge loans increased Zambia's debt, contributing to its 2020 default on repayments (1)\nConcerns about poor working conditions / safety in some Chinese-run mines (1)\nCheap Chinese imports may compete with local manufacturers (1)` },
      { q: `Section A — Dynamic Development.\nBetween 2020 and 2022 a civil war in the Tigray region of northern Ethiopia caused many deaths, displaced millions of people and damaged roads, schools and hospitals.\n\nExplain how political factors such as conflict can slow the development of a country.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, up to 3 marks:\nInfrastructure such as roads, schools and hospitals is destroyed (1)\nPeople are displaced, so farming and work stop and food shortages increase (1)\nGovernment money is spent on the military rather than health or education (1)\nForeign investors / tourists stay away, reducing income (1)\nAllow corruption: money from aid or resources is taken by elites rather than spent on development (1)` },
      { q: `Section A — Dynamic Development.\nWaterAid is a non-governmental organisation (NGO) that works with rural communities in Zambia to build boreholes and toilets. Villagers are trained to repair the hand pumps themselves.\n\nExplain how a bottom-up project such as this can help development.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, up to 3 marks:\nClean water reduces water-borne diseases such as cholera and diarrhoea (1)\nso fewer children die / people are healthier and able to work (1)\nLess time is spent collecting water, so more children (especially girls) can attend school (1)\nLocal people are trained, so the project is sustainable and pumps keep working (1)\nLow cost / appropriate technology suits the needs of the community (1)` },
      { q: `Section A — Dynamic Development.\nFig. 2 is a description of a world map of HDI. Very high HDI (above 0.8) is found in North America, Europe, Australia, Japan, South Korea and the Gulf states. Medium HDI (0.55–0.7) is common in South Asia and Central America. Low HDI (below 0.55) is concentrated in sub-Saharan Africa, especially the Sahel and central Africa, with a few countries in Asia such as Afghanistan and Yemen. Southern African countries such as South Africa and Botswana have higher HDI than their neighbours.\n\nUsing Fig. 2, describe the global pattern of development.`, marks: 4, command: 'Describe', markScheme: `1 mark per valid point, up to 4 marks. Max 3 if no use of data or named places from Fig. 2.\nHighest HDI in the Global North / North America, Europe and Australia (1)\nLowest HDI concentrated in sub-Saharan Africa / Sahel (1)\nSouth Asia and Central America mostly medium HDI (1)\nSome exceptions, e.g. Australia in the south has very high HDI / Afghanistan and Yemen low in Asia (1)\nVariation within regions, e.g. South Africa and Botswana higher than neighbours (1)\nUse of HDI values, e.g. above 0.8 compared with below 0.55 (1)` },
      { q: `Section A — Dynamic Development.\nGlencore, a TNC with its headquarters in Switzerland, ran Mopani Copper Mines in Zambia's Copperbelt until 2021, when the mines were sold to the Zambian state-owned company ZCCM. Local people had complained about sulphur dioxide pollution from the smelter at Mufulira.\n\nExplain the advantages and disadvantages for an LIDC of TNCs such as Glencore.`, marks: 4, command: 'Explain', markScheme: `1 mark per valid point or development, up to 4 marks. Max 3 if only advantages or only disadvantages.\nAdvantages:\nJobs and wages for local people / multiplier effect (1)\nTaxes and royalties for the government (1)\nInvestment in technology, skills and infrastructure (1)\nDisadvantages:\nMuch of the profit leaves the country to shareholders abroad (1)\nTax avoidance can reduce government income (1)\nPollution, e.g. sulphur dioxide from smelters damages health and crops (1)\nTNCs may close mines or cut jobs when copper prices fall (1)` },
      { q: `Section A — Dynamic Development.\nZambia has received several types of aid: emergency food aid during droughts; debt relief in 2005 under the Heavily Indebted Poor Countries (HIPC) scheme; long-term support from the USA for HIV/AIDS treatment; and small-scale NGO projects for clean water.\n\nExplain how different types of aid can influence the development of an LIDC such as Zambia.`, marks: 4, command: 'Explain', markScheme: `1 mark per valid point or development, up to 4 marks. Max 3 if only one type of aid is discussed.\nEmergency / short-term aid saves lives after drought or disaster but does not tackle the causes of poverty (1)\nDebt relief frees government money for health and education, e.g. free primary education / health care (1)\nLong-term aid such as HIV treatment increases life expectancy and keeps people able to work (1)\nNGO / bottom-up projects improve water and health in rural areas and are sustainable because communities are involved (1)\nAid can create dependency or be lost to corruption (1)\nTied aid / loans can add to debt or benefit donor companies (1)` },
      { q: `Section A — Dynamic Development.\nThe Human Development Index (HDI) was introduced by the United Nations in 1990. It combines life expectancy, years of schooling and GNI per capita into a single value between 0 and 1.\n\nExamine the strengths and limitations of using HDI to measure development.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\nStrengths: composite measure combining social and economic factors; shows quality of life not just wealth; allows countries to be ranked and compared over time; widely available UN data; countries with similar GNI can be separated by health and education.\nLimitations: a national average that hides inequality between regions, urban/rural, genders or ethnic groups; leaves out political freedom, human rights, environment, happiness; data in LIDCs may be unreliable or out of date; GNI part ignores informal and subsistence economy; a single number can hide which part is weak.\nLevel 3 (5–6 marks): Demonstrates thorough knowledge and understanding of HDI (AO2). Applies knowledge and understanding to provide a thorough, balanced examination of both strengths and limitations, with a clear judgement (AO3).\nLevel 2 (3–4 marks): Demonstrates reasonable knowledge and understanding of HDI (AO2). Provides a reasonable examination; may be unbalanced (AO3).\nLevel 1 (1–2 marks): Demonstrates basic knowledge (AO2). Limited examination, mostly description of what HDI is (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nFig. 1 shows the HDI of three countries (data written for this practice question): Norway 0.966; Brazil 0.760; Chad 0.394. Chad is a landlocked country in the Sahel region of Africa that was a French colony until 1960 and has experienced several civil wars.\n\nExplain the causes of uneven development between countries.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\nPhysical: landlocked location raises trade costs; hot, dry climate / drought / desertification limits farming; natural hazards damage infrastructure; disease (malaria) in tropical climates; lack of or presence of natural resources.\nHistorical: colonialism set up economies based on raw material exports and drew artificial borders, leading to conflict.\nEconomic: dependence on primary products; unfair trade and fluctuating prices; debt repayments.\nPolitical: conflict, corruption and weak governance discourage investment.\nSocial: poor education and health limit the workforce.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of a range of causes (AO2). Thorough, well-developed explanation linking causes to development, with use of examples or Fig. 1 (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge of at least two causes (AO2). Reasonable explanation with some development (AO3).\nLevel 1 (1–2 marks): Basic knowledge (AO2). Limited explanation, causes listed with little development (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nAssess the usefulness of Rostow's model in explaining the development of your chosen LIDC.`, marks: 6, command: 'Assess', markScheme: `Indicative content (e.g. Zambia):\nUseful: Zambia can be placed in a stage (pre-conditions / early take-off); investment in copper mining and infrastructure fits the idea of a leading sector driving take-off; shows the path to industrialisation the government aims for.\nLess useful: based on the experience of Europe and the USA; assumes all countries follow the same linear path; ignores colonialism and global trade, e.g. Zambia's economy was shaped by Britain to export copper; ignores reliance on one commodity, debt (2020 default) and falling copper prices that can move a country backwards; does not consider aid, TNCs or China's influence; no timescale.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of Rostow's model and the case study (AO2). Thorough assessment of usefulness with a supported judgement and detailed place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable assessment with some case study detail (AO3).\nLevel 1 (1–2 marks): Basic knowledge, mostly description of the stages (AO2). Limited assessment, little or no case study reference (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nExamine how the location of your chosen LIDC and its position in the world have influenced its development.`, marks: 6, command: 'Examine', markScheme: `Indicative content (e.g. Zambia):\nLandlocked in south-central Africa, bordered by eight countries; exports travel long distances to ports in Tanzania, Mozambique, Namibia or South Africa, raising costs.\nRegionally important: member of SADC and COMESA; trade with DRC, South Africa; Zambezi provides HEP (Kariba) shared with Zimbabwe.\nGlobally: one of Africa's largest copper producers, so tied to world demand, especially from China; copper's importance for electric vehicles may increase its global importance.\nClimate: tropical with a wet season; drought (e.g. 2024) affects farming and HEP.\nHistorical position as a British colony shaped its trade links.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of the case study location (AO2). Thorough examination linking location to development, with detailed place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable examination with some case study detail (AO3).\nLevel 1 (1–2 marks): Basic knowledge, generic location statements (AO2). Limited examination of influence on development (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nAnalyse the influence of transnational corporations (TNCs) on the development of your chosen LIDC.`, marks: 6, command: 'Analyse', markScheme: `Indicative content (e.g. Zambia):\nCopper TNCs such as First Quantum Minerals (Kansanshi, Sentinel), Glencore (Mopani, until 2021), Vedanta (Konkola Copper Mines) and Chinese companies (Chambishi).\nPositive: thousands of jobs and training; taxes and royalties to the government; investment in roads, power, schools and clinics near mines; export income.\nNegative: profits sent abroad; disputes over tax payments; pollution of air (sulphur dioxide) and rivers (e.g. Kafue River); job losses when prices fall; dependence on copper continues; government took back control of some mines.\nOther TNCs: supermarkets (e.g. Shoprite) and mobile networks (e.g. MTN, Airtel) bring services and jobs.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of TNCs in the case study (AO2). Thorough analysis of positive and negative influences with detailed place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable analysis, may be one-sided (AO3).\nLevel 1 (1–2 marks): Basic, generic knowledge of TNCs (AO2). Limited analysis (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nExplain how changing patterns of trade and international relationships have influenced the development of your chosen LIDC.`, marks: 6, command: 'Explain', markScheme: `Indicative content (e.g. Zambia):\nAt independence trade was mainly with Britain / Europe; copper exported raw.\nLinks with China grew: TAZARA railway (1970s), Chinese mine ownership, loans for infrastructure; China and Switzerland are now major export destinations, South Africa and China major sources of imports.\nRegional trade through SADC and COMESA, including the African Continental Free Trade Area.\nInternational relationships with the IMF and World Bank: structural adjustment and privatisation of the copper mines in the 1990s; HIPC debt relief (2005); default in 2020 and debt restructuring with an IMF programme.\nEffects: income rises and falls with copper prices; debt limits spending on services; attempts to diversify into agriculture and tourism.\nLevel 3 (5–6 marks): Thorough knowledge and understanding (AO2). Thorough explanation of how changes in trade and relationships have influenced development, with detailed place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable explanation with some case study detail (AO3).\nLevel 1 (1–2 marks): Basic knowledge (AO2). Limited explanation; generic (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nThe Kariba Dam on the Zambezi River was completed in 1959 and is shared by Zambia and Zimbabwe. It created one of the world's largest artificial lakes and supplies much of Zambia's electricity. Building it displaced about 57 000 Tonga people from the valley.\n\nEvaluate the effectiveness of a large-scale top-down project such as the Kariba Dam in helping a country to develop.`, marks: 6, command: 'Evaluate', markScheme: `Indicative content:\nEffective: large supply of cheap, renewable electricity powers the copper mines and cities; electricity can be exported; fishing industry on Lake Kariba; tourism; flood control.\nLess effective: thousands of Tonga people displaced to poorer land, often without fair compensation; benefits go mainly to industry and towns while many rural people have no electricity; huge cost and debt; reliance on one source means drought (e.g. 2024) causes long power cuts; maintenance problems.\nComparison with bottom-up alternatives such as small solar schemes.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of top-down development (AO2). Thorough evaluation of effectiveness with a supported judgement and use of the example (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable evaluation, may be one-sided (AO3).\nLevel 1 (1–2 marks): Basic knowledge (AO2). Limited evaluation, mostly description (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nFig. 3 shows Zambia's HDI (data written for this practice question): 2000 — 0.433; 2010 — 0.528; 2022 — 0.569. During this time Zambia received debt relief (2005), large amounts of aid for HIV/AIDS treatment, and support from NGOs for water and education projects.\n\nUsing Fig. 3 and your own understanding, assess the impact of international aid on the development of an LIDC.`, marks: 6, command: 'Assess', markScheme: `Indicative content:\nUse of Fig. 3: HDI rose from 0.433 to 0.569, an increase of 0.136 / about 31%; faster rise 2000–2010 than 2010–2022.\nPositive impacts: debt relief freed money for free primary education and health care; HIV treatment raised life expectancy; NGO water projects reduced disease.\nLimits: rise may also be due to high copper prices and investment, not aid; aid can create dependency; tied aid and loans add to debt (Zambia defaulted in 2020); corruption can divert aid; HDI still low compared with ACs.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of aid (AO2). Thorough assessment with a supported judgement, accurate use of Fig. 3 and place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge (AO2). Reasonable assessment with some use of Fig. 3 (AO3).\nLevel 1 (1–2 marks): Basic knowledge (AO2). Limited assessment; little or no use of Fig. 3 (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nExamine how the social and environmental context of your chosen LIDC has affected its development.`, marks: 6, command: 'Examine', markScheme: `Indicative content (e.g. Zambia):\nSocial: young, fast-growing population (about 13.1 million in 2010 to 19.6 million in 2022); high HIV prevalence reduced the working population and life expectancy; improvements in primary school attendance; large rural–urban inequality; many people work in the informal sector or subsistence farming.\nEnvironmental: tropical climate with one rainy season; droughts (e.g. 2024) damage maize harvests and HEP; malaria; deforestation for charcoal; pollution around Copperbelt mines; national parks such as South Luangwa and Victoria Falls support tourism.\nLevel 3 (5–6 marks): Thorough knowledge and understanding of both contexts (AO2). Thorough examination of how they affect development, with detailed place-specific evidence (AO3).\nLevel 2 (3–4 marks): Reasonable knowledge, may focus on one context (AO2). Reasonable examination (AO3).\nLevel 1 (1–2 marks): Basic, generic knowledge (AO2). Limited examination (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\n'International aid does more to keep LIDCs poor than to help them develop.'\n\nTo what extent do you agree with this statement? Use evidence from a case study of an LIDC to support your answer. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'To what extent', markScheme: `Indicative content (e.g. Zambia or Ethiopia):\nAgree: dependency on aid; tied aid benefits donor companies; loans increase debt; aid may be lost to corruption; emergency aid does not tackle causes; food aid can undercut local farmers.\nDisagree: debt relief (HIPC 2005) freed money for free primary education and health; HIV/AIDS programmes raised life expectancy; NGO bottom-up projects (e.g. WaterAid boreholes) improve health and are sustainable; multilateral aid funds infrastructure.\nJudgement: depends on the type of aid, how it is managed and whether communities are involved.\nLevel 3 (7–8 marks): Thorough knowledge and understanding of types of aid and the case study (AO2). Thorough, well-supported evaluation reaching a substantiated judgement on the statement, using detailed place-specific evidence (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable evaluation with some case study detail; judgement may be partly supported (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited evaluation; little or no judgement or case study (AO3).\n0 marks: No response or no response worthy of credit.\nSPaG:\nHigh performance (3 marks): spells and punctuates with consistent accuracy; uses rules of grammar with effective control of meaning; uses a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): spells and punctuates with considerable accuracy; uses rules of grammar with general control of meaning; uses a good range of specialist terms as appropriate.\nThreshold performance (1 mark): spells and punctuates with reasonable accuracy; uses rules of grammar with some control of meaning; uses a limited range of specialist terms as appropriate.\n0 marks: errors severely hinder meaning, or no response.` },
      { q: `Section A — Dynamic Development.\nZambia and Ethiopia are both LIDCs. Zambia was a British colony until 1964. Ethiopia was never colonised, apart from an Italian occupation from 1936 to 1941, yet it has a lower HDI than Zambia.\n\nAssess the extent to which historical factors such as colonialism are the main cause of uneven development.`, marks: 8, command: 'Assess', markScheme: `Indicative content:\nHistorical factors: colonies set up to export raw materials; profits taken by colonial powers; artificial borders leading to conflict; infrastructure built only from mines to ports (e.g. Zambia's railways).\nOther factors: Ethiopia's low HDI despite little colonisation suggests other causes matter — drought and famine (1980s), conflict (Tigray 2020–22), landlocked since 1993; economic factors such as debt, unfair trade and dependence on primary products; political factors such as corruption; social factors such as disease (HIV, malaria) and education; physical factors such as climate, hazards and being landlocked.\nJudgement: colonialism helps explain the structure of many LIDC economies but cannot alone explain current patterns.\nLevel 3 (7–8 marks): Thorough knowledge and understanding of the causes of uneven development (AO2). Thorough assessment of the relative importance of historical factors, using the stem examples, reaching a substantiated judgement (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable assessment with some judgement (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited assessment; causes listed (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\nEvaluate whether bottom-up strategies have been more effective than top-down strategies in promoting the development of your chosen LIDC.`, marks: 8, command: 'Evaluate', markScheme: `Indicative content (e.g. Zambia):\nTop-down: Kariba and Kafue Gorge HEP schemes; government road-building (e.g. Link Zambia 8000 road programme); free primary education after debt relief; IMF/World Bank programmes; privatisation of mines. Benefits: large-scale infrastructure and national services; drawbacks: debt, displacement (Tonga people), benefits concentrated in towns and Copperbelt.\nBottom-up: NGO water and sanitation projects (WaterAid), community schools, small-scale farming cooperatives, solar lamps. Benefits: cheap, sustainable, meet local needs, involve local people; drawbacks: small scale, depend on donor funding, do not create national infrastructure.\nJudgement: the two work best together; depends on the aspect of development.\nLevel 3 (7–8 marks): Thorough knowledge and understanding of both strategies in the case study (AO2). Thorough, balanced evaluation reaching a substantiated judgement with detailed place-specific evidence (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable evaluation, may be unbalanced; some case study detail (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited evaluation; generic (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — Dynamic Development.\nCASE STUDY — An LIDC.\n\n'The development of LIDCs depends more on their links with other countries than on decisions made within the country.'\n\nAssess this statement with reference to your chosen LIDC.`, marks: 8, command: 'Assess', markScheme: `Indicative content (e.g. Zambia):\nExternal links: world copper prices set income; TNCs (First Quantum, Chinese companies) own most mines; Chinese loans and infrastructure; aid and debt relief from the IMF, World Bank, UK and USA; regional trade through SADC; reliance on neighbours' ports.\nInternal decisions: nationalisation of mines (1970s) then privatisation (1990s); government borrowing that led to the 2020 default; spending on free education and health; corruption cases; policies to diversify into agriculture and tourism; state company ZCCM buying Mopani in 2021.\nJudgement: external links are powerful because of copper dependence, but government decisions determine how income and aid are used.\nLevel 3 (7–8 marks): Thorough knowledge and understanding (AO2). Thorough, balanced assessment with a substantiated judgement and detailed place-specific evidence (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable assessment with some judgement and case study detail (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited assessment; generic (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — Development in Ethiopia.\nFig. 1: Ethiopia is a landlocked country in the Horn of Africa with a population of over 120 million. About 70% of workers are employed in farming, mainly small-scale; coffee is the main export.\nFig. 2: the Grand Ethiopian Renaissance Dam (GERD) on the Blue Nile, a top-down project funded mainly by the Ethiopian government and its citizens, began generating electricity in 2022. When fully running it is planned to roughly double Ethiopia's electricity output. Egypt and Sudan downstream have objected to its effect on Nile water.\nFig. 3: Hawassa Industrial Park opened in 2016. Foreign TNCs make clothing there for export to Europe and the USA; most workers are young women on low wages.\nFig. 4: a rural village scheme (written for this practice question) in which an NGO trains farmers in terracing and tree-planting to reduce soil erosion and helps women set up savings groups.\n\nUsing Figs. 1–4 and your own understanding, assess whether large-scale top-down projects are the best way to improve quality of life in Ethiopia.`, marks: 12, command: 'Assess', markScheme: `Indicative content:\nFor top-down: GERD provides renewable electricity for industry, homes and export income; supports industrial parks and jobs (Fig. 3) which could move Ethiopia towards take-off in Rostow's model; national scale.\nAgainst top-down: high cost and debt; international tension with Egypt and Sudan; electricity may not reach rural villages where most people live (Fig. 1); industrial park jobs low-paid and dependent on foreign TNCs.\nBottom-up (Fig. 4): improves farming for the 70% who farm; reduces soil erosion; empowers women; cheap and sustainable; but small scale and dependent on NGO funding.\nJudgement: a combination is needed; top-down creates national infrastructure while bottom-up reaches rural communities.\nLevel 4 (10–12 marks): Thorough knowledge and understanding of development strategies (AO2). Applies knowledge and understanding to produce a thorough, well-balanced assessment, drawing on all figures and own understanding, reaching a fully substantiated judgement (AO3).\nLevel 3 (7–9 marks): Good knowledge and understanding (AO2). Good assessment using several figures with a supported judgement (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable assessment; limited use of figures; judgement may be partial (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited assessment; mostly description of the figures (AO3).\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — Zambia's copper economy.\nFig. 1: copper makes up about three-quarters of the value of Zambia's exports (data written for this practice question).\nFig. 2: world copper prices (data written for this practice question) rose from under US$2 000 per tonne in 2002 to almost US$9 000 in 2011, fell to under US$5 000 in 2016, and rose again above US$9 000 in 2021. Demand is expected to grow because copper is used in electric vehicles, wind turbines and power cables.\nFig. 3: in 2020 Zambia became the first African country of the COVID-19 period to default on its foreign debt repayments.\nFig. 4: the Zambian government plans to diversify into farming, tourism (Victoria Falls, South Luangwa National Park) and processing copper into wire and cable within Zambia.\n\nUsing Figs. 1–4 and your own understanding, assess the extent to which dependence on copper is the main barrier to Zambia's development.`, marks: 12, command: 'Assess', markScheme: `Indicative content:\nCopper as a barrier: income rises and falls with world prices (Fig. 2) so government budgets and jobs are unstable; price falls contributed to borrowing and the 2020 default (Fig. 3); copper is exported raw so value is added elsewhere; profits go to foreign TNCs; pollution in the Copperbelt; little diversification.\nCopper as an opportunity: rising global demand for green technology could raise income; processing copper into wire and cable (Fig. 4) would add value and jobs.\nOther barriers: landlocked location and transport costs; drought and HEP power cuts (2024); HIV and health; rural poverty and subsistence farming; debt from loans for infrastructure; corruption; legacy of colonialism.\nJudgement on the extent to which copper dependence is the main barrier.\nLevel 4 (10–12 marks): Thorough knowledge and understanding of the causes of uneven development and Zambia (AO2). Applies knowledge and understanding to produce a thorough, well-balanced assessment, drawing on all figures and own understanding, reaching a fully substantiated judgement (AO3).\nLevel 3 (7–9 marks): Good knowledge and understanding (AO2). Good assessment using several figures with a supported judgement (AO3).\nLevel 2 (4–6 marks): Reasonable knowledge (AO2). Reasonable assessment; limited use of figures; judgement may be partial (AO3).\nLevel 1 (1–3 marks): Basic knowledge (AO2). Limited assessment; mostly description of the figures (AO3).\n0 marks: No response or no response worthy of credit.` }
    ]
  },
  '2.3': {
    name: 'UK in the 21st Century',
    questions: [
      { q: `Section A — UK in the 21st Century.\nFig. 1 is a population pyramid for a UK seaside town (data written for this practice question). The bars show the percentage of the total population in each age group.\nFemales: 0–14 6.1%; 15–29 6.8%; 30–44 7.0%; 45–59 9.4%; 60–74 11.2%; 75+ 8.3%.\nMales: 0–14 6.4%; 15–29 7.2%; 30–44 6.9%; 45–59 9.0%; 60–74 10.1%; 75+ 5.6%.\n\nIdentify the age group with the largest percentage of females.`, marks: 1, command: 'Identify', markScheme: `60–74 (1)\nAllow 60–74 year olds / 11.2%.` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 shows census data for England and Wales. In the 2011 Census, 16.4% of the population were aged 65 and over. In the 2021 Census, 18.6% of the population were aged 65 and over.\n\nCalculate the increase in the percentage of the population aged 65 and over between 2011 and 2021.`, marks: 1, command: 'Calculate', markScheme: `2.2 (percentage points) (1)\n18.6 − 16.4 = 2.2. Allow 2.2%.` },
      { q: `Section A — UK in the 21st Century.\nFig. 2 shows the percentage of UK jobs in four employment sectors in 1981 and 2021 (data written for this practice question).\nPrimary: 1981 3%; 2021 1%.\nSecondary: 1981 32%; 2021 16%.\nTertiary: 1981 60%; 2021 71%.\nQuaternary: 1981 5%; 2021 12%.\n\nIdentify the sector with the largest decrease in its share of UK jobs between 1981 and 2021.`, marks: 1, command: 'Identify', markScheme: `Secondary (1)\nAllow manufacturing / secondary sector (fell by 16 percentage points).` },
      { q: `Section A — UK in the 21st Century.\nFig. 3 is a newspaper extract about the UK's political links: "The UK is one of only five countries that hold a permanent seat on the Security Council of this organisation, alongside the USA, France, China and Russia. A permanent member can veto any resolution put to the Council."\n\nGive the name of the international organisation described in Fig. 3.`, marks: 1, command: 'Give', markScheme: `The United Nations / UN (1)\nAllow UN Security Council. Do not accept NATO or EU.` },
      { q: `Section A — UK in the 21st Century.\nThe UK has a land area of about 242 500 km². In mid-2021 its population was about 67 000 000.\n\nCalculate the population density of the UK. Give your answer to the nearest whole number.`, marks: 1, command: 'Calculate', markScheme: `276 people per km² (1)\n67 000 000 ÷ 242 500 = 276.3. Units not required for the mark. Do not accept 276.3 (not to nearest whole number).` },
      { q: `Section A — UK in the 21st Century.\nFig. 4 is a table of population density for six parts of the UK in 2021 (figures rounded, written for this practice question).\nLondon 5 600 people per km²\nNorth West England 520 people per km²\nSouth East England 480 people per km²\nWales 150 people per km²\nNorthern Ireland 140 people per km²\nScotland 70 people per km²\n\nIdentify the part of the UK in Fig. 4 with the lowest population density.`, marks: 1, command: 'Identify', markScheme: `Scotland (1)` },
      { q: `Section A — UK in the 21st Century.\nFig. 5 shows the main reasons given by people arriving in the UK in one year (data written for this practice question): work 38%; study 33%; family 17%; asylum 8%; other 4%.\n\nUsing Fig. 5, give one pull factor that attracts migrants to the UK.`, marks: 1, command: 'Give', markScheme: `One from (1):\n• jobs / employment opportunities / higher wages\n• university / education places\n• joining family members already in the UK\n• safety / asylum from persecution or conflict\nMust be a pull factor linked to Fig. 5.` },
      { q: `Section A — UK in the 21st Century.\nFig. 6 shows the median age (years) of the population in seven UK local authorities (data written for this practice question):\n38, 44, 51, 35, 47, 40, 42\n\nCalculate the median of these values.`, marks: 1, command: 'Calculate', markScheme: `42 (years) (1)\nOrdered: 35, 38, 40, 42, 44, 47, 51 — the middle (4th) value is 42.` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 shows part of the population pyramid for a UK city in 2021 (data written for this practice question). Values are the percentage of the total population.\nMales: 0–4 2.8%; 5–9 3.0%.\nFemales: 0–4 2.7%; 5–9 2.9%.\n\nCalculate the total percentage of males and females aged under 10 years old. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `11.4% (2)\n1 mark for working: 2.8 + 3.0 + 2.7 + 2.9\n1 mark for the correct answer: 11.4 (%)\nCorrect answer with no working = 1 mark.` },
      { q: `Section A — UK in the 21st Century.\nCensus data show that the population of England and Wales was 56 075 900 in 2011 and 59 597 500 in 2021.\n\nCalculate the percentage change in the population of England and Wales between 2011 and 2021. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `+6.3% (2)\n1 mark for working: (59 597 500 − 56 075 900) ÷ 56 075 900 × 100 (= 3 521 600 ÷ 56 075 900 × 100)\n1 mark for the correct answer to 1 d.p.: 6.3% (increase)\nAllow 6.28 for 1 mark only if not rounded. Correct answer with no working = 1 mark.` },
      { q: `Section A — UK in the 21st Century.\nFig. 2 shows the percentage of UK employment in each sector (data written for this practice question).\nPrimary: 2001 2%; 2021 1%; change −1.\nSecondary: 2001 22%; 2021 16%; change ?\nTertiary: 2001 68%; 2021 ?; change +3.\nQuaternary: 2001 8%; 2021 12%; change +4.\n\nComplete the table by calculating the two missing values.`, marks: 2, command: 'Calculate', markScheme: `1 mark for each correct value (2):\n• Secondary change: −6 (16 − 22)\n• Tertiary 2021: 71% (68 + 3)\nCheck: 1 + 16 + 71 + 12 = 100. Do not accept +6 for the secondary change.` },
      { q: `Section A — UK in the 21st Century.\nFig. 3 states: "In 1951 there were about 300 people aged 100 or over in the UK. By 2021 there were more than 13 000 centenarians."\n\nExplain one reason why the UK's population is ageing.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development (2).\nE.g.\n• Improved healthcare / medicine (e.g. free care through the NHS, new treatments for heart disease and cancer) (1) so people live longer and life expectancy has risen to over 80 (1).\n• Falling birth rate (1) because women are having fewer children, later in life, so older people make up a larger share of the population (1).\n• The 'baby boom' generation born after 1945 and in the 1960s (1) is now reaching retirement age, increasing the number of over-65s (1).\n• Better diet, housing and less heavy manual work (1) reduce the death rate among older people (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 4 is a quote from a hospital manager in a town on the south coast of England: "Almost a third of our residents are over 65. Our wards are full every winter."\n\nExplain one way an ageing population can put pressure on services in the UK.`, marks: 2, command: 'Explain', markScheme: `1 mark for a way, 1 mark for development (2).\nE.g.\n• More demand on the NHS (1) because older people are more likely to have long-term illnesses such as dementia or heart disease, leading to longer waiting lists / bed shortages (1).\n• Greater need for social care / care homes (1) which local councils must help pay for, putting pressure on their budgets (1).\n• Pension costs rise (1) and are paid for by a smaller share of working-age taxpayers (1).\n• Demand for adapted housing / transport such as free bus passes (1) increases council spending (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 5 shows the percentage of residents aged 65 and over in two parts of England (data written for this practice question): a district on the North Norfolk coast 33%; an inner London borough 8%.\n\nSuggest one reason why the coastal district in Fig. 5 has a much higher percentage of residents aged 65 and over.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a reason, 1 mark for development (2).\nE.g.\n• Retirement migration (1) — people move to the coast when they retire for the attractive scenery, quiet lifestyle and bungalows (1).\n• Young people move away (out-migration) (1) because there are few well-paid jobs or universities in rural coastal areas (1).\n• Inner London attracts young adults for work and study (1) which lowers its percentage of over-65s (1).\nAllow comparison with London if it explains the coastal figure.` },
      { q: `Section A — UK in the 21st Century.\nFig. 6 is a statement from an NHS trust in Leicester: "Around one in seven of our staff were born outside the UK, including many nurses and doctors."\n\nExplain one economic benefit of international migration for the UK.`, marks: 2, command: 'Explain', markScheme: `1 mark for a benefit, 1 mark for development (2).\nE.g.\n• Fills skills shortages (1) e.g. in the NHS, social care, agriculture or construction where there are not enough UK workers (1).\n• Migrants are often of working age (1) so they pay income tax and National Insurance, helping to fund pensions and services for an ageing population (1).\n• Migrants start new businesses (1) creating jobs and adding to the economy (1).\n• International students pay tuition fees (1) which bring money into UK universities and local economies (1).` },
      { q: `Section A — UK in the 21st Century.\nIn 2015 the steelworks at Redcar, north-east England, closed with the loss of about 2 000 jobs. Steel could be produced more cheaply in other countries such as China.\n\nExplain one reason why manufacturing employment has declined in the UK.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development (2).\nE.g.\n• Globalisation / competition from abroad (1) — countries such as China and India have lower labour costs, so goods made there are cheaper (1).\n• Mechanisation / automation (1) means machines and robots do work that used to need many workers (1).\n• Raw materials ran out or became uneconomic (1) e.g. coal mines closed, the last deep coal mine (Kellingley) closing in 2015 (1).\n• Transnational corporations moved factories overseas (1) to be closer to growing markets or cheaper land (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 7 shows the percentage of UK jobs in manufacturing (data written for this practice question): 1981 24%; 1991 18%; 2001 14%; 2011 9%; 2021 8%.\n\nDescribe the trend shown in Fig. 7.`, marks: 2, command: 'Describe', markScheme: `1 mark for the overall trend, 1 mark for use of data or detail (2).\n• Manufacturing's share of jobs has decreased / fallen continuously (1).\n• From 24% in 1981 to 8% in 2021 / fell by 16 percentage points / to one third of its 1981 level (1).\n• The fastest fall was 2001–2011 (5 percentage points) and it then slowed / levelled off (1).\nMax 1 mark without data.` },
      { q: `Section A — UK in the 21st Century.\nCambridge Science Park was opened in 1970 by Trinity College, University of Cambridge. It is now home to over 100 companies in fields such as biotechnology, software and artificial intelligence.\n\nExplain one reason why quaternary industries locate near universities such as Cambridge.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development (2).\nE.g.\n• Access to a highly skilled / educated workforce (1) — graduates and researchers can be recruited locally (1).\n• Links with university research (1) so companies can share ideas, laboratories and develop new products (1).\n• Prestige / reputation of the location (1) attracts investors and other firms (clustering) (1).\n• Good transport links, e.g. to London and Stansted Airport (1), for business travel (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 8 shows internet sales as a percentage of all UK retail sales (data written for this practice question): 2008 5%; 2015 13%; 2020 33%; 2023 26%.\n\nExplain one impact of the growth of the digital economy on UK high streets.`, marks: 2, command: 'Explain', markScheme: `1 mark for an impact, 1 mark for development (2).\nE.g.\n• Shop closures / vacant units (1) because shoppers buy online, so high street stores lose sales and chains close branches (1).\n• Job losses in retail (1) while new jobs appear in warehouses / distribution centres often on edge-of-town sites (1).\n• High streets change function (1) towards cafés, leisure, services or housing rather than shops (1).\nAllow use of Fig. 8, e.g. peak of 33% in 2020 during the COVID-19 lockdowns.` },
      { q: `Section A — UK in the 21st Century.\nThe BBC World Service broadcasts radio, TV and online news in more than 40 languages to a weekly audience of several hundred million people around the world.\n\nExplain one way the UK's media exports give it influence in the world.`, marks: 2, command: 'Explain', markScheme: `1 mark for a way, 1 mark for development (2).\nE.g.\n• Spreads British values and views (1) — trusted news such as the BBC shapes how people in other countries see the UK and world events ('soft power') (1).\n• Promotes the English language (1) which makes the UK attractive for business, students and tourists (1).\n• TV programmes, films and formats (e.g. Doctor Who, 'Strictly Come Dancing' sold as 'Dancing with the Stars') are sold abroad (1), earning money and raising the UK's profile (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 9 is a fact file on the UK's political links. It states that the UK is a permanent member of the UN Security Council and left the European Union on 31 January 2020.\n\nGive two other international organisations or groups that the UK belongs to.`, marks: 2, command: 'Give', markScheme: `1 mark for each correct organisation (2). E.g.\n• NATO\n• G7 / G20\n• The Commonwealth\n• World Trade Organization (WTO)\n• Council of Europe\n• AUKUS\nDo not credit the UN or the EU (given in the stem).` },
      { q: `Section A — UK in the 21st Century.\nBefore 2020, goods could move between the UK and other European Union countries without customs checks. Since leaving the EU, UK exporters must complete customs paperwork for goods sent to EU countries.\n\nExplain one effect of leaving the European Union on UK trade.`, marks: 2, command: 'Explain', markScheme: `1 mark for an effect, 1 mark for development (2).\nE.g.\n• More paperwork and border checks (1) increase costs and delays, so some small firms stopped exporting to the EU (1).\n• The UK can make its own trade deals (1) e.g. with Australia, New Zealand and the CPTPP group of Pacific countries (1).\n• Some companies moved offices / jobs to the EU (1) to keep easy access to the single market (1).\n• Shortages of some workers or goods (1) because free movement ended (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 10 shows the population of a UK market town by age (data written for this practice question): aged 0–15: 18 000; aged 16–64: 60 000; aged 65 and over: 24 000.\nDependency ratio = (population aged 0–15 + population aged 65 and over) ÷ population aged 16–64 × 100.\n\nCalculate the dependency ratio for the town. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `70 (2)\n1 mark for working: (18 000 + 24 000) ÷ 60 000 × 100 (= 42 000 ÷ 60 000 × 100)\n1 mark for the correct answer: 70\nCorrect answer with no working = 1 mark.` },
      { q: `Section A — UK in the 21st Century.\nThe Notting Hill Carnival in London was first held in the 1960s by people who had migrated from the Caribbean. It now attracts around one million people each August.\n\nSuggest one way that migration has influenced culture in the UK.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a way, 1 mark for development (2).\nE.g.\n• Food (1) — curry, Caribbean, Chinese and Polish foods are now widely eaten and sold in UK supermarkets and restaurants (1).\n• Festivals and celebrations (1) such as Diwali in Leicester, Chinese New Year or Notting Hill Carnival are enjoyed by many people (1).\n• Music and fashion (1) e.g. reggae, bhangra, grime influenced UK popular music (1).\n• Language / religion (1) — new words and many places of worship add to a multicultural society (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 11 shows average weekly pay for full-time workers in two UK regions (data written for this practice question): London £850; North East England £600.\n\nExplain one reason for the difference in pay between London and North East England.`, marks: 2, command: 'Explain', markScheme: `1 mark for a reason, 1 mark for development (2).\nE.g.\n• London has many high-paid quaternary and financial jobs (1) e.g. banks in the City and Canary Wharf, headquarters of TNCs (1).\n• The North East lost heavy industry such as shipbuilding, coal mining and steel (1) and new jobs are often lower-paid service jobs (1).\n• Higher cost of living in London (1) means employers must pay more to attract workers (1).\nAllow use of data: London pay is £250 a week more.` },
      { q: `Section A — UK in the 21st Century.\nA student used data from the 2021 Census of England and Wales to study how the population of her town had changed since the 2011 Census.\n\nSuggest one limitation of using census data to study population change.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a limitation, 1 mark for development (2).\nE.g.\n• Only taken every 10 years (1) so data quickly become out of date / changes between censuses are missed (1).\n• Some people do not complete it or give inaccurate answers (1) e.g. homeless people or recent migrants may be undercounted (1).\n• The 2021 Census was taken during the COVID-19 pandemic (1) when some people (e.g. students) were not living at their usual address (1).\n• Scotland held its census in 2022 (1) so UK-wide data are not for the same date (1).` },
      { q: `Section A — UK in the 21st Century.\nA student has data on the number of people in each five-year age group, for males and females, for her local authority in 2021.\n\nSuggest an appropriate way to present these data. Justify your choice.`, marks: 2, command: 'Suggest', markScheme: `1 mark for an appropriate method, 1 mark for justification (2).\n• Population pyramid (1) because it shows males and females side by side for each age group, so the structure (e.g. ageing, a bulge of young adults) is easy to see (1).\nAllow a divided/compound bar chart (1) with justification (1). Do not credit a line graph or pie chart for all age groups without justification.` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 compares the 2011 and 2021 Censuses for England and Wales.\nMedian age: 2011 39 years; 2021 40 years.\nPercentage aged 65 and over: 2011 16.4%; 2021 18.6%.\nNumber of residents born outside the UK: 2011 7.5 million; 2021 10.0 million.\n\nDescribe the changes in the population of England and Wales shown in Fig. 1.`, marks: 3, command: 'Describe', markScheme: `1 mark per valid point; at least one must use data (3).\n• The population is getting older / ageing (1).\n• Median age rose by one year from 39 to 40 (1).\n• The share aged 65+ rose by 2.2 percentage points, from 16.4% to 18.6% (1).\n• More people were born outside the UK (1) — up by 2.5 million / about a third (33%) (1).\nMax 2 marks if no data used.` },
      { q: `Section A — UK in the 21st Century.\nThe Redcar steelworks on Teesside closed in 2015. About 2 000 people worked directly at the plant and many more worked for local suppliers.\n\nExplain the consequences of deindustrialisation for a former industrial area such as Teesside.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development (3).\n• High unemployment (1) as factory and supplier jobs are lost (multiplier effect) (1).\n• Less money spent in local shops (1) causing further business closures (1).\n• Young people move away for work (1) leaving an older population (1).\n• Derelict / contaminated land (1), but this may later be used for regeneration, e.g. Teesworks freeport (1).\n• Health and social problems linked to poverty (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 2 is a table of population density for six parts of the UK in 2021 (figures rounded, written for this practice question).\nLondon 5 600 people per km²\nNorth West England 520 people per km²\nSouth East England 480 people per km²\nWales 150 people per km²\nNorthern Ireland 140 people per km²\nScotland 70 people per km²\n\nDescribe the distribution of population density shown in Fig. 2.`, marks: 3, command: 'Describe', markScheme: `1 mark per valid point; credit use of data (3).\n• Density is highest in England / London (1) — 5 600 per km², over ten times any other area shown (1).\n• North West and South East England are also densely populated (around 500 per km²) (1).\n• Density is lowest in Scotland (70 per km²), Wales and Northern Ireland (the north and west / upland areas) (1).\n• London's density is 80 times that of Scotland (1).\nMax 2 marks without data.` },
      { q: `Section A — UK in the 21st Century.\nIn England and Wales the total fertility rate (average number of children per woman) fell to a record low of 1.44 in 2023.\n\nExplain why the birth rate in the UK has fallen.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development (3).\n• More women in higher education and careers (1) so they delay having children (1).\n• High cost of raising children / housing / childcare (1) so couples choose smaller families (1).\n• Easy access to contraception and family planning (1).\n• Changing attitudes — some people choose not to have children (1).\n• Low infant mortality (1) means families do not need to have many children to ensure some survive (1).` },
      { q: `Section A — UK in the 21st Century.\nThe UK is a permanent member of the UN Security Council, a founding member of NATO (1949), a member of the G7 and head of the Commonwealth, a group of 56 countries.\n\nExplain how these political links help to give the UK an important place in the world.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development (3).\n• The UN Security Council veto (1) means the UK can block or shape decisions on peacekeeping and sanctions (1).\n• NATO membership (1) gives the UK a role in defence and security alongside the USA and Europe (1).\n• G7 membership (1) means the UK helps shape global economic policy, e.g. on climate finance or debt (1).\n• Commonwealth links (1) give historic, trade and cultural ties with countries such as India, Canada and Australia (1).` },
      { q: `Section A — UK in the 21st Century.\nEnglish Premier League football matches are broadcast to around 190 countries. Many fans in Asia and Africa support English clubs such as Manchester United, Liverpool and Arsenal.\n\nExplain how sport helps to spread UK culture around the world.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development (3).\n• Global TV / online coverage (1) makes UK clubs, places and the English language familiar worldwide (1).\n• Overseas fans buy merchandise and visit the UK (1) bringing money through tourism (1).\n• Clubs are owned by and employ people from many countries (1) strengthening links between the UK and those countries (1).\n• Many sports (football, rugby, cricket) were spread by the UK (1) and the Commonwealth Games keep these links (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 3 describes the population pyramid of a large UK city (written for this practice question). The pyramid has a narrow top and a large bulge in the 20–39 age groups. Many residents in this age group were born outside the UK.\n\nExplain how international migration can change the population structure of a UK city.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development (3).\n• Most migrants are young adults of working age (1) who come for jobs or study, creating a bulge at 20–39 (1).\n• Migrants may start families in the UK (1) which widens the base of the pyramid / raises the birth rate (1).\n• This makes the city's population younger than the UK average (1).\n• Increases ethnic and cultural diversity of the city (1).` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 shows the population of two UK local authorities by age group, as a percentage of total population (data written for this practice question).\nA university city: 0–15 16%; 16–29 31%; 30–64 41%; 65+ 12%.\nA coastal retirement district: 0–15 13%; 16–29 11%; 30–64 42%; 65+ 34%.\n\nUsing Fig. 1, compare the population structures of the two local authorities.`, marks: 4, command: 'Compare', markScheme: `1 mark per valid comparative point; credit use of data (4).\n• The coastal district has a much older population (1) — 34% aged 65+ compared with 12% in the city (nearly three times as much) (1).\n• The university city has many more young adults (1) — 31% aged 16–29 compared with 11% (1).\n• Both have a similar share aged 30–64 (41% and 42%) (1).\n• The city has slightly more children, 16% compared with 13% (1).\nMax 2 marks for points that only describe one place. Max 3 marks without data.` },
      { q: `Section A — UK in the 21st Century.\nMany products sold in the UK are now made overseas, while UK-based companies such as banks, insurers and software firms sell their services around the world. London is one of the world's largest financial centres.\n\nExplain how globalisation has changed the UK's economy.`, marks: 4, command: 'Explain', markScheme: `1 mark per valid point, with up to 2 further marks for development (4).\n• Manufacturing moved to lower-cost countries (1) causing deindustrialisation and job losses in areas such as the North East and South Wales (1).\n• The UK specialises in services (1) such as finance, law, education and creative industries, which it exports (1).\n• Foreign direct investment by TNCs (1) e.g. Nissan in Sunderland and Tata in Port Talbot, creating jobs but also making them vulnerable to decisions made abroad (1).\n• Cheaper imported goods for consumers (1).\n• More international trade and migration of workers (1).` },
      { q: `Section A — UK in the 21st Century.\nMediaCityUK in Salford opened in 2011. Parts of the BBC and ITV moved there, and it now has hundreds of creative and digital businesses on the site of former docks.\n\nExplain why the service and digital economy has grown in the UK.`, marks: 4, command: 'Explain', markScheme: `1 mark per valid point, with up to 2 further marks for development (4).\n• Rising incomes mean people spend more on services such as leisure, tourism and eating out (1).\n• Fast broadband and mobile internet (1) allow online businesses, streaming and remote working (1).\n• A well-educated workforce / universities (1) supply skilled workers for IT, media and research (1).\n• Government policy and investment (1) e.g. relocating the BBC to Salford, tech hubs, enterprise zones (1).\n• The English language and time zone (1) help UK firms sell services globally (1).` },
      { q: `Section A — UK in the 21st Century.\nBetween 1985 and 2015 all of the UK's deep coal mines closed. Former mining towns such as Grimethorpe in South Yorkshire lost their main employer.\n\nExplain the social impacts of deindustrialisation on communities in the UK.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\n• Long-term unemployment and loss of identity in communities built around one industry.\n• Poverty, poorer health and higher rates of illness / depression; higher crime in some areas.\n• Out-migration of young people, leaving an ageing population and closed schools / shops.\n• Breakdown of community life, e.g. closure of miners' welfare clubs.\n• Some positive impacts: cleaner environment, regeneration and retraining, new jobs in services and warehousing (e.g. along the M1/A1).\n\nLevel 3 (5–6 marks): Thorough understanding of the social impacts. Detailed explanation of a range of impacts, well supported by accurate examples. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some explanation of impacts, partly supported by examples. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Limited, mainly descriptive points. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nBy 2040 it is projected that about one in four people in the UK will be aged 65 or over. The state pension age rose to 66 in 2020 and is due to rise to 67 between 2026 and 2028.\n\nExamine the challenges and opportunities of an ageing population for the UK.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\nChallenges: rising cost of pensions; pressure on the NHS and social care; fewer working-age taxpayers per pensioner (higher dependency ratio); need for adapted housing and transport; loneliness in rural areas.\nOpportunities: older people volunteer and provide childcare for grandchildren; the 'grey pound' — spending on leisure and tourism; experienced workers staying in work longer; new jobs in care and health industries.\nResponses: raising pension age; encouraging immigration of working-age people.\nHigher-level answers weigh challenges against opportunities and recognise variation between places.\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed examination of both challenges and opportunities, well supported by evidence. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some examination, may be unbalanced towards challenges or opportunities. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Limited points, mainly description. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nIn the 2021 Census, 10.0 million residents of England and Wales (16.8%) were born outside the UK, compared with 7.5 million (13.4%) in 2011.\n\nDiscuss the impacts of international migration on the UK.`, marks: 6, command: 'Discuss', markScheme: `Indicative content:\nEconomic: fills labour shortages (NHS, agriculture, hospitality); working-age migrants pay taxes; new businesses; may keep some wages low in low-skilled jobs; remittances sent abroad.\nSocial / cultural: more multicultural society — food, music, festivals, religion; younger population structure in cities; pressure on housing, school places and GP surgeries in some areas; tensions or integration issues.\nDemographic: slows population ageing; raises birth rate.\nHigher-level answers discuss both positive and negative impacts and how they vary between places (e.g. London vs rural towns such as Boston, Lincolnshire).\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed discussion of a range of positive and negative impacts, well supported by evidence. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some discussion, may be one-sided. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Limited, simple points. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 describes two population pyramids for the UK (written for this practice question). The 2001 pyramid has a bulge at ages 30–39 and another at 50–59 (the post-war baby boom). The 2021 pyramid has a narrower base than 2001, bulges at ages 50–59 and 30–39, and wider bars at ages 70 and over, especially for women.\n\nUsing Fig. 1, analyse how the UK's population structure has changed since 2001.`, marks: 6, command: 'Analyse', markScheme: `Indicative content:\nAO3 (use of Fig. 1): narrower base — fewer young children; baby-boom bulge has moved up the pyramid by 20 years into the 50–59 / 70+ groups; wider top — more elderly, especially women; bulge at 30–39 maintained by migration.\nAO2 (reasons): falling birth rate due to later marriage, careers, cost of children; rising life expectancy from medical advances; women live longer than men; immigration of young adults since EU expansion in 2004.\nHigher-level answers link changes to their causes and consequences (ageing population, higher dependency).\n\nLevel 3 (5–6 marks): Thorough analysis making detailed use of Fig. 1, with changes clearly linked to accurate reasons. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable analysis with some use of Fig. 1 and some reasons given. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic description of the figure or simple reasons. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nIn 2021 about 83% of UK jobs were in services. Fast-growing sectors include finance, information technology, the creative industries and research and development.\n\nExplain why the tertiary and quaternary sectors have grown in the UK since 2001.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\n• Deindustrialisation — the UK shifted to a post-industrial economy as manufacturing moved abroad.\n• Higher disposable incomes increased demand for leisure, retail, tourism and personal services.\n• Ageing population increases demand for health and care services.\n• Growth of the internet and digital technology: e-commerce, apps, streaming, fintech; tech clusters in Shoreditch (London), Manchester, Cambridge.\n• Highly educated workforce and world-class universities; science parks (e.g. Cambridge Science Park).\n• London as a global financial centre; government investment and policies.\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed explanation of a range of reasons, well supported by accurate examples. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some explanation with some examples. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Limited reasons, little explanation. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nFig. 2 lists some UK media exports: BBC World Service news; TV dramas such as Doctor Who and Downton Abbey; game-show formats such as 'Who Wants to Be a Millionaire?'; the Harry Potter books and films; music artists such as Adele and Ed Sheeran.\n\nExamine the UK's global influence through its media exports.`, marks: 6, command: 'Examine', markScheme: `Indicative content:\n• Soft power: UK news, TV and music shape global views of the UK and its values (e.g. trusted BBC news).\n• Economic value: sales of programmes, formats, films and music earn export income; overseas viewers become tourists (e.g. visiting film locations).\n• Spread of the English language and British culture.\n• Limits: competition from US media giants (Netflix, Disney) and from other countries (e.g. K-pop); reduced funding for the BBC World Service; some UK productions are foreign-owned.\nHigher-level answers judge how great the influence is.\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed examination of the extent of influence, well supported by examples, with a clear judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some examination with some examples; judgement may be implied. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Mostly a list of media exports. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nA politician said: "Since leaving the European Union, Britain's links with the rest of the world matter more than ever."\n\nAssess the importance of the UK's political links with other countries.`, marks: 6, command: 'Assess', markScheme: `Indicative content:\n• UN Security Council permanent seat with veto; role in peacekeeping and sanctions.\n• NATO — collective defence; support for Ukraine since 2022.\n• G7 / G20 — shaping global economic and climate policy (e.g. hosted COP26 in Glasgow, 2021).\n• Commonwealth — historic, cultural and trade ties.\n• New trade deals and partnerships since Brexit (e.g. CPTPP, AUKUS).\n• Counter-arguments: reduced influence in Europe since leaving the EU; the UK's relative economic size is falling as China and India grow.\nHigher-level answers reach a supported judgement.\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed assessment with a well-supported judgement on importance. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some assessment, judgement may be limited. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Simple description of links. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nIn the 2021 Census, Leicester and Birmingham became 'minority-majority' cities, where no single ethnic group made up more than half of the population.\n\nExplain how the UK has become more multicultural and the effects of this on UK culture.`, marks: 6, command: 'Explain', markScheme: `Indicative content:\nHow: post-war migration from the Commonwealth (Windrush generation from the Caribbean from 1948; South Asia in the 1950s–70s); East African Asians in the 1970s; migration from EU countries such as Poland after 2004; refugees and international students; children born to migrant families.\nEffects: food (curry, Chinese, Polish shops); music and fashion; festivals (Diwali, Eid, Notting Hill Carnival, Chinese New Year); places of worship; language; sport; media representation. Some challenges of integration and discrimination.\n\nLevel 3 (5–6 marks): Thorough understanding of both how and effects. Detailed explanation well supported by accurate examples. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some explanation, may focus on one aspect. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Simple points with few examples. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nFig. 3 shows economic data for three UK regions (data written for this practice question).\nLondon: unemployment 4.6%; jobs in finance and professional services 25%; average weekly pay £850.\nSouth East England: unemployment 3.4%; jobs in finance and professional services 18%; average weekly pay £720.\nNorth East England: unemployment 5.4%; jobs in finance and professional services 10%; average weekly pay £600.\n\nUsing Fig. 3, analyse the regional differences in the UK economy.`, marks: 6, command: 'Analyse', markScheme: `Indicative content:\nAO3 (use of Fig. 3): North East has highest unemployment (5.4%) and lowest pay (£600, £250 less than London); London has the most finance / professional jobs (25%, 2.5 times the North East); South East has the lowest unemployment; London's unemployment is higher than the South East's despite high pay — inequality within London.\nAO2 (reasons): deindustrialisation hit the North East (coal, steel, shipbuilding); quaternary and financial jobs concentrated in London and the South East (the City, headquarters, airports); North–South divide; government 'levelling up' policies, freeports.\n\nLevel 3 (5–6 marks): Thorough analysis making detailed use of Fig. 3, with differences explained by accurate reasons. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable analysis with some use of data and some explanation. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic description of the data, little explanation. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nAfter Russia's invasion of Ukraine in February 2022, the UK supplied weapons and training to Ukraine, introduced sanctions on Russian individuals and companies, and launched the 'Homes for Ukraine' scheme for refugees.\n\nExplain the UK's role in one recent international conflict.`, marks: 6, command: 'Explain', markScheme: `Indicative content (credit any recent conflict, e.g. Ukraine, Syria, Afghanistan):\n• Military role: weapons, training (e.g. Ukrainian troops trained in the UK), air strikes (Syria), working with NATO allies.\n• Political / diplomatic role: UN Security Council resolutions and debates; G7 sanctions; hosting talks.\n• Humanitarian role: aid, accepting refugees (Homes for Ukraine), funding through the UN.\n• Consequences for the UK: rising energy prices and cost of living; cost of military aid; new migrants; strengthened alliances.\n\nLevel 3 (5–6 marks): Thorough understanding. Detailed explanation of the UK's roles, well supported by accurate detail of the named conflict. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (3–4 marks): Reasonable understanding. Some explanation, some detail of the conflict. A line of reasoning with some structure.\nLevel 1 (1–2 marks): Basic understanding. Simple, generic points. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nIn 2021 manufacturing made up about 8% of UK jobs. However, the UK is still one of the world's ten largest manufacturing nations, with car plants such as Nissan in Sunderland and aerospace firms such as Airbus and Rolls-Royce.\n\nAssess the extent to which the UK has become a post-industrial economy.`, marks: 8, command: 'Assess', markScheme: `Indicative content:\nFor: over 80% of jobs in services; decline of coal, steel, shipbuilding and textiles; closure of the last deep coal mine (Kellingley, 2015) and Port Talbot's blast furnaces (2024); growth of finance, digital, creative industries and research; London as global financial centre.\nAgainst: high-value manufacturing remains important (cars, aerospace, pharmaceuticals, food); manufacturing is a large share of UK exports; new green industries (offshore wind, batteries); output has fallen less than employment because of automation.\nJudgement: UK employment is largely post-industrial but manufacturing still matters, varying by region.\n\nLevel 3 (7–8 marks): Thorough understanding. A detailed, balanced assessment, well supported by accurate examples, leading to a substantiated judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some assessment, may be unbalanced, with a partial judgement. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Limited assessment, mainly descriptive; judgement absent or unsupported. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nBetween the 2011 and 2021 Censuses, the population of England and Wales grew by about 3.5 million (6.3%). The number of residents born outside the UK rose by about 2.5 million over the same period.\n\nTo what extent is international migration the main cause of the UK's changing population?`, marks: 8, command: 'To what extent', markScheme: `Indicative content:\nMigration: net migration has contributed a large share of recent population growth; young adult migrants create bulges at 20–39 and have children (raising births); diversity in cities; migration from the EU after 2004 and from outside the EU since 2021.\nOther causes: natural increase (births exceeding deaths) — though shrinking as birth rate falls to record lows; rising life expectancy causes ageing, which migration cannot reverse; the post-war baby boomers reaching old age; internal migration redistributes population (retirement to the coast, young people to cities).\nJudgement: migration is the main cause of growth, but ageing is driven mostly by falling birth rates and longer life expectancy.\n\nLevel 3 (7–8 marks): Thorough understanding. A detailed, balanced evaluation, well supported by evidence, leading to a substantiated judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some evaluation, may be unbalanced, with a partial judgement. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Limited evaluation, mainly descriptive. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nFig. 1 is a fact file on the UK's place in the world: sixth-largest economy in the world (2023); permanent member of the UN Security Council; member of NATO, G7 and G20; left the EU on 31 January 2020; joined the CPTPP trade bloc in 2024.\n\nEvaluate whether the UK's trade and political links still give it a major role in the world.`, marks: 8, command: 'Evaluate', markScheme: `Indicative content:\nFor: large economy and major exporter of services (finance, education, law); permanent UN seat with veto; leading NATO military power with nuclear weapons; G7 influence; Commonwealth; new trade deals and CPTPP membership; global language and soft power.\nAgainst: lost influence in EU decision-making; EU remains the largest trading partner but trade faces more barriers; relative decline as China, India and other emerging economies grow; reduced aid spending (cut from 0.7% to 0.5% of GNI).\nJudgement: still a major player, but influence is now based more on soft power and alliances than on economic size.\n\nLevel 3 (7–8 marks): Thorough understanding. A detailed, balanced evaluation, well supported by evidence from Fig. 1 and own knowledge, leading to a substantiated judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some evaluation with some evidence; judgement partly supported. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Mainly lists links from Fig. 1. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Section A — UK in the 21st Century.\nFig. 2 contains two views (written for this practice question).\nA software developer in Manchester: "I work from home for a London tech company. Fast broadband means I don't need to live in the South East."\nA shopkeeper in a small Welsh town: "Online shopping has taken our customers and the mobile signal here is still poor."\n\nAssess the impacts of the growth of the digital economy on different parts of the UK.`, marks: 8, command: 'Assess', markScheme: `Indicative content:\nPositive: new jobs in tech, media and online retail; tech clusters in London (Shoreditch), Manchester (MediaCityUK), Cambridge, Edinburgh; remote working lets people live outside expensive cities; online services reduce isolation; warehouses and distribution centres create jobs (e.g. along the M1 'golden triangle').\nNegative: high street shop closures; rural areas and parts of Wales and Scotland with poor broadband are left behind (digital divide); older people less able to access online services; jobs may be low-paid or insecure.\nJudgement: benefits concentrated in cities and the South East; impacts are uneven.\n\nLevel 3 (7–8 marks): Thorough understanding. A detailed, balanced assessment of impacts in different places, well supported by examples, leading to a substantiated judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some assessment of impacts; places may be treated generally. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Simple points, often repeating Fig. 2. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` },
      { q: `Resource Booklet — an ageing coastal town (data written for this practice question).\nFig. 1: the town has 45 000 residents; 31% are aged 65 and over (UK average 19%); 14% of working-age adults are unemployed; the main employers are care homes, the hospital and summer tourism.\nFig. 2: the town council has money for one option.\nOption 1 — Build a new health and social-care centre with 120 extra care beds and a day centre for older residents.\nOption 2 — Create a digital business hub with fast broadband, start-up offices and training courses to attract young workers and new companies.\nOption 3 — Build 600 affordable homes for first-time buyers and young families.\n\nUsing Figs. 1 and 2 and your own understanding, choose the option that you think would best meet the needs of the town's changing population. Justify your choice. [12 marks + 3 marks for SPaG]`, marks: 12, command: 'Justify', markScheme: `No option is correct; credit the quality of justification.\nIndicative content:\nOption 1: meets the immediate needs of a population where 31% are over 65; creates care jobs; but does not address out-migration of young people and increases dependency.\nOption 2: diversifies the economy away from seasonal tourism; creates higher-paid digital / quaternary jobs; could retain young people and reduce unemployment; but needs skills and time, and benefits may not reach older residents.\nOption 3: attracts young families to rebalance the population structure and widen the pyramid base; but needs jobs to support them, and uses land.\nHigher-level answers use data from Figs. 1 and 2, explain why the chosen option is best, and explain why the rejected options are less suitable, considering sustainability and different groups of people.\n\nLevel 4 (10–12 marks): Thorough understanding. A comprehensive, well-reasoned justification of the chosen option, making detailed use of Figs. 1 and 2, with clear reasons for rejecting the other options. Well-developed line of reasoning which is clear and logically structured.\nLevel 3 (7–9 marks): Good understanding. A clear justification with good use of the resources and some consideration of other options. A line of reasoning which is clear and mostly logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some justification with some use of the resources; other options not considered or only briefly. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Choice made with limited justification, largely copying the resources. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.\n\nSPaG:\nHigh performance (3 marks): spells and punctuates with consistent accuracy; consistently uses rules of grammar with effective control of meaning; uses a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): spells and punctuates with considerable accuracy; uses rules of grammar with general control of meaning; uses a good range of specialist terms.\nThreshold performance (1 mark): spells and punctuates with reasonable accuracy; uses rules of grammar with some control of meaning; uses a limited range of specialist terms.\n0 marks: errors severely hinder meaning, or no response.` },
      { q: `Resource Booklet — the UK's place in the world.\nFig. 1: the UK is a permanent member of the UN Security Council and a member of NATO, the G7 and the Commonwealth; it left the EU in 2020.\nFig. 2: UK media and culture — the BBC World Service broadcasts in more than 40 languages; Premier League football is watched in around 190 countries; UK music, film and TV formats are sold worldwide.\nFig. 3: UK economy — London is one of the world's largest financial centres; services make up over 80% of UK jobs; China and India have grown faster than the UK economy since 2000.\n\nUsing Figs. 1, 2 and 3 and your own understanding, assess whether the UK's importance in the world is increasing or decreasing in the 21st century.`, marks: 12, command: 'Assess', markScheme: `Indicative content:\nIncreasing / maintained: soft power through media, sport, music, universities and the English language; London's global financial role; new trade deals since Brexit (e.g. CPTPP) and partnerships (AUKUS); leading role in NATO and support for Ukraine; hosting COP26 (2021); UN Security Council veto.\nDecreasing: relative economic decline as emerging economies (China, India, Brazil) grow; loss of influence in EU decision-making; trade barriers with the EU; cuts to overseas aid; competition from US and Asian media; questions over the UN permanent seat.\nJudgement: e.g. economic importance declining relatively, but political and cultural (soft) power keeps the UK influential.\nHigher-level answers use all three figures, add own knowledge and examples, and reach a substantiated conclusion.\n\nLevel 4 (10–12 marks): Thorough understanding. A comprehensive and balanced assessment, making detailed use of the figures and own knowledge, leading to a well-substantiated judgement. Well-developed line of reasoning which is clear and logically structured.\nLevel 3 (7–9 marks): Good understanding. A clear assessment with good use of the figures and some own knowledge, with a supported judgement. A line of reasoning which is clear and mostly logically structured.\nLevel 2 (4–6 marks): Reasonable understanding. Some assessment with some use of the figures; may be one-sided; judgement limited. A line of reasoning with some structure.\nLevel 1 (1–3 marks): Basic understanding. Mostly description of the figures with little assessment. Information is basic and communicated in an unstructured way.\n0 marks: No response or no response worthy of credit.` }
    ]
  },
  '2.4': {
    name: 'Resource Reliance',
    questions: [
      { q: `Section A — Resource Reliance.\nFig. 1 shows the mean daily calorie intake per person in six countries (data written for this practice question).\nUSA 3 750 kcal\nUK 3 340 kcal\nBrazil 3 260 kcal\nIndia 2 580 kcal\nTanzania 2 370 kcal\nMadagascar 2 050 kcal\n\nIdentify the country in Fig. 1 with the lowest daily calorie intake per person.`, marks: 1, command: 'Identify', markScheme: `Madagascar (1)` },
      { q: `Section A — Resource Reliance.\nFig. 1 shows the mean daily calorie intake per person in six countries (data written for this practice question).\nUSA 3 750 kcal\nUK 3 340 kcal\nBrazil 3 260 kcal\nIndia 2 580 kcal\nTanzania 2 370 kcal\nMadagascar 2 050 kcal\n\nCalculate the difference in daily calorie intake per person between the UK and Tanzania.`, marks: 1, command: 'Calculate', markScheme: `970 kcal (1)\n(3 340 − 2 370 = 970)` },
      { q: `Section A — Resource Reliance.\nIn 1798 Thomas Malthus wrote that population, when unchecked, increases in the ratio 1, 2, 4, 8, 16 … while food supply can only increase in the ratio 1, 2, 3, 4, 5 …\n\nIdentify the type of growth that Malthus said population follows.`, marks: 1, command: 'Identify', markScheme: `Geometric / exponential growth (1)\nAllow doubling. Do not accept arithmetic / linear.` },
      { q: `Section A — Resource Reliance.\nFig. 2 is an extract from a news report about farming in northern Tanzania (written for this practice question).\n'The short rains failed again this year and many maize fields dried out before the cobs had formed. Where crops did survive, fall armyworm caterpillars ate the leaves. Farmers who did harvest a crop struggled to sell it because the dirt road to the market town is impassable after rain, and much of the stored grain was spoiled by rats and damp.'\n\nGive one physical factor from Fig. 2 that has reduced food supply.`, marks: 1, command: 'Give', markScheme: `One from: failure of the short rains / drought / low or unreliable rainfall (1); pests / fall armyworm (1)\nDo not credit human factors (poor roads, storage losses).` },
      { q: `Section A — Resource Reliance.\nFig. 3 is a description of a world choropleth map showing the percentage of the population that is undernourished. The darkest shading (more than 35%) covers Somalia, the Central African Republic, the Democratic Republic of the Congo, Madagascar, Haiti and Yemen. Most of Europe, North America and Australia are shaded in the lightest category (less than 2.5%).\n\nIdentify the continent that has the most countries in the highest category of undernourishment.`, marks: 1, command: 'Identify', markScheme: `Africa (1)\nAllow sub-Saharan Africa.` },
      { q: `Section A — Resource Reliance.\nFig. 4 shows Malthus's model of population and food supply over time. Both start at an index of 1 and each step is 25 years.\nYears: 0, 25, 50, 75, 100, 125, 150\nPopulation index: 1, 2, 4, 8, 16, 32, 64\nFood supply index: 1, 2, 3, 4, 5, 6, 7\n\nCalculate how many times larger the population index is than the food supply index after 150 years. Give your answer to one decimal place.`, marks: 1, command: 'Calculate', markScheme: `9.1 times (1)\n(64 ÷ 7 = 9.14…)` },
      { q: `Section A — Resource Reliance.\nFig. 5 shows the mean monthly rainfall for Dodoma, central Tanzania (data written for this practice question).\nJan 150 mm, Feb 115 mm, Mar 135 mm, Apr 55 mm, May 5 mm, Jun 0 mm, Jul 0 mm, Aug 0 mm, Sep 0 mm, Oct 5 mm, Nov 25 mm, Dec 130 mm\n\nCalculate the range of mean monthly rainfall shown in Fig. 5.`, marks: 1, command: 'Calculate', markScheme: `150 mm (1)\n(150 − 0 = 150)` },
      { q: `Section A — Resource Reliance.\nFig. 6 shows energy consumption per person in five countries (data written for this practice question).\nUSA 280 GJ\nUK 110 GJ\nChina 105 GJ\nIndia 27 GJ\nTanzania 8 GJ\n\nSuggest one reason why energy consumption per person is much higher in the USA than in Tanzania.`, marks: 1, command: 'Suggest', markScheme: `One from, e.g.: higher incomes / wealthier so people can afford more cars, appliances, heating and air conditioning (1); more industry / more energy-intensive economy (1); almost everyone connected to electricity, whereas many people in Tanzania have no mains supply (1); greater car use / longer journeys (1)\nAllow converse points about Tanzania.` },
      { q: `Section B — Human geography fieldwork.\nGCSE students investigated where food sold in their local supermarket comes from. They stood at the exit and asked every fifth shopper to complete a questionnaire about the food in their basket.\n\nIdentify the sampling method the students used.`, marks: 1, command: 'Identify', markScheme: `Systematic sampling (1)` },
      { q: `Section A — Resource Reliance.\nThe national census of Tanzania recorded a population of 44.93 million in 2012 and 61.74 million in 2022.\n\nCalculate the percentage change in the population of Tanzania between 2012 and 2022. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 61.74 − 44.93 = 16.81; 16.81 ÷ 44.93 × 100 (1)\n1 mark for answer: 37.4% (increase) (1)\nAllow 37% or 37.41%. Correct answer without working = 1 mark.` },
      { q: `Section A — Resource Reliance.\nFig. 7 shows maize production in Tanzania over five years (data written for this practice question).\n2019: 5.7 million tonnes\n2020: 6.7 million tonnes\n2021: 7.0 million tonnes\n2022: 5.9 million tonnes\n2023: 6.4 million tonnes\n\nCalculate the mean annual maize production for 2019–2023. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 5.7 + 6.7 + 7.0 + 5.9 + 6.4 = 31.7; 31.7 ÷ 5 (1)\n1 mark for answer: 6.34 million tonnes (1)\nAllow 6.3 million tonnes.` },
      { q: `Section A — Resource Reliance.\nThe Food and Agriculture Organization (FAO) estimated that about 733 million people faced hunger in 2023, when the world population was about 8.06 billion.\n\nCalculate the percentage of the world population that faced hunger in 2023. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 733 million ÷ 8 060 million × 100 (1)\n1 mark for answer: 9.1% (1)\nAllow 9% or 9.09%. Penalise answers not adjusted for millions/billions (e.g. 0.0091%).` },
      { q: `Section A — Resource Reliance.\nFig. 8 shows food production and consumption in the UK in one year (data written for this practice question).\nFood produced in the UK: 24.6 million tonnes\nFood consumed in the UK: 41.0 million tonnes\n\nCalculate the percentage of the food consumed in the UK that was produced in the UK. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 24.6 ÷ 41.0 × 100 (1)\n1 mark for answer: 60% (1)` },
      { q: `Section B — Human geography fieldwork.\nGCSE students recorded the distance travelled (food miles, in km) by nine items in a shopping basket (data written for this practice question).\n45, 320, 8 900, 1 600, 12, 2 400, 650, 18 000, 95\n\nCalculate the median distance travelled. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: data put in order 12, 45, 95, 320, 650, 1 600, 2 400, 8 900, 18 000 and the 5th value identified (1)\n1 mark for answer: 650 km (1)` },
      { q: `Section A — Resource Reliance.\nFig. 9 shows energy data for a country (data written for this practice question).\nTotal energy consumption: 1 200 petajoules (PJ) per year\nPopulation: 60 million\n(1 PJ = 1 000 000 GJ)\n\nCalculate the energy consumption per person in gigajoules (GJ). You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 1 200 × 1 000 000 = 1 200 000 000 GJ; 1 200 000 000 ÷ 60 000 000 (1)\n1 mark for answer: 20 GJ per person (1)` },
      { q: `Section A — Resource Reliance.\nFig. 10 is a description of a world map showing countries with a food surplus (production greater than consumption) and a food deficit. Food surplus countries shown include the USA, Canada, Brazil, Argentina, Australia, France, Ukraine and Russia. Large areas of food deficit are shown across North Africa, the Middle East, much of sub-Saharan Africa and parts of South Asia.\n\nDescribe the global distribution of food deficit shown in Fig. 10.`, marks: 2, command: 'Describe', markScheme: `1 mark per valid descriptive point, e.g.:\nconcentrated in Africa / sub-Saharan Africa (1)\nNorth Africa and the Middle East (1)\nparts of South Asia (1)\nmainly in lower-latitude / tropical and arid regions (1)\nmostly LIDCs / few deficit areas in the Americas, Europe or Australia (1)\nMax 2. Do not credit explanation.` },
      { q: `Section A — Resource Reliance.\nFig. 11 shows GNI per person and daily calorie intake per person for five countries (data written for this practice question).\nNorway — GNI US$84 000 — 3 480 kcal\nUK — GNI US$48 000 — 3 340 kcal\nMexico — GNI US$11 000 — 3 070 kcal\nKenya — GNI US$2 100 — 2 210 kcal\nMalawi — GNI US$650 — 2 400 kcal\n\nDescribe the relationship between GNI per person and daily calorie intake shown in Fig. 11.`, marks: 2, command: 'Describe', markScheme: `1 mark for the relationship, 1 mark for supporting data or an anomaly, e.g.:\npositive relationship — as GNI per person increases, calorie intake tends to increase (1)\ne.g. Norway has the highest GNI (US$84 000) and highest intake (3 480 kcal) (1)\nanomaly: Malawi has a lower GNI than Kenya but a higher calorie intake (2 400 vs 2 210 kcal) (1)\nMax 2.` },
      { q: `Section A — Resource Reliance.\nIn much of northern Tanzania there are two rainy seasons, the short rains (October–December) and the long rains (March–May). Most small-scale farmers rely on rainfall rather than irrigation.\n\nExplain one way that climate can affect food security in Tanzania.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\nif a rainy season fails / drought (1) crops such as maize wilt and harvests fall, so families have less food to eat or sell (1)\nheavy rain / floods (1) wash away crops and soil and damage roads, so food cannot reach markets (1)\nhigh temperatures (1) increase evaporation so soil moisture is lost and yields fall (1)\nunreliable rainfall (1) makes planting dates uncertain so farmers may plant at the wrong time (1)` },
      { q: `Section A — Resource Reliance.\nSince fighting began in Sudan in April 2023, millions of people have been forced from their homes. Farmers in some regions have been unable to plant or harvest crops and aid convoys have been blocked.\n\nExplain one way that conflict affects food security.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\nfarmers flee their land (1) so crops are not planted or harvested and food production falls (1)\ntransport routes are blocked (1) so food and aid cannot reach people, and prices rise (1)\nfarmland, stores or irrigation are destroyed (1) reducing future production (1)\nmoney is spent on fighting rather than agriculture (1)` },
      { q: `Section A — Resource Reliance.\nIn many low-income households in Dar es Salaam, Tanzania, more than half of household income is spent on food. Food prices in the city rose sharply in 2022 (written for this practice question).\n\nExplain one way that poverty can reduce food security.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\npoor households cannot afford enough food when prices rise (1) so they eat fewer meals or less nutritious food (1)\npoor farmers cannot afford seeds, fertiliser or irrigation (1) so yields stay low (1)\nlack of money for storage (1) leads to post-harvest losses to pests and damp (1)` },
      { q: `Section A — Resource Reliance.\nFig. 12 shows meat consumption per person in China (data written for this practice question).\n1980: 15 kg per year\n2000: 45 kg per year\n2020: 63 kg per year\n\nExplain one reason why economic development increases the demand for food.`, marks: 2, command: 'Explain', markScheme: `1 mark for the reason, 1 mark for development, e.g.:\nrising incomes / a growing middle class (1) means people can afford more meat and dairy, which need large amounts of grain and land to produce (1)\nurbanisation (1) means more people buy food rather than grow it / more processed food is demanded (1)\nchanging lifestyles / western diets (1) increase consumption of calorie-rich and imported foods (1)` },
      { q: `Section A — Resource Reliance.\nFig. 13 is a description of a satellite image of a large open-pit gold mine in north-west Tanzania. It shows a deep pit about 1 km across, large grey spoil heaps, a lagoon of waste water (tailings), cleared land and a river running close to the edge of the site.\n\nUsing Fig. 13, explain one impact of resource extraction on the natural world.`, marks: 2, command: 'Explain', markScheme: `1 mark for the impact linked to Fig. 13, 1 mark for development, e.g.:\nland / vegetation cleared (1) so habitats are destroyed and wildlife lost (1)\ntailings lagoon / waste water (1) may leak toxic chemicals (e.g. cyanide, heavy metals) into the river, harming fish and drinking water (1)\nspoil heaps (1) are unstable and bare so soil is eroded into rivers (1)\nthe pit (1) permanently changes the landscape / lowers the water table (1)` },
      { q: `Section A — Resource Reliance.\nLarge areas of lowland rainforest in Sumatra and Borneo, Indonesia, have been cleared and replaced with oil palm plantations to meet global demand for palm oil.\n\nExplain one way that this use of resources affects the natural world.`, marks: 2, command: 'Explain', markScheme: `1 mark for the effect, 1 mark for development, e.g.:\nloss of biodiversity (1) as a monoculture replaces a diverse forest, threatening species such as orangutans (1)\nmore carbon dioxide released (1) when forest and peat are burned / drained, adding to the greenhouse effect (1)\nsoil erosion (1) because the canopy no longer intercepts heavy rain (1)\nwater pollution (1) from fertiliser and pesticide runoff (1)` },
      { q: `Section A — Resource Reliance.\nIn the UK each person uses about 140 litres of water a day at home. In rural Tanzania many people use less than 20 litres a day, often collected from a well or river (written for this practice question).\n\nSuggest two reasons for the difference in water consumption.`, marks: 2, command: 'Suggest', markScheme: `1 mark for each reason, e.g.:\nUK homes have piped water / taps on demand, whereas in rural Tanzania water must be carried (1)\nUK homes have water-using appliances (washing machines, dishwashers, showers, flushing toilets) (1)\nhigher incomes in the UK so people can afford to pay for water (1)\nwater scarcity / long dry season in parts of Tanzania (1)\nlack of infrastructure / investment in rural Tanzania (1)\nMax 2.` },
      { q: `Section A — Resource Reliance.\nFig. 14 shows where the calories in the average diet come from in two countries (data written for this practice question).\nUK — cereals 30%, meat and dairy 30%, sugars and fats 25%, other 15%\nTanzania — cereals 55%, roots (cassava) 15%, meat and dairy 5%, sugars and fats 15%, other 10%\n\nCompare the diets of the UK and Tanzania shown in Fig. 14.`, marks: 2, command: 'Compare', markScheme: `1 mark per valid comparative point, e.g.:\nTanzania gets a much larger share of calories from cereals than the UK (55% vs 30%) (1)\nthe UK gets six times the share of calories from meat and dairy (30% vs 5%) (1)\nthe UK gets more calories from sugars and fats (25% vs 15%) (1)\nroots / cassava are an important part of the Tanzanian diet but are not shown for the UK (1)\nMax 2. Points must be comparative; data alone does not score.` },
      { q: `Section A — Resource Reliance.\nIn 1965 the economist Ester Boserup argued that 'necessity is the mother of invention': as population grows, people find new ways to produce more food from the same land.\n\nGive two ways that farmers could increase food production in response to population growth, as suggested by Boserup.`, marks: 2, command: 'Give', markScheme: `1 mark for each way, e.g.:\nirrigation (1)\nusing fertiliser / manure (1)\nnew crop varieties / higher-yield seeds (1)\nterracing steep slopes (1)\nshorter fallow periods / multiple cropping in a year (1)\nmechanisation / new tools (1)\nMax 2.` },
      { q: `Section A — Resource Reliance.\nFig. 15 shows the food wasted by households in one UK town in a year (data written for this practice question).\nFruit and vegetables 38%\nBread and bakery 22%\nDairy 14%\nMeat and fish 10%\nOther 16%\n\nExplain one way that reducing food waste could improve food security.`, marks: 2, command: 'Explain', markScheme: `1 mark for the way, 1 mark for development, e.g.:\nless food bought and thrown away (1) reduces demand, so more food is available for others / prices fall (1)\nsurplus food redistributed to food banks (1) gives access to food for people in poverty (1)\nless land, water and energy used to grow wasted food (1) so resources can be used to grow food that is eaten (1)` },
      { q: `Section B — Human geography fieldwork.\nGCSE students used this questionnaire to find out about shoppers' food choices.\n1. Do you buy local food? Yes / No\n2. Why don't you care about where your food comes from?\n3. How much do you earn?\n\nSuggest two ways that the students could improve their questionnaire.`, marks: 2, command: 'Suggest', markScheme: `1 mark for each improvement, e.g.:\nremove the leading / biased question 2 / reword it neutrally (1)\nremove or replace the personal / sensitive question about income, e.g. with optional income bands (1)\ndefine 'local' (e.g. within 50 km) so answers are consistent (1)\nadd closed questions with tick boxes / scales so results are easier to compare (1)\nadd a question on how often they buy local food / Fairtrade food (1)\ncarry out a pilot survey first (1)\nMax 2.` },
      { q: `Section A — Resource Reliance.\nA charity has helped small-scale farmers in Dodoma region, Tanzania, to install drip irrigation kits. Water from a raised tank drips slowly through thin pipes onto the roots of each plant.\n\nExplain one advantage of drip irrigation for small-scale farmers.`, marks: 2, command: 'Explain', markScheme: `1 mark for the advantage, 1 mark for development, e.g.:\nuses much less water than flooding fields (1) because water goes straight to the roots and less is lost to evaporation (1)\nallows crops to be grown in the dry season (1) so farmers can harvest more than once a year / have food all year (1)\ncheap and simple technology (1) which farmers can afford and repair themselves (1)\nhigher yields (1) so surplus vegetables can be sold for income (1)` },
      { q: `Section A — Resource Reliance.\nIn 2018 the government of Tanzania halted field trials of genetically modified (GM) drought-tolerant maize.\n\nExplain one disadvantage of using GM crops to improve food security.`, marks: 2, command: 'Explain', markScheme: `1 mark for the disadvantage, 1 mark for development, e.g.:\nGM seed is expensive / patented by large companies (1) so poor farmers must buy new seed each year and may fall into debt (1)\nconcern about cross-pollination with local varieties (1) reducing biodiversity of crops (1)\nlong-term health or environmental effects are uncertain (1) so consumers or importers may refuse to buy them (1)\npests / weeds may become resistant (1) so more chemicals are needed later (1)` },
      { q: `Section A — Resource Reliance.\nIn the 1960s and 1970s India introduced the Green Revolution. Farmers in states such as Punjab were given high-yielding varieties (HYVs) of wheat and rice, chemical fertilisers and pesticides, and new tube wells were dug for irrigation.\n\nExplain how the Green Revolution increased food supply.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, e.g.:\nHYVs produce more grain per plant / per hectare (1)\nfaster-growing varieties allowed two or three harvests a year (1)\nfertilisers replaced nutrients so yields stayed high (1)\npesticides reduced crop losses to insects and disease (1)\nirrigation meant crops could be grown in the dry season / were less affected by drought (1)\nIndia changed from relying on food imports to being largely self-sufficient in grain (1)\nMax 3.` },
      { q: `Section A — Resource Reliance.\nThe world population was about 1 billion in 1800 and passed 8 billion in 2022. Over the same period the amount of food produced per person in the world increased.\n\nExplain why Malthus's prediction of global famine has not happened.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, e.g.:\nnew technology has increased food supply faster than population, e.g. the Green Revolution, fertilisers, mechanisation (1)\nmore land has been brought into farming, e.g. irrigation of dry areas (1)\nfood can be traded globally, moving surpluses to deficit areas (1)\nbirth rates have fallen as countries develop, slowing population growth (1)\nthis supports Boserup's view that population pressure drives innovation (1)\nMax 3. Allow recognition that local famines have still occurred (1).` },
      { q: `Section A — Resource Reliance.\nFig. 16 shows the percentage of the population of Tanzania that is undernourished (data written for this practice question).\n2005: 32%\n2010: 31%\n2015: 26%\n2020: 23%\n\nDescribe the changes shown in Fig. 16.`, marks: 3, command: 'Describe', markScheme: `1 mark per valid point, at least one using data, e.g.:\nundernourishment has decreased overall (1)\nfrom 32% in 2005 to 23% in 2020 / a fall of 9 percentage points (1)\nlittle change between 2005 and 2010 (only 1 percentage point) (1)\nfastest fall between 2010 and 2015 (5 percentage points) (1)\nabout a quarter of the population is still undernourished in 2020 (1)\nMax 3.` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\nFor a named country you have studied, explain how physical factors affect its food security.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, with credit for case study detail, e.g. Tanzania:\nunreliable rainfall and droughts, e.g. in central regions such as Dodoma, cause maize crops to fail (1)\nmost farmers rely on rain rather than irrigation so drought quickly reduces harvests (1)\npests such as fall armyworm (from 2017) and locusts damage crops (1)\nsoils in some areas are thin / infertile / eroded by heavy rain, lowering yields (1)\nfloods in rainy seasons wash away crops and damage roads to markets (1)\nMax 3. Max 2 if no named country.` },
      { q: `Section A — Resource Reliance.\nA Fairtrade coffee co-operative on the slopes of Mount Kilimanjaro, Tanzania, receives a guaranteed minimum price for its coffee and an extra Fairtrade Premium. UK shoppers buy its coffee in supermarkets.\n\nExplain how ethical consumerism can improve food security for farmers in LIDCs.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, e.g.:\nguaranteed minimum price gives farmers a reliable income even when world prices fall (1)\nso they can afford to buy food in the hungry season (1)\nthe Premium can be invested in community projects, e.g. water supplies, schools, new tools (1)\nfarmers can invest in their own food crops, e.g. better seeds, storage (1)\nlonger-term contracts reduce uncertainty / allow planning (1)\nMax 3.` },
      { q: `Section B — Human geography fieldwork.\nGCSE students wanted to find out whether shoppers in their town preferred locally produced food. They asked 15 shoppers outside one organic farm shop between 10:00 and 10:30 on a Tuesday morning.\n\nExplain one limitation of the students' data collection and how it could be improved.`, marks: 3, command: 'Explain', markScheme: `1 mark for the limitation, 1 mark for why it matters, 1 mark for the improvement, e.g.:\nonly one location, an organic farm shop (1) so the sample is biased towards people who already buy local food (1) — survey at several locations, e.g. a supermarket and a market (1)\nsmall sample of 15 (1) so results may not be representative / reliable (1) — increase the sample to e.g. 50+ (1)\nonly one short time on a weekday (1) misses workers / weekend shoppers (1) — repeat at different times and days (1)\nMax 3.` },
      { q: `Section A — Resource Reliance.\nThe Julius Nyerere Hydropower Station on the Rufiji River in southern Tanzania has a planned capacity of 2 115 MW. Its dam and reservoir lie inside the Selous Game Reserve, a protected wildlife area.\n\nExplain how energy production can affect the natural world.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, e.g.:\nthe reservoir floods a large area of land (1) destroying woodland habitats and displacing wildlife (1)\nroads, power lines and construction clear vegetation / fragment habitats (1)\nthe dam traps sediment (1) so the river and delta downstream receive fewer nutrients, affecting farmland, fisheries and mangroves (1)\nchanges river flow / blocks fish migration (1)\nAllow other energy examples, e.g. fossil fuel extraction causing pollution / greenhouse gas emissions.\nMax 3.` },
      { q: `Section A — Resource Reliance.\nThe world population passed 8 billion in November 2022. The United Nations projects that it will reach about 9.7 billion by 2050.\n\nExplain why the global demand for resources is increasing.`, marks: 3, command: 'Explain', markScheme: `1 mark per valid point or development, e.g.:\npopulation growth means more people need food, water and energy (1)\neconomic development raises incomes so people consume more per person, e.g. meat, cars, electricity (1)\nindustrialisation in EDCs such as China and India needs more energy and raw materials (1)\nurbanisation increases demand for piped water, electricity and transport (1)\nMax 3.` },
      { q: `Section A — Resource Reliance.\nMalthus argued that population would eventually grow faster than food supply, leading to a crisis that would be ended by 'positive checks' such as famine, disease and war.\n\nDraw a labelled graph to show Malthus's theory of population and food supply.`, marks: 4, command: 'Draw', diagram: true, markScheme: `1 mark per correct feature (max 4):\naxes labelled — time on the x-axis and amount / quantity on the y-axis (1)\nfood supply shown as a straight line rising steadily (arithmetic growth) (1)\npopulation shown as a curve rising more and more steeply (geometric / exponential growth) (1)\nthe point where the lines cross labelled as the crisis / Malthusian catastrophe point (1)\npopulation shown falling back after the crisis, labelled with positive checks (famine / disease / war) (1)` },
      { q: `Section A — Resource Reliance.\nFig. 17 shows the mean daily calorie intake per person in world regions (data written for this practice question).\nNorth America 3 700 kcal\nEurope 3 400 kcal\nSouth America 3 050 kcal\nAsia 2 900 kcal\nSub-Saharan Africa 2 350 kcal\nThe recommended intake for an adult is about 2 000–2 500 kcal.\n\nDescribe the global pattern of food consumption shown in Fig. 17.`, marks: 4, command: 'Describe', markScheme: `1 mark per valid descriptive point, with up to 2 marks for accurate use of data, e.g.:\nconsumption is uneven / unequal across the world (1)\nhighest in North America (3 700 kcal) and Europe (3 400 kcal) — richer regions (1)\nlowest in sub-Saharan Africa (2 350 kcal) (1)\nNorth America consumes 1 350 kcal more per person than sub-Saharan Africa (1)\nall regions are above 2 000 kcal on average, but sub-Saharan Africa is within / near the lower end of the recommended range (1)\nNorth America and Europe are well above the recommended intake (1)\nMax 4.` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\nFor a named country you have studied, explain two ways that small-scale farmers have been helped to increase their food security.`, marks: 4, command: 'Explain', markScheme: `For each way: 1 mark for the way, 1 mark for development. Max 2 marks if no named country.\ne.g. Tanzania:\nrainwater harvesting / drip irrigation (1) allows vegetables to be grown into the dry season, so families have food when maize stores run out (1)\nimproved storage, e.g. hermetic (airtight) grain bags or metal silos (1) cut post-harvest losses to weevils and damp (1)\ndrought-tolerant seed varieties, e.g. sorghum or cassava (1) survive failed rains (1)\nco-operatives / Fairtrade (1) give farmers better prices so they can buy food and inputs (1)\nmobile phone market price information (1) helps farmers sell at the best time (1)` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\nFor a named country you have studied, explain how and why its food security has changed over time.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of both how and why food security has changed, with accurate and detailed case study knowledge (named places, crops, dates, data).\nLevel 2 (3–4 marks): Clear explanation of some changes and reasons, with some case study detail.\nLevel 1 (1–2 marks): Basic, mostly descriptive points; little or no case study detail.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. Tanzania):\n• the share of people undernourished has generally fallen since the early 2000s but many rural households are still food insecure, especially in the lean season\n• maize is the main staple; harvests vary from year to year with rainfall\n• improvement linked to economic growth, government policy (Kilimo Kwanza, 'Agriculture First', 2009) and investment in farming, e.g. SAGCOT\n• improved seeds, fertiliser subsidies and better roads in some regions\n• rapid population growth (44.9 million in 2012 to 61.7 million in 2022) increases demand\n• droughts, fall armyworm and rising food prices (e.g. 2022) have caused setbacks\n• food security differs between regions, e.g. the drier centre (Dodoma) and the wetter Southern Highlands` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\nExamine the success of one large-scale attempt to improve food security in a country you have studied.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): Thorough examination of successes and limitations of the named scheme, with accurate, detailed knowledge; a clear, supported judgement on how successful it has been.\nLevel 2 (3–4 marks): Clear examination of some successes and/or limitations with some detail; judgement limited.\nLevel 1 (1–2 marks): Basic description of the scheme; little examination or detail.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. SAGCOT, the Southern Agricultural Growth Corridor of Tanzania, launched 2010):\n• public–private partnership to attract investment in commercial farming along the road and rail corridor from Dar es Salaam to the Southern Highlands\n• planned targets included about 350 000 ha brought into commercial production, about 420 000 jobs and 2 million people lifted out of poverty\n• successes: investment in irrigation, processing and storage; outgrower schemes link smallholders to companies; higher yields of crops such as rice, maize, tea and potatoes\n• limitations: progress slower than planned; benefits concentrated on larger farms and companies; risk of land grabbing and displacement of smallholders and pastoralists\n• environmental concerns: water use and fertiliser pollution, loss of habitat\n• may increase food production for export rather than local food security\nAllow other large-scale schemes, e.g. the Green Revolution in India.` },
      { q: `Section A — Resource Reliance.\n\nAssess the effectiveness of one small-scale attempt to achieve food security.`, marks: 6, command: 'Assess', markScheme: `Level 3 (5–6 marks): Thorough assessment of the strengths and limitations of a named small-scale attempt, with accurate detail; a clear, supported judgement on effectiveness.\nLevel 2 (3–4 marks): Clear discussion of some strengths and/or limitations with some detail; judgement limited.\nLevel 1 (1–2 marks): Basic description of an attempt; little assessment.\n0 marks: No response worthy of credit.\n\nIndicative content (any appropriate small-scale example, e.g. rainwater harvesting and drip irrigation in Dodoma, Tanzania; permaculture / allotments / urban farming; Fairtrade co-operatives):\n• uses cheap, appropriate technology that local people can maintain\n• increases yields / allows growing in the dry season / diversifies diets\n• builds local skills and community ownership, so likely to last\n• environmentally sustainable — uses less water and fewer chemicals\n• limitations: benefits a small number of households; depends on charity funding; may not survive a severe drought; does not tackle national causes such as poverty or poor roads\n• judgement: effective for local food security but limited in scale` },
      { q: `Section A — Resource Reliance.\nFig. 18 shows some ways that humans exploit natural resources: open-pit mining for copper and gold; clearing rainforest for oil palm and soya; building large dams for hydro-electricity; drilling for oil and gas; drawing water from aquifers for irrigation.\n\nUsing Fig. 18 and your own understanding, explain the impact of human activity on the natural world.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of a range of impacts, linked clearly to resource activities, using Fig. 18 and accurate examples.\nLevel 2 (3–4 marks): Clear explanation of some impacts with some use of Fig. 18 or examples.\nLevel 1 (1–2 marks): Basic list of impacts; little explanation; may copy Fig. 18.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• mining removes vegetation and soil; toxic waste (tailings) pollutes rivers and groundwater\n• deforestation for oil palm (e.g. Borneo, Sumatra) or soya (e.g. Amazon) causes biodiversity loss and releases carbon dioxide\n• dams flood valleys, trap sediment and change river ecosystems, e.g. the Julius Nyerere dam on the Rufiji, Tanzania\n• oil spills and gas flaring pollute land and sea; burning fossil fuels increases the enhanced greenhouse effect\n• over-abstraction lowers water tables, dries rivers and wetlands, and can cause salinisation\n• impacts can be local (habitat loss) and global (climate change)\n• some impacts can be reduced by management, e.g. reclamation of mine sites` },
      { q: `Section A — Resource Reliance.\nIn Machakos district, Kenya, the population grew more than fivefold between 1930 and 1990. In the 1930s the land was described as badly eroded. By 1990 farmers had built terraces on most slopes, planted trees and used manure, and crop output per hectare had increased.\n\nExamine how far the Machakos example supports Boserup's theory.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): Thorough examination linking the Machakos evidence to Boserup's theory, with a clear understanding of the theory and its limits; a supported judgement.\nLevel 2 (3–4 marks): Clear links between the example and the theory with some examination; judgement limited.\nLevel 1 (1–2 marks): Basic description of the theory or the example; few links.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• Boserup (1965): population growth creates pressure that drives agricultural innovation and intensification\n• Machakos: more people led to terracing, tree planting and manuring — new methods, as Boserup predicted\n• land became less eroded and more productive despite the larger population\n• supports Boserup and contradicts Malthus's prediction of collapse\n• other factors also helped: access to Nairobi markets, cash crops, money sent home by migrants, government and NGO support — so population pressure was not the only cause\n• one case may not apply everywhere, e.g. land degradation in parts of the Sahel where population growth has led to overgrazing` },
      { q: `Section A — Resource Reliance.\nFig. 19 shows the share of world population and world food consumption for two groups of countries (data written for this practice question).\nACs — 16% of world population — 28% of world food consumption (by calories)\nLIDCs and EDCs — 84% of world population — 72% of world food consumption (by calories)\n\nUsing Fig. 19 and your own understanding, explain why the consumption of food is uneven across the world.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of a range of physical and human reasons, with good use of Fig. 19 and examples.\nLevel 2 (3–4 marks): Clear explanation of some reasons with some use of Fig. 19.\nLevel 1 (1–2 marks): Basic points; little explanation; may simply describe Fig. 19.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• ACs have 16% of people but 28% of consumption, so consumption per person is much higher\n• wealth: people in ACs can afford more, and more calorie-rich foods (meat, processed food); ACs can import food from around the world\n• poverty in LIDCs limits buying power and investment in farming\n• physical factors: drought, poor soils, pests and climate in parts of Africa and South Asia reduce supply\n• human factors: conflict, poor infrastructure and storage, corruption, debt\n• technology: mechanisation, fertilisers and irrigation in ACs give higher yields\n• trade rules and food waste in ACs` },
      { q: `Section A — Resource Reliance.\nScientists predict that by 2050 average temperatures in East Africa could rise by about 1.5–2 °C, with longer droughts and more intense rainfall events (written for this practice question).\n\nAnalyse how climate change may affect food security in the future.`, marks: 6, command: 'Analyse', markScheme: `Level 3 (5–6 marks): Thorough analysis of a range of effects, positive and negative, linked through chains of reasoning to food security, with examples.\nLevel 2 (3–4 marks): Clear analysis of some effects with some development.\nLevel 1 (1–2 marks): Basic, largely unconnected points.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• higher temperatures increase evaporation and heat stress, lowering yields of staple crops such as maize\n• longer droughts cause crop failures and livestock deaths, especially for rain-fed farmers\n• intense rainfall causes floods and soil erosion\n• pests and diseases may spread to new areas\n• sea-level rise threatens low-lying farmland and freshwater supplies (e.g. salinisation)\n• food prices may rise, hitting the poorest hardest\n• some higher-latitude areas may gain longer growing seasons (e.g. Canada, northern Europe)\n• impact depends on ability to adapt, e.g. irrigation, drought-tolerant crops` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\nFor a named country you have studied, explain how human factors affect its food security.`, marks: 6, command: 'Explain', markScheme: `Level 3 (5–6 marks): Thorough explanation of a range of human factors with accurate, detailed case study knowledge.\nLevel 2 (3–4 marks): Clear explanation of some human factors with some case study detail.\nLevel 1 (1–2 marks): Basic points; little or no case study detail.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. Tanzania):\n• poverty: many small-scale farmers cannot afford fertiliser, improved seed or irrigation\n• rapid population growth (about 37% between 2012 and 2022) increases demand\n• poor rural roads make it hard to get crops to market or food to deficit areas\n• post-harvest losses from poor storage\n• land tenure insecurity / competition for land with large investors\n• government policy: Kilimo Kwanza, fertiliser subsidies, export bans on maize at times of shortage\n• rising global food and fuel prices\n• relative political stability has helped compared with conflict-affected neighbours` },
      { q: `Section A — Resource Reliance.\nIn the UK some salad crops are now grown in vertical hydroponic farms, where plants grow in nutrient-rich water under LED lights in stacked trays inside buildings.\n\nAssess the role of technology in increasing food supply.`, marks: 6, command: 'Assess', markScheme: `Level 3 (5–6 marks): Thorough assessment of a range of technologies, considering benefits and limitations, with examples; a clear, supported judgement.\nLevel 2 (3–4 marks): Clear discussion of some technologies with some evaluation.\nLevel 1 (1–2 marks): Basic description of technology; little assessment.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• the Green Revolution (HYVs, fertilisers, irrigation) greatly increased yields in Asia\n• GM crops, e.g. pest-resistant or drought-tolerant varieties\n• hydroponics / vertical farming: high yields per m², all-year growing, little water, near cities; but high energy and set-up costs, only some crops\n• mechanisation and irrigation increase output per farmer / per hectare\n• limitations: expensive for poor farmers; environmental costs (water, soil, pollution); may increase inequality\n• technology increases supply but does not by itself fix access problems such as poverty, conflict and waste\n• judgement: important, but must be appropriate and affordable` },
      { q: `Section B — Human geography fieldwork.\nGCSE students recorded the food miles of 20 items in one family's weekly shop from a single supermarket. They used the country of origin on each label and an online calculator to estimate the distance. They concluded: 'Most food in the UK travels a very long way, so UK food supply is unsustainable.'\n\nEvaluate the reliability of the students' conclusion.`, marks: 6, command: 'Evaluate', markScheme: `Level 3 (5–6 marks): Thorough evaluation of the reliability of the conclusion, considering several aspects of the method and data, with a clear judgement.\nLevel 2 (3–4 marks): Clear discussion of some strengths and limitations; judgement limited.\nLevel 1 (1–2 marks): Basic comments on the method; little evaluation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• small sample — 20 items from one family and one supermarket cannot represent the whole UK\n• labels give the country, not the farm, so distances are estimates; transport route not known\n• one week only — seasonal variation in imports (e.g. more imported fruit in winter)\n• food miles measure distance, not total environmental impact; UK-grown food in heated greenhouses may have a larger carbon footprint than imported food\n• sustainability also depends on social and economic factors, e.g. income for farmers abroad (Fairtrade)\n• strengths: a clear, repeatable method; secondary data from labels is objective\n• judgement: the conclusion is only partly reliable; more data and other measures are needed` },
      { q: `Section A — Resource Reliance.\nFig. 20 shows results of a survey of households in a village in central Tanzania during a drought year (data written for this practice question).\n68% of households ate fewer than two meals a day in the lean season\n42% of children under five were underweight\n35% of households sold livestock to buy food\n25% of men migrated to towns to look for work\nWoodland near the village was cut down for charcoal to sell\n\nUsing Fig. 20 and your own understanding, examine the impacts of food insecurity.`, marks: 6, command: 'Examine', markScheme: `Level 3 (5–6 marks): Thorough examination of a range of social, economic and environmental impacts, using Fig. 20 well, with links between impacts.\nLevel 2 (3–4 marks): Clear explanation of some impacts with some use of Fig. 20.\nLevel 1 (1–2 marks): Basic points, often copied from Fig. 20.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• health: malnutrition and stunting (42% of under-fives underweight) increase disease and child mortality\n• fewer meals reduce energy to work and children's ability to learn\n• economic: selling livestock (35%) loses assets, making families poorer and less able to cope with the next drought\n• migration (25% of men) splits families; may bring remittances\n• environmental: charcoal production causes deforestation and soil erosion, reducing future yields\n• cycle: food insecurity → poverty → lower investment → further food insecurity\n• wider impacts: rising food prices, social unrest, reliance on food aid` },
      { q: `Section A — Resource Reliance.\n'The growing global demand for resources is causing serious damage to the natural world.'\n\nAssess the extent to which you agree with this statement. Use examples you have studied.`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): Thorough assessment of how far demand for resources damages the natural world, using a range of accurate examples; a clear, well-supported judgement.\nLevel 2 (3–5 marks): Clear discussion with some examples; some evaluation; judgement may be limited.\nLevel 1 (1–2 marks): Basic, one-sided points; few examples; no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• demand is rising with population (8 billion in 2022) and development\n• agree: deforestation for oil palm in Indonesia and cattle and soya in the Amazon; mining pollution; over-fishing; aquifer depletion; dams such as the Julius Nyerere dam in the Selous; fossil fuel use and climate change\n• damage is often long-term or irreversible, e.g. extinction, peat loss\n• disagree: renewable energy, recycling and efficiency reduce damage; sustainable certification (e.g. FSC, MSC); reclamation of mines; protected areas\n• damage varies by place and by how well resources are managed and regulated\n• the scale of damage depends more on consumption per person (mainly in ACs) than on numbers\n• judgement on the extent of agreement` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\n'Large-scale strategies are more effective than small-scale strategies in achieving food security.'\n\nTo what extent do you agree with this statement? Use a country you have studied. [8 marks + 3 marks for SPaG]`, marks: 8, command: 'To what extent', markScheme: `Level 3 (6–8 marks): Thorough evaluation of both large- and small-scale strategies, with detailed, accurate case study knowledge; a clear, well-supported judgement on the extent of agreement.\nLevel 2 (3–5 marks): Clear discussion of both types with some case study detail; judgement may be limited or not fully supported.\nLevel 1 (1–2 marks): Basic, one-sided points; little case study support; no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. Tanzania):\n• large-scale: SAGCOT (2010) — investment in irrigation, processing and transport; potential to raise national output and create jobs; but slow progress, benefits to companies and larger farms, land grabbing risk, may focus on export or cash crops\n• Kilimo Kwanza / fertiliser subsidies — wide reach but costly and not always reaching the poorest\n• small-scale: rainwater harvesting, drip irrigation, hermetic storage bags, co-operatives, Fairtrade — cheap, appropriate, directly help poor households; but limited reach and dependent on NGO funding\n• effectiveness depends on whether the aim is national supply or household access\n• the strategies can complement each other, e.g. outgrower schemes linking smallholders to large investors\n• judgement on the extent of agreement\n\nSPaG:\nHigh performance (3 marks): spelling and punctuation consistently accurate; rules of grammar used with effective control of meaning; wide range of specialist terms used precisely.\nIntermediate performance (2 marks): spelling and punctuation considerable accuracy; general control of meaning; good range of specialist terms.\nThreshold performance (1 mark): reasonable accuracy; meaning not seriously obstructed; limited range of specialist terms.\n0 marks: no response, or response does not relate to the question, or errors severely hinder meaning.` },
      { q: `Section A — Resource Reliance.\nDrought-tolerant and pest-resistant genetically modified (GM) maize varieties have been developed for farmers in Africa. Some governments have approved GM crops; others, such as Tanzania in 2018, have halted trials.\n\nEvaluate the use of GM crops to improve food security in LIDCs.`, marks: 8, command: 'Evaluate', markScheme: `Level 3 (6–8 marks): Thorough evaluation of benefits and drawbacks of GM crops for LIDCs, with examples; a clear, well-supported judgement.\nLevel 2 (3–5 marks): Clear discussion of benefits and/or drawbacks with some development; judgement may be limited.\nLevel 1 (1–2 marks): Basic points; little evaluation.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• benefits: higher and more reliable yields; drought tolerance helps rain-fed farmers; pest resistance reduces losses and pesticide use; biofortified crops (e.g. Golden Rice) can tackle vitamin deficiency\n• drawbacks: expensive patented seed bought each year; dependence on large companies; debt for poor farmers\n• environmental concerns: cross-pollination, loss of crop diversity, resistant pests and weeds\n• public and export-market resistance (e.g. EU consumers); uncertain long-term effects\n• GM does not solve access problems — poverty, poor roads, storage losses, conflict\n• other approaches may be cheaper and more appropriate, e.g. conventional drought-tolerant varieties, irrigation\n• judgement: can help, but only with fair access, regulation and alongside other strategies` },
      { q: `Section A — Resource Reliance.\nCASE STUDY — food security in an LIDC or EDC.\n\n'Physical factors are more important than human factors in causing food insecurity.'\n\nAssess the extent to which this statement is true for a country you have studied.`, marks: 8, command: 'Assess', markScheme: `Level 3 (6–8 marks): Thorough assessment of both physical and human factors, with detailed, accurate case study knowledge and links between factors; a clear, well-supported judgement.\nLevel 2 (3–5 marks): Clear discussion of both types of factor with some case study detail; judgement may be limited.\nLevel 1 (1–2 marks): Basic, one-sided points; little case study support.\n0 marks: No response worthy of credit.\n\nIndicative content (e.g. Tanzania):\n• physical: unreliable rains and drought (especially the central semi-arid zone around Dodoma); floods; fall armyworm and other pests; poor or eroded soils\n• human: poverty and lack of inputs; rapid population growth; poor rural roads and storage; land competition; rising food prices; government policy\n• factors interact: drought hits hardest because most farming is rain-fed and households are poor\n• human factors explain why similar droughts cause less hunger in ACs\n• physical factors vary across the country, e.g. the wetter Southern Highlands produce maize surpluses\n• judgement, e.g. physical factors trigger crises but human factors decide how severe they are` },
      { q: `Section A — Resource Reliance.\nFig. 21 shows global food data (rounded; data written for this practice question).\nWorld population: 8.0 billion (2022); projected 9.7 billion (2050)\nFood produced today is enough to provide about 2 900 kcal per person per day\nAbout one third of food produced is lost or wasted\nAbout 9% of the world population faced hunger in 2023\n\nDiscuss whether the world will be able to feed nine billion people.`, marks: 8, command: 'Discuss', markScheme: `Level 3 (6–8 marks): Thorough discussion of both sides, using Fig. 21 and own understanding, with clear chains of reasoning; a clear, well-supported conclusion.\nLevel 2 (3–5 marks): Clear discussion with some use of Fig. 21; conclusion may be limited.\nLevel 1 (1–2 marks): Basic, one-sided points; Fig. 21 may be copied.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• yes: enough food is already produced (about 2 900 kcal per person, above needs); cutting the one-third loss and waste would add a large supply; technology (GM, hydroponics, irrigation) can raise yields — Boserup's view; falling birth rates slow growth\n• no: hunger already affects about 9% despite enough food — the problem is access and distribution; climate change, water scarcity and soil degradation may cut yields; rising meat demand uses more land and grain; conflict — closer to Malthus's concerns\n• depends on reducing inequality, poverty and waste, and on sustainable intensification\n• conclusion on whether, and under what conditions, nine billion can be fed` },
      { q: `Resource Booklet — improving food security in Dodoma region, Tanzania.\nFig. 22: Dodoma region is in the semi-arid centre of Tanzania. It has one rainy season (December–April) and a long dry season. Most families are small-scale farmers growing maize, sorghum and groundnuts on rain-fed plots of 1–2 hectares. In drought years many households run out of stored food by October (data written for this practice question).\nFig. 23: three options for improving food security in the region.\nOption 1 — A large irrigation scheme: a dam and canals supplying 5 000 hectares of commercial farmland run by an investor, growing rice and vegetables. About 2 000 jobs would be created; some families would be moved off their land.\nOption 2 — Village rainwater harvesting and drip irrigation: tanks, small earth dams and drip kits for 3 000 households, run by an NGO with training for farmers. Low cost per household; depends on rainfall to fill tanks.\nOption 3 — Seed and storage programme: drought-tolerant sorghum and cassava seed, and airtight grain storage bags, sold to farmers at subsidised prices through village co-operatives.\n\nUsing Figs. 22 and 23, and your own understanding, choose which option you think is the best way to improve food security in Dodoma region. Justify your choice.`, marks: 12, command: 'Justify', markScheme: `Level 4 (10–12 marks): Comprehensive, well-reasoned justification of the chosen option, using the resources thoroughly and accurate own understanding of food security; evaluates the rejected options; considers social, economic and environmental factors and short- and long-term sustainability; well-supported conclusion.\nLevel 3 (7–9 marks): Clear justification with good use of resources; some evaluation of other options; conclusion supported.\nLevel 2 (4–6 marks): Some justification, mainly of the chosen option; some use of resources; limited evaluation.\nLevel 1 (1–3 marks): Basic choice with little justification; resources copied.\n0 marks: No response worthy of credit.\nNo option is 'correct'; credit any choice that is well justified.\n\nIndicative content:\n• Option 1: large increase in production and year-round growing; jobs and income; but benefits an investor and workers rather than all households; displacement and loss of land; high cost; water conflicts and environmental impacts; similar concerns to large SAGCOT investments\n• Option 2: targets the dry-season food gap directly; cheap, appropriate technology owned by communities; training builds skills; environmentally sustainable; but may fail in a severe drought; reliant on NGO funding; reaches 3 000 households only\n• Option 3: tackles both crop failure (drought-tolerant crops) and post-harvest losses; works through co-operatives; affordable with subsidies; but subsidies cost the government; cassava and sorghum may be less popular than maize; does not provide water\n• links to the one rainy season, rain-fed farming and food running out by October\n• a combination may be discussed, but one option must be chosen and justified` },
      { q: `Resource Booklet — the Julius Nyerere Hydropower Station, Tanzania.\nFig. 24: the hydro-electric power (HEP) station is on the Rufiji River in southern Tanzania. Its planned capacity is 2 115 MW. Its dam and reservoir are inside the Selous Game Reserve, a protected wildlife area.\nFig. 25: views about the scheme (written for this practice question).\nGovernment official: 'Only about half of our people have electricity. This dam will provide cheap, renewable power for homes, factories and irrigation pumps.'\nConservation group: 'The reservoir floods a huge area of woodland in a World Heritage Site and will harm elephants and other wildlife.'\nFarmer in the Rufiji delta: 'Every year the floods bring fresh silt to our rice fields. If the dam stops the floods, our harvests may fall.'\nBusiness owner in Dar es Salaam: 'Power cuts cost us money every week. A reliable supply would let us expand and employ more people.'\n\nUsing Figs. 24 and 25, and your own understanding, assess whether the benefits of the Julius Nyerere Hydropower Station are greater than its costs.`, marks: 12, command: 'Assess', markScheme: `Level 4 (10–12 marks): Comprehensive assessment of benefits and costs, using the resources thoroughly and accurate own understanding of energy resources and their impact on the natural world; considers different groups, scales and timescales; well-supported conclusion.\nLevel 3 (7–9 marks): Clear assessment of benefits and costs with good use of resources; conclusion supported.\nLevel 2 (4–6 marks): Some discussion of benefits and/or costs; some use of resources; limited assessment.\nLevel 1 (1–3 marks): Basic points; resources copied; no judgement.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• benefits: large increase in electricity supply (2 115 MW) for a country where many have no access; renewable and lower carbon than fossil fuels; reliable power for industry and jobs; could power irrigation and food processing, helping food security; flood control\n• costs: loss of woodland and habitat in a protected area; wildlife disturbance and fragmentation; trapping of sediment reduces fertile silt and floods for delta farmers, affecting rice yields, fisheries and mangroves; high construction cost and debt\n• risks: drought and climate change may lower reservoir levels and output\n• benefits are national and economic; costs are local and environmental — winners and losers\n• alternative energy options (solar, wind, geothermal) could be compared\n• judgement on whether benefits outweigh costs, and for whom` },
      { q: `Resource Booklet — population and food.\nFig. 26: global data (rounded; data written for this practice question).\nWorld population: 3.07 billion (1961); 7.8 billion (2020)\nWorld cereal production: 880 million tonnes (1961); 3 000 million tonnes (2020)\nCereal production per person: about 287 kg (1961); about 385 kg (2020)\nPercentage of world population undernourished: about 12% (2005); about 8% (2019); about 9% (2023)\nFig. 27: summary of two theories.\nMalthus (1798): population grows geometrically and food supply arithmetically, so population will outstrip food, leading to famine, disease and war.\nBoserup (1965): population pressure leads to new farming techniques and technology, so food supply rises to meet demand.\n\nUsing Figs. 26 and 27, and your own understanding, assess whether the evidence supports the views of Malthus or Boserup more strongly.`, marks: 12, command: 'Assess', markScheme: `Level 4 (10–12 marks): Comprehensive assessment of both theories, using the data in Fig. 26 accurately (e.g. calculations), with detailed own understanding and examples; considers different scales and the limits of the data; well-supported conclusion.\nLevel 3 (7–9 marks): Clear assessment of both theories with good use of the resources; conclusion supported.\nLevel 2 (4–6 marks): Some discussion of the theories with some use of data; limited assessment.\nLevel 1 (1–3 marks): Basic description of the theories; data copied.\n0 marks: No response worthy of credit.\n\nIndicative content:\n• population rose by about 154% (3.07 to 7.8 billion) while cereal production rose by about 241% (880 to 3 000 million tonnes), so food grew faster than population — supports Boserup\n• cereal per person rose from about 287 kg to about 385 kg\n• Green Revolution, irrigation, GM crops and mechanisation as examples of Boserup's innovation; Machakos, Kenya\n• undernourishment fell from about 12% to about 8% but rose again to about 9% in 2023 — hunger persists; conflict, climate shocks and price rises\n• local famines (e.g. Somalia 2011, Sudan) and resource limits (soil degradation, water scarcity, climate change) give some support to Malthus or neo-Malthusian views\n• Malthus did not foresee technology, trade or falling birth rates\n• global averages hide inequality; hunger is often about access, not total supply\n• judgement: evidence at global scale supports Boserup more strongly, but Malthusian concerns may apply locally or in the future` }
    ]
  },
  '3.1': {
    name: 'Geographical Exploration and Fieldwork',
    questions: [
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 2 compares Kenya with the UK (data written for this practice question, based on recent estimates):\nIndicator | Kenya | UK\nTotal population (millions) | 54 | 67\nGNI per capita (US$) | 2 100 | 48 000\nLife expectancy (years) | 62 | 81\nUrban population (%) | 29 | 84\nDoctors per 10 000 people | 2 | 32\n\nLook at Fig. 2. Calculate the difference in total population between Kenya and the UK.`, marks: 1, command: 'Calculate', markScheme: `13 million (1).\nAccept 13 or 13 000 000. Units not required if 13 is given.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 5 shows the sources of Kenya's electricity generation (data written for this practice question, based on the pattern in recent years): geothermal 46%; hydro-electric power (HEP) 25%; wind 16%; oil-fired thermal power stations 10%; solar 3%.\n\nIdentify the largest source of electricity in Kenya.`, marks: 1, command: 'Identify', markScheme: `Geothermal (1).` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 5 shows the sources of Kenya's electricity generation (data written for this practice question, based on the pattern in recent years): geothermal 46%; hydro-electric power (HEP) 25%; wind 16%; oil-fired thermal power stations 10%; solar 3%.\n\nUsing Fig. 5, calculate the total percentage of Kenya's electricity generated from renewable sources.`, marks: 1, command: 'Calculate', markScheme: `90% (1).\n(46 + 25 + 16 + 3 = 90.) Do not credit 100% or 80%.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 7 shows the number of foreign visitors arriving in Iceland through Keflavík International Airport (millions, values rounded):\nYear | Visitors (millions)\n2010 | 0.49\n2014 | 1.0\n2018 | 2.3\n2020 | 0.5\n2022 | 1.7\n\nIdentify the year with the highest number of visitors shown in Fig. 7.`, marks: 1, command: 'Identify', markScheme: `2018 (1).` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 10 is a climate graph for Dhaka, the capital of Bangladesh. Mean monthly rainfall (mm) is (data written for this practice question, based on the real pattern): Jan 8; Feb 20; Mar 55; Apr 135; May 280; Jun 340; Jul 400; Aug 330; Sep 300; Oct 170; Nov 30; Dec 10.\n\nIdentify the wettest month in Dhaka.`, marks: 1, command: 'Identify', markScheme: `July (1).\nAccept Jul.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students investigated the hypothesis 'River velocity increases with distance downstream' on a small river in northern England. At each site they timed how long a float took to travel 10 m.\n\nSuggest one other piece of equipment the students could use to measure river velocity more accurately.`, marks: 1, command: 'Suggest', markScheme: `1 mark for one valid piece of equipment, e.g.:\n• a flow meter / impeller / velocity meter\n• a digital flow probe.\nDo not credit a stopwatch, tape measure or float (already used).` },
      { q: `Section B — Human geography fieldwork.\nGCSE students carried out a questionnaire in a town centre to find out residents' views about a new shopping development. They stood outside the library and asked every tenth person who walked past.\n\nIdentify the type of sampling the students used.`, marks: 1, command: 'Identify', markScheme: `Systematic sampling (1).` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students timed how long an orange took to float 10 m downstream at site A on a river. They repeated the test three times: 25.0 seconds, 22.5 seconds and 27.5 seconds (data written for this practice question).\n\nCalculate the mean speed of the river at site A in metres per second. (Speed = distance ÷ time.)`, marks: 1, command: 'Calculate', markScheme: `0.4 m/s (1).\n(Mean time = 75.0 ÷ 3 = 25.0 s; 10 ÷ 25.0 = 0.4.) Accept 0.40.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 1 (map of Kenya, scale bar 0–200 km): Kenya is in East Africa and the equator passes through the centre of the country. It borders Ethiopia to the north, Somalia to the north-east, Tanzania to the south, Uganda to the west and South Sudan to the north-west, and has a coastline on the Indian Ocean to the south-east. The capital, Nairobi, is in the south-central highlands about 440 km north-west of the port of Mombasa. Lake Victoria is on the western border.\n\nLook at Fig. 1. Describe the location of Kenya.`, marks: 2, command: 'Describe', markScheme: `1 mark per valid locational point, up to 2 marks, e.g.:\n• in East Africa (1)\n• on / crossed by the equator (1)\n• has a coastline on the Indian Ocean / to the south-east (1)\n• bordered by Ethiopia to the north / Tanzania to the south / Uganda to the west / Somalia to the north-east (1)\n• borders Lake Victoria in the west (1).\nMax 1 for 'in Africa' with no further detail. Answers must be about Kenya, not Nairobi.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 3 shows the population of Nairobi at each national census (millions, rounded):\nYear | Population (millions)\n1969 | 0.5\n1979 | 0.8\n1989 | 1.3\n1999 | 2.1\n2009 | 3.1\n2019 | 4.4\n\nCalculate the percentage change in the population of Nairobi between 2009 and 2019. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (4.4 − 3.1) ÷ 3.1 × 100 or 1.3 ÷ 3.1 × 100.\n1 mark for the answer: 41.9% (accept +41.9%).\nCorrect answer with no working = 1 mark only.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 3 shows the population of Nairobi at each national census (millions, rounded):\nYear | Population (millions)\n1969 | 0.5\n1979 | 0.8\n1989 | 1.3\n1999 | 2.1\n2009 | 3.1\n2019 | 4.4\n\nCalculate how many times larger the population of Nairobi was in 2019 than in 1969. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 4.4 ÷ 0.5.\n1 mark for the answer: 8.8 times.\nCorrect answer with no working = 1 mark only.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 3 shows that the population of Nairobi grew from about 0.5 million in 1969 to about 4.4 million in 2019. Only 29% of Kenya's population lives in urban areas.\n\nExplain one reason why many people migrate from rural areas of Kenya to Nairobi.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid reason, 1 mark for development/explanation.\nE.g.:\n• pull of jobs (1) in offices, services, manufacturing or the informal sector, which pay more than subsistence farming (1)\n• push of drought / crop failure in rural areas (1) leaving families with no income or food (1)\n• better access to schools / healthcare in the city (1) so people hope for a higher quality of life (1).\nReasons may be push or pull. Max 1 for a list of reasons with no development.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 2 compares Kenya with the UK (data written for this practice question, based on recent estimates):\nIndicator | Kenya | UK\nTotal population (millions) | 54 | 67\nGNI per capita (US$) | 2 100 | 48 000\nLife expectancy (years) | 62 | 81\nUrban population (%) | 29 | 84\nDoctors per 10 000 people | 2 | 32\n\nUsing Fig. 2, describe two differences in development between Kenya and the UK.`, marks: 2, command: 'Describe', markScheme: `1 mark for each valid difference supported by data from Fig. 2, up to 2 marks, e.g.:\n• GNI per capita is much lower in Kenya (US$2 100 compared with US$48 000) (1)\n• life expectancy is 19 years lower in Kenya (62 compared with 81) (1)\n• Kenya has far fewer doctors (2 per 10 000 compared with 32) (1)\n• a much smaller share of Kenya's population is urban (29% compared with 84%) (1).\nDo not credit total population as a development difference. Differences must be comparative.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 7 shows the number of foreign visitors arriving in Iceland through Keflavík International Airport (millions, values rounded):\nYear | Visitors (millions)\n2010 | 0.49\n2014 | 1.0\n2018 | 2.3\n2020 | 0.5\n2022 | 1.7\n\nCalculate the percentage increase in visitors between 2010 and 2018. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (2.3 − 0.49) ÷ 0.49 × 100 or 1.81 ÷ 0.49 × 100.\n1 mark for the answer: 369.4%.\nCorrect answer with no working = 1 mark only.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 6: Iceland is an island country in the North Atlantic Ocean, just south of the Arctic Circle. It had a population of about 360 000 in 2018, about two-thirds of whom live in and around the capital, Reykjavík. Fig. 7 shows that about 2.3 million foreign visitors arrived in Iceland in 2018.\n\nCalculate the number of foreign visitors per resident of Iceland in 2018. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 2 300 000 ÷ 360 000 (or 2.3 ÷ 0.36).\n1 mark for the answer: 6.4 visitors per resident.\nCorrect answer with no working = 1 mark only.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 6 (map of Iceland): the Mid-Atlantic Ridge runs across Iceland from the south-west to the north-east. Active volcanoes, including Eyjafjallajökull, Hekla and the volcanoes of the Reykjanes peninsula, are found along this zone. The North American Plate is to the west and the Eurasian Plate is to the east.\n\nExplain one reason why Iceland has many active volcanoes.`, marks: 2, command: 'Explain', markScheme: `1 mark for the reason, 1 mark for development.\nE.g.:\n• Iceland lies on a constructive (divergent) plate margin / the Mid-Atlantic Ridge (1) where the North American and Eurasian Plates move apart, so magma rises to fill the gap (1)\n• Iceland lies over a hotspot / mantle plume (1) which supplies extra magma to the surface (1).\nDo not credit 'the plates collide'.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 9: Bangladesh is a country in South Asia. It has a population of about 170 million and an area of about 148 000 km².\n\nCalculate the population density of Bangladesh. Give your answer to the nearest whole number. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: 170 000 000 ÷ 148 000.\n1 mark for the answer: 1149 people per km².\nCorrect answer with no working = 1 mark only. Accept 1148.6 for the working mark only if not rounded.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 10 is a climate graph for Dhaka. Mean monthly rainfall (mm) is (data written for this practice question, based on the real pattern): Jan 8; Feb 20; Mar 55; Apr 135; May 280; Jun 340; Jul 400; Aug 330; Sep 300; Oct 170; Nov 30; Dec 10. The total annual rainfall is 2078 mm.\n\nCalculate the percentage of Dhaka's annual rainfall that falls in the monsoon months of June to September. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (340 + 400 + 330 + 300) ÷ 2078 × 100 or 1370 ÷ 2078 × 100.\n1 mark for the answer: 65.9%.\nCorrect answer with no working = 1 mark only.` },
      { q: `Section B — Physical geography fieldwork.\nGCSE students measured a river channel at site B (data written for this practice question). The channel was 4.2 m wide. They measured the depth at five equally spaced points across the channel: 0.18 m, 0.32 m, 0.40 m, 0.26 m and 0.12 m.\n\nCalculate the cross-sectional area of the river channel at site B. (Cross-sectional area = width × mean depth.) Give your answer to two decimal places. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: mean depth = 1.28 ÷ 5 = 0.256 m, then 4.2 × 0.256.\n1 mark for the answer: 1.08 m².\nCorrect answer with no working = 1 mark only.` },
      { q: `Section B — Physical geography fieldwork.\nGCSE students measured the long axis of 11 pebbles at site C on a river bed. Their results, in order, were (mm, data written for this practice question):\n12, 18, 23, 25, 31, 34, 38, 42, 47, 55, 61\n\nCalculate the interquartile range of the pebble sizes. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: lower quartile = 3rd value = 23 mm and upper quartile = 9th value = 47 mm, then 47 − 23.\n1 mark for the answer: 24 mm.\nCorrect answer with no working = 1 mark only.` },
      { q: `Section B — Human geography fieldwork.\nGCSE students investigated how the quality of the environment changes with distance from the centre of a town in the Midlands. They counted pedestrians for 10 minutes at five sites along a transect (data written for this practice question):\nSite | Distance from centre (m) | Pedestrians in 10 minutes\n1 | 0 | 84\n2 | 250 | 112\n3 | 500 | 47\n4 | 750 | 23\n5 | 1000 | 9\n\nCalculate the percentage decrease in pedestrians between site 1 and site 5. Give your answer to one decimal place. You must show your working.`, marks: 2, command: 'Calculate', markScheme: `1 mark for working: (84 − 9) ÷ 84 × 100 or 75 ÷ 84 × 100.\n1 mark for the answer: 89.3% (accept −89.3%).\nCorrect answer with no working = 1 mark only.` },
      { q: `Section B — Physical geography fieldwork.\nGCSE students measured 11 pebbles at each site along a river. At each site, one student picked up the pebbles that were nearest to the bank and easiest to reach.\n\nSuggest one way the students could make their pebble data more reliable.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a valid improvement, 1 mark for explaining how it improves reliability.\nE.g.:\n• use random sampling, e.g. random number tables to pick points on a tape across the channel (1) so pebbles are not chosen because they are easy to reach / sampling bias is removed (1)\n• measure a larger sample, e.g. 30 pebbles per site (1) so that anomalies have less effect on the mean / median (1)\n• use callipers / a pebbleometer rather than a ruler (1) so measurements are more precise and consistent between students (1)\n• use the same student / same method at every site (1) so results are comparable (1).` },
      { q: `Section B — Physical geography fieldwork.\nGCSE students collected data in a river in early spring. At one site the water was knee-deep and fast-flowing, and the river bed was covered in slippery, moss-covered stones.\n\nExplain one risk to the students at this site and how it could be reduced.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid risk, 1 mark for a linked way to reduce it.\nE.g.:\n• slipping on moss-covered stones and falling into the water (1) — wear boots/waders with grip, move slowly and hold hands or a ranging pole for balance (1)\n• being swept away by the fast current (1) — only enter where water is below knee height, work in groups, have a throw line / check weather and river levels first (1)\n• cold water causing hypothermia (1) — wear waders and warm clothing, limit time in the water (1)\n• water-borne disease, e.g. Weil's disease (1) — cover cuts, wear gloves, wash hands before eating (1).` },
      { q: `Section B — Human geography fieldwork.\nGCSE students used a bipolar environmental quality survey at five sites in a town. At each site they scored six features, such as litter, noise and the condition of buildings, on a scale from −3 (very poor) to +3 (very good).\n\nSuggest one advantage of using a bipolar survey to collect data about environmental quality.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a valid advantage, 1 mark for development.\nE.g.:\n• it turns opinions into numbers / quantitative data (1) so totals can be calculated and sites compared or graphed (1)\n• it is quick and cheap to complete (1) so many sites can be surveyed in the time available (1)\n• every site is judged using the same criteria (1) making results more comparable (1).` },
      { q: `Section B — Human geography fieldwork.\nGCSE students investigated views about a new park in an area where 60% of residents are under 40 and 40% are aged 40 or over. They decided to interview 30 people under 40 and 20 people aged 40 or over.\n\nExplain why the students chose this sampling method.`, marks: 2, command: 'Explain', markScheme: `1 mark for identifying stratified sampling / sample in proportion to the population, 1 mark for explanation.\nE.g.:\n• it is stratified sampling (1) so each age group is represented in proportion to the local population (60:40) (1)\n• so the views of both younger and older residents are included (1) and the results are more representative / less biased towards one group (1).` },
      { q: `Section B — Human geography fieldwork.\nGCSE students counted pedestrians for 10 minutes at five sites along a transect from a town centre. Their counts were 84, 112, 47, 23 and 9 at 0 m, 250 m, 500 m, 750 m and 1000 m from the centre. They presented the data in a pie chart.\n\nSuggest a more effective way of presenting these data. Justify your choice.`, marks: 2, command: 'Suggest', markScheme: `1 mark for a suitable technique, 1 mark for justification.\nE.g.:\n• a bar chart of pedestrians at each site (1) because it shows the change along the transect / sites can be compared easily (1)\n• a line graph or scatter graph of pedestrians against distance from the centre (1) because distance is continuous data and the trend / relationship can be seen (1)\n• proportional symbols on a base map of the transect (1) because it shows the location of each site as well as the count (1).\nThe justification must be linked to the data. Do not credit a pie chart.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry.\n\nIdentify one source of secondary data you used in your human geography enquiry and explain how it helped your enquiry.`, marks: 2, command: 'Explain', markScheme: `1 mark for a valid secondary source, 1 mark for explaining how it helped this enquiry.\nE.g.:\n• census data / ONS neighbourhood statistics (1) showed the age structure or deprivation of the area, which helped explain differences in residents' views (1)\n• Index of Multiple Deprivation (IMD) data (1) allowed comparison with our environmental quality scores (1)\n• historical maps / old photographs (1) showed how land use had changed over time (1)\n• crime statistics from a police website (1) were compared with perceptions of safety from our questionnaire (1).\nThe source must be secondary (collected by someone else). Credit must be linked to a human enquiry.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 6: Konza Technopolis is a planned 'smart city' being built about 60 km south-east of Nairobi as part of Kenya's Vision 2030. Its plans include solar power, rainwater harvesting, public transport and technology businesses, to reduce pressure on Nairobi.\n\nFig. 6 states that Konza Technopolis is intended to be a sustainable city. Explain what is meant by the term 'sustainable development'.`, marks: 3, command: 'Explain', markScheme: `1 mark for a basic definition; up to 3 marks for a developed explanation.\n• development that meets the needs of people today (1)\n• without compromising the ability of future generations to meet their own needs (1)\n• balancing / considering economic, social and environmental factors (1)\n• e.g. using renewable resources such as solar power so they are not used up (1).\nMax 2 without reference to future generations or to balancing the three dimensions.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 8: almost all of Iceland's electricity comes from renewable sources — about 70% from HEP and about 30% from geothermal energy — and about 90% of homes are heated using geothermal hot water.\n\nExplain why geothermal energy is widely used in Iceland.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for a developed explanation, e.g.:\n• Iceland lies on the Mid-Atlantic Ridge / a constructive plate margin and a hotspot (1)\n• so magma is close to the surface and heats rocks and groundwater (1)\n• hot water and steam can be piped directly to homes or used to drive turbines (1)\n• Iceland has few fossil fuel resources, so importing oil or coal would be expensive (1)\n• the cold climate means there is high demand for heating (1)\n• it is a renewable, low-carbon source of energy (1).\nMax 1 for 'there are lots of volcanoes' without explanation.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 9 (map of Bangladesh): Bangladesh lies on the delta of three large rivers, the Ganges (Padma), Brahmaputra (Jamuna) and Meghna, which rise in the Himalayas. Most of the country is less than 10 m above sea level. The south of the country borders the Bay of Bengal, where tropical cyclones form.\n\nUsing Fig. 9, explain why Bangladesh is at risk from flooding.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed points, using Fig. 9 and own understanding, e.g.:\n• most land is less than 10 m above sea level / it is a low-lying delta (1) so river and sea water easily spread over the land (1)\n• three large rivers meet in Bangladesh (1) and snowmelt from the Himalayas in spring/summer adds to their discharge (1)\n• heavy monsoon rainfall from June to September (1)\n• tropical cyclones from the Bay of Bengal cause storm surges along the coast (1)\n• sea level rise due to climate change increases the risk (1)\n• deforestation in the Himalayas increases run-off into the rivers (1).\nMax 2 if no use of Fig. 9.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students measured river velocity by timing an orange as it floated 10 m downstream. They released the orange from the middle of the channel and timed it with a stopwatch on a mobile phone. Each measurement was repeated three times.\n\nExplain why the students' velocity results may not be accurate.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed points, e.g.:\n• human reaction time when starting and stopping the stopwatch (1) creates errors, especially over a short 10 m distance (1)\n• the orange may get caught on rocks / vegetation / in eddies (1) making the time longer than the true flow (1)\n• the orange floats on the surface (1) and is affected by wind, so only surface velocity is measured, not the velocity of the whole channel (1)\n• velocity varies across the channel, so one release point in the middle is not representative (1)\n• only three repeats is a small sample (1).` },
      { q: `Section B — Physical geography fieldwork.\nYou have carried out a physical geography fieldwork enquiry.\n\nExplain why the location of your physical geography fieldwork was suitable for your enquiry.`, marks: 3, command: 'Explain', markScheme: `Up to 3 marks for developed points that link the site to the enquiry question, e.g.:\n• the river had a clear upstream to downstream gradient with several accessible sites (1) so changes in the channel could be measured along its course (1)\n• the coast had groynes / a clear direction of longshore drift (1) so we could compare beach material on either side (1)\n• it was safe, e.g. shallow water / a gently sloping beach / public footpaths (1)\n• it was close to school / easy to access by coach, so data could be collected in one day (1)\n• secondary data was available for the site, e.g. Environment Agency river levels (1).\nMax 1 for general points not linked to the student's own enquiry.` },
      { q: `Section B — Human geography fieldwork.\nGCSE students counted pedestrians for 10 minutes at five sites along a transect from a town centre (data written for this practice question):\nSite | Distance from centre (m) | Pedestrians in 10 minutes\n1 | 0 | 84\n2 | 250 | 112\n3 | 500 | 47\n4 | 750 | 23\n5 | 1000 | 9\n\nDescribe the pattern of pedestrian counts shown in the table.`, marks: 3, command: 'Describe', markScheme: `Up to 3 marks, e.g.:\n• overall, pedestrian counts decrease with distance from the town centre (1)\n• from 84 at the centre to 9 at 1000 m (1)\n• the highest count is at site 2 / 250 m (112), not the centre (1) — an anomaly to the overall pattern (1)\n• the decrease is steepest between 250 m and 500 m (112 to 47) (1).\nMax 2 if no data are used.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry.\n\nExplain one limitation of using a questionnaire to collect data in your human geography enquiry.`, marks: 3, command: 'Explain', markScheme: `1 mark for identifying a limitation, up to 2 further marks for development linked to the student's enquiry.\nE.g.:\n• sampling bias (1) — we surveyed on a weekday morning so most people were retired or shoppers and workers were under-represented (1), so the views may not represent the whole community (1)\n• people may not answer honestly / give the answer they think is wanted (1), e.g. on questions about crime or income (1), reducing the accuracy of the results (1)\n• small sample size (1) — only 30 people answered in the time available (1), so the results may not be reliable (1)\n• poorly worded / leading questions (1) can influence answers (1).` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 4 (photograph): a view across Kibera, an informal settlement about 6 km south-west of Nairobi's city centre. Single-storey homes made of mud walls and corrugated iron roofs are packed tightly together with narrow dirt paths between them. A railway line runs through the settlement and people walk along it. Plastic rubbish lies in an open drainage channel. Overhead electricity wires are strung between houses. In the background, the high-rise office buildings of central Nairobi can be seen.\n\nUsing Fig. 4, describe the challenges of living in Kibera.`, marks: 4, command: 'Describe', markScheme: `1 mark per valid challenge from Fig. 4, with up to 2 marks for a developed point, max 4.\nE.g.:\n• homes are built of mud and corrugated iron (1) so they are poor quality and may not withstand heavy rain (1)\n• open drainage channels full of rubbish (1) increase the risk of disease such as cholera / flooding (1)\n• houses are very densely packed (1) increasing the risk of fire spreading (1)\n• narrow dirt paths (1) make access difficult for emergency services (1)\n• people walk along the railway line (1), which is dangerous (1)\n• informal electricity wires (1) risk electrocution / fire (1)\n• lack of waste collection / services (1).\nMust be based on Fig. 4. Max 2 for a list without development.` },
      { q: `Section B — Physical geography fieldwork.\nYou have carried out a physical geography fieldwork enquiry.\n\nExplain how a geographical theory or model helped you to plan your physical geography enquiry.`, marks: 4, command: 'Explain', markScheme: `Up to 4 marks for a developed explanation linked to the student's own enquiry.\n• Names an appropriate theory / model, e.g. the Bradshaw model (rivers), longshore drift, the Hjulström curve, or the process of erosion at a meander (1)\n• States what the model predicts, e.g. width, depth and velocity increase downstream while pebble size decreases (1)\n• Explains how this was used to form a hypothesis / enquiry question, e.g. 'Does the River X follow the Bradshaw model?' (1)\n• Explains how it guided the choice of data, e.g. measuring width, depth, velocity and pebble size at sites from upstream to downstream (1)\n• Explains how it gave something to compare results with in the conclusion (1).\nMax 2 if theory is not linked to the student's own enquiry.` },
      { q: `Section B — Physical geography fieldwork.\nSome GCSE students investigated the hypothesis 'River velocity increases with distance downstream' on a small river. They timed a float over 10 m, three times at each site, and calculated the mean velocity (data written for this practice question):\nSite | Distance from source (km) | Mean time (s) | Mean velocity (m/s)\nA | 2 | 25.0 | 0.40\nB | 5 | 13.3 | 0.75\nC | 8 | 16.0 | 0.63\n\nUsing the data, explain how far the results support the hypothesis.`, marks: 4, command: 'Explain', markScheme: `Up to 4 marks, e.g.:\n• partly support the hypothesis (1)\n• velocity increases from 0.40 m/s at site A to 0.75 m/s at site B / velocity at site C (0.63 m/s) is still higher than at site A (1)\n• but velocity falls between site B and site C (from 0.75 to 0.63 m/s), so the increase is not continuous (1)\n• possible reason for site C: e.g. vegetation / large boulders / a pool or meander at site C increasing friction, or measurement error with the float (1)\n• only three sites is too few to judge the pattern reliably (1).\nMax 2 if no data are used. A clear judgement is needed for full marks.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 5 shows the sources of Kenya's electricity generation (data written for this practice question, based on the pattern in recent years): geothermal 46%; hydro-electric power (HEP) 25%; wind 16%; oil-fired thermal power stations 10%; solar 3%.\nFig. 8: the Olkaria geothermal power stations are in the Rift Valley near Lake Naivasha. The Lake Turkana Wind Power project in northern Kenya has 365 turbines and opened in 2019. Many rural homes not connected to the national grid now use small solar panels to charge phones and power lights.\n\nUsing Figs. 5 and 8 and your own understanding, examine how renewable energy can help Kenya to develop.`, marks: 6, command: 'Examine', markScheme: `Levels of response (AO2 3, AO3 3).\nLevel 3 (5–6 marks): Thorough understanding of how renewable energy links to development. Makes good use of Figs. 5 and 8. Thorough examination of a range of benefits, and perhaps limitations, leading to a well-developed conclusion.\nLevel 2 (3–4 marks): Reasonable understanding. Some use of the resources. Sound examination, with some developed points.\nLevel 1 (1–2 marks): Basic understanding; mainly lifted from the resources. Limited examination.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• 90% of electricity is from renewable sources, so Kenya spends less on imported oil, saving money for schools and healthcare\n• reliable electricity attracts manufacturing and foreign investment (TNCs), creating jobs and multiplier effects\n• off-grid solar brings lighting to rural homes, so children can study at night and businesses (e.g. phone charging, M-Pesa agents) can operate\n• geothermal and wind are not affected by drought, unlike HEP (25%), so supply is more secure\n• low-carbon energy reduces emissions and air pollution, supporting sustainable development\n• limitations: high initial cost and dependence on foreign loans/investors; Lake Turkana project needed long transmission lines; benefits may not reach the poorest rural areas; land conflicts with local communities.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 9: Kenya's links with the wider world:\n• Cut flowers grown around Lake Naivasha are flown to Europe overnight; the UK and the Netherlands are major buyers.\n• Over 1 million international tourists visit each year, many on safari in the Maasai Mara.\n• The mobile money service M-Pesa, launched in 2007, is used by most adults in Kenya.\n• A new standard gauge railway between Mombasa and Nairobi, opened in 2017, was mainly funded by loans from China.\n\nUsing Fig. 9 and your own understanding, explain how Kenya's links with other countries are affecting its development.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 2, AO2 2, AO3 2).\nLevel 3 (5–6 marks): Thorough explanation of a range of positive and negative effects of global links on Kenya's development. Makes good use of Fig. 9 and own understanding with clear links to development.\nLevel 2 (3–4 marks): Reasonable explanation with some use of Fig. 9; some links to development.\nLevel 1 (1–2 marks): Basic explanation; mainly lifted from Fig. 9.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• flower exports earn foreign currency and create jobs, but wages may be low and water use may lower Lake Naivasha\n• tourism provides income, jobs and investment in infrastructure; but is vulnerable to global shocks (e.g. COVID-19) and leakage of profits to foreign companies\n• M-Pesa allows people to send money / receive remittances, start businesses and save safely, increasing financial inclusion\n• the railway cuts journey times for goods from the port, supporting trade, but Chinese loans increase national debt\n• overall, global links help economic growth but can create dependency and uneven benefits.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 7 shows the number of foreign visitors to Iceland rose from about 0.49 million in 2010 to about 2.3 million in 2018.\nFig. 8: views about tourism in Iceland:\n• Hotel owner, Reykjavík: 'Tourism is now one of Iceland's biggest earners and it helped us recover after the banking crisis of 2008.'\n• Farmer, south Iceland: 'Visitors walk across fragile moss and leave tracks that take decades to recover.'\n• Reykjavík resident: 'Many flats in the city centre are now holiday rentals, so rents have gone up.'\n• Tour guide: 'I earn a good income guiding visitors to glaciers and waterfalls.'\n\nUsing Figs. 7 and 8 and your own understanding, assess the impacts of the growth of tourism on Iceland.`, marks: 6, command: 'Assess', markScheme: `Levels of response (AO2 3, AO3 3).\nLevel 3 (5–6 marks): Thorough understanding of a range of economic, social and environmental impacts. Makes good use of Figs. 7 and 8. Thorough assessment of the relative importance of the impacts, leading to a substantiated judgement.\nLevel 2 (3–4 marks): Reasonable understanding of impacts. Some use of the resources. Sound assessment with a partial judgement.\nLevel 1 (1–2 marks): Basic understanding; mainly lifted from resources; little or no assessment.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• positive economic: income, jobs (tour guides, hotels), helped recovery after 2008 crash, multiplier effect in rural areas\n• negative social: higher rents and housing shortages in Reykjavík; overcrowding at popular sites\n• negative environmental: erosion of fragile moss and vegetation; litter; emissions from flights and hire cars\n• economic risk: dependence on tourism shown by the fall in visitors in 2020\n• judgement: e.g. benefits are large and national, but environmental damage and housing pressure are concentrated in particular places and need management.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 10: In April 2010 the eruption of Eyjafjallajökull in southern Iceland produced a large ash cloud. About 800 people were evacuated from nearby farms and there were no deaths, but more than 100 000 flights across Europe were cancelled. Iceland has a network of seismometers and GPS stations monitoring its volcanoes, and an emergency text-message warning system.\n\nUsing Fig. 10 and your own understanding, explain why volcanic eruptions in Iceland usually cause few deaths.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 2, AO2 4).\nLevel 3 (5–6 marks): Thorough explanation of a range of factors, both physical and human, with good use of Fig. 10 and own understanding.\nLevel 2 (3–4 marks): Reasonable explanation of some factors, with some use of Fig. 10.\nLevel 1 (1–2 marks): Basic explanation; mainly lifted from Fig. 10.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• monitoring (seismometers, GPS, gas readings) allows eruptions to be predicted and people evacuated in time\n• emergency text warnings and practised evacuation plans\n• low population density — about 360 000 people, mostly in and around Reykjavík, far from most volcanoes\n• constructive margin eruptions are often effusive with basaltic lava rather than very explosive\n• Iceland is an advanced country (high income) able to fund emergency services, flood defences against glacial floods (jökulhlaups) and rebuilding\n• comparison: e.g. deaths are higher where monitoring is limited and people live close to volcanoes, such as Nyiragongo (DR Congo, 2021).` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 11: Dhaka, the capital of Bangladesh, has over 20 million people in its wider urban area and is one of the fastest-growing megacities in the world. The garment industry employs about 4 million people in Bangladesh, many of them women who have migrated from rural areas. In 2013 the Rana Plaza garment factory building collapsed, killing more than 1100 workers. Traffic congestion in Dhaka is severe and many people live in informal settlements built on land at risk of flooding.\n\nUsing Fig. 11 and your own understanding, examine the challenges created by rapid urban growth in Dhaka.`, marks: 6, command: 'Examine', markScheme: `Levels of response (AO2 3, AO3 3).\nLevel 3 (5–6 marks): Thorough understanding of a range of social, economic and environmental challenges. Makes good use of Fig. 11 and own understanding. Thorough examination, e.g. of which challenges are most serious or how they are linked, leading to a well-developed conclusion.\nLevel 2 (3–4 marks): Reasonable understanding of some challenges. Some use of Fig. 11; sound examination.\nLevel 1 (1–2 marks): Basic understanding; mainly lifted from Fig. 11.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• housing shortages leading to informal settlements on floodplains, increasing exposure to flooding\n• poor working conditions and weak building regulations, shown by Rana Plaza\n• traffic congestion wasting time and causing air pollution\n• pressure on water supply, sanitation and waste collection, increasing disease\n• pressure on schools and healthcare\n• opportunities as well as challenges: garment jobs give women income and independence; the city drives national economic growth\n• conclusion: e.g. challenges are linked to the speed of growth outpacing infrastructure and regulation.` },
      { q: `Section B — Physical geography fieldwork.\nYou have carried out a physical geography fieldwork enquiry.\n\nEvaluate the effectiveness of the data presentation techniques you used in your physical geography enquiry.`, marks: 6, command: 'Evaluate', markScheme: `Levels of response (AO3 3, AO4 3).\nLevel 3 (5–6 marks): Thorough evaluation of two or more techniques used in the student's own enquiry, considering strengths and limitations, with a clear judgement about their effectiveness for showing patterns and answering the enquiry question.\nLevel 2 (3–4 marks): Reasonable evaluation of at least one technique; some strengths and limitations; judgement partly supported.\nLevel 1 (1–2 marks): Basic description of techniques; little or no evaluation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• cross-sections drawn to scale showed changes in channel shape downstream, but were time-consuming and vertical exaggeration could mislead\n• scatter graph of velocity against distance downstream with a line of best fit showed the strength of the relationship and anomalies\n• proportional symbols / located bar charts on a map showed where data were collected\n• pie charts or bar charts of pebble roundness (Powers scale) were clear but did not show change along the river\n• judgement: e.g. scatter graphs were most effective because they directly tested the hypothesis.\nCredit must refer to the student's own enquiry; generic answers max Level 1.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry.\n\nJustify the sampling strategy you used to collect primary data in your human geography enquiry.`, marks: 6, command: 'Justify', markScheme: `Levels of response (AO3 3, AO4 3).\nLevel 3 (5–6 marks): Thorough justification of the sampling strategy used in the student's own enquiry, including sample size, type of sampling and location/timing, explaining why it was appropriate and recognising limitations.\nLevel 2 (3–4 marks): Reasonable justification of the strategy, with some reasons why it was appropriate.\nLevel 1 (1–2 marks): Basic description of the sampling, with little justification.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• type of sampling: systematic (e.g. every 100 m along a transect / every 5th passer-by), random (random number tables), stratified (by age group or land-use zone), or opportunistic\n• why chosen: reduces bias, covers the whole study area, represents different groups, practical within time and safety limits\n• sample size: e.g. 50 questionnaires to make results reliable; larger samples reduce the effect of anomalies\n• timing: e.g. weekday vs weekend counts\n• limitations: e.g. opportunistic sampling biased towards people willing to stop; refusals.\nGeneric answers with no link to the student's own enquiry max Level 1.` },
      { q: `Section B — Human geography fieldwork.\nGCSE students investigated environmental quality in two parts of a city. They visited one site in each area on a single Friday afternoon. At each site, one student completed a bipolar survey of six features, such as litter, noise, graffiti and green space, scoring each from −3 to +3. The total scores were −11 at site X and +9 at site Y.\n\nAssess the reliability of the students' method.`, marks: 6, command: 'Assess', markScheme: `Levels of response (AO3 3, AO4 3).\nLevel 3 (5–6 marks): Thorough assessment of the strengths and weaknesses of the method, with developed points about subjectivity, sample size and timing, and a clear judgement on reliability. Improvements may be suggested.\nLevel 2 (3–4 marks): Reasonable assessment of some strengths and weaknesses; partial judgement.\nLevel 1 (1–2 marks): Basic points about the method; little assessment.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• strengths: same six criteria and scale at both sites allow comparison; quick and quantitative\n• weaknesses: scores are subjective and depend on one student's opinion; only one site per area is not representative; a single Friday afternoon may not be typical (e.g. traffic noise, litter before bin collection)\n• improvements: several students score each site and take a mean; more sites per area chosen by systematic sampling; repeat on different days/times; add photographs or a noise meter for objective data\n• judgement: e.g. the method has low reliability, so the large difference between −11 and +9 can only be a tentative result.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry.\n\nExplain how the results of your human geography enquiry link to geographical theory or wider geographical understanding.`, marks: 6, command: 'Explain', markScheme: `Levels of response (AO1 2, AO3 4).\nLevel 3 (5–6 marks): Thorough explanation of the student's own results, clearly linked to relevant theory or wider understanding, with data used and recognition of where results did or did not fit.\nLevel 2 (3–4 marks): Reasonable explanation of results with some links to theory.\nLevel 1 (1–2 marks): Basic description of results; little or no link to theory.\n0 marks: No response or no response worthy of credit.\n\nIndicative content (depends on the enquiry):\n• Burgess model / urban land-use zones: e.g. building age and density decreased and green space increased away from the CBD\n• bid-rent theory: shops and offices at the centre where land is most expensive; pedestrian counts highest near the centre\n• urban regeneration / rebranding: e.g. environmental quality scores higher in regenerated areas\n• deprivation and quality of life: e.g. links between IMD data and environmental quality scores\n• results that did not fit the theory and possible reasons (e.g. an out-of-town retail park, a park near the centre).\nGeneric answers with no use of own results max Level 1.` },
      { q: `Section B — Physical geography fieldwork.\nGCSE students investigated whether beach material gets smaller along a 2 km stretch of beach in the direction of longshore drift. They walked along the beach and stopped wherever they saw a mixture of pebbles. At each stop they measured the long axis of the first 5 pebbles they picked up. They made 4 stops in total.\n\nExamine the strengths and weaknesses of the students' sampling.`, marks: 6, command: 'Examine', markScheme: `Levels of response (AO3 3, AO4 3).\nLevel 3 (5–6 marks): Thorough examination of both strengths and weaknesses of the sampling, with developed points about bias and representativeness, leading to a clear conclusion. Improvements may be suggested.\nLevel 2 (3–4 marks): Reasonable examination of some strengths and/or weaknesses.\nLevel 1 (1–2 marks): Basic points; little examination.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• strengths: quick and easy (opportunistic/convenience sampling); covered the length of the beach\n• weaknesses: stopping where they 'saw' pebbles and picking up the first ones is biased towards larger or more visible pebbles; only 4 stops and 20 pebbles in total is a small sample; stops not evenly spaced so the pattern along the beach is unclear; no control of position on the beach profile (high or low tide line)\n• improvements: systematic sampling every 200 m along the beach at the same point on the profile, random sampling of pebbles using a quadrat and random numbers, larger sample (e.g. 15–20 per site)\n• conclusion: the sampling is too biased and small to test the hypothesis reliably.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 12: threats facing people in Bangladesh:\n• Sea level is projected to rise by up to about 1 m by 2100; a rise of this size could flood a large part of the coastal zone.\n• Tropical cyclones such as Cyclone Sidr (2007) caused storm surges along the coast, killing about 3400 people.\n• In the 1998 floods about two-thirds of the country was under water.\n• Many rural families are moving to Dhaka to find work in garment factories.\n• Arsenic is naturally present in the groundwater of many wells.\n\nUsing Fig. 12 and your own understanding, assess the extent to which climate change is the greatest threat to people in Bangladesh.`, marks: 8, command: 'Assess', markScheme: `Levels of response (AO1 2, AO2 2, AO3 4).\nLevel 3 (6–8 marks): Thorough knowledge and understanding of climate change and other threats in Bangladesh. Makes good use of Fig. 12 and own understanding. Thorough assessment of the relative importance of different threats, leading to a well-supported judgement on 'extent'.\nLevel 2 (3–5 marks): Reasonable knowledge and understanding. Some use of Fig. 12. Some assessment, with a partial judgement.\nLevel 1 (1–2 marks): Basic knowledge, mainly lifted from Fig. 12. Little or no assessment.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nClimate change as the greatest threat:\n• sea level rise threatens low-lying coastal land, homes and farmland; saltwater intrusion damages crops and drinking water\n• warmer seas may make tropical cyclones more intense, increasing storm surge risk\n• more intense monsoon rainfall and glacial melt in the Himalayas may increase river flooding\nOther threats:\n• flooding and cyclones are natural hazards that happened before recent climate change (e.g. 1970 Bhola cyclone)\n• poverty and rapid urbanisation in Dhaka, poor housing and working conditions\n• arsenic in groundwater is a health threat unrelated to climate change\nJudgement: e.g. climate change is the greatest long-term threat because it worsens existing hazards, but in the short term poverty and vulnerability determine how badly people are affected.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 7 shows the number of foreign visitors arriving in Iceland through Keflavík International Airport (millions, values rounded): 2010 — 0.49; 2014 — 1.0; 2018 — 2.3; 2020 — 0.5; 2022 — 1.7.\nFig. 8: Iceland's main exports are fish and aluminium. Aluminium smelters use cheap renewable electricity from HEP and geothermal power. Tourism earns more foreign currency than either fishing or aluminium in most recent years.\n\n'Iceland's economy depends too much on tourism.'\n\nUsing Figs. 7 and 8 and your own understanding, evaluate this statement.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response (AO1 2, AO2 2, AO3 4).\nLevel 3 (6–8 marks): Thorough understanding of Iceland's economy. Makes good use of Figs. 7 and 8 and own understanding. Thorough evaluation of both sides, leading to a well-supported judgement.\nLevel 2 (3–5 marks): Reasonable understanding. Some use of the resources. Some evaluation; judgement partly supported or one-sided.\nLevel 1 (1–2 marks): Basic understanding; mainly lifted from the resources. Little or no evaluation.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nAgree:\n• tourism is the largest earner of foreign currency\n• visitor numbers fell by about 78% between 2018 and 2020 (COVID-19), showing vulnerability to global shocks\n• tourism is affected by airline failures, volcanic eruptions (e.g. 2010 ash cloud) and changing exchange rates\nDisagree:\n• Iceland has other export sectors: fishing and aluminium smelting using renewable energy\n• tourism recovered quickly (1.7 million in 2022)\n• tourism spreads income to rural areas and diversified the economy after the 2008 banking crisis\nJudgement: e.g. Iceland's economy is diversified but tourism is now so large that a shock has a major effect, so further diversification (e.g. data centres using renewable energy) would reduce risk.` },
      { q: `Section B — Physical geography fieldwork.\nYou have carried out a physical geography fieldwork enquiry.\n\nAssess how successful your physical geography fieldwork enquiry was in answering your enquiry question.`, marks: 8, command: 'Assess', markScheme: `Levels of response (AO3 4, AO4 4).\nLevel 3 (6–8 marks): Thorough assessment of the success of the student's own enquiry, covering methods, data, presentation, analysis and conclusions. Clear reference to the enquiry question and specific results. Well-supported judgement on how successful the enquiry was.\nLevel 2 (3–5 marks): Reasonable assessment of some stages of the enquiry, with some reference to the enquiry question; partial judgement.\nLevel 1 (1–2 marks): Basic description of the enquiry; little assessment.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• the enquiry question / hypothesis and how far the conclusion answered it, using data (e.g. width increased from 1.2 m to 5.6 m downstream)\n• accuracy of methods: e.g. float method affected by reaction time and wind; depth hard to read in fast water\n• reliability: number of sites and repeats; sampling strategy (systematic sites every 1 km)\n• external factors: weather, recent rainfall changing discharge, human modification of the channel (e.g. a weir)\n• presentation and analysis: whether graphs showed clear patterns; anomalies identified and explained\n• judgement: e.g. partly successful — clear trends supported the hypothesis but too few sites to be confident.\nGeneric answers with no reference to own enquiry max Level 1.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry.\n\nEvaluate how reliable the conclusions of your human geography enquiry were.`, marks: 8, command: 'Evaluate', markScheme: `Levels of response (AO3 4, AO4 4).\nLevel 3 (6–8 marks): Thorough evaluation of the reliability of the student's own conclusions, considering sampling, methods, data quality, anomalies and outside factors. Specific results are used. Well-supported judgement.\nLevel 2 (3–5 marks): Reasonable evaluation of some factors affecting reliability; some reference to the student's own data; partial judgement.\nLevel 1 (1–2 marks): Basic points; little evaluation or reference to own enquiry.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\n• states the conclusion and the evidence for it (e.g. environmental quality scores fell from +12 in the regenerated area to −8 in the older terraced area)\n• sample size and sampling bias (e.g. 40 questionnaires on a weekday; mainly older residents)\n• subjectivity of bipolar surveys and perception data; different students scoring differently\n• timing: one day only, weather, events affecting pedestrian or traffic counts\n• use of secondary data (e.g. census, IMD) to support or challenge conclusions\n• judgement: e.g. the conclusions are partly reliable — the overall pattern was clear and supported by secondary data, but small samples mean details are less certain.\nGeneric answers max Level 1.` },
      { q: `Section B — Human geography fieldwork.\nYou have carried out a human geography fieldwork enquiry using both primary and secondary data.\n\n'Primary data was more useful than secondary data in answering my enquiry question.'\n\nTo what extent do you agree with this statement? Refer to your own human geography enquiry.`, marks: 8, command: 'Assess', markScheme: `Levels of response (AO3 4, AO4 4).\nLevel 3 (6–8 marks): Thorough assessment of the usefulness of both primary and secondary data in the student's own enquiry, with specific examples and a clear, well-supported judgement on the extent of agreement.\nLevel 2 (3–5 marks): Reasonable assessment of primary and/or secondary data with some reference to own enquiry; partial judgement.\nLevel 1 (1–2 marks): Basic points about primary and secondary data; little reference to own enquiry.\n0 marks: No response or no response worthy of credit.\n\nIndicative content:\nPrimary data:\n• directly answered the question for the chosen sites (e.g. pedestrian counts, questionnaires, environmental quality surveys)\n• up to date, and the student controlled the method\n• but small samples, one day only and subjectivity reduce reliability\nSecondary data:\n• census / IMD data cover the whole population, so are larger and more reliable\n• historical maps or photographs show change over time, which primary data cannot\n• but may be out of date (census every 10 years) or at a different scale from the study sites\nJudgement: e.g. primary data was more useful because it was specific to the question, but secondary data was needed to check and explain the results.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Kenya.\nFig. 3: Nairobi's population grew from about 0.5 million in 1969 to about 4.4 million in 2019. More than half of Nairobi's people are estimated to live in informal settlements such as Kibera.\nFig. 4 (photograph described): Kibera has densely packed homes made of mud and corrugated iron, narrow dirt paths, open drains full of rubbish and informal electricity connections.\nFig. 13: Kenya's government is considering three options to improve living conditions for people in Nairobi's informal settlements:\n• Option 1 — Clearance and rehousing: demolish areas of informal housing and build high-rise flats with water, sanitation and electricity. Residents pay rent for the new flats. Cost: high.\n• Option 2 — Upgrading in place: work with residents to pave paths, build drains, toilets and water points, and give residents legal ownership of their plots so they can improve their own homes. Cost: medium.\n• Option 3 — New satellite city: invest in Konza Technopolis, a planned city about 60 km south-east of Nairobi, to provide new jobs and housing away from the capital. Cost: very high.\n\nChoose the option which you think will be the most sustainable way to improve living conditions for people in Nairobi's informal settlements. Justify your decision, using Figs. 3, 4 and 13 and your own understanding. [12 marks + 3 marks for SPaG]`, marks: 12, command: 'Justify', markScheme: `Levels of response (AO2 4, AO3 8). Spelling, punctuation and grammar and the use of specialist terminology are assessed in this question.\nLevel 4 (10–12 marks): Thorough understanding of the issues facing informal settlements and of sustainability (social, economic, environmental). Makes full and effective use of the resources and own understanding (e.g. located examples of slum upgrading or rehousing). A thorough justification of the chosen option, with clear consideration of its disadvantages and why the other options were rejected, leading to a well-substantiated decision.\nLevel 3 (7–9 marks): Good understanding. Makes good use of the resources. A clear justification of the chosen option, with some consideration of disadvantages and other options.\nLevel 2 (4–6 marks): Reasonable understanding. Some use of resources. Some justification, but largely one-sided; other options considered briefly or not at all.\nLevel 1 (1–3 marks): Basic understanding; largely lifted from resources. Option chosen with little or no justification.\n0 marks: No response or no response worthy of credit.\nAny option can access full marks.\n\nIndicative content:\nOption 1: improves housing quality and services quickly; but rents may be unaffordable so the poorest are displaced; breaks up communities and informal businesses; very costly for a country with GNI per capita about US$2 100; examples of past rehousing schemes where new flats were occupied by richer tenants.\nOption 2: cheaper, so more people can benefit; keeps communities and livelihoods together; legal ownership encourages residents to invest in their homes; bottom-up and involves people, so more socially sustainable; but density and overcrowding remain, and progress may be slow.\nOption 3: reduces pressure on Nairobi long-term and creates high-tech jobs; planned with solar power and rainwater harvesting (environmentally sustainable); but very expensive, slow to build, jobs may need skills that slum residents do not have, so it may not help the people in Kibera.\nJudgement linking to sustainability over the short and long term.\n\nSPaG (3 marks):\nHigh performance (3 marks): learners spell and punctuate with consistent accuracy; learners use rules of grammar with effective control of meaning overall; learners use a wide range of specialist terms as appropriate.\nIntermediate performance (2 marks): learners spell and punctuate with considerable accuracy; learners use rules of grammar with general control of meaning overall; learners use a good range of specialist terms as appropriate.\nThreshold performance (1 mark): learners spell and punctuate with reasonable accuracy; learners use rules of grammar with some control of meaning and any errors do not significantly hinder meaning overall; learners use a limited range of specialist terms as appropriate.\n0 marks: learners write nothing; or the response does not relate to the question; or errors severely hinder meaning.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Iceland.\nFig. 14: Grindavík is a fishing town of about 3700 people on the Reykjanes peninsula in south-west Iceland. In November 2023, after hundreds of earthquakes, the whole town was evacuated as magma moved beneath it. Since then there have been repeated fissure eruptions nearby. In January 2024 lava reached the edge of the town and destroyed several houses. Earth barriers (walls of rock and soil) have been built to divert lava away from the town and from the Svartsengi geothermal power station, which supplies hot water and electricity to about 30 000 people on the peninsula.\nFig. 15: options for the future of Grindavík:\n• Option 1 — Protect and return: build higher and longer lava barriers, repair roads and pipes, and allow residents to return when monitoring shows it is safe.\n• Option 2 — Managed relocation: the government buys residents' homes and helps them move permanently to other towns; the town is left as a monitored zone.\n• Option 3 — Partial use: residents live elsewhere, but the harbour and fish-processing businesses reopen during the day, with a 24-hour monitoring and warning system.\n\nChoose the option which you think is best for the future of Grindavík. Justify your choice, using Fig. 14 and Fig. 15 and your own understanding.`, marks: 12, command: 'Justify', markScheme: `Levels of response (AO2 4, AO3 8).\nLevel 4 (10–12 marks): Thorough understanding of tectonic hazards and their management, and of the social, economic and environmental issues for Grindavík. Makes full use of the resources and own understanding. Thorough justification of the chosen option, considering its weaknesses and why other options were rejected, with a well-substantiated decision.\nLevel 3 (7–9 marks): Good understanding. Good use of the resources. Clear justification with some consideration of other options.\nLevel 2 (4–6 marks): Reasonable understanding. Some use of the resources. Some justification, largely one-sided.\nLevel 1 (1–3 marks): Basic understanding; lifted from resources; little justification.\n0 marks: No response or no response worthy of credit.\nAny option can access full marks.\n\nIndicative content:\nOption 1: keeps the community and its fishing economy; barriers have already diverted lava; Iceland can afford monitoring and engineering; but eruptions may continue for years or decades, ground cracking damages pipes and roads, residents remain at risk, and costs keep rising.\nOption 2: removes risk to life permanently; gives residents certainty; but loss of homes, community and identity; cost of buying homes; loss of a fishing port and jobs; may be unpopular.\nOption 3: compromise that keeps the economically valuable harbour and fish processing working while reducing the risk to life at night; relies on reliable monitoring and warning (seismometers, GPS); commuting costs; the community is still split up.\nOther considerations: protection of Svartsengi (wider regional energy supply); Iceland's wealth and monitoring technology; uncertainty of future eruptions; views of residents vs government.\nJudgement on the best balance of safety, cost and community over the short and long term.` },
      { q: `Paper 3 — Geographical Exploration. Resource Booklet — Bangladesh.\nFig. 9: Bangladesh lies on the low-lying delta of the Ganges, Brahmaputra and Meghna rivers. Most of the country is less than 10 m above sea level. It has a population of about 170 million.\nFig. 10: about 66% of Dhaka's annual rainfall falls in the monsoon months of June to September.\nFig. 16: options for reducing the impact of flooding in Bangladesh:\n• Option 1 — Large-scale engineering: build high embankments along the major rivers and new flood barriers around cities, funded mainly by international loans.\n• Option 2 — Community-based adaptation: build raised homes on earth plinths, more cyclone and flood shelters, floating gardens and schools, and improve early warnings sent by mobile phone and loudspeaker.\n• Option 3 — Planned migration: invest in secondary towns away from the coast and major rivers so that people can move away from the highest-risk areas over time.\n\nChoose the option which you think will be most effective in reducing the impact of flooding on people in Bangladesh. Justify your choice, using Figs. 9, 10 and 16 and your own understanding.`, marks: 12, command: 'Justify', markScheme: `Levels of response (AO2 4, AO3 8).\nLevel 4 (10–12 marks): Thorough understanding of the causes of flooding in Bangladesh and of the strategies. Makes full use of the resources and own understanding. Thorough justification of the chosen option, considering its weaknesses and why the other options were rejected, leading to a well-substantiated decision.\nLevel 3 (7–9 marks): Good understanding. Good use of the resources. Clear justification with some consideration of other options.\nLevel 2 (4–6 marks): Reasonable understanding. Some use of resources. Some justification, largely one-sided.\nLevel 1 (1–3 marks): Basic understanding; lifted from resources; little justification.\n0 marks: No response or no response worthy of credit.\nAny option can access full marks.\n\nIndicative content:\nOption 1: protects cities and large areas of farmland; but very expensive for a lower-income country and increases debt; embankments can fail or raise water levels elsewhere; stop silt fertilising farmland; flooding is part of the farming cycle.\nOption 2: relatively cheap and can be built by local people; works with the natural flood cycle; early warnings and cyclone shelters have greatly reduced deaths since 1970 (e.g. Sidr 2007 compared with Bhola 1970); but does not stop damage to crops and property; depends on reaching remote communities.\nOption 3: long-term response to sea level rise and climate change; reduces pressure on Dhaka; but costly, slow, breaks up communities and people may not want to move; land is scarce with about 1150 people per km².\nJudgement on effectiveness for people over short and long term, possibly combining options but clearly choosing one.` }
    ]
  }
};
